window.SB_INDUSTRY_PROFILES = {"generated":"2026-10-26","note":"Research notes written for Stock Blueprint (general analysis, not NSE text). Official NSE definitions are not included.","profiles":{"b-commodity-chemicals":{"simplifiedExplanation":"Companies that make basic chemicals in large volumes, such as acids, alkalis, solvents and intermediates. These are standard products, so buyers mostly choose on price and reliable supply.","productsAndServices":["Caustic soda and chlorine","Soda ash","Sulphuric, nitric and other acids","Phenol, acetone and solvents","Methanol and ammonia derivatives","Phthalic anhydride and plasticiser inputs","Hydrogen peroxide and bleaching chemicals"],"valueChainPosition":"Upstream-to-midstream: buys salt, minerals, natural gas, coal and crude derivatives, and supplies other chemical makers plus textile, glass, detergent, paper, pharma and agrochemical industries.","howTheyMakeMoney":"They sell large volumes at prices close to domestic and import-parity levels. Profit is the spread between product price and feedstock plus energy cost, multiplied by how fully the plant runs.","revenueSources":["Bulk chemical sales to industrial buyers","Co-products and by-products","Exports of surplus volumes","Surplus power or steam (some)"],"operatingCosts":["Feedstock (salt, gas, benzene, propylene and similar)","Power and fuel","Freight and handling of bulk liquids","Plant maintenance","Effluent treatment and compliance"],"customersAndEndMarkets":"Downstream chemical makers, textile processors, glass, soap and detergent makers, aluminium refiners, paper mills, pharma and water-treatment users.","demandSupplyDrivers":"Demand follows general industrial output. Supply is lumpy: a large new plant at home or abroad, or cheap Chinese and Middle Eastern exports, can pull prices down across the market.","domesticInternationalExposure":"Mostly sold in India but priced against imports; global prices of benzene, propylene, ammonia and similar feedstocks feed straight into costs.","capexIntensity":"High","capexNote":"Large continuous-process plants need heavy investment and scale to be cost-competitive.","workingCapital":"Moderate: feedstock and finished-goods stocks plus credit to industrial customers; price falls can hurt inventory values.","regulation":"Environmental clearance from MoEF and state pollution control boards, hazardous-chemical storage rules, and anti-dumping duties set on DGTR recommendations shape operations.","competitiveAdvantages":"Scale, feedstock integration, captive power and locations near customers or ports lower costs; costly plants and slow approvals keep new entrants few.","drivers":[{"factor":"Commodity prices","impact":"Product and feedstock prices move with global chemical cycles and set the spread."},{"factor":"Imports & dumping","impact":"Cheap imports cap domestic prices; anti-dumping duties can restore them."},{"factor":"Capacity utilisation","impact":"High fixed costs mean profits jump when plants run full and drop sharply when they do not."},{"factor":"Crude oil prices","impact":"Crude-linked feedstocks and fuel make up a large part of costs for many products."},{"factor":"Exports & global demand","impact":"Weak global demand pushes surplus product into India and lowers prices."}],"risks":[{"risk":"Price cycles","detail":"Global capacity additions can cause long stretches of low prices."},{"risk":"Plant shutdowns","detail":"Accidents, breakdowns or pollution orders can halt output."},{"risk":"Energy costs","detail":"Power and fuel price spikes squeeze spreads quickly."},{"risk":"Duty changes","detail":"Lapse of anti-dumping protection can expose producers to imports."}],"cyclicality":"Cyclical","cyclicalityNote":"Earnings swing with global chemical spreads and industrial demand.","metricSet":"chemicals","relatedBasicIndustries":["b-petrochemicals","b-specialty-chemicals","b-fertilizers","b-trading-chemicals","b-glass-industrial"],"aliases":["commodity chemicals","bulk chemicals","basic chemicals","chlor alkali","caustic soda","soda ash","industrial acids","industrial chemicals"],"themes":[]},"b-specialty-chemicals":{"simplifiedExplanation":"Companies that make chemicals designed for a specific job, such as an ingredient for a medicine, a crop-protection molecule or a coating additive. They sell on performance and quality, not just price.","productsAndServices":["Pharma and agrochemical intermediates","Fluorochemicals","Surfactants and textile chemicals","Construction chemicals and admixtures","Flavours, fragrances and aroma chemicals","Polymer and rubber additives","Water-treatment and oilfield chemicals","Custom synthesis and contract manufacturing"],"valueChainPosition":"Midstream: buys basic and petrochemical inputs and supplies pharma, agrochemical, personal-care, paint, textile, construction and electronics makers in India and abroad.","howTheyMakeMoney":"They earn margins from process know-how, purity and reliability, often as an approved vendor or under multi-year supply agreements. Contract manufacturing for global innovators pays for dedicated capacity and technical skill.","revenueSources":["Product sales to industrial customers","Custom synthesis and contract manufacturing","Exports to regulated markets","Technical service and formulation support"],"operatingCosts":["Raw materials and intermediates (often imported)","Power, steam and utilities","R&D and skilled chemists","Effluent treatment and safety systems","Plant depreciation"],"customersAndEndMarkets":"Global and domestic pharma, agrochemical, personal-care, paint, textile, construction and electronics companies.","demandSupplyDrivers":"Demand depends on end-market growth and on global buyers shifting supply away from China. Customer destocking and Chinese price cuts can cause sharp temporary falls.","domesticInternationalExposure":"Many companies export a large part of output, so global demand, the rupee and Chinese competition matter a lot; several key inputs are imported.","capexIntensity":"Medium","capexNote":"Multipurpose plants need steady investment, plus spending on R&D, customer approvals and pollution control.","workingCapital":"Fairly high: export receivables, stocks of many raw materials and long customer qualification phases tie up cash.","regulation":"Pollution control board consents and environmental clearances, hazardous-chemical rules, and export-market rules such as EU REACH registration; customer audits act as a further check.","competitiveAdvantages":"Chemistry skills, long customer approval processes, safety and compliance records and backward integration make switching suppliers slow and costly.","drivers":[{"factor":"Exports & global demand","impact":"Orders from global pharma, agrochemical and consumer companies drive volumes."},{"factor":"China+1 sourcing","impact":"Buyers diversifying away from China can bring new contracts to Indian makers."},{"factor":"Imports & dumping","impact":"Low-priced Chinese products pressure prices in India and export markets."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts export realisations; a stronger rupee reduces them."},{"factor":"Technology change","impact":"New molecules and greener chemistry open niches for skilled makers."}],"risks":[{"risk":"Customer destocking","detail":"Global customers cutting inventory can reduce orders for several quarters."},{"risk":"Concentration","detail":"A few large clients or molecules can dominate revenue."},{"risk":"Plant accidents","detail":"Fires or leaks can halt production and invite regulatory action."},{"risk":"Chinese pricing","detail":"Aggressive pricing from Chinese producers can erode margins."}],"cyclicality":"Mixed","cyclicalityNote":"Steadier than bulk chemicals, but exposed to global inventory cycles and end-market slowdowns.","metricSet":"chemicals","relatedBasicIndustries":["b-commodity-chemicals","b-pesticides-and-agrochemicals","b-pharmaceuticals","b-dyes-and-pigments","b-paints"],"aliases":["specialty chemicals","speciality chemicals","fine chemicals","performance chemicals","CDMO chemicals","custom synthesis","fluorochemicals","chemical intermediates"],"themes":["China+1","Exports"]},"b-carbon-black":{"simplifiedExplanation":"Carbon black is a fine black powder made by burning heavy oil in a controlled way. It makes tyres and rubber stronger and gives black colour to inks, paints and plastics.","productsAndServices":["Rubber-grade carbon black for tyres","Grades for belts, hoses and moulded rubber","Specialty grades for plastics, inks and coatings","Conductive carbon for batteries and cables","Co-generated power from process tail gas","Coal-tar pitch and related products (some)"],"valueChainPosition":"Midstream: buys carbon black feedstock oil from refineries and coal-tar distillers and supplies tyre makers, rubber goods makers and ink, paint and plastics compounders.","howTheyMakeMoney":"They sell by the tonne, usually under price formulas that pass feedstock changes to tyre customers with a lag. Specialty grades earn higher margins, and selling surplus power made from tail gas adds income.","revenueSources":["Tyre-grade carbon black","Specialty and performance grades","Exports","Power sales from co-generation"],"operatingCosts":["Carbon black feedstock oil","Natural gas and fuel","Freight and packaging","Plant maintenance","Emission control"],"customersAndEndMarkets":"Tyre makers are the largest buyers, followed by mechanical rubber goods, plastics masterbatch, ink, paint and battery makers.","demandSupplyDrivers":"Demand follows tyre production, which tracks new vehicle sales and replacement tyre demand. New plants and imports affect pricing.","domesticInternationalExposure":"Feedstock prices follow crude and coal-tar markets; Indian makers export to global tyre companies and face imports in turn.","capexIntensity":"High","capexNote":"Reactors, feedstock handling and co-generation plants are capital heavy.","workingCapital":"Moderate: feedstock is often imported in large lots and tyre customers get credit periods.","regulation":"State pollution control board consents and emission norms are important; anti-dumping duties on imported carbon black have been used in the past.","competitiveAdvantages":"Long approval cycles with tyre makers, scale, feedstock sourcing and a rising specialty mix protect established players.","drivers":[{"factor":"Crude oil prices","impact":"Feedstock cost moves with heavy oil and coal-tar prices."},{"factor":"Consumer demand","impact":"Vehicle sales and replacement tyre demand set volumes."},{"factor":"Exports & global demand","impact":"Global tyre makers sourcing from India support export volumes."},{"factor":"Imports & dumping","impact":"Cheaper imports can pressure domestic prices."},{"factor":"EV battery materials","impact":"Conductive carbon for batteries is a newer, higher-value market."}],"risks":[{"risk":"Pass-through lag","detail":"Fast feedstock price moves can hurt margins before contract prices reset."},{"risk":"Tyre slowdown","detail":"Weak vehicle or tyre demand cuts volumes."},{"risk":"Emission norms","detail":"Tighter pollution rules can raise costs or restrict plants."},{"risk":"Customer concentration","detail":"A small number of tyre makers buy most of the output."}],"cyclicality":"Cyclical","cyclicalityNote":"Tied to auto and tyre cycles and crude-linked feedstock costs.","metricSet":"chemicals","relatedBasicIndustries":["b-tyres-and-rubber-products","b-refineries-and-marketing","b-specialty-chemicals","b-rubber","b-printing-inks"],"aliases":["carbon black","furnace black","tyre carbon","rubber black","conductive carbon","specialty black"],"themes":["EV","Exports"]},"b-dyes-and-pigments":{"simplifiedExplanation":"Companies that make colours: dyes that colour fabric, yarn and leather, and pigments that colour paints, inks and plastics.","productsAndServices":["Reactive, disperse and acid dyes","Organic pigments","Inorganic pigments such as ultramarine and iron oxide","Dye intermediates","Pigment preparations for plastics","Detergent and specialty colourants"],"valueChainPosition":"Midstream: buys benzene- and naphthalene-based intermediates and minerals, and supplies textile processors and paint, ink, plastics and detergent makers.","howTheyMakeMoney":"They sell colours by the kilogram, with margins tied to shade range, batch consistency and customer approvals. Backward integration into intermediates can widen margins.","revenueSources":["Dyes for textile processors","Pigments for paint, ink and plastic makers","Intermediate sales","Exports"],"operatingCosts":["Aromatic intermediates and raw materials","Effluent treatment","Power and steam","Freight","Technical and colour-lab staff"],"customersAndEndMarkets":"Textile dyeing and printing units serving garment makers and exporters, paint companies, ink makers, plastics compounders and detergent makers.","demandSupplyDrivers":"Textile and garment demand and paint and ink volumes drive sales. Pollution crackdowns in India or China can suddenly cut supply and lift prices.","domesticInternationalExposure":"Exports are significant and Chinese supply largely sets global prices; many intermediates are imported.","capexIntensity":"Medium","capexNote":"Batch plants are moderately costly, with significant spending on effluent treatment.","workingCapital":"High: many shades and grades must be stocked, and textile customers often take long credit.","regulation":"Close scrutiny of effluent by state pollution control boards and the National Green Tribunal; export markets restrict banned amines and heavy metals.","competitiveAdvantages":"Shade libraries, consistent quality, a clean compliance record and integration into intermediates protect established makers.","drivers":[{"factor":"Exports & global demand","impact":"Global textile and coatings demand sets export orders."},{"factor":"Imports & dumping","impact":"Chinese supply and pricing heavily influence realisations."},{"factor":"Regulation","impact":"Pollution enforcement can shut capacity in India or abroad, changing supply."},{"factor":"Raw material availability","impact":"Supply and price of aromatic intermediates drive costs."},{"factor":"Consumer demand","impact":"Clothing and paint demand drives dye and pigment volumes."}],"risks":[{"risk":"Pollution action","detail":"Closure orders over effluent can halt plants."},{"risk":"Textile slowdown","detail":"Weak garment demand reduces dye offtake."},{"risk":"Chinese competition","detail":"Low-cost imports can compress margins."},{"risk":"Receivable stress","detail":"Small textile customers may delay payments."}],"cyclicality":"Cyclical","cyclicalityNote":"Moves with textile and paint cycles and Chinese supply conditions.","metricSet":"chemicals","relatedBasicIndustries":["b-specialty-chemicals","b-paints","b-printing-inks","b-other-textile-products","b-garments-and-apparels"],"aliases":["dyes","pigments","dyestuff","colourants","colorants","reactive dyes","organic pigments","dye intermediates"],"themes":["Exports","China+1"]},"b-explosives":{"simplifiedExplanation":"Companies that make industrial explosives and detonators used to break rock in mines and construction, and, in some cases, ammunition and propellants for defence.","productsAndServices":["Bulk and packaged (cartridge) explosives","Detonators and initiating systems","Ammonium-nitrate-based emulsions","Blasting services at mine sites","Propellants, warheads and ammunition for defence","Boosters and blasting accessories"],"valueChainPosition":"Midstream: buys ammonium nitrate and other chemicals and supplies coal, limestone and metal-ore miners, infrastructure contractors and the armed forces.","howTheyMakeMoney":"Mining explosives are sold through tenders and supply contracts, often with price-variation clauses linked to ammonium nitrate. Defence products are sold against orders from the Ministry of Defence and export customers, usually at higher margins.","revenueSources":["Bulk explosives and blasting services for mines","Packaged explosives and detonators","Defence products","Exports"],"operatingCosts":["Ammonium nitrate and fuel oils","Other chemicals and packaging","Safety systems and licensed storage","Transport under special rules","Skilled manpower"],"customersAndEndMarkets":"Coal and metal miners, limestone quarries of cement makers, tunnel, road and dam builders, and defence buyers in India and abroad.","demandSupplyDrivers":"Demand follows mining output, especially coal, and tunnelling and quarrying for infrastructure. Defence demand depends on procurement orders and export approvals.","domesticInternationalExposure":"Mining demand is mostly domestic, with growing exports of industrial explosives and defence items; ammonium nitrate prices follow global markets.","capexIntensity":"Medium","capexNote":"Licensed plants and magazines need investment; defence facilities need more specialised spending.","workingCapital":"Moderate to high: tender customers can pay slowly and defence orders tie up inventory.","regulation":"Tightly licensed under the Explosives Act through PESO, with Ammonium Nitrate Rules on storage and handling; defence items need Ministry of Defence licences and export authorisation.","competitiveAdvantages":"Licences, safety records, on-site blasting know-how and defence qualifications make entry difficult.","drivers":[{"factor":"Infrastructure spending","impact":"Roads, tunnels, dams and railways raise blasting needs."},{"factor":"Coal mining output","impact":"Coal production is the largest user of bulk explosives."},{"factor":"Defence spending","impact":"Ammunition and propellant orders add higher-margin revenue."},{"factor":"Commodity prices","impact":"Ammonium nitrate cost changes flow into margins until contract prices reset."},{"factor":"Exports & global demand","impact":"Overseas mining and defence orders widen the market."}],"risks":[{"risk":"Safety incidents","detail":"An accident can stop plants and trigger licence reviews."},{"risk":"Tender pricing","detail":"Competitive tenders from large miners can keep margins thin."},{"risk":"Order timing","detail":"Defence orders are lumpy and can slip."},{"risk":"Input costs","detail":"Ammonium nitrate price spikes squeeze margins."}],"cyclicality":"Mixed","cyclicalityNote":"Mining demand is fairly steady, while defence orders follow government budgets.","metricSet":"chemicals","relatedBasicIndustries":["b-coal","b-aerospace-and-defense","b-fertilizers","b-industrial-minerals","b-civil-construction"],"aliases":["explosives","industrial explosives","detonators","blasting","emulsion explosives","ammunition","propellants"],"themes":["Defence","Infrastructure"]},"b-petrochemicals":{"simplifiedExplanation":"Companies that turn oil- and gas-based feedstocks into plastics, synthetic rubber and chemical building blocks used to make thousands of everyday products.","productsAndServices":["Polyethylene and polypropylene","PVC and other vinyls","ABS and engineering plastics","Linear alkyl benzene (LAB) for detergents","PTA and MEG for polyester","Benzene, toluene and xylene","Synthetic rubber","Plasticisers and solvents"],"valueChainPosition":"Midstream: buys naphtha, natural gas, ethylene, propylene or aromatics from refineries and crackers, and supplies plastics processors and polyester, detergent, packaging and auto-part makers.","howTheyMakeMoney":"They earn the spread between polymer or chemical prices and feedstock cost, which tracks Asian benchmark prices. Running large plants at high utilisation is key.","revenueSources":["Polymer and resin sales","Chemical intermediates","Specialty compounds and grades","Exports"],"operatingCosts":["Naphtha, gas or monomer feedstock","Power and utilities","Catalysts and additives","Freight","Plant depreciation and maintenance"],"customersAndEndMarkets":"Plastics processors, packaging converters, polyester and textile makers, detergent makers, and pipe, appliance and auto-part manufacturers.","demandSupplyDrivers":"Demand tracks packaging, construction, consumer goods and autos. Large new crackers in China and the Middle East can depress global spreads for long periods.","domesticInternationalExposure":"India imports a good part of its polymer needs, so domestic prices follow import parity; feedstock prices follow crude and global gas.","capexIntensity":"High","capexNote":"Crackers and polymer plants are among the most capital-intensive projects in industry.","workingCapital":"Moderate: feedstock and product stocks carry price risk, while distributors carry much of the credit to small processors.","regulation":"Environmental clearance and pollution norms, BIS quality control orders on several polymers and chemicals, and anti-dumping or safeguard duties via DGTR affect imports.","competitiveAdvantages":"Feedstock integration with refineries, scale and nearness to customers give cost leadership; smaller players survive in niche grades.","drivers":[{"factor":"Crude oil prices","impact":"Naphtha and other feedstocks move with crude, shifting costs."},{"factor":"Commodity prices","impact":"Global polymer and chemical spreads decide profitability."},{"factor":"Imports & dumping","impact":"Import parity and trade duties set domestic prices."},{"factor":"Consumer demand","impact":"Packaging, appliances and autos drive polymer use."},{"factor":"Capacity utilisation","impact":"Global capacity additions versus demand shape the cycle."}],"risks":[{"risk":"Global oversupply","detail":"New capacity abroad can depress spreads for years."},{"risk":"Feedstock volatility","detail":"Sudden crude moves can squeeze margins."},{"risk":"Plastic rules","detail":"Bans on single-use plastics can reduce some end uses."},{"risk":"Plant outages","detail":"Unplanned shutdowns hit volumes and fixed-cost absorption."}],"cyclicality":"Cyclical","cyclicalityNote":"Spreads follow global petrochemical capacity cycles and crude prices.","metricSet":"chemicals","relatedBasicIndustries":["b-refineries-and-marketing","b-commodity-chemicals","b-plastic-products-industrial","b-packaging","b-gas-transmission-marketing"],"aliases":["petrochemicals","petchem","polymers","plastic resin","polyethylene","polypropylene","PVC","ABS","LAB"],"themes":[]},"b-printing-inks":{"simplifiedExplanation":"Companies that make the inks used to print packaging, newspapers, magazines and labels.","productsAndServices":["Gravure and flexo inks for flexible packaging","Offset inks for publications and commercial print","News inks","Label and narrow-web inks","Digital and UV-curable inks","Coatings, varnishes and packaging adhesives"],"valueChainPosition":"Midstream: buys pigments, resins, solvents and additives, and supplies packaging converters, printing presses and newspaper publishers.","howTheyMakeMoney":"They sell formulated inks with colour matching and on-press technical support, often as approved suppliers to packaging converters. Margins depend on the gap between selling prices and petroleum-based raw material costs.","revenueSources":["Packaging inks","Publication and commercial printing inks","Coatings and adhesives","Exports (some)"],"operatingCosts":["Pigments and resins","Solvents linked to crude","Technical service staff","Freight and packaging","Technology fees (some)"],"customersAndEndMarkets":"Flexible packaging converters serving food and FMCG brands, carton makers, commercial printers and newspaper publishers.","demandSupplyDrivers":"Packaged food and FMCG volumes drive packaging inks, while newspaper and magazine circulation trends drive publication inks.","domesticInternationalExposure":"Sales are mainly domestic; key pigments, resins and solvents follow global petrochemical prices and some are imported.","capexIntensity":"Low","capexNote":"Mixing and milling plants need modest investment relative to sales.","workingCapital":"Moderate: many colours and grades in stock, plus credit to converters and printers.","regulation":"Pollution control consents for solvent handling; food-packaging inks are expected to meet BIS standards referenced in FSSAI packaging rules.","competitiveAdvantages":"Colour-matching capability, technical service at the press, approvals with large brand owners and access to global technology.","drivers":[{"factor":"Consumer demand","impact":"Packaged food and FMCG sales drive packaging print volumes."},{"factor":"Crude oil prices","impact":"Solvents and resins track crude, moving costs."},{"factor":"Technology change","impact":"Digital printing and shrinking print media change the product mix."},{"factor":"Regulation","impact":"Food-safety norms push demand toward safer, premium inks."}],"risks":[{"risk":"Print media decline","detail":"Falling newspaper use reduces publication-ink demand."},{"risk":"Input cost spikes","detail":"Pigment and solvent price rises can run ahead of selling-price hikes."},{"risk":"Customer bargaining power","detail":"Large converters negotiate hard on price."}],"cyclicality":"Mixed","cyclicalityNote":"Packaging demand is steady, but margins swing with petrochemical input costs.","metricSet":"chemicals","relatedBasicIndustries":["b-packaging","b-dyes-and-pigments","b-print-media","b-printing-and-publication","b-specialty-chemicals"],"aliases":["printing inks","inks","packaging inks","gravure inks","flexo inks","offset inks","news ink"],"themes":[]},"b-trading-chemicals":{"simplifiedExplanation":"Companies that buy chemicals from manufacturers or overseas suppliers and resell them to smaller industrial users. They are distributors, not manufacturers.","productsAndServices":["Solvents and bulk liquids","Imported specialty chemicals","Agrochemical and pharma inputs","Polymers and additives","Storage, repacking and delivery","Agency (indenting) services for foreign suppliers"],"valueChainPosition":"Midstream distribution: sits between chemical producers or importers and small and mid-sized manufacturers who buy in smaller lots.","howTheyMakeMoney":"They earn a trading margin or commission on each lot sold, plus value from the storage, credit and logistics they offer buyers.","revenueSources":["Trading margin on chemical sales","Agency commissions","Logistics and repacking services"],"operatingCosts":["Cost of goods bought","Warehousing and tank storage","Freight","Interest on working capital","Sales staff"],"customersAndEndMarkets":"Small and mid-sized makers of paints, textiles, pharma, agrochemicals, plastics and cleaning products.","demandSupplyDrivers":"Volumes follow activity among small manufacturers; price swings between buying and selling change profits.","domesticInternationalExposure":"Many traders import their products, so currency moves, freight and global chemical prices matter.","capexIntensity":"Low","capexNote":"Assets are mainly warehouses, tanks and vehicles.","workingCapital":"High: inventory and customer credit are the core of the business, funded mostly by bank lines.","regulation":"Hazardous-chemical storage and transport rules, GST and customs compliance; some chemicals need special licences.","competitiveAdvantages":"Supplier agency rights, storage near industrial clusters, credit-assessment skill and customer relationships.","drivers":[{"factor":"Commodity prices","impact":"Rising prices give inventory gains; falling prices cause losses."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported products."},{"factor":"Credit growth","impact":"Access to bank credit limits how much stock and customer credit a trader can carry."},{"factor":"Consumer demand","impact":"Downstream manufacturing activity sets volumes."}],"risks":[{"risk":"Inventory losses","detail":"Sharp price falls hurt stock bought at higher prices."},{"risk":"Bad debts","detail":"Small buyers may default or pay late."},{"risk":"Loss of agency","detail":"Suppliers can switch distributors or sell directly."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and margins follow chemical price cycles and small-industry demand.","metricSet":"trading-distribution","relatedBasicIndustries":["b-commodity-chemicals","b-specialty-chemicals","b-trading-and-distributors","b-distributors","b-petrochemicals"],"aliases":["chemical trading","chemical distributor","chemical traders","chemicals dealer","solvent trading","chemical importer"],"themes":[]},"b-industrial-gases":{"simplifiedExplanation":"Companies that separate air into oxygen, nitrogen and argon, or make gases such as hydrogen, carbon dioxide and refrigerants, and supply them to factories and hospitals.","productsAndServices":["Oxygen, nitrogen and argon","Medical oxygen","Hydrogen and carbon dioxide","Specialty and calibration gases","Refrigerant and fluorinated gases","On-site gas plants and steam supply","Cylinders, tankers and gas equipment"],"valueChainPosition":"Midstream: uses air, electricity and chemical feedstock to produce gases and supplies steel, chemicals, refining, glass, electronics, healthcare and food industries.","howTheyMakeMoney":"Large customers such as steel plants get gas from on-site plants under long-term take-or-pay contracts, giving steady income. Smaller customers buy liquid gas by tanker or cylinder at higher prices, and medical and specialty gases earn premium margins.","revenueSources":["Long-term on-site supply contracts","Merchant liquid gas sales","Cylinder and packaged gases","Medical gases and hospital pipeline systems","Equipment and project engineering"],"operatingCosts":["Electricity for air separation","Distribution by tanker and cylinder","Plant maintenance","Feedstock for hydrogen and CO2","Depreciation of plants and cylinders"],"customersAndEndMarkets":"Steel plants, refineries, chemical and glass makers, electronics and solar units, hospitals, food and beverage companies and metal fabricators.","demandSupplyDrivers":"Steel and industrial output drive bulk volumes, while hospital and specialty uses grow more steadily; merchant prices depend on local surplus capacity.","domesticInternationalExposure":"Mostly domestic because gases are costly to transport; some specialty gases and refrigerants are imported or exported.","capexIntensity":"High","capexNote":"Air separation units, cylinders and tanker fleets need heavy upfront investment.","workingCapital":"Low to moderate: contracts bill monthly, though hospital and government dues can be slow.","regulation":"Cylinders, tankers and storage are regulated by PESO; medical oxygen falls under drug rules and can face price controls; refrigerants face phase-down rules under the Montreal Protocol.","competitiveAdvantages":"Long-term contracts, plants located at customer sites, dense distribution and safety know-how create high entry barriers.","drivers":[{"factor":"Power tariffs","impact":"Electricity is the largest cost of air separation, so tariff changes move margins."},{"factor":"Capacity utilisation","impact":"Steel and industrial output decide how fully gas plants run."},{"factor":"Healthcare spending","impact":"Hospital growth drives medical oxygen and gas systems."},{"factor":"Technology change","impact":"Electronics, solar and green hydrogen projects create new gas demand."},{"factor":"Regulation","impact":"Price caps on medical oxygen and refrigerant phase-downs affect earnings."}],"risks":[{"risk":"Anchor customer slowdown","detail":"A steel plant cutting output reduces on-site volumes."},{"risk":"Merchant oversupply","detail":"Surplus liquid gas can drive down spot prices."},{"risk":"Safety incidents","detail":"Cylinder or plant accidents bring regulatory action."},{"risk":"Power cost increase","detail":"Higher tariffs hurt margins where contracts lack pass-through."}],"cyclicality":"Mixed","cyclicalityNote":"Contracted on-site supply is steady, while merchant volumes follow industrial cycles.","metricSet":"chemicals","relatedBasicIndustries":["b-iron-and-steel","b-specialty-chemicals","b-hospital","b-commodity-chemicals","b-medical-equipment-and-supplies"],"aliases":["industrial gases","oxygen","nitrogen","argon","medical oxygen","air separation","hydrogen","refrigerant gas","specialty gases"],"themes":[]},"b-fertilizers":{"simplifiedExplanation":"Companies that make or import plant nutrients such as urea, DAP and complex fertilisers and sell them to farmers, mostly at prices shaped by government subsidies.","productsAndServices":["Urea","DAP (di-ammonium phosphate)","NPK complex fertilisers","Single super phosphate (SSP)","Muriate of potash (traded)","Specialty and water-soluble fertilisers","Ammonia and industrial chemicals (some)","Nano and bio fertilisers"],"valueChainPosition":"Upstream-to-downstream: buys natural gas, rock phosphate, phosphoric acid, ammonia and potash (much of it imported) and sells through dealers and cooperatives to farmers.","howTheyMakeMoney":"Urea sells at a government-fixed farm price and the maker receives a subsidy covering the gap to its normative cost, so beating efficiency norms drives profit. Phosphatic and potassic fertilisers get a fixed subsidy per nutrient under the Nutrient Based Subsidy scheme, so margins depend on global raw material prices and the selling price companies can charge.","revenueSources":["Sales to farmers through dealers","Government subsidy receipts","Traded imported fertilisers","Industrial chemicals and specialty nutrients"],"operatingCosts":["Natural gas and LNG (urea)","Phosphoric acid, rock phosphate and ammonia","Imported finished fertilisers","Freight and bagging","Interest on subsidy dues"],"customersAndEndMarkets":"Farmers across India, reached through dealers, cooperatives and state marketing federations; some industrial buyers for chemicals.","demandSupplyDrivers":"Demand depends on the monsoon, cropped area and crop mix, and on the farm price after subsidy. Supply depends on global raw material availability and government import planning.","domesticInternationalExposure":"India relies heavily on imported gas, phosphates and potash, so global prices and the rupee matter, while sales are almost entirely domestic.","capexIntensity":"High","capexNote":"Urea, ammonia and phosphoric acid plants are large and energy- or acid-intensive.","workingCapital":"High and seasonal: subsidy dues from the government and stocking ahead of kharif and rabi seasons tie up cash.","regulation":"Heavily controlled by the Department of Fertilizers through urea pricing policy, the Nutrient Based Subsidy scheme and movement plans; quality is governed by the Fertiliser Control Order.","competitiveAdvantages":"Energy-efficient plants, raw material tie-ups abroad, strong dealer networks and brand recall among farmers.","drivers":[{"factor":"Government policy","impact":"Subsidy rates, urea pricing norms and import decisions directly set profits."},{"factor":"Monsoon & agriculture","impact":"Rainfall and sown area drive fertiliser offtake each season."},{"factor":"Commodity prices","impact":"Global prices of gas, ammonia, phosphates and potash move costs."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported inputs."},{"factor":"Interest rates","impact":"Delayed subsidies are funded with borrowing, so rates affect costs."}],"risks":[{"risk":"Subsidy delays","detail":"Late government payments raise debt and interest costs."},{"risk":"Subsidy rate cuts","detail":"Lower nutrient subsidies can squeeze phosphatic margins."},{"risk":"Raw material shocks","detail":"Global supply disruptions can spike input costs."},{"risk":"Poor monsoon","detail":"Weak rains reduce demand and leave stock unsold."}],"cyclicality":"Mixed","cyclicalityNote":"Farm demand is steady, but margins depend on subsidy policy and global input prices.","metricSet":"agrochem-fertilizers","relatedBasicIndustries":["b-pesticides-and-agrochemicals","b-commodity-chemicals","b-gas-transmission-marketing","b-other-agricultural-products","b-sugar"],"aliases":["fertilizers","fertilisers","urea","DAP","NPK","complex fertiliser","SSP","potash","agri inputs"],"themes":["Rural demand"]},"b-pesticides-and-agrochemicals":{"simplifiedExplanation":"Companies that make chemicals protecting crops from insects, weeds and diseases, sold as branded products to farmers or as bulk ingredients to global agrochemical companies.","productsAndServices":["Insecticides","Herbicides (weedicides)","Fungicides","Technical-grade active ingredients","Ready-to-use formulations","Plant growth regulators and bio-stimulants","Custom synthesis for global innovators"],"valueChainPosition":"Midstream-to-downstream: buys chemical intermediates (many from China) to make technical-grade molecules, which are formulated and sold through distributors and retailers to farmers, or exported.","howTheyMakeMoney":"Branded domestic sellers earn from distribution reach and farmer trust; generic exporters earn from low-cost manufacturing and product registrations in many countries; contract makers earn from producing patented molecules for innovators.","revenueSources":["Branded formulations in India","Technical-grade exports","Generic formulations sold abroad","Contract manufacturing","Registration data licensing (some)"],"operatingCosts":["Intermediates and raw materials","Registration and regulatory data costs","Distribution and farmer marketing","Effluent treatment and safety","R&D"],"customersAndEndMarkets":"Indian farmers through dealers and retailers, global agrochemical companies, and distributors in the Americas, Europe, Africa and Asia.","demandSupplyDrivers":"Pest pressure, rainfall and crop prices drive farmer demand; global channel inventory and Chinese pricing drive export demand.","domesticInternationalExposure":"Many companies are strongly export-oriented; reliance on Chinese intermediates and global pricing makes them sensitive to China and the rupee.","capexIntensity":"Medium","capexNote":"Multipurpose chemical plants and formulation units need steady investment and pollution-control spending.","workingCapital":"High and seasonal: stock is built before kharif and rabi, dealers get long credit and export receivables are large.","regulation":"Products must be registered with the Central Insecticides Board and Registration Committee under the Insecticides Act; molecule bans and export-market registrations (such as US EPA and EU rules) shape portfolios.","competitiveAdvantages":"Product registrations, distribution reach, brand trust among farmers, low-cost chemistry and long relationships with global innovators.","drivers":[{"factor":"Monsoon & agriculture","impact":"Rains, pest incidence and crop area decide domestic sales each season."},{"factor":"Exports & global demand","impact":"Global farm demand and channel inventory drive export orders."},{"factor":"Imports & dumping","impact":"Chinese technical prices set the floor for generic molecules."},{"factor":"Regulation","impact":"Registrations and bans change which products can be sold."},{"factor":"Currency (INR)","impact":"Moves export realisations and imported input costs."}],"risks":[{"risk":"Channel destocking","detail":"Excess stock with distributors can cut orders sharply."},{"risk":"Weather","detail":"Drought or floods reduce pesticide use."},{"risk":"Molecule bans","detail":"Bans in India or abroad can wipe out product lines."},{"risk":"China dependence","detail":"Supply or price shocks in Chinese intermediates hurt costs."}],"cyclicality":"Mixed","cyclicalityNote":"Crop protection is a farm necessity, but export cycles and weather cause sharp swings.","metricSet":"agrochem-fertilizers","relatedBasicIndustries":["b-fertilizers","b-specialty-chemicals","b-commodity-chemicals","b-other-agricultural-products"],"aliases":["pesticides","agrochemicals","agro chemicals","crop protection","insecticides","herbicides","fungicides","weedicides"],"themes":["Rural demand","Exports","China+1"]},"b-cement-and-cement-products":{"simplifiedExplanation":"Companies that make cement, the grey powder that binds concrete, and related products like ready-mix concrete. Plants sit near limestone mines and sell mostly within their region.","productsAndServices":["Ordinary Portland Cement (OPC)","Portland Pozzolana Cement (PPC) and slag cement","Clinker","Ready-mix concrete","White cement and wall putty","Dry-mix mortars and concrete blocks"],"valueChainPosition":"Upstream-to-midstream: mines limestone and buys coal, petcoke, gypsum, fly ash and slag, then sells through dealers to home builders and directly to developers and infrastructure contractors.","howTheyMakeMoney":"They earn the price per tonne minus the cost of fuel, power, raw materials and freight. Selling through dealers to individual home builders (trade sales) usually fetches better prices than bulk project sales.","revenueSources":["Trade sales via dealers","Non-trade sales to developers and infrastructure projects","Ready-mix concrete","Clinker sales","Surplus or waste-heat power (some)"],"operatingCosts":["Coal, petcoke and other fuel","Power","Rail and road freight","Limestone, fly ash, slag and gypsum","Packing bags","Royalty on limestone"],"customersAndEndMarkets":"Individual home builders, real estate developers, road, rail, metro and irrigation contractors, and industrial and commercial construction.","demandSupplyDrivers":"Demand follows housing, infrastructure and commercial construction and slows during the monsoon. Large capacity additions in a region can hurt prices until demand catches up.","domesticInternationalExposure":"Almost fully domestic; imported coal and petcoke prices and the rupee affect fuel costs.","capexIntensity":"High","capexNote":"Integrated plants, limestone mines, captive power and logistics require heavy investment per tonne of capacity.","workingCapital":"Low: dealer sales are largely on short credit or advance, with some fuel and clinker inventory.","regulation":"Limestone leases are auctioned under the MMDR Act, cement needs BIS certification, environmental clearance and emission norms apply, and the CCI watches pricing conduct.","competitiveAdvantages":"Limestone reserves, plants close to markets, low-cost fuel and power, brand pull with dealers and efficient logistics.","drivers":[{"factor":"Infrastructure spending","impact":"Government spending on roads, rail and housing boosts volumes."},{"factor":"Real estate cycle","impact":"Housing and commercial construction drive dealer and project demand."},{"factor":"Commodity prices","impact":"Coal, petcoke and diesel costs move cost per tonne."},{"factor":"Capacity utilisation","impact":"Regional supply additions versus demand decide pricing power."},{"factor":"Monsoon & agriculture","impact":"Rains pause construction; good harvests support rural housing."}],"risks":[{"risk":"Oversupply","detail":"Fresh capacity in a region can trigger price cuts."},{"risk":"Fuel price spikes","detail":"Costlier coal and petcoke squeeze margins."},{"risk":"Demand slowdown","detail":"Weak housing or delayed government projects reduce volumes."},{"risk":"Regulatory action","detail":"Mining, environmental or competition rulings can affect operations."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and prices follow construction activity and regional capacity cycles.","metricSet":"cement","relatedBasicIndustries":["b-other-construction-materials","b-coal","b-civil-construction","b-residential-commercial-projects","b-industrial-minerals"],"aliases":["cement","cement companies","OPC","PPC","clinker","ready mix concrete","RMC","white cement"],"themes":["Infrastructure"]},"b-other-construction-materials":{"simplifiedExplanation":"Companies that make or supply building materials other than cement, such as roofing sheets, boards, blocks, panels and glass facades.","productsAndServices":["Fibre-cement roofing sheets and boards","Autoclaved aerated concrete (AAC) blocks","Gypsum boards and plaster","Glass facades and curtain walls","Fly-ash bricks and pavers","Wall panels and prefabricated building systems","B2B supply of building materials"],"valueChainPosition":"Midstream: buys cement, fly ash, fibre, gypsum, glass and aluminium, and supplies dealers, developers, contractors and facade projects.","howTheyMakeMoney":"Product makers sell through dealers or directly to projects, earning margins from brands, reach and a lower installed cost than traditional methods. Facade and supply-platform firms earn on project contracts or trading margins.","revenueSources":["Dealer sales of sheets, boards and blocks","Facade and building-system contracts","Material supply to builders","Exports (some)"],"operatingCosts":["Cement, fly ash, fibre and gypsum","Glass and aluminium sections","Power and fuel","Freight","Dealer and marketing expenses"],"customersAndEndMarkets":"Rural and semi-urban households (roofing), real estate developers, commercial and office buildings, warehouses and infrastructure contractors.","demandSupplyDrivers":"Housing, rural incomes and commercial construction drive demand, helped by a shift from site-made bricks and plaster to factory-made products.","domesticInternationalExposure":"Mostly domestic; inputs such as fibre, gypsum and glass are partly imported or priced globally.","capexIntensity":"Medium","capexNote":"Plants are moderately capital-intensive, while project and trading businesses need little fixed capital.","workingCapital":"Moderate to high: dealer stocks and project receivables, with retention money held back on facade contracts.","regulation":"BIS standards for building products and environmental norms; asbestos-based products face health and regulatory scrutiny.","competitiveAdvantages":"Brand, dealer reach in rural markets, plants near fly-ash sources and design and execution skill for facades.","drivers":[{"factor":"Real estate cycle","impact":"Residential and commercial construction drive product demand."},{"factor":"Rural demand","impact":"Farm incomes affect demand for roofing sheets and low-cost building products."},{"factor":"Infrastructure spending","impact":"Public projects and warehouses add volume."},{"factor":"Commodity prices","impact":"Cement, fibre, glass and aluminium costs move margins."},{"factor":"Technology change","impact":"Prefabricated and lighter materials replace bricks and plaster."}],"risks":[{"risk":"Unorganised competition","detail":"Local makers compete hard on price."},{"risk":"Input cost swings","detail":"Raw material spikes are hard to pass on quickly."},{"risk":"Project delays","detail":"Facade and supply contracts suffer when developers slow down."},{"risk":"Material restrictions","detail":"Curbs on asbestos or other materials could hit product lines."}],"cyclicality":"Cyclical","cyclicalityNote":"Demand rises and falls with housing and commercial construction.","metricSet":"building-materials","relatedBasicIndustries":["b-cement-and-cement-products","b-plywood-boards-laminates","b-glass-industrial","b-ceramics","b-residential-commercial-projects"],"aliases":["building materials","construction materials","roofing sheets","fibre cement","AAC blocks","gypsum board","facade","curtain wall"],"themes":["Infrastructure","Rural demand"]},"b-ferro-and-silica-manganese":{"simplifiedExplanation":"Companies that smelt manganese ore, chrome ore or quartz with coke in electric furnaces to make ferro alloys, the additives steelmakers use to strengthen steel and remove oxygen from it.","productsAndServices":["Silico manganese","High-carbon and medium-carbon ferro manganese","Ferro chrome","Ferro silicon","Low-carbon and specialty ferro alloys","Surplus captive power (some)"],"valueChainPosition":"Midstream: buys manganese and chrome ore, coke, quartz and large amounts of electricity, and sells alloys to steel mills and foundries in India and abroad.","howTheyMakeMoney":"They earn the gap between the alloy price and the cost of ore, reductant and power per tonne. Power is the biggest cost, so units with captive power or cheap tariffs earn better spreads.","revenueSources":["Alloy sales to domestic steel mills","Exports of ferro alloys","Conversion jobs for steelmakers (some)","Sale of surplus power (some)"],"operatingCosts":["Electricity","Manganese and chrome ore","Coke and coal used as reductants","Electrode paste and quartz","Freight and handling"],"customersAndEndMarkets":"Integrated and secondary steel plants, stainless steel makers, foundries and overseas steel producers.","demandSupplyDrivers":"Demand tracks steel production, especially stainless and alloy grades. Supply depends on ore availability, power costs and output decisions in large producing countries.","domesticInternationalExposure":"Alloy and ore prices follow global markets; many producers export and import manganese ore, so overseas steel demand and the rupee matter.","capexIntensity":"Medium","capexNote":"Submerged arc furnaces cost moderately, but adding a captive power plant raises the investment sharply.","workingCapital":"Moderate: ore and coke are bought in bulk ahead of use, and export receivables add to the cash tied up.","regulation":"State electricity tariffs and open-access rules, mining leases under the MMDR Act for captive ore, pollution control norms and changes in trade duties on ores and alloys.","competitiveAdvantages":"Captive power and ore, plants near ore mines or ports, and long supply ties with steel mills.","drivers":[{"factor":"Commodity prices","impact":"Global alloy and manganese ore prices set realisations and raw material costs."},{"factor":"Power cost","impact":"Electricity tariffs and coal prices decide the cost of every tonne smelted."},{"factor":"Steel production","impact":"Domestic steel output sets the volume of alloys needed."},{"factor":"Exports & global demand","impact":"Overseas steel output drives export orders and prices."},{"factor":"Currency (INR)","impact":"Moves export realisations and the cost of imported ore."}],"risks":[{"risk":"Power tariff hikes","detail":"Costlier electricity can wipe out thin smelting margins."},{"risk":"Alloy price crash","detail":"Global oversupply can push prices below cost."},{"risk":"Ore supply disruption","detail":"Mining curbs or shipping problems can starve furnaces."},{"risk":"Trade policy changes","detail":"New duties at home or abroad can shift margins quickly."}],"cyclicality":"Cyclical","cyclicalityNote":"Fortunes swing with steel production and global alloy prices.","metricSet":"metals","relatedBasicIndustries":["b-iron-and-steel","b-industrial-minerals","b-electrodes-and-refractories","b-sponge-iron","b-coal"],"aliases":["ferro alloys","ferroalloys","silico manganese","silicomanganese","ferro manganese","ferro chrome","ferro silicon","manganese alloys"],"themes":[]},"b-pig-iron":{"simplifiedExplanation":"Companies that melt iron ore with coke in small blast furnaces to make pig iron, a high-carbon iron sold in blocks to foundries and steelmakers.","productsAndServices":["Foundry-grade pig iron","Steel-grade (basic) pig iron","Ductile iron pipes (some)","Metallurgical coke (some)","Iron castings (some)","Slag and other by-products"],"valueChainPosition":"Upstream-to-midstream: buys iron ore, coking coal or coke and limestone, and supplies foundries, castings makers and secondary steel plants.","howTheyMakeMoney":"They earn the spread between the pig iron price and the cost of ore, coke and fluxes. Several convert hot metal straight into ductile iron pipes or castings, which earns more than selling plain pig iron.","revenueSources":["Merchant pig iron sales","Ductile iron pipes and castings (some)","Coke and by-product sales","Power from waste heat (some)"],"operatingCosts":["Coking coal and coke","Iron ore","Limestone and fluxes","Power","Freight"],"customersAndEndMarkets":"Foundries making castings for autos, tractors, pumps and machinery, secondary steel plants, and water and gas pipeline projects for pipe makers.","demandSupplyDrivers":"Demand follows foundry output, which tracks autos, tractors, pumps and capital goods, while water-supply schemes drive pipe demand. Integrated steel plants selling surplus pig iron add to supply.","domesticInternationalExposure":"Sales are mostly domestic, but coking coal is largely imported and pig iron prices follow global trade, so imports and the rupee matter.","capexIntensity":"Medium","capexNote":"Mini blast furnaces and coke ovens need sizeable investment, though far less than an integrated steel plant.","workingCapital":"Moderate: raw material stocks and foundry receivables, with pipe orders from government agencies sometimes paid late.","regulation":"Pollution control norms for blast furnaces and coke ovens, BIS standards for pipes and state mining rules that govern ore supply.","competitiveAdvantages":"Secure ore and coke supply, plants close to foundry clusters, and forward integration into pipes or castings.","drivers":[{"factor":"Commodity prices","impact":"Coking coal and iron ore prices drive the cost per tonne."},{"factor":"Foundry and engineering output","impact":"Casting demand from autos, tractors and machinery sets volumes."},{"factor":"Infrastructure spending","impact":"Water and gas pipeline schemes lift demand for ductile iron pipes."},{"factor":"Imports & dumping","impact":"Cheap imported pig iron or castings can cap local prices."}],"risks":[{"risk":"Coke price spikes","detail":"A jump in coking coal costs squeezes the spread."},{"risk":"Surplus from big mills","detail":"Large steel plants selling extra pig iron can depress prices."},{"risk":"Delayed government payments","detail":"Pipe orders from public agencies can stretch receivables."},{"risk":"Emission rules","detail":"Stricter norms can force costly upgrades or shutdowns."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and spreads follow the foundry and engineering cycle.","metricSet":"metals","relatedBasicIndustries":["b-iron-and-steel","b-sponge-iron","b-castings-and-forgings","b-iron-and-steel-products","b-coal"],"aliases":["pig iron","foundry grade pig iron","hot metal","mini blast furnace","ductile iron pipes","di pipes","met coke"],"themes":[]},"b-sponge-iron":{"simplifiedExplanation":"Companies that turn iron ore into sponge iron, also called direct reduced iron (DRI), by removing oxygen with coal or gas without melting it. Sponge iron is the main feed for induction and electric arc furnaces.","productsAndServices":["Sponge iron / DRI","Iron ore pellets (some)","Billets and TMT bars (integrated players)","Power from waste heat and coal fines","Char and iron fines"],"valueChainPosition":"Midstream: buys iron ore or pellets and non-coking coal, and supplies secondary steelmakers that melt it with scrap in induction or electric furnaces.","howTheyMakeMoney":"They earn the spread between sponge iron prices and the cost of ore and coal. Many add pellet plants upstream, billets or TMT bars downstream and waste-heat power to capture more margin.","revenueSources":["Merchant sponge iron sales","Pellets, billets and TMT bars (some)","Sale of surplus power","By-product sales"],"operatingCosts":["Iron ore and pellets","Non-coking coal (often imported)","Power","Freight","Kiln refractories and maintenance"],"customersAndEndMarkets":"Induction furnace and electric arc furnace steelmakers, mostly producing long products such as bars and rods for construction.","demandSupplyDrivers":"Demand follows long-steel output and construction in India, and scrap prices decide how much DRI melters use. Margins hinge on iron ore supply from mining states and on coal prices.","domesticInternationalExposure":"Sales are mostly domestic; coal is often imported, and global scrap and steel prices influence realisations.","capexIntensity":"Medium","capexNote":"Rotary kilns are modest in cost, but pellet, power and steel melting units raise the investment.","workingCapital":"Moderate: ore and coal stocks are sizeable, buyers expect short credit and prices can change within weeks.","regulation":"Iron ore supply depends on state lease auctions under the MMDR Act; coal-based kilns face strict pollution control board norms and growing scrutiny on carbon emissions.","competitiveAdvantages":"Location near iron ore mines, captive ore or pellets, waste-heat power and integration into finished steel.","drivers":[{"factor":"Commodity prices","impact":"Iron ore and coal prices set costs, while steel scrap prices set what buyers will pay."},{"factor":"Infrastructure spending","impact":"Construction demand for TMT bars pulls sponge iron volumes."},{"factor":"Raw material availability","impact":"Mining disruptions or lease auctions can choke ore supply."},{"factor":"Regulation","impact":"Emission and carbon rules raise compliance costs for coal-based kilns."}],"risks":[{"risk":"Ore shortages","detail":"Mining stoppages in key states can idle kilns."},{"risk":"Spread squeeze","detail":"Rising ore costs with flat steel prices narrow margins."},{"risk":"Pollution action","detail":"Closure orders or tighter norms can halt production."},{"risk":"Decarbonisation","detail":"Coal-based DRI may face pressure as steelmaking moves to cleaner routes."}],"cyclicality":"Cyclical","cyclicalityNote":"Spreads swing with long-steel prices and iron ore costs.","metricSet":"metals","relatedBasicIndustries":["b-iron-and-steel","b-pig-iron","b-iron-and-steel-products","b-coal","b-industrial-minerals"],"aliases":["sponge iron","dri","direct reduced iron","hbi","iron ore pellets","pellets","rotary kiln"],"themes":[]},"b-iron-and-steel":{"simplifiedExplanation":"Companies that make steel from iron ore, coal, scrap or sponge iron and sell it as flat sheets and coils or long products such as bars, rods and rails. Steel is a core material for construction, vehicles and machinery.","productsAndServices":["Hot-rolled and cold-rolled coils","Galvanised and coated sheets","TMT bars and wire rods","Structural sections and rails","Billets, blooms and slabs","Special and alloy steels","Stainless steel (some)"],"valueChainPosition":"Upstream-to-midstream: mines or buys iron ore, coking coal and scrap, and sells to auto, appliance, construction, pipe and engineering companies directly or through distributors.","howTheyMakeMoney":"They earn the gap between steel prices and the cost of ore, coking coal, power and conversion per tonne. Captive ore, efficient furnaces and more value-added grades protect margins through the cycle.","revenueSources":["Flat products for autos, appliances and pipes","Long products for construction and infrastructure","Value-added coated and alloy steels","Exports","By-products such as slag and power"],"operatingCosts":["Coking coal (largely imported)","Iron ore and pellets","Steel scrap","Power and fuel","Ferro alloys and refractories","Freight and logistics"],"customersAndEndMarkets":"Construction and infrastructure, automobiles, consumer durables, capital goods, pipe makers, railways and defence.","demandSupplyDrivers":"Demand follows construction, infrastructure and manufacturing activity. Prices depend on domestic capacity additions versus demand, with import parity acting as a ceiling.","domesticInternationalExposure":"Sales are mainly domestic, but prices track global steel markets; coking coal imports, cheap steel imports and trade duties strongly affect margins.","capexIntensity":"High","capexNote":"Blast furnaces, rolling mills and captive mines need very large investment and long build periods.","workingCapital":"Moderate: large raw material and finished steel stocks, partly funded by supplier credit, with dealers buying on short credit.","regulation":"Iron ore and coal block auctions under the MMDR Act, BIS quality control orders on steel, safeguard and anti-dumping duties on imports, and emission and carbon rules.","competitiveAdvantages":"Scale, captive iron ore, low conversion cost, a value-added product mix and wide distribution reach.","drivers":[{"factor":"Infrastructure spending","impact":"Roads, railways, metros and housing lift long and flat steel demand."},{"factor":"Commodity prices","impact":"Coking coal and iron ore costs move margins sharply."},{"factor":"Imports & dumping","impact":"Cheap imports from surplus countries can drag domestic prices down."},{"factor":"Government policy","impact":"Safeguard duties, export duties and quality orders change price parity."},{"factor":"Capacity utilisation","impact":"High fixed costs make plant loading a key profit lever."}],"risks":[{"risk":"Import surge","detail":"Global oversupply can flood India with cheap steel."},{"risk":"Coking coal spikes","detail":"Sudden coal price jumps are hard to pass on."},{"risk":"Debt-funded expansion","detail":"Large projects add leverage just before downturns."},{"risk":"Carbon costs","detail":"Carbon border taxes abroad and decarbonisation targets at home add cost."}],"cyclicality":"Cyclical","cyclicalityNote":"Steel prices and margins rise and fall sharply with the economic and capacity cycle.","metricSet":"metals","relatedBasicIndustries":["b-iron-and-steel-products","b-sponge-iron","b-ferro-and-silica-manganese","b-trading-metals","b-civil-construction"],"aliases":["steel","steel companies","iron and steel","tmt bars","hr coil","hot rolled coil","galvanised steel","stainless steel","flat steel","long steel"],"themes":["Infrastructure"]},"b-aluminium":{"simplifiedExplanation":"Companies that refine bauxite into alumina and smelt it into aluminium, a light metal used in power lines, vehicles, packaging and buildings. Some recycle scrap or roll bought metal instead.","productsAndServices":["Primary aluminium ingots and billets","Alumina and hydrate","Wire rods for conductors","Rolled sheets, foils and extrusions","Recycled aluminium alloys","Bauxite (some)"],"valueChainPosition":"Upstream: mines bauxite, refines alumina and smelts metal using coal-based captive or grid power, and supplies cable, auto, packaging and construction-product makers.","howTheyMakeMoney":"Primary producers earn the global aluminium price plus a local premium, minus a cost per tonne dominated by power and alumina. Recyclers earn the spread between scrap and alloy prices.","revenueSources":["Primary metal sales","Value-added rods, billets and rolled products","Alumina sales","Exports","Surplus power (some)"],"operatingCosts":["Power and coal","Alumina or bauxite","Carbon anodes, pitch and coke","Caustic soda","Freight","Aluminium scrap (recyclers)"],"customersAndEndMarkets":"Power transmission and cable makers, automobiles, packaging, building and construction, consumer durables and overseas buyers.","demandSupplyDrivers":"Demand grows with power grids, lighter vehicles including EVs, packaging and construction. Global supply, especially policy-led output changes in large producing countries, sets the price.","domesticInternationalExposure":"Prices are set on the London Metal Exchange, so the global price and the rupee drive realisations; part of output is exported, and imported scrap competes in India.","capexIntensity":"High","capexNote":"Refineries, smelters and captive power plants are among the most capital-heavy assets in industry.","workingCapital":"Moderate: stocks of alumina, coal and metal plus export receivables, with selling prices linked to global benchmarks.","regulation":"Bauxite and coal leases under the MMDR Act, environmental clearances for mines and red mud disposal, import duties on scrap and primary metal, and power and emission rules.","competitiveAdvantages":"Captive bauxite, coal and power, large scale and a high share of value-added products put integrated players low on the cost curve.","drivers":[{"factor":"Commodity prices","impact":"The global aluminium price is the biggest swing factor for profits."},{"factor":"Power cost","impact":"Coal and power costs decide where a smelter sits on the global cost curve."},{"factor":"Currency (INR)","impact":"A weaker rupee raises realisations on dollar-linked prices."},{"factor":"Infrastructure spending","impact":"Transmission lines and construction lift domestic demand."},{"factor":"Technology change","impact":"Vehicle lightweighting and EVs increase aluminium use."}],"risks":[{"risk":"Price crash","detail":"A global slowdown or oversupply can cut prices sharply."},{"risk":"Coal and power shocks","detail":"Coal shortages or costlier power raise smelting costs."},{"risk":"Carbon cost","detail":"Smelting is emission-heavy, so carbon taxes could add cost."},{"risk":"Cheap imports","detail":"Imported metal and scrap can erode domestic premiums."}],"cyclicality":"Cyclical","cyclicalityNote":"Earnings track global aluminium prices, which move with world growth and supply policy.","metricSet":"metals","relatedBasicIndustries":["b-aluminium-copper-and-zinc-products","b-diversified-metals","b-industrial-minerals","b-coal","b-cables-electricals"],"aliases":["aluminium","aluminum","alumina","bauxite","aluminium smelter","primary aluminium","aluminium ingots","aluminium recycling"],"themes":["EV","Infrastructure"]},"b-copper":{"simplifiedExplanation":"Companies that mine copper ore or smelt and refine imported concentrate into pure copper cathodes and rods, the metal at the heart of wires, motors and power equipment.","productsAndServices":["Copper cathodes","Continuous cast copper rods","Copper concentrate (miners)","Sulphuric and phosphoric acid (by-products)","Gold and silver recovered from anode slime","Copper tubes and strips (some)"],"valueChainPosition":"Upstream-to-midstream: mines ore or imports concentrate, smelts and refines it, and supplies cable, wire, transformer, motor and electronics makers.","howTheyMakeMoney":"Custom smelters earn treatment and refining charges paid by miners, plus by-product income and a premium on rods, so they are less exposed to the copper price itself. Miners keep the copper price minus mining cost, so their profits swing with global prices.","revenueSources":["Treatment and refining charges","Cathode and rod sales","By-product acids","Precious metals recovered from slime","Exports"],"operatingCosts":["Copper concentrate (mostly imported)","Power and fuel","Port handling and logistics","Mining and royalty costs (miners)","Effluent and emission control"],"customersAndEndMarkets":"Cable and wire makers, power transmission and distribution equipment, motors, appliances, construction, autos and electronics.","demandSupplyDrivers":"Demand rises with electrification, power grids, renewable energy, EVs and construction. Smelter earnings depend on global concentrate supply: when mines produce less, treatment charges fall.","domesticInternationalExposure":"Highly global: concentrate is largely imported, prices follow the London Metal Exchange and the rupee, and refined copper competes with imports.","capexIntensity":"High","capexNote":"Smelters, refineries and mines need large investment and long approval periods.","workingCapital":"High: concentrate and metal in process are costly to hold and are usually financed with buyer's credit and hedged on exchanges.","regulation":"Pollution control and environmental clearances for smelters, mining leases under the MMDR Act, and import duties and trade agreements that affect refined copper imports.","competitiveAdvantages":"Efficient large smelters, secure concentrate contracts, port proximity, strong by-product recovery and captive mines.","drivers":[{"factor":"Treatment charges","impact":"Global concentrate supply sets how much smelters earn per tonne processed."},{"factor":"Electricity demand","impact":"Grid and renewable power build-out lifts copper use."},{"factor":"Technology change","impact":"EVs, data centres and electronics use more copper per unit."},{"factor":"Imports & dumping","impact":"Low-duty imports under trade agreements can pressure domestic premiums."},{"factor":"Currency (INR)","impact":"Moves the rupee value of dollar-priced metal and concentrate."}],"risks":[{"risk":"Concentrate shortage","detail":"Tight mine supply cuts treatment charges and smelter margins."},{"risk":"Environmental shutdown","detail":"Pollution concerns can lead to smelter closures."},{"risk":"Price volatility","detail":"Unhedged inventory can cause losses when copper prices fall."},{"risk":"Import competition","detail":"Duty-free refined copper can undercut local producers."}],"cyclicality":"Cyclical","cyclicalityNote":"Demand follows industrial and power investment cycles, while smelter margins follow global concentrate supply.","metricSet":"metals","relatedBasicIndustries":["b-aluminium-copper-and-zinc-products","b-cables-electricals","b-diversified-metals","b-precious-metals","b-commodity-chemicals"],"aliases":["copper","copper smelter","copper cathode","copper rods","cc rods","copper mining","tc rc","treatment charges"],"themes":["EV","Renewable energy"]},"b-zinc":{"simplifiedExplanation":"Companies that mine zinc-lead ore and smelt it into zinc, lead and silver, or recycle used batteries and residues into these metals. Zinc's biggest use is galvanising steel to stop rust.","productsAndServices":["Zinc ingots","Lead ingots and alloys","Silver (by-product)","Zinc oxide and zinc dust","Recycled lead from used batteries","Sulphuric acid (by-product)"],"valueChainPosition":"Upstream-to-midstream: mines ore or collects scrap and battery waste, smelts and refines it, and supplies galvanisers, battery makers, die-casters and chemical users.","howTheyMakeMoney":"Miners and smelters earn the global metal price minus mining and smelting cost, with silver adding meaningful income. Recyclers earn the spread between scrap or battery waste prices and refined metal prices.","revenueSources":["Zinc metal sales","Lead metal sales","Silver sales","Recycled lead and alloys","By-product acid and power"],"operatingCosts":["Mining and ore extraction","Power and coal","Scrap and used batteries (recyclers)","Royalty and statutory payments","Freight"],"customersAndEndMarkets":"Steel galvanisers, battery makers for vehicles and inverters, die-casting and brass makers, tyre and paint makers using zinc oxide, and silver buyers.","demandSupplyDrivers":"Zinc demand follows galvanised steel for towers, roofing, highways and autos, while lead follows vehicle and backup-power batteries. Global mine and smelter output decide prices.","domesticInternationalExposure":"Prices are set on the London Metal Exchange, so global prices and the rupee drive earnings; recyclers rely partly on imported scrap and also export.","capexIntensity":"High","capexNote":"Underground mines and smelters are very capital-heavy, though recycling plants need far less.","workingCapital":"Moderate: ore and metal in process for miners, while recyclers need cash to buy battery scrap ahead of sales.","regulation":"Mining leases and royalties under the MMDR Act, Battery Waste Management Rules for recyclers, pollution control norms and hazardous waste rules on scrap imports.","competitiveAdvantages":"High-grade captive mines with long reserve life, low-cost smelting and silver by-products; for recyclers, licences and collection networks.","drivers":[{"factor":"Commodity prices","impact":"Zinc, lead and silver prices move profits directly."},{"factor":"Infrastructure spending","impact":"Galvanised steel for towers, roofs and highways lifts zinc demand."},{"factor":"Regulation","impact":"Battery recycling rules push volumes towards formal recyclers."},{"factor":"Currency (INR)","impact":"A weaker rupee raises realisations on dollar-linked metal prices."},{"factor":"Exports & global demand","impact":"World industrial activity sets global zinc and lead prices."}],"risks":[{"risk":"Metal price falls","detail":"Lower global prices hit miners and recyclers alike."},{"risk":"Ore grade decline","detail":"Lower grades over time raise mining cost per tonne."},{"risk":"Hazardous handling","detail":"Lead emissions and waste bring strict scrutiny and penalties."},{"risk":"Royalty changes","detail":"Higher levies on mined metal reduce margins."}],"cyclicality":"Cyclical","cyclicalityNote":"Earnings follow global zinc, lead and silver prices and construction activity.","metricSet":"metals","relatedBasicIndustries":["b-diversified-metals","b-aluminium-copper-and-zinc-products","b-iron-and-steel-products","b-precious-metals","b-auto-components-and-equipments"],"aliases":["zinc","lead","zinc smelter","lead recycling","battery recycling","galvanizing","zinc oxide","silver"],"themes":[]},"b-precious-metals":{"simplifiedExplanation":"Companies that refine, process or trade gold, silver and platinum-group metals, turning imported dore, bullion or old jewellery into standard bars, coins and industrial forms.","productsAndServices":["Refined gold and silver bars","Coins and medallions","Gold and silver grains","Recycled gold from old jewellery","Silver for industrial use","Bullion trading"],"valueChainPosition":"Midstream: imports dore or bullion or collects scrap, refines it, and sells to jewellers, banks, investors and industrial users.","howTheyMakeMoney":"They earn small refining and processing margins per gram plus trading spreads. The metal price itself is usually passed on or hedged, so volumes and hedging discipline decide profits.","revenueSources":["Refining charges","Bullion and bar sales","Coin sales","Scrap gold recycling","Industrial silver sales"],"operatingCosts":["Gold and silver purchases (largely passed on)","Hedging and financing costs","Refining chemicals and power","Security, insurance and vaulting","Assaying and logistics"],"customersAndEndMarkets":"Jewellery makers and retailers, banks and bullion dealers, retail investors, and electronics, solar and other industrial silver users.","demandSupplyDrivers":"Demand follows jewellery buying around weddings and festivals, investment flows into gold and silver, and industrial silver use. Supply comes from imports and from old gold recycled when prices are high.","domesticInternationalExposure":"India imports almost all its gold and silver, so global prices, the rupee and import duties shape volumes and margins.","capexIntensity":"Low","capexNote":"Refineries and assaying units need modest capital; most money is tied up in metal inventory.","workingCapital":"Very high: metal inventory is costly, is financed through metal loans or bank lines, and must be hedged against price moves.","regulation":"RBI and DGFT rules on bullion imports, customs duty on gold and silver, BIS hallmarking and refinery standards, GST, and anti-money-laundering checks on bullion dealing.","competitiveAdvantages":"Accreditation and trust with banks and jewellers, certified refining, sourcing access and efficient hedging.","drivers":[{"factor":"Commodity prices","impact":"High gold prices lift scrap recycling but can slow jewellery buying."},{"factor":"Government policy","impact":"Import duty changes shift volumes between official and grey channels."},{"factor":"Consumer demand","impact":"Weddings and festivals drive jewellery and coin demand."},{"factor":"Currency (INR)","impact":"A weaker rupee raises local gold and silver prices."},{"factor":"Interest rates","impact":"Rates affect investment demand for gold and the cost of funding inventory."}],"risks":[{"risk":"Hedging losses","detail":"Unhedged or badly hedged positions can cause large losses."},{"risk":"Duty changes","detail":"Sudden import duty moves can disrupt volumes and inventory values."},{"risk":"Smuggling","detail":"Grey-market gold undercuts legitimate refiners when duties are high."},{"risk":"Thin margins","detail":"Small per-gram margins leave little room for error."}],"cyclicality":"Mixed","cyclicalityNote":"Gold demand often rises in uncertain times, but volumes swing with prices and duties.","metricSet":"metals","relatedBasicIndustries":["b-gems-jewellery-and-watches","b-copper","b-zinc","b-trading-metals"],"aliases":["gold","silver","bullion","gold refinery","precious metals","platinum","gold bars","silver bars"],"themes":[]},"b-diversified-metals":{"simplifiedExplanation":"Companies that produce, refine or recycle several metals at once, such as zinc, lead, silver, aluminium, copper or iron ore, instead of depending on a single metal.","productsAndServices":["Zinc, lead and silver","Aluminium and alumina","Copper","Iron ore","Metals recovered from scrap and residues","Power and oil (some groups)"],"valueChainPosition":"Upstream-to-midstream: owns mines, smelters or recycling plants across metals and sells to steel, cable, battery, auto and construction-product makers worldwide.","howTheyMakeMoney":"Each business earns its metal price minus its own cost, so group profit is the sum of several metal cycles. Holding structures also collect dividends from listed subsidiaries, while recyclers earn the spread between scrap and refined metal.","revenueSources":["Sales of several base metals","Precious metal by-products","Iron ore and other minerals","Recycled metal sales","Dividends from subsidiaries (holding structures)"],"operatingCosts":["Power and coal","Mining and royalty costs","Purchased ore, concentrate or scrap","Logistics","Interest on group debt"],"customersAndEndMarkets":"Steel mills, galvanisers, cable and conductor makers, battery makers, auto and packaging industries, and global commodity buyers.","demandSupplyDrivers":"Demand follows global industrial activity, construction and electrification. Each metal has its own supply cycle, so the mix of prices at any time decides group profit.","domesticInternationalExposure":"Prices are set on global exchanges and many products are exported, so world prices and the rupee matter for every segment.","capexIntensity":"High","capexNote":"Mines, smelters and power plants across several metals need continuous heavy investment.","workingCapital":"Moderate: metal and ore inventories plus export receivables, with cash often moving between group companies.","regulation":"Mining leases and royalties under the MMDR Act, environmental clearances, SEBI rules on related-party transactions, and trade duties on metals and scrap.","competitiveAdvantages":"Low-cost captive mines across several metals, scale, integration with power and the cushion a spread of metals provides.","drivers":[{"factor":"Commodity prices","impact":"Moves across several metal prices together drive group earnings."},{"factor":"Exports & global demand","impact":"Global growth sets demand for most of the metals in the mix."},{"factor":"Currency (INR)","impact":"Dollar-linked prices make the rupee a direct profit lever."},{"factor":"Interest rates","impact":"Large group borrowings make funding costs matter."},{"factor":"Technology change","impact":"Electrification and batteries favour certain metals in the portfolio."}],"risks":[{"risk":"Group debt","detail":"High holding-company debt can drain cash from operating units."},{"risk":"Governance","detail":"Related-party dealings and dividend policies need close watching."},{"risk":"Regulatory disputes","detail":"Mining, tax or environmental cases can stall operations."},{"risk":"Synchronised downturn","detail":"A global slowdown can hit all metals at once."}],"cyclicality":"Cyclical","cyclicalityNote":"Diversification softens swings, but most metals still fall together in a global slowdown.","metricSet":"metals","relatedBasicIndustries":["b-zinc","b-aluminium","b-copper","b-industrial-minerals","b-precious-metals"],"aliases":["diversified metals","base metals","metals and mining","non-ferrous metals","metal recycling","mining conglomerate","natural resources"],"themes":[]},"b-industrial-minerals":{"simplifiedExplanation":"Companies that mine or process minerals such as iron ore, manganese ore, bentonite, kaolin, barytes or calcium carbonate, selling them raw or upgraded into fine powders for industry.","productsAndServices":["Iron ore lumps and fines","Manganese ore","Bentonite and barytes","Kaolin and china clay","Ground and precipitated calcium carbonate","Quartz, silica and feldspar","Beneficiation and mineral processing services"],"valueChainPosition":"Upstream: extracts minerals from leased mines or buys them from miners, then crushes, washes, grinds or beneficiates them for steel, foundry, paint, plastics, paper, ceramics and drilling customers.","howTheyMakeMoney":"Ore miners earn the realised price per tonne minus mining cost, royalty and auction premiums paid to the state. Mineral processors earn more per tonne by grinding, coating or purifying minerals to tight customer specifications.","revenueSources":["Ore sales to steel and alloy plants","Processed mineral powders","Exports of ore or processed minerals","Mining contract services (some)"],"operatingCosts":["Mining and excavation","Royalty, district mineral fund and auction premiums","Diesel and power","Freight to customers or ports","Grinding and processing"],"customersAndEndMarkets":"Steel, sponge iron and ferro alloy plants, foundries, paint, plastics, paper and ceramic makers, oil drilling firms and overseas buyers.","demandSupplyDrivers":"Iron and manganese ore demand follows steel output, while processed minerals follow paints, plastics, paper, ceramics and drilling. Supply is controlled by lease auctions, production caps and clearances.","domesticInternationalExposure":"Ore prices take cues from global markets and export duties; processed minerals face import competition but also find overseas buyers.","capexIntensity":"Medium","capexNote":"Opencast mining equipment and processing plants need moderate capital, and winning leases at auction adds upfront cost.","workingCapital":"Moderate: stockpiles at mines and ports, mining pauses in the monsoon and credit to industrial buyers.","regulation":"State governments auction leases under the MMDR Act and collect royalty and district mineral fund payments; environmental and forest clearances and court-ordered output limits also apply.","competitiveAdvantages":"Long-life leases with good-grade reserves, proximity to customers or ports, and processing know-how for specialty grades.","drivers":[{"factor":"Government policy","impact":"Lease auctions, royalty rates and export duties shape costs and access."},{"factor":"Commodity prices","impact":"Global iron ore prices set domestic ore realisations."},{"factor":"Infrastructure spending","impact":"Construction-led steel demand lifts iron and manganese ore offtake."},{"factor":"Monsoon & agriculture","impact":"Heavy rains slow mining and dispatches."},{"factor":"Exports & global demand","impact":"Overseas demand absorbs ore and processed minerals."}],"risks":[{"risk":"Lease expiry","detail":"Losing a lease at renewal or auction can end production."},{"risk":"Mining bans","detail":"Court or environmental orders can halt mining suddenly."},{"risk":"Price swings","detail":"Global ore price falls cut realisations quickly."},{"risk":"Logistics bottlenecks","detail":"Rail and port constraints can strand output."}],"cyclicality":"Cyclical","cyclicalityNote":"Ore volumes and prices follow the steel cycle, while specialty minerals are steadier.","metricSet":"mining","relatedBasicIndustries":["b-iron-and-steel","b-sponge-iron","b-ferro-and-silica-manganese","b-trading-minerals","b-ceramics"],"aliases":["mining","iron ore","manganese ore","minerals","bentonite","kaolin","china clay","calcium carbonate","barytes","mineral processing"],"themes":[]},"b-trading-metals":{"simplifiedExplanation":"These are traders and stockists rather than producers: they buy steel, non-ferrous metals or scrap from mills and overseas suppliers and resell them in smaller lots to fabricators, manufacturers and builders.","productsAndServices":["Steel sheets, coils, bars and pipes","Aluminium, copper and brass stock","Ferrous and non-ferrous scrap","Stainless steel","Cutting, slitting and processing services","Import sourcing"],"valueChainPosition":"Downstream: sits between steel mills, smelters or overseas suppliers and fragmented buyers such as fabricators, small manufacturers, contractors and recyclers.","howTheyMakeMoney":"They earn a margin per tonne plus service income from cutting to size, credit and delivery. Margins are thin, so turning inventory quickly and buying at the right time matter more than price levels.","revenueSources":["Resale of steel and metal products","Scrap trading","Processing and service charges","Import indent commissions (some)"],"operatingCosts":["Purchase cost of metal","Freight and warehousing","Interest on inventory and receivables","Processing labour and power","Customs duty on imports"],"customersAndEndMarkets":"Small and mid-sized manufacturers, fabricators, construction contractors, auto and engineering ancillaries, and scrap-consuming mills.","demandSupplyDrivers":"Volumes follow construction and small-industry activity and the needs of buyers too small to deal directly with mills. Mill pricing policies and import availability shape margins.","domesticInternationalExposure":"Mostly domestic, though many import metals or scrap, so global prices, freight and the rupee affect landed cost.","capexIntensity":"Low","capexNote":"Warehouses and service-centre equipment need little fixed capital.","workingCapital":"High: inventory and customer credit are the core of the business and are funded with bank lines.","regulation":"Light, general business regulation, plus GST compliance, customs and import duties, and quality control orders on imported steel.","competitiveAdvantages":"Distributorships or supply tie-ups with mills, credit judgement, well-located warehouses and a wide range of grades in stock.","drivers":[{"factor":"Commodity prices","impact":"Falling metal prices cause inventory losses, while rising prices create gains."},{"factor":"Infrastructure spending","impact":"Construction and fabrication activity sets trading volumes."},{"factor":"Credit growth","impact":"Bank funding for stock and customer credit limits how much they can trade."},{"factor":"Imports & dumping","impact":"Import duties and quality rules change sourcing options and margins."}],"risks":[{"risk":"Inventory losses","detail":"Sharp price drops hit traders holding large stocks."},{"risk":"Bad debts","detail":"Small buyers may delay or default on payments."},{"risk":"Tax scrutiny","detail":"Scrap and metal trading draws close checks on GST input credits."},{"risk":"Disintermediation","detail":"Mills selling directly to buyers can squeeze traders."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and margins swing with metal prices and construction activity.","metricSet":"trading-distribution","relatedBasicIndustries":["b-iron-and-steel","b-iron-and-steel-products","b-aluminium-copper-and-zinc-products","b-trading-minerals","b-trading-and-distributors"],"aliases":["metal trading","steel trading","steel trader","steel stockist","scrap trading","metal scrap","non-ferrous trading","steel service centre"],"themes":[]},"b-trading-minerals":{"simplifiedExplanation":"These companies trade minerals rather than mine them: they buy ores, industrial minerals or imported raw materials and supply them to plants, often arranging transport and blending.","productsAndServices":["Iron ore and manganese ore","Bauxite and other ores","Gypsum, limestone, quartz and other industrial minerals","Imported minerals for fertiliser and chemical plants","Sourcing, blending and logistics services"],"valueChainPosition":"Midstream: connects miners at home and abroad with steel, cement, ceramic, alloy and chemical plants, handling shipping, port and rail logistics.","howTheyMakeMoney":"They earn a margin between purchase cost and delivered sale price, plus fees for sourcing, blending and logistics. Some run mining contracts and sell output on behalf of lease holders.","revenueSources":["Mineral resale margins","Sourcing and logistics fees","Import trading","Export sales (some)"],"operatingCosts":["Mineral purchase cost","Ocean freight and port charges","Rail and road transport","Financing costs","Customs duties"],"customersAndEndMarkets":"Steel, sponge iron and ferro alloy plants, cement, ceramic, glass and fertiliser makers, and overseas buyers.","demandSupplyDrivers":"Demand follows output at steel, cement and ceramic plants; gaps left by domestic mining restrictions create room for imports and trading.","domesticInternationalExposure":"Highly exposed to global mineral prices, freight rates and the rupee, since many minerals are imported or exported.","capexIntensity":"Low","capexNote":"The business is asset-light, though some players own stockyards or handling equipment.","workingCapital":"High: cargoes and stockpiles are paid for before resale, with heavy use of letters of credit and buyer's credit.","regulation":"Mineral transit permits and state mining rules, export and import duties, and customs and foreign trade policy administered by DGFT.","competitiveAdvantages":"Long relationships with mines and buyers, logistics capability and access to trade finance.","drivers":[{"factor":"Commodity prices","impact":"Mineral price moves change margins on cargoes in transit."},{"factor":"Government policy","impact":"Mining bans, export duties and import rules decide trade flows."},{"factor":"Raw material availability","impact":"Domestic mining disruptions raise reliance on traders and imports."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the landed cost of imported minerals."}],"risks":[{"risk":"Price and freight swings","detail":"Sudden moves can turn a cargo loss-making."},{"risk":"Counterparty default","detail":"Buyers or suppliers failing to honour contracts cause losses."},{"risk":"Policy changes","detail":"New duties or mining curbs can stop a trade route."},{"risk":"Customer concentration","detail":"Dependence on a few buyers can hit volumes."}],"cyclicality":"Cyclical","cyclicalityNote":"Trade volumes rise and fall with the steel and construction cycle and mineral prices.","metricSet":"trading-distribution","relatedBasicIndustries":["b-industrial-minerals","b-trading-metals","b-trading-coal","b-shipping","b-iron-and-steel"],"aliases":["mineral trading","ore trading","iron ore trading","minerals trader","mineral imports","ore exports"],"themes":[]},"b-paper-and-paper-products":{"simplifiedExplanation":"Companies that turn wood, bamboo, farm residue or waste paper into pulp and then into writing paper, packaging board, newsprint and specialty papers.","productsAndServices":["Writing and printing paper","Copier paper","Virgin and recycled packaging board","Kraft paper for corrugated boxes","Newsprint","Tissue and specialty papers","Paper cups and plates (some)"],"valueChainPosition":"Midstream: buys wood from farm forestry, agro residue or recovered paper, and supplies printers, publishers, carton and box makers, and FMCG, pharma and e-commerce packagers.","howTheyMakeMoney":"They earn the price per tonne of paper or board minus fibre, chemicals, energy and freight. Integrated mills with their own pulp and power and a premium grade mix earn steadier margins than waste-paper-based kraft mills.","revenueSources":["Writing and printing paper","Packaging board and kraft paper","Specialty and tissue papers","Exports","Surplus power (some)"],"operatingCosts":["Wood, bamboo and agro residue","Imported and domestic waste paper","Coal and power","Chemicals such as caustic soda","Freight","Water and effluent treatment"],"customersAndEndMarkets":"Notebook and textbook makers, offices and printers, publishers, FMCG and pharma packaging, corrugated box makers and e-commerce.","demandSupplyDrivers":"Packaging board grows with consumption, e-commerce and the move away from plastics, while writing paper depends on education and office use. New mill capacity and imports decide price discipline.","domesticInternationalExposure":"Mainly domestic, but imported pulp and waste paper and cheap paper or board imports from Asian producers affect costs and prices.","capexIntensity":"High","capexNote":"Pulp mills, paper machines and chemical recovery and power plants need large investment.","workingCapital":"Moderate: wood and waste-paper stocks, seasonal notebook demand before the school year, and dealer credit.","regulation":"Pollution control board effluent norms, forest and plantation rules for wood, plastic-ban rules that favour paper, and import duties.","competitiveAdvantages":"Integrated pulp and captive power, plantation-backed wood supply, value-added board grades and strong dealer networks.","drivers":[{"factor":"Consumer demand","impact":"FMCG and e-commerce growth lifts packaging board demand."},{"factor":"Raw material availability","impact":"Wood and waste paper supply sets fibre costs."},{"factor":"Imports & dumping","impact":"Cheap imported paper and board can cap domestic prices."},{"factor":"Regulation","impact":"Single-use plastic bans shift packaging towards paper."},{"factor":"Commodity prices","impact":"Coal, pulp and chemical prices move cost per tonne."}],"risks":[{"risk":"Cheap imports","detail":"Imports from low-cost producers can force price cuts."},{"risk":"Fibre shortages","detail":"Scarce wood or waste paper raises costs sharply."},{"risk":"Capacity glut","detail":"New board capacity can flood the market."},{"risk":"Effluent compliance","detail":"Water use and discharge norms can force upgrades or closures."}],"cyclicality":"Mixed","cyclicalityNote":"Packaging demand is steady, but paper prices swing with capacity additions and imports.","metricSet":"paper-forest","relatedBasicIndustries":["b-packaging","b-forest-products","b-stationary","b-printing-and-publication","b-commodity-chemicals"],"aliases":["paper","paper mills","paperboard","kraft paper","writing paper","packaging board","duplex board","newsprint","tissue paper","pulp"],"themes":[]},"b-forest-products":{"simplifiedExplanation":"Companies that grow, harvest, process or trade timber and other forest and plantation produce, such as logs, sawn wood and veneers.","productsAndServices":["Logs and sawn timber","Veneers","Plantation wood such as eucalyptus and teak","Wood pallets and packaging","Treated and seasoned timber","Minor forest produce (some)"],"valueChainPosition":"Upstream: sources logs from plantations, farm forestry or imports, and supplies sawmills, plywood and furniture makers, builders and paper mills.","howTheyMakeMoney":"They earn the margin between log costs and the price of processed timber, plus income from plantations or timber trading. The usable yield from each log and how fast stock turns decide profit.","revenueSources":["Timber and log sales","Processed wood and veneers","Plantation produce","Wood packaging"],"operatingCosts":["Log and timber purchases","Import freight and duties","Sawmill labour and power","Seasoning and treatment","Warehousing and transport"],"customersAndEndMarkets":"Plywood and furniture makers, builders and carpenters, packaging and pallet users, and paper mills.","demandSupplyDrivers":"Demand follows housing, furniture and packaging activity. Supply depends on plantation harvests, felling rules and timber imports from producing countries.","domesticInternationalExposure":"India relies on imported logs and sawn timber, so log export bans abroad, ocean freight and the rupee affect costs.","capexIntensity":"Low","capexNote":"Sawmills and depots need little capital, though plantations tie up land and take years to mature.","workingCapital":"High: timber is held for months to season and is sold on credit to traders and carpenters.","regulation":"Felling and transit permits under state forest rules, the Forest Conservation Act, and plant quarantine rules for imported logs.","competitiveAdvantages":"Secure log sourcing, plantation tie-ups, depots near furniture and plywood hubs, and good processing yields.","drivers":[{"factor":"Real estate cycle","impact":"New homes and offices drive demand for doors, frames and furniture wood."},{"factor":"Raw material availability","impact":"Felling permits and overseas log policies decide supply."},{"factor":"Consumer demand","impact":"Furniture and interiors spending lifts timber use."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported logs."}],"risks":[{"risk":"Export bans abroad","detail":"Supplier countries restricting log exports can cut supply."},{"risk":"Inventory losses","detail":"Price falls hurt traders holding seasoned stock."},{"risk":"Permit problems","detail":"Delays in felling or transit permits stall business."},{"risk":"Substitutes","detail":"Engineered panels, steel and plastics can replace solid timber."}],"cyclicality":"Cyclical","cyclicalityNote":"Timber demand moves with construction and furniture spending.","metricSet":"paper-forest","relatedBasicIndustries":["b-plywood-boards-laminates","b-paper-and-paper-products","b-furniture-home-furnishing","b-packaging"],"aliases":["timber","wood","forest products","logs","sawn timber","teak","plantation","veneer"],"themes":[]},"b-jute-and-jute-products":{"simplifiedExplanation":"Companies that spin raw jute fibre into yarn and weave it into sacks, hessian cloth and other goods. Much of the output is bought by government agencies to pack food grains.","productsAndServices":["B-twill sacks for food grains","Hessian cloth and bags","Jute yarn and twine","Jute geotextiles","Shopping bags and lifestyle products","Carpet backing cloth"],"valueChainPosition":"Midstream: buys raw jute from farmers and traders, mostly in eastern India, and supplies government procurement agencies, sugar packers, carpet makers and exporters.","howTheyMakeMoney":"They earn the gap between the price of jute goods and the cost of raw jute and wages. Government sack orders follow a cost-based pricing formula, while private and export sales depend on market prices and product mix.","revenueSources":["Food-grain sack orders from government agencies","Hessian and yarn sales","Exports of diversified jute goods","Geotextiles and specialty products"],"operatingCosts":["Raw jute","Wages in labour-intensive mills","Power","Batching oil and stores","Freight"],"customersAndEndMarkets":"State food procurement agencies and the Food Corporation of India, sugar mills, carpet makers, and overseas buyers of eco-friendly bags.","demandSupplyDrivers":"Demand rests largely on government food-grain procurement under the jute packaging mandate. Costs depend on the raw jute crop, which swings with rains and floods in eastern India.","domesticInternationalExposure":"Mostly domestic; exports of yarn and diversified goods compete with neighbouring producers, and some imports attract anti-dumping duties.","capexIntensity":"Low","capexNote":"Old mills run with limited investment; modernising looms and spindles is the main spend.","workingCapital":"High and seasonal: raw jute is bought after harvest and held for months, and government payments can lag.","regulation":"The Jute Packaging Materials Act mandates jute packing for food grains and part of sugar, the Jute Commissioner allots sack orders and prices, and MSP applies to raw jute.","competitiveAdvantages":"Steady government orders, modernised efficient mills, stable labour relations and diversified product lines.","drivers":[{"factor":"Government policy","impact":"Packaging mandates and sack orders set most of the demand."},{"factor":"Monsoon & agriculture","impact":"Raw jute crop size and food-grain procurement drive costs and volumes."},{"factor":"Exports & global demand","impact":"Demand for eco-friendly bags opens export markets."},{"factor":"Imports & dumping","impact":"Cheap imported jute goods pressure yarn and hessian prices."}],"risks":[{"risk":"Mandate dilution","detail":"Lower jute reservation would shift orders to plastic bags."},{"risk":"Raw jute price spikes","detail":"A poor crop can raise fibre costs faster than selling prices."},{"risk":"Labour unrest","detail":"Labour-intensive mills face strikes and suspensions of work."},{"risk":"Payment delays","detail":"Late dues from procurement agencies strain cash."}],"cyclicality":"Mixed","cyclicalityNote":"Government orders give a steady base, but raw jute prices make margins volatile.","metricSet":"textiles","relatedBasicIndustries":["b-other-textile-products","b-packaging","b-paper-and-paper-products","b-sugar","b-trading-textile-products"],"aliases":["jute","jute mills","gunny bags","gunny","hessian","jute sacks","b twill","jute yarn"],"themes":[]},"b-passenger-cars-and-utility-vehicles":{"simplifiedExplanation":"These companies make cars, SUVs and vans for families and individuals, and sell them through dealer showrooms in India and abroad.","productsAndServices":["Hatchbacks and sedans","SUVs and utility vehicles","MPVs and vans","Electric, hybrid and CNG models","Genuine spare parts and accessories","Vehicle exports"],"valueChainPosition":"Midstream assembler: buys steel, components, electronics and batteries from suppliers and sells finished vehicles to franchised dealers who retail them.","howTheyMakeMoney":"They earn the difference between the price of each vehicle sold to dealers and the cost of parts, labour and overheads. Bigger, feature-rich models carry higher margins, while spare parts, accessories and exports add steady income.","revenueSources":["Domestic vehicle sales to dealers","Exports","Spare parts and accessories","Extended warranty and other income"],"operatingCosts":["Bought-out components","Steel, aluminium and precious metals","Battery cells for EVs","Employee and plant costs","Advertising and dealer incentives","Royalty or technology fees (for some)"],"customersAndEndMarkets":"Individual buyers, families, taxi and fleet operators and government users, reached through dealers; exports go mainly to emerging markets.","demandSupplyDrivers":"Demand follows incomes, fuel prices, loan rates and new launches, with festive months usually strongest. Supply depends on chip and component availability and plant capacity.","domesticInternationalExposure":"Mainly domestic, with exports to emerging markets adding volume. Imported electronics and battery cells mean a weaker rupee can raise costs.","capexIntensity":"High","capexNote":"Plants, tooling, new platforms, EV development and testing need heavy, ongoing investment.","workingCapital":"Often light or negative, since dealers usually pay at dispatch while suppliers are paid on credit. Inventory builds up if retail sales slow.","regulation":"Bharat Stage emission norms, fuel-efficiency (CAFE) rules, safety mandates and Bharat NCAP ratings shape product costs; GST rates vary by vehicle size and fuel, and PLI and EV schemes add incentives.","competitiveAdvantages":"Wide dealer and service networks, brand trust, sourcing scale and a broad, regularly refreshed model line-up are hard for newcomers to match.","drivers":[{"factor":"Consumer demand","impact":"Rising incomes and aspiration lift demand, especially for SUVs and premium variants."},{"factor":"Interest rates","impact":"Most cars are bought on loans, so cheaper EMIs support volumes."},{"factor":"Commodity prices","impact":"Steel, aluminium and precious-metal costs squeeze margins until price hikes catch up."},{"factor":"Regulation","impact":"New emission and safety rules add cost per vehicle and can trigger pre-buying before deadlines."},{"factor":"Technology change","impact":"The move to EVs, hybrids and connected features changes investment needs and competitive positions."},{"factor":"Crude oil prices","impact":"High fuel prices can dampen demand and push buyers toward CNG or electric options."}],"risks":[{"risk":"Demand slowdown","detail":"Weak sentiment or costly loans can leave dealers with excess stock and force discounts."},{"risk":"EV transition","detail":"Late EV moves can cost market position, while early bets may take long to pay off."},{"risk":"Supply disruption","detail":"Shortages of chips or key parts can halt production lines."},{"risk":"Tax changes","detail":"Changes to GST on vehicles can shift demand between segments."}],"cyclicality":"Cyclical","cyclicalityNote":"Car purchases can be postponed, so volumes swing with the economy and credit conditions.","metricSet":"auto-oem","relatedBasicIndustries":["b-auto-components-and-equipments","b-tyres-and-rubber-products","b-auto-dealer","b-commercial-vehicles","b-iron-and-steel"],"aliases":["passenger vehicles","PV","cars","car makers","SUV","utility vehicles","four wheelers","automobile","electric cars","auto OEM"],"themes":["EV","Exports"]},"b-2-3-wheelers":{"simplifiedExplanation":"These companies make motorcycles, scooters, mopeds and three-wheelers such as auto-rickshaws and e-rickshaws, the most common personal and last-mile vehicles in India.","productsAndServices":["Commuter and premium motorcycles","Scooters and mopeds","Electric two-wheelers","Passenger and cargo three-wheelers","E-rickshaws","Spare parts, accessories and merchandise"],"valueChainPosition":"Midstream assembler that buys engine parts, frames, tyres, batteries and electronics from suppliers and sells through dealers spread across towns and villages.","howTheyMakeMoney":"They earn a margin on each vehicle sold, helped by premium models, spare parts and exports. Very high volumes spread plant and R&D costs thinly.","revenueSources":["Domestic vehicle sales","Exports","Spare parts and accessories","Merchandise and other income"],"operatingCosts":["Components and raw materials","Steel, aluminium and rubber","Battery cells for EVs","Employee costs","Marketing and dealer support","R&D"],"customersAndEndMarkets":"Commuters, students, rural households, delivery riders and three-wheeler operators; exports go mainly to Africa, Latin America and Asia.","demandSupplyDrivers":"Rural incomes, harvests, weddings and loan availability drive commuter demand, while premium bikes and electric scooters follow urban aspiration and running-cost savings.","domesticInternationalExposure":"The domestic market dominates, but exports matter for several makers, so currencies and import curbs in buyer countries affect results.","capexIntensity":"Medium","capexNote":"Assembly plants are moderately capital-intensive, but EV platforms, battery packs and R&D raise spending.","workingCapital":"Usually light because dealers pay upfront; export receivables and EV battery stocks can stretch it.","regulation":"Bharat Stage emission and on-board diagnostics norms, safety rules, central EV incentive schemes and PLI for advanced automotive technology; state permits limit three-wheeler numbers in many cities.","competitiveAdvantages":"Deep rural dealer reach, trusted brands, low-cost manufacturing and strong resale value protect incumbents, while EV start-ups compete on technology and design.","drivers":[{"factor":"Rural demand","impact":"Good harvests and farm incomes lift commuter motorcycle sales."},{"factor":"Credit growth","impact":"Easy two-wheeler loans from NBFCs and banks widen the buyer base."},{"factor":"Crude oil prices","impact":"Higher petrol prices raise running costs and can speed the switch to electric scooters."},{"factor":"Government policy","impact":"EV subsidies and PLI support electric models, and cuts to them can dent demand."},{"factor":"Exports & global demand","impact":"Currency and economic swings in African and Latin American markets move export volumes."}],"risks":[{"risk":"EV disruption","detail":"New electric players and fast battery progress can erode the position of petrol models."},{"risk":"Rural slowdown","detail":"A weak monsoon or farm stress can hurt entry-level demand."},{"risk":"Export market shocks","detail":"Currency crises or import curbs abroad can cut export orders suddenly."},{"risk":"Battery safety and cost","detail":"EV fires or battery cost spikes can hurt trust and margins."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes follow rural incomes, credit and fuel costs, though a two-wheeler is basic mobility for many families.","metricSet":"auto-oem","relatedBasicIndustries":["b-auto-components-and-equipments","b-tyres-and-rubber-products","b-passenger-cars-and-utility-vehicles","b-non-banking-financial-company-nbfc","b-auto-dealer"],"aliases":["two wheelers","2W","2 wheeler","motorcycles","bikes","scooters","electric scooter","three wheelers","3W","auto rickshaw","e-rickshaw"],"themes":["EV","Rural demand","Exports"]},"b-auto-dealer":{"simplifiedExplanation":"Auto dealers run showrooms and workshops that sell new vehicles made by manufacturers, service them and sell spare parts, used cars and add-ons.","productsAndServices":["New car and two-wheeler sales","Service and repair workshops","Spare parts and accessories","Pre-owned vehicles","Vehicle loan and insurance tie-ups","Extended warranties"],"valueChainPosition":"Downstream retailer between vehicle makers and buyers: buys vehicles from the manufacturer, sells them to customers and earns commissions from lenders and insurers.","howTheyMakeMoney":"New-vehicle sales give thin trade margins plus manufacturer incentives. Service, spares, accessories and finance or insurance commissions earn much higher margins and are steadier.","revenueSources":["New vehicle sales","After-sales service and spares","Accessories and extended warranties","Finance and insurance commissions","Pre-owned vehicle sales"],"operatingCosts":["Vehicle purchase cost","Showroom and workshop rent","Sales staff and technicians","Interest on inventory funding","Local marketing"],"customersAndEndMarkets":"Individual and corporate vehicle buyers in the dealer's territory, and existing owners who return for service and repairs.","demandSupplyDrivers":"New-vehicle sales follow the auto cycle and the manufacturer's model line-up; service income grows with the number of vehicles the dealer has sold in its region.","domesticInternationalExposure":"Purely domestic with no direct export exposure; luxury-brand dealers feel import duty and currency changes through vehicle prices.","capexIntensity":"Medium","capexNote":"Showrooms and workshops need fit-outs and equipment to the brand's standards, often on leased premises.","workingCapital":"Vehicle inventory is the largest item, funded by bank inventory lines; slow sales or stock pushed by the manufacturer tie up cash and raise interest costs.","regulation":"Light, general business regulation plus dealer agreements with manufacturers; insurance selling follows IRDAI rules and vehicle registration runs through state transport departments.","competitiveAdvantages":"Exclusive rights to a brand in a territory, prime locations and a large base of serviced vehicles give a steady after-sales stream.","drivers":[{"factor":"Consumer demand","impact":"Showroom footfall and retail sales track buyer sentiment and new launches."},{"factor":"Interest rates","impact":"Customer loan rates and the dealer's own inventory funding cost both affect profits."},{"factor":"Credit growth","impact":"Easy retail finance helps convert enquiries and earns dealers commissions."},{"factor":"Manufacturer strategy","impact":"Model launches, incentive schemes and stock pushed by the brand drive dealer margins."}],"risks":[{"risk":"Brand dependence","detail":"Results hinge on one or a few brands, so a weak line-up or loss of a dealership hurts sharply."},{"risk":"Inventory pile-up","detail":"Unsold stock raises interest costs and forces discounts."},{"risk":"Thin margins","detail":"Small vehicle-sale margins leave little cushion when volumes fall."},{"risk":"Changing sales models","detail":"Direct online sales and low-maintenance EVs can shrink the dealer's role over time."}],"cyclicality":"Cyclical","cyclicalityNote":"Vehicle sales are cyclical, though service and spares income cushions downturns.","metricSet":"auto-dealer","relatedBasicIndustries":["b-passenger-cars-and-utility-vehicles","b-2-3-wheelers","b-dealers-commercial-vehicles-tractors-construction-vehicles","b-insurance-distributors","b-non-banking-financial-company-nbfc"],"aliases":["car dealer","dealership","automobile dealer","car showroom","auto retail","vehicle dealer","used cars","pre-owned cars"],"themes":[]},"b-auto-components-and-equipments":{"simplifiedExplanation":"These companies make the many parts that go into vehicles, from engine and brake parts to wiring, lights, seats and batteries, and sell them to vehicle makers and as spare parts.","productsAndServices":["Engine and transmission parts","Brakes, steering and suspension","Wiring harnesses and electronics","Lighting, seating and interiors","Forged and cast components","Batteries","EV motors, controllers and chargers"],"valueChainPosition":"Upstream of vehicle makers: buys steel, aluminium, copper, plastics and electronics, and supplies vehicle makers, larger first-tier suppliers and the replacement aftermarket.","howTheyMakeMoney":"They win multi-year supply contracts for specific vehicle models and earn a manufacturing margin per part. Aftermarket and export sales usually earn better margins than domestic supply to vehicle makers.","revenueSources":["Supply to domestic vehicle makers","Replacement aftermarket","Exports to global vehicle makers and suppliers","Tooling and engineering fees"],"operatingCosts":["Steel, aluminium, copper and plastics","Electronic parts and chips","Power and fuel","Employee costs","Tooling and maintenance"],"customersAndEndMarkets":"Car, two-wheeler, commercial-vehicle and tractor makers, global automotive and industrial customers, and mechanics and parts retailers in the aftermarket.","demandSupplyDrivers":"Demand follows vehicle production at home and abroad and rising content per vehicle from safety, comfort and electronics; replacement demand follows the vehicles already on the road.","domesticInternationalExposure":"Many firms export to North America, Europe and Asia, so global auto cycles, tariffs and the rupee matter; some electronics are imported.","capexIntensity":"Medium","capexNote":"Machining, forging, casting and testing lines need steady investment, with new capacity usually tied to won programmes.","workingCapital":"Receivables from vehicle makers and export customers plus raw-material stocks tie up cash; aftermarket distribution needs more inventory.","regulation":"Vehicle safety and emission rules set through Automotive Industry Standards (AIS) and BIS shape products; PLI supports advanced automotive components, and export markets apply tariffs and local-content rules.","competitiveAdvantages":"Approved-supplier status, long validation cycles, engineering skills and cost leadership make customers reluctant to switch suppliers mid-programme.","drivers":[{"factor":"Domestic vehicle production","impact":"Vehicle makers' output schedules directly set volumes for their suppliers."},{"factor":"Exports & global demand","impact":"Global vehicle makers diversifying sourcing to India can lift export orders."},{"factor":"Commodity prices","impact":"Metal cost changes are passed to customers only with a lag, squeezing or helping margins."},{"factor":"Technology change","impact":"EVs need new parts such as motors and power electronics while reducing engine and exhaust parts."},{"factor":"Capacity utilisation","impact":"High fixed costs mean margins expand when plants run fuller."}],"risks":[{"risk":"Customer concentration","detail":"Losing or slowing one large vehicle-maker customer can hit revenue hard."},{"risk":"Engine-part obsolescence","detail":"Parts used only in petrol and diesel engines face shrinking demand as EVs spread."},{"risk":"Export tariffs","detail":"Trade duties in key markets can cut orders or margins."},{"risk":"Price-down pressure","detail":"Vehicle makers often negotiate regular price reductions from suppliers."}],"cyclicality":"Cyclical","cyclicalityNote":"Tied to vehicle production cycles, softened somewhat by replacement and export sales.","metricSet":"auto-components","relatedBasicIndustries":["b-passenger-cars-and-utility-vehicles","b-2-3-wheelers","b-commercial-vehicles","b-castings-and-forgings","b-abrasives-and-bearings"],"aliases":["auto parts","auto ancillary","auto ancillaries","automotive components","car parts","spare parts","tier 1 supplier","OEM supplier","EV components"],"themes":["EV","Exports","China+1"]},"b-tyres-and-rubber-products":{"simplifiedExplanation":"Tyre companies make tyres and tubes for cars, bikes, trucks, tractors and mining vehicles; most sales go to owners replacing worn-out tyres.","productsAndServices":["Truck and bus radial tyres","Passenger car tyres","Two-wheeler tyres and tubes","Farm and tractor tyres","Off-highway and mining tyres","Tread rubber and other rubber products"],"valueChainPosition":"Midstream converter: buys natural and synthetic rubber, carbon black, tyre cord and chemicals, and sells to vehicle makers, replacement dealers and overseas buyers.","howTheyMakeMoney":"They earn the gap between tyre prices and raw-material costs. Replacement tyres sold through dealers under strong brands usually earn more than tyres supplied to vehicle makers.","revenueSources":["Replacement market","Original equipment supply to vehicle makers","Exports","Other rubber products"],"operatingCosts":["Natural rubber","Synthetic rubber and carbon black (crude-linked)","Tyre cord and steel bead wire","Power and fuel","Employee costs","Advertising and dealer schemes"],"customersAndEndMarkets":"Vehicle owners, fleet operators and farmers through dealers; car, two-wheeler, truck and tractor makers; and global farm and off-highway equipment users.","demandSupplyDrivers":"Replacement demand follows kilometres driven and freight activity, while supply to vehicle makers tracks production. Input costs swing with crude oil and rubber harvests.","domesticInternationalExposure":"Natural rubber is partly imported and crude-linked inputs follow global prices; some makers export a large share of specialty farm and off-highway tyres.","capexIntensity":"High","capexNote":"Tyre plants, especially radial lines, need large investment and take time to ramp up.","workingCapital":"Raw-material stocks and dealer credit are significant, and rubber price swings change the value of inventory.","regulation":"Mandatory BIS standards for tyres, import licensing and trade-remedy duties on some tyre types, and Rubber Board oversight of natural rubber.","competitiveAdvantages":"Strong brands, wide dealer networks, approvals from vehicle makers and radial and specialty-tyre technology create high entry barriers.","drivers":[{"factor":"Commodity prices","impact":"Natural rubber prices are the largest swing factor in tyre margins."},{"factor":"Crude oil prices","impact":"Synthetic rubber, carbon black and other inputs move with crude."},{"factor":"Infrastructure spending","impact":"Road building, mining and freight movement lift truck and off-highway tyre demand."},{"factor":"Imports & dumping","impact":"Cheap imported truck and car tyres pressure prices when import curbs ease."},{"factor":"Exports & global demand","impact":"Global farm and construction equipment cycles drive specialty tyre exports."}],"risks":[{"risk":"Raw-material spike","detail":"Sharp rubber or crude moves hurt margins before price hikes catch up."},{"risk":"Price competition","detail":"Discounting among large players in replacement tyres can erode margins."},{"risk":"Export slowdown","detail":"Weak farm or mining demand abroad hits specialty tyre makers."},{"risk":"Overcapacity","detail":"Simultaneous capacity additions can depress utilisation and pricing."}],"cyclicality":"Mixed","cyclicalityNote":"Replacement demand is steady, but supply to vehicle makers and raw-material swings make margins cyclical.","metricSet":"auto-components","relatedBasicIndustries":["b-carbon-black","b-rubber","b-passenger-cars-and-utility-vehicles","b-commercial-vehicles","b-tractors"],"aliases":["tyres","tires","tyre makers","tyre companies","rubber products","radial tyres","OTR tyres","tubes"],"themes":["Exports"]},"b-trading-auto-components":{"simplifiedExplanation":"These firms do not make parts; they buy spare parts and accessories from manufacturers and distribute them to shops, garages and fleet owners.","productsAndServices":["Distribution of branded spare parts","Filters, brakes, bearings and clutches","Lubricants and accessories","Batteries and tyres (some)","Warehousing and delivery to retailers"],"valueChainPosition":"Downstream distributor between component makers and the aftermarket of parts retailers, workshops and fleets.","howTheyMakeMoney":"They earn a distribution margin and volume incentives from the brands they carry, and win business through range, stock availability and fast delivery.","revenueSources":["Sale of traded spare parts","Supplier incentives and discounts","Accessories and consumables"],"operatingCosts":["Purchase cost of goods","Warehousing and logistics","Sales staff","Interest on working capital"],"customersAndEndMarkets":"Spare-parts retailers, independent garages, fleet operators and institutional buyers such as state transport undertakings.","demandSupplyDrivers":"Demand follows the number and age of vehicles on the road and kilometres driven rather than new-vehicle sales. Supply terms depend on distribution agreements with principal brands.","domesticInternationalExposure":"Mostly domestic; some traded parts are imported, so the rupee and import duties affect costs.","capexIntensity":"Low","capexNote":"Assets are mainly warehouses, delivery vehicles and IT systems.","workingCapital":"Heavy: stocking thousands of part numbers and giving credit to retailers make working capital the main use of cash.","regulation":"Light, general business regulation; GST compliance and BIS rules for some safety-critical parts apply.","competitiveAdvantages":"Long-term distribution rights for strong brands, wide reach and efficient logistics, though brands can switch distributors or sell directly.","drivers":[{"factor":"Vehicles on the road","impact":"A larger and older vehicle base needs more replacement parts."},{"factor":"Interest rates","impact":"Inventory and receivables are often funded with borrowings, so rates affect profit."},{"factor":"Technology change","impact":"EVs have fewer wear-and-tear parts, which can slowly shrink the aftermarket mix."},{"factor":"Imports & dumping","impact":"Cheap or counterfeit parts compete with the branded products distributors carry."}],"risks":[{"risk":"Principal dependence","detail":"Losing a key brand's distribution rights can cut revenue sharply."},{"risk":"Counterfeit competition","detail":"Fake and unbranded parts undercut prices."},{"risk":"Inventory obsolescence","detail":"Slow-moving part numbers for older models can become dead stock."},{"risk":"Online disintermediation","detail":"E-commerce platforms and brands selling direct can bypass distributors."}],"cyclicality":"Mixed","cyclicalityNote":"Replacement demand is steadier than new-vehicle sales, but credit stress among retailers can hurt collections.","metricSet":"trading-distribution","relatedBasicIndustries":["b-auto-components-and-equipments","b-tyres-and-rubber-products","b-trading-and-distributors","b-distributors"],"aliases":["auto parts distributor","spare parts distributor","auto aftermarket","automotive trading","spares trading","replacement parts"],"themes":[]},"b-cycles":{"simplifiedExplanation":"Cycle companies make bicycles for everyday transport, children, fitness and sport, along with parts such as frames, rims and chains.","productsAndServices":["Standard roadster bicycles","Kids' bicycles","Premium geared and sports bicycles","Electric bicycles","Cycle parts and components","Fitness equipment (some)"],"valueChainPosition":"Midstream maker and assembler: buys steel tubes, alloy parts, tyres and gears, and sells through dealers, retail stores, e-commerce and government tenders.","howTheyMakeMoney":"Standard cycles are a high-volume, thin-margin business. Premium, kids' and electric cycles and branded retail earn better margins.","revenueSources":["Dealer and retail sales","Government and institutional tenders","Exports","Parts and components"],"operatingCosts":["Steel and alloy","Bought-out parts such as gears and tyres","Labour","Freight and distribution","Marketing"],"customersAndEndMarkets":"Low-income commuters, rural users, students under state school schemes, children and urban fitness enthusiasts.","demandSupplyDrivers":"Mass demand depends on rural incomes and lumpy state bicycle-distribution tenders for students; premium demand follows fitness trends and urban lifestyles.","domesticInternationalExposure":"Mostly domestic with some exports; high-end parts and premium bikes are often imported, so the rupee and import duties matter.","capexIntensity":"Low","capexNote":"Frame-making, painting and assembly lines need modest investment.","workingCapital":"Government tenders can bring delayed payments, and stocking before school-year and festive demand raises inventory.","regulation":"BIS standards cover bicycles and parts; import duties and state school-scheme tender rules shape demand.","competitiveAdvantages":"Brand, dealer reach and low-cost manufacturing matter in mass cycles, while design and retail presence matter in premium segments.","drivers":[{"factor":"Rural demand","impact":"Farm incomes decide how many households buy basic cycles."},{"factor":"Government policy","impact":"State schemes that give bicycles to students create large but irregular orders."},{"factor":"Commodity prices","impact":"Steel cost moves hit margins in a price-sensitive market."},{"factor":"Imports & dumping","impact":"Cheap imported cycles and parts compete with local makers."},{"factor":"Consumer demand","impact":"Fitness and leisure trends lift premium and electric cycles."}],"risks":[{"risk":"Tender dependence","detail":"Delayed or cancelled state orders cause sharp revenue swings."},{"risk":"Price competition","detail":"Unorganised makers and imports keep pricing tight."},{"risk":"Steel cost spikes","detail":"Input inflation is hard to pass on to low-income buyers."},{"risk":"Shift to motorised transport","detail":"Rising incomes push buyers from cycles to two-wheelers."}],"cyclicality":"Mixed","cyclicalityNote":"Basic cycles are a low-cost necessity, but tenders and premium demand swing.","metricSet":"consumer-durables","relatedBasicIndustries":["b-2-3-wheelers","b-leisure-products","b-iron-and-steel-products","b-tyres-and-rubber-products"],"aliases":["bicycles","bicycle","cycle makers","e-bikes","electric cycles","kids cycles","geared cycles"],"themes":["Rural demand"]},"b-consumer-electronics":{"simplifiedExplanation":"Companies that make or assemble TVs, smartphones, LED lights, audio products and other electronics, either under their own brand or as contract manufacturers for big brands.","productsAndServices":["Televisions and displays","Mobile phones and wearables","LED lighting and fixtures","Audio and smart devices","Set-top boxes and IoT devices","Electronics contract manufacturing (EMS)"],"valueChainPosition":"Midstream: imports or buys chips, display panels and components, assembles finished products and supplies brands, distributors and retailers.","howTheyMakeMoney":"Contract manufacturers earn thin margins on very high volumes and gain from scale and making their own components. Brand owners earn higher gross margins but spend heavily on marketing and service.","revenueSources":["Contract manufacturing for brands","Own-brand product sales","Component and sub-assembly sales","Exports"],"operatingCosts":["Imported chips, panels and components","Labour","Freight and logistics","Warranty and after-sales service","Marketing (brand owners)"],"customersAndEndMarkets":"Global and Indian electronics brands, telecom and DTH operators, retailers, e-commerce platforms and end consumers.","demandSupplyDrivers":"Demand follows product upgrades, festive seasons and global brands moving production to India; supply depends on component availability and chip and panel price cycles.","domesticInternationalExposure":"Heavy reliance on imported components makes the rupee and global component prices important, and exports of phones and devices are a major driver.","capexIntensity":"Medium","capexNote":"Assembly is fairly capital-light, but component plants such as displays, circuit boards and camera modules need more investment.","workingCapital":"Component stocks and customer receivables are large; contract makers usually pass on component costs but must manage inventory tightly.","regulation":"MeitY PLI schemes for mobile phones and IT hardware, component-manufacturing incentives, compulsory BIS registration for many electronic products, and import duties on finished goods and parts.","competitiveAdvantages":"Scale, quality track record, approvals from global brands and in-house components create stickiness; brand owners rely on distribution and service reach.","drivers":[{"factor":"Government policy","impact":"PLI and component incentives make local assembly competitive and attract global brands."},{"factor":"Exports & global demand","impact":"Brands diversifying away from China add large export volumes."},{"factor":"Consumer demand","impact":"Festive sales and upgrade cycles drive domestic TV, phone and audio demand."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported components."},{"factor":"Technology change","impact":"Short product cycles demand constant retooling and new capabilities."}],"risks":[{"risk":"Customer concentration","detail":"A few large brands often make up most of a contract maker's revenue."},{"risk":"Thin margins","detail":"Small cost overruns or price cuts can wipe out profit on high-volume contracts."},{"risk":"Incentive changes","detail":"Profitability can fall when PLI support ends or rules change."},{"risk":"Component shortages","detail":"Chip or panel supply problems can halt production."}],"cyclicality":"Mixed","cyclicalityNote":"End demand is discretionary, but the structural shift of electronics manufacturing to India adds steadier growth drivers.","metricSet":"consumer-durables","relatedBasicIndustries":["b-household-appliances","b-computers-hardware-and-equipments","b-telecom-equipment-and-accessories","b-other-electrical-equipment"],"aliases":["electronics","EMS","electronics manufacturing services","contract manufacturing","TV makers","mobile phone manufacturing","LED lighting","consumer electronics"],"themes":["China+1","Exports","PLI"]},"b-furniture-home-furnishing":{"simplifiedExplanation":"These companies make mattresses, sofas, beds, modular furniture and home furnishings, and sell them through stores, dealers and online.","productsAndServices":["Mattresses and pillows","PU foam","Sofas, recliners and beds","Modular and office furniture","Home furnishings and decor","Vinyl and other flooring (some)"],"valueChainPosition":"Downstream maker and brand: buys foam chemicals, wood panels, fabric and steel, and sells to households, offices and hotels through dealers, own stores and e-commerce.","howTheyMakeMoney":"Brands earn healthy gross margins on design and comfort but spend on marketing, showrooms and delivery. Foam and contract-furniture makers earn more on volume and efficiency.","revenueSources":["Retail and dealer sales","Online and direct-to-consumer sales","Institutional and hotel projects","Exports"],"operatingCosts":["Foam chemicals (crude-linked)","Wood panels, fabric and steel","Showroom rent and staff","Freight and last-mile delivery","Advertising"],"customersAndEndMarkets":"Households moving into new or renovated homes, offices, hotels, hospitals and export buyers.","demandSupplyDrivers":"Demand follows home completions, upgrades, weddings and online shopping, while a large unorganised market competes on price.","domesticInternationalExposure":"Mainly domestic; foam chemicals track global prices, imported furniture competes in some categories and a few firms export.","capexIntensity":"Medium","capexNote":"Foam and furniture plants plus company-owned showrooms need steady investment.","workingCapital":"Finished goods across many designs and stores tie up cash; online sales cut receivables but raise returns and delivery costs.","regulation":"Light, general business regulation; BIS standards exist for several furniture and foam products, and GST rates affect pricing.","competitiveAdvantages":"Trusted brands, wide distribution, in-house foam or panel production and reliable delivery separate leaders from unorganised makers.","drivers":[{"factor":"Real estate cycle","impact":"New home handovers trigger furniture and mattress purchases."},{"factor":"Consumer demand","impact":"Upgrading to branded mattresses and furniture lifts premium sales."},{"factor":"Crude oil prices","impact":"Foam chemicals follow crude, so oil moves drive gross margins."},{"factor":"Online and direct sales","impact":"E-commerce widens reach but adds discounting and logistics costs."}],"risks":[{"risk":"Raw-material swings","detail":"Foam chemical and wood-panel price spikes squeeze margins."},{"risk":"Unorganised competition","detail":"Local carpenters and foam makers undercut on price."},{"risk":"Imports","detail":"Cheap imported furniture pressures pricing in some segments."},{"risk":"Discretionary slowdown","detail":"Big-ticket home purchases are easy to postpone."}],"cyclicality":"Cyclical","cyclicalityNote":"Linked to housing and discretionary spending, so purchases can be delayed in downturns.","metricSet":"consumer-durables","relatedBasicIndustries":["b-plywood-boards-laminates","b-residential-commercial-projects","b-plastic-products-consumer","b-houseware","b-petrochemicals"],"aliases":["furniture","mattress","mattresses","home furnishing","home decor","foam","sofa","modular furniture"],"themes":["Housing"]},"b-ceramics":{"simplifiedExplanation":"Ceramics companies make floor and wall tiles, vitrified and glazed tiles and ceramic tableware used in homes, offices and shops.","productsAndServices":["Ceramic wall and floor tiles","Vitrified and porcelain tiles","Large-format slabs","Outdoor and industrial tiles","Ceramic tableware","Tile adhesives and care products"],"valueChainPosition":"Midstream maker: uses clay, feldspar and glazes fired in gas kilns, and sells to dealers, builders, contractors and export buyers.","howTheyMakeMoney":"They earn a spread between tile prices and the cost of minerals, fuel and freight. Brands and premium designs earn more, and many also sell tiles sourced from partner plants.","revenueSources":["Retail sales through dealers","Project sales to builders","Exports","Outsourced and traded tiles"],"operatingCosts":["Natural gas or propane fuel","Clay, feldspar and glazes","Power","Freight (tiles are heavy)","Dealer incentives and advertising"],"customersAndEndMarkets":"Home builders and renovators, real-estate developers, commercial projects and importers abroad.","demandSupplyDrivers":"Demand follows housing, renovation and commercial construction; a large unorganised manufacturing cluster in Gujarat adds supply and keeps prices competitive.","domesticInternationalExposure":"Exports to the Middle East, Europe, the US and other markets are significant, and gas prices and global freight rates affect competitiveness.","capexIntensity":"Medium","capexNote":"Kilns and presses are capital-intensive, though many brands limit spending by sourcing from associate plants.","workingCapital":"Dealer credit and finished-goods stock across many designs and sizes keep working capital significant.","regulation":"BIS standards for tiles, pollution-control rules on kilns and fuel use, and trade remedies such as anti-dumping duties at home or in export markets.","competitiveAdvantages":"Brand, design range, dealer reach and low fuel cost matter; scale and exports help, but entry barriers in basic tiles are low.","drivers":[{"factor":"Real estate cycle","impact":"New construction and renovation drive most tile demand."},{"factor":"Gas prices","impact":"Fuel is a major cost, so gas price moves swing margins."},{"factor":"Exports & global demand","impact":"Export orders absorb surplus capacity when domestic demand is soft."},{"factor":"Imports & dumping","impact":"Trade duties at home and abroad shape pricing and export access."},{"factor":"Consumer demand","impact":"Preference for large-format and designer tiles supports branded players."}],"risks":[{"risk":"Fuel cost spike","detail":"A jump in gas prices can erase margins quickly."},{"risk":"Overcapacity","detail":"Rapid additions in unorganised clusters cause price wars."},{"risk":"Export barriers","detail":"Anti-dumping actions or freight disruption can shut export markets."},{"risk":"Housing slowdown","detail":"Weak construction activity cuts volumes."}],"cyclicality":"Cyclical","cyclicalityNote":"Tied closely to housing and construction activity.","metricSet":"building-materials","relatedBasicIndustries":["b-sanitary-ware","b-granites-and-marbles","b-residential-commercial-projects","b-lpg-cng-png-lng-supplier"],"aliases":["tiles","ceramic tiles","vitrified tiles","floor tiles","wall tiles","porcelain tiles","tile makers","GVT tiles"],"themes":["Housing","Exports"]},"b-granites-and-marbles":{"simplifiedExplanation":"These companies quarry granite and marble, cut and polish it into slabs and tiles, and some make engineered quartz surfaces for kitchen tops and floors.","productsAndServices":["Granite blocks and slabs","Marble slabs and tiles","Engineered quartz surfaces","Kitchen countertops and vanity tops","Monuments and cut-to-size stone"],"valueChainPosition":"Upstream to midstream: quarries stone under state leases or buys blocks, processes it, and sells to builders, fabricators, distributors and export buyers.","howTheyMakeMoney":"They earn the premium that colour, quality and finish command over quarrying and processing costs; engineered quartz and export orders can earn better margins.","revenueSources":["Export sales","Domestic slab and tile sales","Quarry block sales","Engineered surfaces"],"operatingCosts":["Quarrying costs and royalties","Power and cutting consumables","Resins and quartz (engineered stone)","Labour","Freight and container costs"],"customersAndEndMarkets":"Home builders, interior fabricators, real-estate projects and kitchen and bath distributors in the US, Europe and Asia.","demandSupplyDrivers":"Demand follows housing and renovation, especially in export markets; supply depends on quarry approvals and competition from tiles and other surfaces.","domesticInternationalExposure":"Many firms are export-heavy, so overseas housing, trade duties abroad and the rupee matter a great deal.","capexIntensity":"Medium","capexNote":"Quarry equipment, gang-saws and quartz lines need moderate investment.","workingCapital":"Large stocks of blocks and slabs in many colours plus export receivables make working capital heavy.","regulation":"Granite and marble are minor minerals, so quarry leases, royalties and environmental clearances follow state rules under the MMDR Act; trade duties abroad affect exports.","competitiveAdvantages":"Rare colour deposits, quarry rights, finishing quality and long buyer relationships are hard to replicate.","drivers":[{"factor":"Exports & global demand","impact":"Housing and remodelling in the US and Europe drive export orders."},{"factor":"Real estate cycle","impact":"Premium homes and offices at home use natural stone for floors and counters."},{"factor":"Currency (INR)","impact":"A weaker rupee raises export realisations."},{"factor":"Regulation","impact":"Lease renewals and mining clearances decide quarry output."},{"factor":"Trade duties abroad","impact":"Anti-dumping or other duties in buyer countries can shut out exports."}],"risks":[{"risk":"Export duties","detail":"Trade actions in a key market can cut volumes sharply."},{"risk":"Quarry lease issues","detail":"Delays or disputes over leases can stop supply of key colours."},{"risk":"Substitution","detail":"Large tiles and other engineered surfaces compete with natural stone."},{"risk":"Freight costs","detail":"Heavy, bulky shipments are exposed to container rate spikes."}],"cyclicality":"Cyclical","cyclicalityNote":"Follows housing cycles at home and in key export markets.","metricSet":"building-materials","relatedBasicIndustries":["b-ceramics","b-industrial-minerals","b-residential-commercial-projects","b-other-construction-materials"],"aliases":["granite","marble","natural stone","quartz surfaces","engineered stone","stone slabs","countertops"],"themes":["Exports","Housing"]},"b-gems-jewellery-and-watches":{"simplifiedExplanation":"These companies make and sell gold, diamond and silver jewellery, cut and polish diamonds, or make and retail watches.","productsAndServices":["Gold jewellery","Diamond and studded jewellery","Silver and platinum jewellery","Cut and polished diamonds, natural and lab-grown","Watches","Jewellery exports"],"valueChainPosition":"Midstream to downstream: buys gold from banks and bullion dealers and diamonds from traders, then makes and sells jewellery through own stores, franchises, wholesalers or export buyers.","howTheyMakeMoney":"Retailers earn making charges and design margins, especially on studded jewellery, while manufacturers and diamond processors earn thinner margins on large revenue. Gold-price moves also create inventory gains or losses.","revenueSources":["Retail jewellery sales","Wholesale and B2B jewellery","Exports of jewellery and diamonds","Watches and accessories","Gold savings schemes"],"operatingCosts":["Gold, silver and diamond purchases","Making and labour charges","Store rent and staff","Advertising","Interest on gold loans and inventory funding"],"customersAndEndMarkets":"Indian households buying for weddings, festivals and savings, and global jewellery retailers and wholesalers for exporters.","demandSupplyDrivers":"Demand peaks in wedding and festive seasons and rises with incomes, but very high or volatile gold prices can delay buying. The shift from local jewellers to trusted chains supports organised players.","domesticInternationalExposure":"Gold and rough diamonds are mostly imported, so global prices, import duty and the rupee matter; diamond and jewellery exporters depend on demand in the US, Middle East and other markets.","capexIntensity":"Low","capexNote":"Stores and workshops need modest investment; most capital goes into inventory.","workingCapital":"Very heavy: large gold and diamond stocks are funded by equity, gold metal loans and bank credit, and exporters also carry receivables.","regulation":"Mandatory BIS hallmarking with HUID for gold jewellery, customs duty on gold, RBI rules on gold imports and gold loans, KYC and anti-money-laundering rules, and SEZ-based export schemes.","competitiveAdvantages":"Trust in purity, wide store networks, design range and access to low-cost gold funding protect established brands.","drivers":[{"factor":"Commodity prices","impact":"Gold prices drive revenue, buying behaviour and inventory gains or losses."},{"factor":"Consumer demand","impact":"Wedding and festive seasons create strong seasonal peaks."},{"factor":"Government policy","impact":"Changes in gold import duty shift demand and the appeal of smuggled gold."},{"factor":"Exports & global demand","impact":"Diamond and jewellery exporters follow consumer demand abroad."},{"factor":"Currency (INR)","impact":"A weaker rupee raises local gold prices and export realisations."}],"risks":[{"risk":"Gold price volatility","detail":"Sharp falls cause inventory losses and sharp rises can stall buying."},{"risk":"Duty and tax changes","detail":"Import duty or GST changes alter pricing and demand overnight."},{"risk":"Lab-grown diamonds","detail":"Cheaper lab-grown stones disrupt pricing for natural diamonds."},{"risk":"Governance and credit","detail":"Past frauds and defaults in the trade make lenders cautious about funding."}],"cyclicality":"Mixed","cyclicalityNote":"Wedding and gifting demand is resilient, but gold prices and export demand make results swing.","metricSet":"jewellery","relatedBasicIndustries":["b-precious-metals","b-speciality-retail","b-diversified-retail"],"aliases":["jewellery","jewelry","gold jewellery","diamonds","jewellers","watches","lab grown diamonds","gems"],"themes":["Exports"]},"b-glass-consumer":{"simplifiedExplanation":"These companies make glass products for homes, such as dinner sets, tumblers, bowls, opal ware and heat-resistant kitchen glassware.","productsAndServices":["Opal glass dinnerware","Glass tumblers and stemware","Borosilicate kitchen and oven ware","Glass storage jars","Decorative glassware","Gift sets"],"valueChainPosition":"Midstream maker: melts silica sand, soda ash and other minerals in furnaces and sells finished glassware through distributors, retail chains, e-commerce and corporate gifting.","howTheyMakeMoney":"They earn healthy margins when furnaces run near full and branded designs command a premium over imports and unorganised products.","revenueSources":["Retail and distributor sales","Corporate gifting and institutional sales","E-commerce","Exports"],"operatingCosts":["Natural gas and power for furnaces","Silica sand, soda ash and minerals","Packaging","Labour","Marketing"],"customersAndEndMarkets":"Households, hotels and restaurants, corporate gift buyers and retailers.","demandSupplyDrivers":"Demand follows household upgrades, gifting and wedding seasons; supply depends on furnace capacity, which cannot easily be switched off once lit.","domesticInternationalExposure":"Imports compete in some categories and gas and soda ash follow global prices; exports are modest for most makers.","capexIntensity":"High","capexNote":"Furnaces are costly and need periodic rebuilds, so new capacity comes in large steps.","workingCapital":"Finished goods across many designs and festive stocking raise inventory; dealer credit is moderate.","regulation":"Light, general business regulation plus pollution-control rules for furnaces and food-contact safety standards.","competitiveAdvantages":"Brand, design, furnace know-how and distribution reach; the high cost of furnaces deters small entrants.","drivers":[{"factor":"Consumer demand","impact":"Gifting, weddings and kitchen upgrades drive sales of premium glassware."},{"factor":"Commodity prices","impact":"Gas and soda ash costs move margins because furnaces burn fuel non-stop."},{"factor":"Imports & dumping","impact":"Cheap imported tableware pressures prices."},{"factor":"Capacity utilisation","impact":"Full furnaces spread fixed costs; idle capacity hurts profits fast."}],"risks":[{"risk":"Fuel cost spikes","detail":"Gas price jumps raise costs immediately."},{"risk":"Cheap imports","detail":"Low-priced imports can take share in mass segments."},{"risk":"Furnace outages","detail":"Breakdowns or rebuilds halt production for long periods."},{"risk":"Material substitution","detail":"Steel, plastic and ceramic products compete for the same shelf."}],"cyclicality":"Mixed","cyclicalityNote":"Gifting and upgrades are discretionary, but everyday replacement demand is steady.","metricSet":"consumer-durables","relatedBasicIndustries":["b-houseware","b-glass-industrial","b-ceramics","b-plastic-products-consumer"],"aliases":["glassware","opal ware","dinnerware","crockery","tableware","borosilicate glass","glass tumblers"],"themes":[]},"b-household-appliances":{"simplifiedExplanation":"These companies make and sell home appliances such as fans, air conditioners, refrigerators, washing machines, kitchen appliances and water heaters, or build them for other brands.","productsAndServices":["Ceiling and table fans","Air conditioners and air coolers","Refrigerators and washing machines","Mixer-grinders and kitchen appliances","Water heaters and domestic pumps","Lighting","Contract manufacturing of appliances and parts"],"valueChainPosition":"Midstream: buys compressors, motors, copper, steel, plastics and electronics, assembles appliances and sells through distributors, dealers, large retail and e-commerce, or supplies brands as a contract maker.","howTheyMakeMoney":"Brand owners earn gross margins on design, features and trust, minus advertising and service costs. Contract makers earn thinner margins on volume.","revenueSources":["Branded appliance sales","Contract manufacturing for brands","Components and sub-assemblies","After-sales service and spares","Exports"],"operatingCosts":["Copper, aluminium, steel and plastics","Compressors, motors and electronics","Advertising and channel incentives","Warranty and service","Freight"],"customersAndEndMarkets":"Households, offices and small businesses reached through dealers, retail chains and online; contract makers serve appliance brands.","demandSupplyDrivers":"Cooling products swing sharply with summer heat, while kitchen and laundry appliances follow housing, rising incomes and electrification. Low ownership levels support long-term demand.","domesticInternationalExposure":"Sales are mostly domestic, but compressors and electronics are often imported, so the rupee and import duties affect costs.","capexIntensity":"Medium","capexNote":"Assembly needs moderate investment; making motors, compressors and electronics in-house raises spending.","workingCapital":"Seasonal: stocks build before summer and the festive season, and a mild summer can leave excess inventory.","regulation":"BEE star-rating rules on energy efficiency, BIS quality-control orders for many appliances, PLI for air-conditioner and LED components, and import duties on finished goods.","competitiveAdvantages":"Strong brands, dealer reach, service networks and local manufacturing scale protect leaders.","drivers":[{"factor":"Summer heat","impact":"A hot, long summer lifts AC, cooler and fan sales; a mild one leaves stock unsold."},{"factor":"Consumer demand","impact":"Rising incomes and easy EMIs move households to bigger and better appliances."},{"factor":"Commodity prices","impact":"Copper, steel and aluminium costs drive gross margins."},{"factor":"Real estate cycle","impact":"New homes need a full set of appliances."},{"factor":"Government policy","impact":"PLI and quality-control orders favour local manufacturing over imports."}],"risks":[{"risk":"Weak season","detail":"An unseasonal or short summer hurts the year's cooling sales."},{"risk":"Commodity spikes","detail":"Metal price jumps squeeze margins before price hikes stick."},{"risk":"Price wars","detail":"Many brands and online discounting limit pricing power."},{"risk":"Energy-rule changes","detail":"Tighter star-rating norms raise costs and can make old stock harder to sell."}],"cyclicality":"Cyclical","cyclicalityNote":"Purchases are discretionary and strongly seasonal.","metricSet":"consumer-durables","relatedBasicIndustries":["b-consumer-electronics","b-houseware","b-other-electrical-equipment","b-cables-electricals"],"aliases":["home appliances","white goods","air conditioners","AC","fans","refrigerators","washing machines","kitchen appliances","consumer electricals"],"themes":["PLI","China+1"]},"b-houseware":{"simplifiedExplanation":"Houseware companies make everyday kitchen and home items such as pressure cookers, cookware, bottles, flasks, lunch boxes and storage containers.","productsAndServices":["Pressure cookers and cookware","Steel and insulated bottles and flasks","Plastic and glass storage containers","Lunch boxes","Kitchen tools","Cleaning and home-organisation products"],"valueChainPosition":"Midstream maker or brand: buys aluminium, steel, plastics and glass, makes or outsources products, and sells through distributors, modern retail, e-commerce and exports.","howTheyMakeMoney":"Brands earn margins from trust, design and broad ranges; many outsource part of the range and focus on distribution and marketing.","revenueSources":["Distributor and retail sales","E-commerce","Corporate gifting and institutional sales","Exports"],"operatingCosts":["Aluminium, steel and plastics","Outsourced products","Advertising","Freight and distribution","Labour"],"customersAndEndMarkets":"Households across urban and rural India, gift buyers and overseas retailers.","demandSupplyDrivers":"Replacement, gifting, weddings and new households drive steady sales, while unorganised makers and imports keep prices competitive.","domesticInternationalExposure":"Mostly domestic; metal and polymer costs follow global prices and imports compete in some categories.","capexIntensity":"Low","capexNote":"Moulding and pressing plants need moderate investment, and outsourcing keeps it lower.","workingCapital":"Wide product ranges need inventory, and distributors usually get credit.","regulation":"BIS mandatory certification applies to items such as pressure cookers, and food-contact safety standards cover containers and cookware.","competitiveAdvantages":"Trust on safety and durability, wide distribution and a broad range give brands an edge over unorganised makers.","drivers":[{"factor":"Consumer demand","impact":"New households, gifting and kitchen upgrades support volumes."},{"factor":"Commodity prices","impact":"Aluminium and steel costs drive margins on cookware and bottles."},{"factor":"Crude oil prices","impact":"Plastic resin costs for containers move with crude."},{"factor":"Rural demand","impact":"Rural households upgrading kitchenware add volume for mass brands."},{"factor":"Imports & dumping","impact":"Low-priced imports compete in steel and plastic items."}],"risks":[{"risk":"Input cost spikes","detail":"Metal and polymer inflation can outpace price hikes."},{"risk":"Unorganised and import competition","detail":"Cheaper alternatives limit pricing power."},{"risk":"Channel shift","detail":"Growth of online sales changes margins and distributor relationships."},{"risk":"Discretionary slowdown","detail":"Premium and gifting items are cut first when budgets tighten."}],"cyclicality":"Mixed","cyclicalityNote":"Everyday replacement keeps demand steady, while gifting and premium products are discretionary.","metricSet":"consumer-durables","relatedBasicIndustries":["b-household-appliances","b-glass-consumer","b-plastic-products-consumer","b-aluminium-copper-and-zinc-products"],"aliases":["kitchenware","cookware","pressure cooker","housewares","bottles and flasks","storage containers","lunch box","steel utensils"],"themes":[]},"b-leather-and-leather-products":{"simplifiedExplanation":"These companies tan hides into finished leather, make leather goods such as bags and garments, or produce synthetic leather used in footwear, cars and furniture.","productsAndServices":["Finished leather","Leather bags, wallets and belts","Leather garments","Shoe uppers and components","Synthetic PU and PVC leather","Coated fabrics for vehicles and furniture"],"valueChainPosition":"Midstream: buys raw hides and chemicals, or base fabrics and polymers, and supplies footwear, fashion, automotive and furniture makers and global brands.","howTheyMakeMoney":"Exporters earn on processing and making goods for global brands, while synthetic-leather makers earn on approved supply to vehicle and footwear makers.","revenueSources":["Export orders","Domestic sales to manufacturers","Supply to vehicle makers (synthetic leather)","Branded leather goods"],"operatingCosts":["Raw hides and skins","Tanning chemicals and dyes","PVC and PU resins and fabrics","Labour","Effluent treatment and power"],"customersAndEndMarkets":"Global fashion and footwear brands, domestic shoe and bag makers, and vehicle and furniture makers.","demandSupplyDrivers":"Export demand follows fashion and retail cycles in Europe and the US, while synthetic-leather demand follows vehicle and footwear production.","domesticInternationalExposure":"Leather goods are export-oriented, so the rupee, trade agreements and European demand matter; synthetic-leather inputs are crude-linked.","capexIntensity":"Medium","capexNote":"Tanneries need effluent treatment and coating lines need significant investment, while goods assembly is lighter.","workingCapital":"Seasonal export orders, raw-material stocks and receivables from overseas buyers need sizable working capital.","regulation":"State pollution control boards regulate tannery effluent, export incentives such as RoDTEP apply, and the Council for Leather Exports supports exporters.","competitiveAdvantages":"Meeting environmental and labour standards, long brand relationships and vehicle-maker approvals are hard to win.","drivers":[{"factor":"Exports & global demand","impact":"Orders from European and US brands drive volumes for leather-goods exporters."},{"factor":"Currency (INR)","impact":"A weaker rupee improves export competitiveness."},{"factor":"Raw material availability","impact":"Supply and quality of hides affect costs and output."},{"factor":"Regulation","impact":"Effluent rules can force tannery upgrades or shutdowns."},{"factor":"Crude oil prices","impact":"PVC and PU resin costs for synthetic leather move with crude."}],"risks":[{"risk":"Environmental closures","detail":"Pollution-control action can shut tanneries or clusters."},{"risk":"Export slowdown","detail":"Weak fashion demand abroad cuts orders."},{"risk":"Material substitution","detail":"Synthetic and plant-based alternatives can replace natural leather."},{"risk":"Buyer concentration","detail":"Reliance on a few large brands or vehicle makers raises revenue risk."}],"cyclicality":"Cyclical","cyclicalityNote":"Follows global fashion demand and vehicle production.","metricSet":"manufacturing-generic","relatedBasicIndustries":["b-footwear","b-garments-and-apparels","b-auto-components-and-equipments","b-other-textile-products"],"aliases":["leather","leather goods","tannery","synthetic leather","artificial leather","PU leather","leather exports","coated fabrics"],"themes":["Exports"]},"b-leisure-products":{"simplifiedExplanation":"These companies make products people use for fun, sport and hobbies, such as toys, sports goods, fitness equipment and musical or outdoor items.","productsAndServices":["Toys and games","Sports goods and equipment","Fitness equipment","Musical instruments","Outdoor and camping gear","Recreational boats and vehicles (few)"],"valueChainPosition":"Midstream maker or brand: uses plastics, wood, metals, rubber and electronics, and sells through retailers, e-commerce, institutions and export buyers.","howTheyMakeMoney":"Brands earn margins on design, licensed characters and trust, while contract makers earn on volume orders from global brands.","revenueSources":["Domestic retail and online sales","Contract manufacturing for global brands","Sales to schools, clubs and gyms","Exports"],"operatingCosts":["Plastics, rubber, wood and metals","Electronic parts","Labour","Licensing fees","Marketing and distribution"],"customersAndEndMarkets":"Children and families, sports clubs, schools, gyms, hobbyists and global toy and sports brands.","demandSupplyDrivers":"Demand follows discretionary spending, festivals, school calendars and sports and fitness trends; local supply has expanded as import curbs tightened.","domesticInternationalExposure":"The market was historically import-heavy; tighter quality rules have helped local manufacturing, and some firms export to global brands.","capexIntensity":"Low","capexNote":"Moulding and assembly lines need modest investment.","workingCapital":"Stocks build before festivals and holidays, and export orders can bring long receivable cycles.","regulation":"BIS mandatory certification for toys, higher import duties on toys and child-safety standards.","competitiveAdvantages":"Safety certifications, licensed characters, design capability and relationships with global brands matter.","drivers":[{"factor":"Consumer demand","impact":"Festive gifting and spending on children and fitness drive sales."},{"factor":"Government policy","impact":"Quality-control orders and higher duties have shifted demand from imports to local makers."},{"factor":"Imports & dumping","impact":"Low-priced imports remain the main competition in many categories."},{"factor":"Exports & global demand","impact":"Global brands diversifying away from China can bring contract orders."}],"risks":[{"risk":"Fads and discretion","detail":"Popular products can fall out of favour quickly."},{"risk":"Import competition","detail":"Easing of import curbs could bring back cheap supply."},{"risk":"Buyer concentration","detail":"Contract makers often depend on a few global brands."},{"risk":"Compliance costs","detail":"Safety testing and certification add cost for small makers."}],"cyclicality":"Cyclical","cyclicalityNote":"Leisure spending is among the first to be cut when budgets tighten.","metricSet":"consumer-durables","relatedBasicIndustries":["b-cycles","b-plastic-products-consumer","b-amusement-parks-other-recreation","b-speciality-retail"],"aliases":["toys","toy makers","sports goods","fitness equipment","sporting goods","musical instruments","games","leisure"],"themes":["China+1","Exports"]},"b-plastic-products-consumer":{"simplifiedExplanation":"These companies make plastic goods for consumers, such as moulded chairs and tables, luggage and travel bags, storage boxes and household items.","productsAndServices":["Moulded furniture","Hard and soft luggage","Backpacks and travel bags","Storage and organisation products","Mattresses and home items (some)","Precision plastic parts for consumer brands"],"valueChainPosition":"Midstream converter: buys polymers such as polypropylene, polyethylene and polycarbonate, moulds products in-house or sources them, and sells through dealers, retail, e-commerce and global brands.","howTheyMakeMoney":"They earn the spread between product prices and polymer costs; branded luggage and designer products earn higher margins than commodity moulded goods.","revenueSources":["Branded retail and dealer sales","E-commerce","Institutional sales","Contract manufacturing and exports"],"operatingCosts":["Polymer resins (crude-linked)","Outsourced products such as soft luggage","Power","Advertising and retail costs","Freight"],"customersAndEndMarkets":"Households, travellers, offices, hotels and global home-goods brands.","demandSupplyDrivers":"Luggage demand follows travel, weddings and holiday seasons, and moulded goods follow household spending; cheap imports and unorganised makers add supply.","domesticInternationalExposure":"Polymer prices follow global crude and petrochemical markets; some soft luggage is sourced from other Asian countries, and a few firms export.","capexIntensity":"Medium","capexNote":"Moulding machines and dies need moderate investment, and sourcing reduces it.","workingCapital":"Inventory across sizes and designs plus channel credit is significant, and retail and online sales need careful stock planning.","regulation":"Light, general business regulation; Plastic Waste Management Rules with extended producer responsibility apply to packaging, and BIS standards cover some items.","competitiveAdvantages":"Brand, design, distribution and sourcing scale, plus approvals from global customers for precision parts.","drivers":[{"factor":"Crude oil prices","impact":"Polymer costs follow crude and drive gross margins."},{"factor":"Tourism & travel","impact":"More domestic and overseas travel lifts luggage sales."},{"factor":"Consumer demand","impact":"Weddings and household spending support furniture and storage sales."},{"factor":"Imports & dumping","impact":"Low-cost imported luggage and plastics pressure prices."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported resins and sourced products."}],"risks":[{"risk":"Polymer price swings","detail":"Resin spikes squeeze margins before price increases."},{"risk":"Import and unorganised competition","detail":"Cheaper products limit pricing power."},{"risk":"Design misses","detail":"Unpopular styles leave unsold inventory."},{"risk":"Discretionary slowdown","detail":"Travel and home spending fall in weak economic periods."}],"cyclicality":"Cyclical","cyclicalityNote":"Luggage and furniture purchases follow travel and discretionary spending.","metricSet":"consumer-durables","relatedBasicIndustries":["b-plastic-products-industrial","b-houseware","b-petrochemicals","b-furniture-home-furnishing"],"aliases":["luggage","suitcases","plastic furniture","moulded furniture","travel bags","plastic products","backpacks","consumer plastics"],"themes":[]},"b-plywood-boards-laminates":{"simplifiedExplanation":"These companies make the wood panels and decorative surfaces used in furniture and interiors: plywood, MDF, particle boards, laminates and veneers.","productsAndServices":["Plywood and block boards","MDF and particle boards","Decorative laminates and compact boards","Veneers","Doors and wooden flooring","Edge bands and adhesives"],"valueChainPosition":"Midstream: buys plantation timber, resins and decor paper, makes panels and surfaces, and sells through distributors, dealers, carpenters and furniture makers, plus exports.","howTheyMakeMoney":"Plywood brands earn a premium over unorganised products through quality and dealer reach; MDF makers earn on plant utilisation and timber cost; laminate makers earn on design range and exports.","revenueSources":["Dealer and distributor sales","Sales to furniture and modular-kitchen makers","Exports of laminates and boards","Project and institutional sales"],"operatingCosts":["Timber","Resins and chemicals (phenol, melamine, urea)","Decor paper","Power and fuel","Freight","Dealer and carpenter incentives"],"customersAndEndMarkets":"Home owners and interior contractors, carpenters, modular-kitchen and furniture makers, offices and hotels.","demandSupplyDrivers":"Demand follows housing completions, interiors and furniture making; timber availability and new MDF capacity drive supply and pricing.","domesticInternationalExposure":"Laminates and some boards are exported widely; imported panels from South-East Asia compete, and chemical inputs track global prices.","capexIntensity":"Medium","capexNote":"MDF and particle-board plants are capital-heavy, while plywood and laminate plants are lighter.","workingCapital":"Dealer credit and stocks of many designs and thicknesses keep working capital significant.","regulation":"BIS quality-control orders cover several wood-panel products, forest and timber-transit rules affect sourcing, and trade-remedy duties can affect imports.","competitiveAdvantages":"Brand trust matters because panels are hidden inside furniture, along with dealer and carpenter networks and timber sourcing close to plants.","drivers":[{"factor":"Real estate cycle","impact":"Home completions and interior fit-outs drive panel demand."},{"factor":"Raw material availability","impact":"Plantation timber supply sets costs for plywood and MDF makers."},{"factor":"Commodity prices","impact":"Resin chemicals and decor paper costs move margins."},{"factor":"Imports & dumping","impact":"Cheap imported boards pressure domestic prices."},{"factor":"Exports & global demand","impact":"Overseas demand for laminates adds volume beyond India."}],"risks":[{"risk":"Timber cost spike","detail":"Shortages of plantation wood raise costs sharply."},{"risk":"MDF overcapacity","detail":"Many new plants at once can trigger price cuts."},{"risk":"Unorganised competition","detail":"Local plywood makers compete on price with uneven quality."},{"risk":"Housing slowdown","detail":"Weak home completions cut interior spending."}],"cyclicality":"Cyclical","cyclicalityNote":"Moves with housing, interior and furniture demand.","metricSet":"building-materials","relatedBasicIndustries":["b-furniture-home-furnishing","b-forest-products","b-residential-commercial-projects","b-commodity-chemicals","b-paper-and-paper-products"],"aliases":["plywood","MDF","laminates","particle board","wood panels","veneer","decorative laminates","boards"],"themes":["Housing","Exports"]},"b-sanitary-ware":{"simplifiedExplanation":"These companies make bathroom products such as toilets, wash basins, taps, showers and other bath fittings.","productsAndServices":["Toilets and urinals","Wash basins","Faucets, taps and showers","Bath fittings and accessories","Wellness products such as shower panels and tubs","Tiles and kitchen sinks (some)"],"valueChainPosition":"Midstream maker: fires clay products in gas kilns, makes faucets from brass and sources some ranges, then sells through dealers, plumbers, retailers and real-estate projects.","howTheyMakeMoney":"They earn margins on brand, design and finish; premium bathware and faucets earn more than basic ceramic products.","revenueSources":["Dealer and retail sales","Project sales to developers","Faucets and fittings","Outsourced or traded bathware"],"operatingCosts":["Clay and ceramic raw materials","Brass, copper and zinc","Gas and power","Freight","Advertising and dealer incentives"],"customersAndEndMarkets":"Households building or renovating, real-estate developers, hotels, hospitals and offices.","demandSupplyDrivers":"Demand follows new homes, renovation and upgrades to better bathrooms; government sanitation drives have widened the basic market.","domesticInternationalExposure":"Mainly domestic; brass and gas prices follow global markets, and imports compete in some faucet and wellness ranges.","capexIntensity":"Medium","capexNote":"Kilns and faucet plants need investment, and sourcing part of the range reduces it.","workingCapital":"Dealer credit and stock of many designs are significant, and project sales carry longer receivables.","regulation":"BIS standards for sanitaryware and fittings, water-efficiency guidelines, and sanitation programmes such as Swachh Bharat that support basic demand.","competitiveAdvantages":"Brand, design range, dealer and plumber networks and after-sales service; once plumbers recommend a brand, switching is rare.","drivers":[{"factor":"Real estate cycle","impact":"New homes and commercial buildings drive most volumes."},{"factor":"Commodity prices","impact":"Brass and zinc costs move faucet margins."},{"factor":"Consumer demand","impact":"Bathroom upgrades and premium fittings lift realisations."},{"factor":"Government policy","impact":"Sanitation and housing schemes expand demand for basic products."}],"risks":[{"risk":"Housing slowdown","detail":"Fewer new homes cut demand for full bathroom sets."},{"risk":"Metal price spikes","detail":"Brass inflation hurts faucet profits."},{"risk":"Unorganised and imported products","detail":"Cheaper alternatives compete in mass segments."},{"risk":"Fuel cost","detail":"Gas price jumps raise kiln costs."}],"cyclicality":"Cyclical","cyclicalityNote":"Linked to construction and renovation activity.","metricSet":"building-materials","relatedBasicIndustries":["b-ceramics","b-residential-commercial-projects","b-plastic-products-industrial","b-aluminium-copper-and-zinc-products"],"aliases":["sanitaryware","bathware","bathroom fittings","faucets","taps","toilets","CP fittings","plumbing fixtures"],"themes":["Housing"]},"b-paints":{"simplifiedExplanation":"Paint companies make decorative paints for homes and industrial coatings for vehicles, machinery and infrastructure, plus related products such as putty and waterproofing.","productsAndServices":["Interior and exterior emulsions","Enamels and primers","Wall putty and waterproofing","Wood finishes","Automotive and industrial coatings","Powder coatings and adhesives"],"valueChainPosition":"Midstream formulator: buys titanium dioxide, monomers, solvents and pigments, makes paints and sells through large dealer networks with tinting machines or directly to industrial customers.","howTheyMakeMoney":"Decorative paints earn strong gross margins from brand, colour range and dealer reach. Industrial coatings earn on technical approvals and long contracts, usually at lower margins.","revenueSources":["Decorative paints via dealers","Industrial and automotive coatings","Waterproofing and construction chemicals","Painting services and home decor (some)","Overseas operations and exports"],"operatingCosts":["Titanium dioxide and pigments","Crude-linked monomers and solvents","Packaging","Freight and distribution","Advertising and dealer incentives"],"customersAndEndMarkets":"Home owners and painters through dealers, real-estate developers, vehicle makers, and industrial and infrastructure users.","demandSupplyDrivers":"Repainting of existing homes gives steady demand, while new construction, festive seasons and weather add swings; large new entrants have increased supply and competition.","domesticInternationalExposure":"Sales are largely domestic, but many raw materials are imported or crude-linked, so the rupee and crude prices drive costs.","capexIntensity":"Medium","capexNote":"Plants, depots and tinting machines need investment, though the business turns its capital over quickly.","workingCapital":"Usually efficient because dealers pay quickly; stocks of raw materials and finished goods rise before the festive season.","regulation":"Rules limiting lead in household and decorative paints, BIS standards, pollution-control norms on solvents and GST on paints.","competitiveAdvantages":"Deep dealer networks, tinting machines, brand recall, supply-chain efficiency and painter loyalty create strong barriers.","drivers":[{"factor":"Crude oil prices","impact":"Many inputs are crude derivatives, so oil prices drive gross margins."},{"factor":"Real estate cycle","impact":"New homes and offices add first-time painting demand."},{"factor":"Consumer demand","impact":"Festive repainting and the move to premium emulsions lift sales."},{"factor":"Weather","impact":"Long or heavy monsoons delay painting work and shift sales between quarters."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported raw materials."}],"risks":[{"risk":"Rising competition","detail":"New large entrants spending on dealers and discounts can pressure margins."},{"risk":"Raw-material spikes","detail":"Crude and titanium dioxide price jumps hurt profitability."},{"risk":"Housing slowdown","detail":"Weak construction reduces new-paint demand."},{"risk":"Dealer overstocking","detail":"Pushing stock into the channel can mask weak end demand."}],"cyclicality":"Mixed","cyclicalityNote":"Repainting demand is resilient, while new construction and industrial coatings are cyclical.","metricSet":"consumer-durables","relatedBasicIndustries":["b-specialty-chemicals","b-dyes-and-pigments","b-residential-commercial-projects","b-plywood-boards-laminates","b-passenger-cars-and-utility-vehicles"],"aliases":["paint","paints","decorative paints","coatings","industrial coatings","emulsion","waterproofing","paint companies"],"themes":["Housing"]},"b-diversified-consumer-products":{"simplifiedExplanation":"Companies that make or sell several kinds of consumer goods, such as electronics, small appliances, lighting and home items, rather than focusing on one product category.","productsAndServices":["Consumer electronics and lighting","Small appliances","Home and personal-use products","Contract manufacturing for consumer brands","Components and sub-assemblies"],"valueChainPosition":"Midstream: assembles or sources a mix of consumer products and supplies brands, distributors and retailers; the exact position varies by company.","howTheyMakeMoney":"They earn margins across a portfolio of categories, with contract work earning on volume and own brands earning on mark-ups and reach.","revenueSources":["Contract manufacturing","Own-brand sales","Component sales","Exports"],"operatingCosts":["Components and raw materials","Labour","Freight","Marketing","Warranty"],"customersAndEndMarkets":"Consumer brands, distributors, retail chains, e-commerce platforms and households.","demandSupplyDrivers":"Demand follows overall consumer spending and seasonal peaks; each category has its own cycle, which can either balance or add to swings.","domesticInternationalExposure":"Varies by company; imported components and the rupee often matter, and some firms export.","capexIntensity":"Medium","capexNote":"Spending depends on how much is made in-house versus sourced from others.","workingCapital":"Inventory across many categories and receivables from brands and distributors need careful management.","regulation":"Rules depend on the category, including BIS quality-control orders, BEE energy labels and PLI schemes for electronics and appliances.","competitiveAdvantages":"A broad range and customer relationships help, but each category faces focused specialist rivals.","drivers":[{"factor":"Consumer demand","impact":"Household spending on gadgets and home products sets overall volumes."},{"factor":"Government policy","impact":"Manufacturing incentives and quality rules favour local production."},{"factor":"Commodity prices","impact":"Metal, plastic and component costs affect margins across categories."},{"factor":"Currency (INR)","impact":"A weaker rupee raises imported component costs."}],"risks":[{"risk":"Lack of focus","detail":"Spreading across many categories can leave each one sub-scale."},{"risk":"Customer concentration","detail":"Contract work often depends on a few brands."},{"risk":"Input swings","detail":"Component and material price moves are hard to pass on quickly."},{"risk":"Specialist competition","detail":"Focused rivals may out-invest in a single category."}],"cyclicality":"Mixed","cyclicalityNote":"A spread of categories can smooth demand, but all depend on discretionary spending.","metricSet":"consumer-durables","relatedBasicIndustries":["b-consumer-electronics","b-household-appliances","b-houseware","b-diversified-fmcg"],"aliases":["diversified consumer","consumer products","multi-category consumer","consumer goods","diversified durables"],"themes":[]},"b-footwear":{"simplifiedExplanation":"Footwear companies make and sell shoes, sandals, slippers and sports footwear through their own stores, dealers and online.","productsAndServices":["Casual and sports shoes","Slippers and flip-flops","Formal leather shoes","School shoes","Women's and kids' footwear","Bags and accessories"],"valueChainPosition":"Downstream maker and retailer: buys EVA, PVC, rubber, PU and leather, makes or outsources footwear, and sells through exclusive stores, multi-brand outlets, distributors and e-commerce.","howTheyMakeMoney":"Mass brands earn on volume through distributors in towns and villages. Premium and store-led brands earn high gross margins but carry rent and staff costs.","revenueSources":["Own and franchise store sales","Distributor and multi-brand outlet sales","E-commerce","Institutional sales and exports"],"operatingCosts":["EVA, PVC, rubber and leather","Outsourced production","Store rent and staff","Advertising","Freight and inventory carrying costs"],"customersAndEndMarkets":"Consumers of all ages and income levels, from rural buyers of everyday slippers to urban buyers of branded sneakers.","demandSupplyDrivers":"Demand follows incomes, fashion, school and wedding seasons and the shift from unorganised to branded footwear; quality rules have curbed cheap imports.","domesticInternationalExposure":"Sales are mostly domestic; polymer inputs are crude-linked and some products are imported or exported.","capexIntensity":"Medium","capexNote":"Store fit-outs and factories need steady spending, and outsourcing reduces factory needs.","workingCapital":"Inventory across sizes, colours and seasons is high; store-led models carry more stock than distributor-led ones.","regulation":"BIS quality-control orders cover many types of footwear, GST rates differ by price point, and shop and labour laws apply to stores.","competitiveAdvantages":"Brand, design, wide store and distributor reach and efficient sourcing, though unorganised makers still compete on price.","drivers":[{"factor":"Consumer demand","impact":"Fashion, sports and casual trends lift branded and premium footwear."},{"factor":"Rural demand","impact":"Mass slippers and sandals depend on rural and small-town spending."},{"factor":"Crude oil prices","impact":"EVA, PVC and rubber costs move with crude."},{"factor":"Government policy","impact":"Quality-control orders push demand toward compliant, organised makers."},{"factor":"Imports & dumping","impact":"Cheap imported footwear competes when rules are loosely enforced."}],"risks":[{"risk":"Discretionary slowdown","detail":"Premium and fashion footwear purchases are postponed in weak times."},{"risk":"Inventory obsolescence","detail":"Unsold seasonal styles need discounting."},{"risk":"Global and online brands","detail":"International sports brands and online-first labels compete for urban buyers."},{"risk":"Input costs","detail":"Polymer and leather price spikes squeeze margins."}],"cyclicality":"Mixed","cyclicalityNote":"Basic footwear is a need, while fashion and premium footwear are discretionary.","metricSet":"retail","relatedBasicIndustries":["b-leather-and-leather-products","b-speciality-retail","b-garments-and-apparels","b-rubber","b-petrochemicals"],"aliases":["shoes","footwear","slippers","sneakers","sandals","chappals","footwear retail","sports shoes"],"themes":["Rural demand"]},"b-garments-and-apparels":{"simplifiedExplanation":"These companies make clothing, from innerwear and t-shirts to shirts, denims and winterwear, either for their own brands or for global retailers.","productsAndServices":["Innerwear and athleisure","Shirts, trousers and denims","Knitwear and t-shirts","Women's and kids' wear","Winterwear","Export garments for global brands"],"valueChainPosition":"Downstream: buys fabric and trims, cuts and stitches garments, and sells to global retailers, domestic brands, own stores, multi-brand outlets and e-commerce.","howTheyMakeMoney":"Exporters earn a manufacturing margin from efficient, compliant factories. Domestic brands earn higher gross margins from design and brand pull but spend on marketing and retail.","revenueSources":["Export orders from global retailers","Own-brand sales via stores, multi-brand outlets and online","Licensed brands","Private-label supply to retailers"],"operatingCosts":["Fabric and trims","Labour","Store rent and marketing (brands)","Freight","Royalty for licensed brands"],"customersAndEndMarkets":"Global apparel retailers and brands, Indian department stores and chains, online marketplaces and consumers.","demandSupplyDrivers":"Export orders follow US and European retail demand and sourcing shifts between countries; domestic demand follows incomes, seasons, weddings and fashion trends.","domesticInternationalExposure":"Exporters depend on overseas buyers, trade agreements, tariffs and the rupee, while domestic brands are mostly local.","capexIntensity":"Low","capexNote":"Garmenting is labour-intensive with modest machinery needs.","workingCapital":"Fabric stocks, season-based inventory and export or retail receivables need significant working capital.","regulation":"Export incentives such as RoSCTL and RoDTEP, PLI and PM MITRA parks for textiles, labour laws and buyer-driven compliance audits.","competitiveAdvantages":"Buyer relationships, compliance records and speed for exporters; brand, design and distribution for domestic players.","drivers":[{"factor":"Exports & global demand","impact":"Retail sales and stock levels at Western retailers decide export orders."},{"factor":"Consumer demand","impact":"Rising incomes and brand preference lift domestic branded apparel."},{"factor":"Currency (INR)","impact":"A weaker rupee helps exporters compete with other sourcing countries."},{"factor":"Government policy","impact":"Trade agreements, tariffs and export incentives change competitiveness."},{"factor":"Commodity prices","impact":"Cotton and fabric prices affect costs and pricing."}],"risks":[{"risk":"Export demand slump","detail":"Retailer destocking can cut orders sharply."},{"risk":"Rival exporting countries","detail":"Lower-cost or duty-advantaged countries can win orders."},{"risk":"Unsold inventory","detail":"Brands face markdowns if seasonal collections do not sell."},{"risk":"Labour availability","detail":"Rising wages or shortages of skilled tailors raise costs."}],"cyclicality":"Mixed","cyclicalityNote":"Basic clothing and innerwear demand is steady, while fashion and export orders swing.","metricSet":"textiles","relatedBasicIndustries":["b-other-textile-products","b-trading-textile-products","b-speciality-retail","b-diversified-retail","b-footwear"],"aliases":["apparel","garments","clothing","readymade garments","innerwear","fashion brands","apparel exports","RMG"],"themes":["Exports","China+1"]},"b-other-textile-products":{"simplifiedExplanation":"Companies that make the materials behind clothes and home textiles: yarn, fabric, polyester fibre, processed cloth, towels, bed linen and technical textiles.","productsAndServices":["Cotton and blended yarn","Polyester and viscose fibre and yarn","Woven and knitted fabrics","Dyeing, printing and processing","Home textiles such as towels and bed linen","Technical textiles"],"valueChainPosition":"Upstream to midstream: buys cotton or polyester feedstock and supplies yarn and fabric to weavers, garment makers, home-textile buyers and exporters.","howTheyMakeMoney":"Spinners and fibre makers earn a spread between raw-material and yarn or fibre prices, which swings with the cycle. Home and technical textile makers earn on value-added products and buyer relationships.","revenueSources":["Yarn and fibre sales","Fabric sales","Home-textile exports","Job-work processing","Technical textiles"],"operatingCosts":["Cotton or PTA and MEG feedstock","Power and fuel","Labour","Dyes and chemicals","Interest costs"],"customersAndEndMarkets":"Weavers, garment makers, home-textile buyers and global retailers, plus automotive, healthcare and infrastructure users of technical textiles.","demandSupplyDrivers":"Demand follows global and domestic clothing and home-textile demand; supply and spreads depend on cotton crops, China's textile output and polyester capacity additions.","domesticInternationalExposure":"Cotton and yarn are traded globally and exports are significant; polyester feedstock follows crude prices, and imported fibre and fabric compete.","capexIntensity":"High","capexNote":"Spinning, weaving, processing and fibre plants need large investment in modern machinery.","workingCapital":"Heavy: cotton is bought and stored in season, and receivables from weavers and exporters can be long.","regulation":"Cotton MSP and Cotton Corporation of India buying, import duty on cotton, anti-dumping duties on some fibres and yarns, PLI for man-made fibre and technical textiles, and state power tariffs.","competitiveAdvantages":"Scale, integration from yarn to fabric, modern machines, low power cost and buyer certifications help good companies.","drivers":[{"factor":"Commodity prices","impact":"Cotton price swings decide spinners' spreads and inventory gains or losses."},{"factor":"Crude oil prices","impact":"Polyester feedstock costs follow crude."},{"factor":"Exports & global demand","impact":"Yarn, fabric and home-textile exports depend on global retail demand."},{"factor":"Monsoon & agriculture","impact":"Cotton crop size and quality set raw-material availability."},{"factor":"Imports & dumping","impact":"Cheap imported fibre and fabric can undercut local prices."}],"risks":[{"risk":"Spread squeeze","detail":"Raw-material costs rising faster than yarn prices crush margins."},{"risk":"High fixed costs and debt","detail":"Capital-heavy mills suffer when utilisation falls."},{"risk":"Export slowdown","detail":"Weak overseas demand hits volumes and prices."},{"risk":"Power costs","detail":"Spinning and processing are power-hungry, so tariff increases hurt."}],"cyclicality":"Cyclical","cyclicalityNote":"Spreads and volumes swing with cotton crops, global demand and capacity cycles.","metricSet":"textiles","relatedBasicIndustries":["b-garments-and-apparels","b-trading-textile-products","b-petrochemicals","b-dyes-and-pigments","b-jute-and-jute-products"],"aliases":["textiles","yarn","spinning","fabric","cotton yarn","polyester","home textiles","technical textiles","weaving"],"themes":["Exports","China+1"]},"b-trading-textile-products":{"simplifiedExplanation":"These firms mainly do not make textiles; they source, buy and sell yarn, fabrics and garments, often managing supply chains for global retailers.","productsAndServices":["Garment sourcing for global brands","Yarn and fabric trading","Design and product development","Supply-chain and quality management","Merchandising services"],"valueChainPosition":"Middleman between manufacturers, often in several countries, and retailers or brands; organises design, sourcing, quality checks and logistics.","howTheyMakeMoney":"They earn a trading margin or sourcing commission on volumes handled, adding value through design, vendor networks and reliable delivery.","revenueSources":["Trading margin on goods sold","Sourcing and agency commissions","Design and product development fees"],"operatingCosts":["Cost of goods bought","Merchandisers and staff","Logistics and freight","Interest on working capital","Offices and design centres"],"customersAndEndMarkets":"Global and domestic apparel retailers and brands, garment makers and fabric buyers.","demandSupplyDrivers":"Volumes follow retailer orders and sourcing strategies; buyers spreading supply across countries can favour multi-country sourcers.","domesticInternationalExposure":"Often highly international, sourcing from Asian factories and selling to Western retailers, so currencies, tariffs and freight matter.","capexIntensity":"Low","capexNote":"Asset-light; spending goes on offices, design centres and systems.","workingCapital":"Receivables from retailers and advances to suppliers can be large, and thin margins make credit control important.","regulation":"Light, general business regulation; trade rules such as tariffs and rules of origin, and foreign-exchange rules under FEMA, matter.","competitiveAdvantages":"Long retailer relationships, broad vendor networks across countries and design skills; entry barriers are otherwise low.","drivers":[{"factor":"Exports & global demand","impact":"Order books follow sales and inventory levels at Western retailers."},{"factor":"Currency (INR)","impact":"Exchange-rate moves change margins on cross-border deals."},{"factor":"Trade tariffs","impact":"Tariff changes shift where retailers source and how much sourcers earn."},{"factor":"Interest rates","impact":"Funding receivables and supplier advances costs more when rates rise."}],"risks":[{"risk":"Customer concentration","detail":"A few large retailers often account for most business."},{"risk":"Thin margins","detail":"Small cost overruns or chargebacks can wipe out profit."},{"risk":"Retailer failures","detail":"Bankruptcy of a big buyer can leave unpaid receivables."},{"risk":"Tariff shocks","detail":"Sudden duty changes can disrupt sourcing plans."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes follow global apparel retail cycles.","metricSet":"trading-distribution","relatedBasicIndustries":["b-garments-and-apparels","b-other-textile-products","b-trading-and-distributors","b-diversified-retail"],"aliases":["textile trading","garment sourcing","apparel sourcing","fabric trading","yarn trading","sourcing agent","textile traders"],"themes":["Exports","China+1"]},"b-advertising-and-media-agencies":{"simplifiedExplanation":"Advertising agencies help brands get noticed. They create ad campaigns, plan where ads should appear, buy TV, print, digital and outdoor space for the client, and some run hoardings or do market research.","productsAndServices":["Creative ad campaigns","Media planning and buying","Digital and social media marketing","Outdoor hoardings and transit ads","Market research and analytics","Events and brand activation"],"valueChainPosition":"A middle layer between brands (advertisers) and media owners such as TV channels, publishers, digital platforms and outdoor sites.","howTheyMakeMoney":"They earn retainer or project fees for creative and strategy work and commissions or incentives on the media they buy. Outdoor firms earn rent for ad space on sites they own or lease from municipal bodies, airports and transit operators.","revenueSources":["Creative and strategy fees","Media buying commissions and incentives","Outdoor and transit ad space","Research and analytics fees","Event and activation fees"],"operatingCosts":["Employee salaries","Concession and site rentals for outdoor media","Production costs","Technology and data tools","Media costs passed through to clients"],"customersAndEndMarkets":"Consumer brands, FMCG, auto, telecom, financial services, real estate and e-commerce firms, and governments running public campaigns.","demandSupplyDrivers":"Demand follows corporate marketing budgets, product launches, festive seasons and elections. Many agencies and freelancers compete, and digital platforms that sell ads directly to brands squeeze agency fees.","domesticInternationalExposure":"Billings are mostly domestic; a few firms serve overseas clients or are part of global agency networks.","capexIntensity":"Low","capexNote":"Mostly a people business; outdoor firms spend more on hoarding structures and digital screens.","workingCapital":"Can be heavy because agencies often pay media owners before clients settle bills, and large clients and government bodies may pay late.","regulation":"Ad content follows the ASCI self-regulatory code and Consumer Protection Act rules on misleading ads; outdoor hoardings need municipal permissions.","competitiveAdvantages":"Long client relationships, creative talent, data capabilities and control of prime outdoor sites protect good agencies.","drivers":[{"factor":"Advertising spend","impact":"Brand marketing budgets are the main source of agency billings."},{"factor":"Consumer demand","impact":"Strong consumer spending encourages brands to launch products and advertise more."},{"factor":"Technology change","impact":"Programmatic and self-serve digital ads move some work in-house or to platforms."},{"factor":"Government policy","impact":"Government and election campaigns add billings in certain periods."}],"risks":[{"risk":"Client loss","detail":"Losing one large account can cut revenue sharply."},{"risk":"Fee pressure","detail":"Clients and platforms keep pushing commissions down."},{"risk":"Slow collections","detail":"Late-paying clients tie up cash and raise borrowing."},{"risk":"Concession renewals","detail":"Outdoor sites must be re-won in tenders when contracts expire."}],"cyclicality":"Cyclical","cyclicalityNote":"Ad budgets are among the first costs companies cut in a slowdown.","metricSet":"services-generic","relatedBasicIndustries":["b-electronic-media","b-print-media","b-web-based-media-and-service","b-tv-broadcasting-and-software-production"],"aliases":["advertising agency","ad agency","media agency","outdoor advertising","ooh","hoardings","digital marketing","marketing services"],"themes":["Digital"]},"b-electronic-media":{"simplifiedExplanation":"Electronic media companies run TV news channels, radio stations and similar broadcast outlets. They attract viewers or listeners and sell airtime to advertisers.","productsAndServices":["National TV news channels","Regional language news channels","FM radio stations","News websites, apps and video channels","Sponsored shows and events"],"valueChainPosition":"Downstream content owners: they gather news and hire talent, rent satellite or transmitter capacity, and reach audiences through cable, DTH, radio frequencies and the internet.","howTheyMakeMoney":"Most revenue comes from selling ad time, priced on audience ratings. Some also earn subscription fees from cable and DTH distributors and digital advertising on their websites and video channels.","revenueSources":["Advertising airtime","Subscription fees from distributors","Digital ads and video views","Sponsorships and events"],"operatingCosts":["Journalists and production staff","Satellite, transmitter and carriage fees","Radio licence fees","Marketing and distribution","Studios and technology"],"customersAndEndMarkets":"Advertisers across FMCG, auto, real estate, education and government; viewers and listeners are reached free or for a small fee.","demandSupplyDrivers":"Ad demand rises around elections, big news events and festive seasons. The number of channels is large, which keeps ad rates low, and viewers increasingly follow news on phones.","domesticInternationalExposure":"Almost entirely domestic; small international revenue comes from diaspora viewers and global digital platforms.","capexIntensity":"Medium","capexNote":"Studios, broadcast equipment and radio licences need upfront spend, but ongoing capex is moderate.","workingCapital":"Moderate; receivables from advertisers, agencies and government departments can stretch.","regulation":"Channels need permission from the Ministry of Information & Broadcasting, follow programme and advertising codes and FDI limits on news, and private FM frequencies are allotted through government auctions.","competitiveAdvantages":"A credible brand, leadership in a language or region and strong ratings let channels charge better ad rates.","drivers":[{"factor":"Advertising spend","impact":"Ad budgets of brands and government decide most of the revenue."},{"factor":"Election cycle","impact":"National and state elections bring bursts of political and government advertising."},{"factor":"Technology change","impact":"Viewers shifting to mobile and online video dilute TV and radio reach."},{"factor":"Regulation","impact":"Licensing, FDI caps and content codes shape who can operate and what they air."}],"risks":[{"risk":"Audience fragmentation","detail":"Social media and online video pull viewers away from channels."},{"risk":"Content action","detail":"Regulatory notices or bans over content can disrupt operations."},{"risk":"Ad rate pressure","detail":"Too many channels chasing the same advertisers keep rates low."},{"risk":"Ratings disputes","detail":"Doubts over audience measurement can affect ad pricing."}],"cyclicality":"Cyclical","cyclicalityNote":"Revenue depends heavily on advertising, which tracks the economy and the election calendar.","metricSet":"media","relatedBasicIndustries":["b-tv-broadcasting-and-software-production","b-print-media","b-web-based-media-and-service","b-media-and-entertainment"],"aliases":["news channel","tv news","radio","fm radio","broadcast media","electronic media","news broadcaster"],"themes":["Digital"]},"b-web-based-media-and-service":{"simplifiedExplanation":"These companies deliver content and services over the internet and mobile networks - news and video portals, music and game apps, and value-added services such as caller tunes and contests that telecom operators sell to their users.","productsAndServices":["Online news and content portals","Mobile value-added services","Caller tunes and content subscriptions","Casual games and quizzes","Digital video and audio content","White-label content platforms for telecom operators"],"valueChainPosition":"Downstream digital publishers and service providers that license or create content and reach users through app stores, search, social media and telecom operator billing.","howTheyMakeMoney":"They earn from digital advertising, user subscriptions and revenue sharing with telecom operators that bill customers for content services.","revenueSources":["Digital advertising","User subscriptions","Telecom operator revenue share","Content licensing","Sponsored content"],"operatingCosts":["Content licensing and creation","User acquisition and marketing","Cloud hosting and technology","Developers and staff","Revenue share to telecom operators and app stores"],"customersAndEndMarkets":"Mobile and internet users in India and abroad, advertisers, and telecom operators that bundle content with their plans.","demandSupplyDrivers":"Cheap data and smartphones grow the audience, but large global platforms capture most digital ad money and the barrier to starting a site or app is low.","domesticInternationalExposure":"Mixed; some firms earn much of their revenue from telecom operators and users overseas, so currency moves matter.","capexIntensity":"Low","capexNote":"Technology runs on cloud and leased infrastructure; spending is mostly on content and marketing.","workingCapital":"No physical inventory, but receivables from telecom operators and ad networks can be slow.","regulation":"Governed by the IT Act and IT Rules for digital media and intermediaries, data protection law, and TRAI rules on customer consent for paid mobile services.","competitiveAdvantages":"Telecom partnerships, large user bases, content rights and good data on user habits are the main barriers.","drivers":[{"factor":"Technology change","impact":"New apps and platforms can quickly make older services obsolete."},{"factor":"Advertising spend","impact":"Digital ad budgets fund free content and portals."},{"factor":"Regulation","impact":"Telecom and data rules affect how services are sold and billed."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts the value of overseas revenue."}],"risks":[{"risk":"Platform dependence","detail":"Changes by app stores, search engines or telecom partners can cut traffic or revenue."},{"risk":"Low entry barriers","detail":"New apps and creators compete for the same users."},{"risk":"Data and privacy rules","detail":"Stricter consent rules raise compliance costs."},{"risk":"Shrinking legacy services","detail":"Older mobile content services fade as users move to free apps."}],"cyclicality":"Mixed","cyclicalityNote":"Subscriptions are steadier, while advertising swings with the economy.","metricSet":"media","relatedBasicIndustries":["b-digital-entertainment","b-internet-and-catalogue-retail","b-electronic-media","b-other-telecom-services"],"aliases":["digital media","internet media","web portal","online content","mobile vas","value added services","caller tunes","digital publishing"],"themes":["Digital"]},"b-print-media":{"simplifiedExplanation":"Print media companies publish newspapers and magazines. They earn from advertisements printed in their pages and from the cover price readers pay.","productsAndServices":["Daily newspapers","Regional language newspapers","Magazines","E-papers and news websites","Classified and supplement advertising","Events and allied radio or digital businesses"],"valueChainPosition":"Downstream publishers that buy newsprint, ink and news content, print in their own plants and reach readers through distributors and newspaper vendors.","howTheyMakeMoney":"Advertising is the main earner, while circulation sales cover part of the cost of printing and distribution. Many publishers also run digital editions, radio or events.","revenueSources":["Display and classified advertising","Circulation (copy sales and subscriptions)","Government advertising","Digital advertising","Printing job work"],"operatingCosts":["Newsprint","Ink and printing plant costs","Editorial and sales staff","Distribution and vendor commissions","Marketing"],"customersAndEndMarkets":"Local and national advertisers such as retailers, real estate, education, auto and government, plus households that buy papers.","demandSupplyDrivers":"Regional language papers still have loyal readers in smaller towns, while metro readers have shifted to digital. Ad volumes rise in festive seasons and around elections.","domesticInternationalExposure":"Revenue is domestic, but much newsprint is imported, so global newsprint prices and the rupee directly affect costs.","capexIntensity":"Medium","capexNote":"Printing presses are long-lived; new spend is mostly maintenance and upgrades.","workingCapital":"Newsprint must be stocked ahead, and dues from agencies and government advertising can take long to collect.","regulation":"Publications register with the Press Registrar General of India, news publishing has FDI limits, and government ad rates are set by the Central Bureau of Communication.","competitiveAdvantages":"A strong local brand, reading habit, distribution reach and leadership in a region are hard for newcomers to copy.","drivers":[{"factor":"Advertising spend","impact":"Local and national ad budgets make up most of the revenue."},{"factor":"Newsprint prices","impact":"Newsprint is the biggest raw material, so global price spikes squeeze margins."},{"factor":"Currency (INR)","impact":"A weaker rupee makes imported newsprint costlier."},{"factor":"Technology change","impact":"Readers moving to phones slowly reduce circulation."},{"factor":"Government policy","impact":"Government ad rates and spending affect a meaningful slice of revenue."}],"risks":[{"risk":"Structural decline","detail":"Younger readers prefer digital news, shrinking print reach."},{"risk":"Newsprint cost","detail":"Sharp rises in imported newsprint prices hit profits quickly."},{"risk":"Ad slowdown","detail":"Weak retail, property or auto ad spending cuts revenue."},{"risk":"Government dues","detail":"Delayed payments for government ads strain cash flow."}],"cyclicality":"Cyclical","cyclicalityNote":"Ad revenue tracks the economy, while newsprint costs follow global paper cycles.","metricSet":"media","relatedBasicIndustries":["b-electronic-media","b-paper-and-paper-products","b-printing-and-publication","b-advertising-and-media-agencies"],"aliases":["newspaper","newspapers","print media","magazine","regional newspaper","dailies","news publisher"],"themes":[]},"b-film-production-distribution-and-exhibition":{"simplifiedExplanation":"This industry makes films, distributes them to cinemas and streaming platforms, and runs the cinema halls where audiences watch them.","productsAndServices":["Feature film production","Film distribution rights","Multiplex and single-screen cinemas","Cinema food and beverages","On-screen advertising","Sale of satellite, streaming and music rights"],"valueChainPosition":"Producers sit upstream creating content, distributors buy and release films in the middle, and exhibitors are downstream selling tickets and snacks to audiences.","howTheyMakeMoney":"Producers recover costs from their theatrical share and the sale of streaming, TV and music rights. Exhibitors share ticket revenue with distributors and keep most of the food and advertising income.","revenueSources":["Box office ticket sales","Food and beverage sales","In-cinema advertising","Streaming and satellite rights","Music and overseas rights"],"operatingCosts":["Distributor share of ticket revenue","Cinema rent and upkeep","Film production and star fees","Staff and electricity","Food and beverage inputs","Marketing and promotion"],"customersAndEndMarkets":"Moviegoers in cities and towns, streaming and TV platforms that buy content, and brands that advertise in cinemas.","demandSupplyDrivers":"Footfalls depend on a steady flow of hit films across languages; streaming competes for viewers and shortens the period films play only in theatres.","domesticInternationalExposure":"Mainly domestic; some films earn from overseas releases and dubbed versions, and foreign releases add to cinema footfalls.","capexIntensity":"High","capexNote":"Exhibitors spend heavily on screen fit-outs, seating and projection, while producers sink money into films upfront.","workingCapital":"Cinemas run on cash ticket sales with little inventory, but producers lock up money in films for long periods before release.","regulation":"Films need certification from the CBFC under the Cinematograph Act; tickets attract GST and, in some states, local entertainment taxes.","competitiveAdvantages":"Prime cinema locations, scale in dealing with producers and advertisers, and established production banners with talent relationships give an edge.","drivers":[{"factor":"Content slate","impact":"A run of hit or flop films directly drives footfalls and producer earnings."},{"factor":"Consumer demand","impact":"Spending on outings decides ticket and snack sales."},{"factor":"Technology change","impact":"Streaming platforms compete for viewers but also buy film rights."},{"factor":"Regulation","impact":"Certification, content disputes and ticket taxes affect releases and pricing."},{"factor":"Real estate cycle","impact":"New malls and commercial projects create sites for new screens."}],"risks":[{"risk":"Content risk","detail":"Flops can leave producers with losses and cinemas half empty."},{"risk":"Streaming competition","detail":"Early streaming releases reduce reasons to visit cinemas."},{"risk":"Piracy","detail":"Illegal copies cut into ticket and rights income."},{"risk":"Fixed costs","detail":"Rent and staff costs stay the same even when films flop."}],"cyclicality":"Mixed","cyclicalityNote":"Spending is discretionary, but results depend more on the film slate than on the economic cycle.","metricSet":"media","relatedBasicIndustries":["b-tv-broadcasting-and-software-production","b-media-and-entertainment","b-digital-entertainment","b-amusement-parks-other-recreation"],"aliases":["film production","movies","cinema","multiplex","film distribution","box office","bollywood","movie theatre"],"themes":[]},"b-digital-entertainment":{"simplifiedExplanation":"Digital entertainment companies make or publish games, run esports and online entertainment platforms, and offer content people enjoy on phones, computers and consoles.","productsAndServices":["Mobile and PC games","Esports leagues and tournaments","Kids' learning and casual games","Game publishing and distribution","In-game and mobile advertising","Fan engagement and streaming platforms"],"valueChainPosition":"Content creators and publishers that hire developers, rent cloud capacity and distribute through app stores, consoles and their own platforms to players and advertisers.","howTheyMakeMoney":"They earn from in-app purchases, subscriptions, game sales and advertising shown to players, plus sponsorships and media rights in esports.","revenueSources":["In-app purchases and subscriptions","In-game advertising","Game sales and licensing","Esports sponsorships and media rights","Ad-tech services"],"operatingCosts":["Game developers and creative staff","User acquisition marketing","App store and platform fees","Cloud servers","Content licensing and royalties"],"customersAndEndMarkets":"Gamers and young users in India and abroad, advertisers seeking young audiences, and esports sponsors.","demandSupplyDrivers":"Smartphone reach and cheap data expand the audience, but a few successful titles bring most revenue and competition from global studios is intense.","domesticInternationalExposure":"Often significant overseas revenue through global app stores and acquired studios, so currency moves and global gaming trends matter.","capexIntensity":"Low","capexNote":"Spending goes into people and game development rather than physical assets.","workingCapital":"Light; app store and ad network payouts arrive with a lag, and there is no physical inventory.","regulation":"A central online gaming law bans real-money games while promoting esports and social games; IT Rules, GST and data protection rules also apply.","competitiveAdvantages":"Hit game titles and characters, loyal player communities and skill in acquiring users cheaply are key; a portfolio of games spreads hit risk.","drivers":[{"factor":"Technology change","impact":"Better phones, networks and new formats open new game genres and audiences."},{"factor":"Regulation","impact":"Rules on game formats and taxes can open or close entire business lines."},{"factor":"Consumer demand","impact":"More time spent on phones grows the number of paying players."},{"factor":"Advertising spend","impact":"Brands pay to reach young gamers through in-game ads."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts the value of overseas earnings."}],"risks":[{"risk":"Regulatory shock","detail":"Sudden bans or tax changes can wipe out a segment."},{"risk":"Hit dependence","detail":"Revenue can fall sharply when a popular title fades."},{"risk":"Platform fees","detail":"App store charges and policy changes cut margins."},{"risk":"Acquisition integration","detail":"Bought studios may underperform or lose key staff."}],"cyclicality":"Mixed","cyclicalityNote":"Spending is discretionary but small-ticket, so it is less tied to the economy than big purchases.","metricSet":"media","relatedBasicIndustries":["b-web-based-media-and-service","b-media-and-entertainment","b-software-products","b-leisure-products"],"aliases":["gaming","online gaming","mobile games","esports","video games","game developer","digital entertainment"],"themes":["Digital"]},"b-media-and-entertainment":{"simplifiedExplanation":"This group covers mixed media and entertainment businesses - music labels, radio networks, visual effects and post-production studios, and news-plus-entertainment networks - that do not fit one narrower category.","productsAndServices":["Music catalogues and streaming royalties","FM radio stations","Visual effects and animation","Post-production services","News and entertainment channels","Live events and concerts"],"valueChainPosition":"Content owners and service providers in the middle of the chain, supplying music, shows and effects to streaming platforms, broadcasters, film studios and advertisers.","howTheyMakeMoney":"Music labels earn royalties each time songs are streamed, broadcast or used in films and ads; radio and TV networks sell ad time; VFX studios charge film and streaming studios project fees.","revenueSources":["Music licensing and royalties","Advertising","VFX and post-production fees","Content syndication","Events and sponsorships"],"operatingCosts":["Content acquisition and artist royalties","Creative and technical staff","Studio technology and software","Licence fees","Marketing"],"customersAndEndMarkets":"Streaming apps, TV channels, film studios in India and abroad, advertisers, and audiences at live events.","demandSupplyDrivers":"Paid music streaming, film output and global studio budgets drive demand; older content libraries keep earning as new platforms license them.","domesticInternationalExposure":"Mixed; VFX and animation studios export services to global film and streaming studios, while music and radio are largely domestic.","capexIntensity":"Medium","capexNote":"Buying music catalogues and studio technology needs upfront spend, but heavy physical assets are few.","workingCapital":"Royalty dues from platforms and project dues from studios can be lumpy, and advances to artists and producers tie up cash.","regulation":"Music rights are governed by the Copyright Act and royalty-collecting societies; radio stations need Ministry of Information & Broadcasting permission.","competitiveAdvantages":"Large owned content libraries, long-term artist contracts and technical skills trusted by global studios are hard to copy.","drivers":[{"factor":"Technology change","impact":"Streaming turns old music and shows into fresh licensing income."},{"factor":"Advertising spend","impact":"Radio and channel revenue moves with brand ad budgets."},{"factor":"Exports & global demand","impact":"Global studio and streaming budgets decide VFX and animation work."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts earnings from overseas studio clients."},{"factor":"Regulation","impact":"Copyright and royalty rules decide how much platforms pay content owners."}],"risks":[{"risk":"Platform bargaining power","detail":"A few large streaming platforms negotiate royalty rates."},{"risk":"Global studio slowdown","detail":"Strikes or budget cuts at foreign studios reduce VFX work."},{"risk":"Copyright disputes","detail":"Legal fights over rights can block income from a catalogue."},{"risk":"Ad slowdown","detail":"Radio and channel revenue falls when brands cut spending."}],"cyclicality":"Mixed","cyclicalityNote":"Royalty income is steady, while ad and project income moves with the cycle.","metricSet":"media","relatedBasicIndustries":["b-tv-broadcasting-and-software-production","b-film-production-distribution-and-exhibition","b-electronic-media","b-digital-entertainment"],"aliases":["music label","music company","radio network","vfx","animation","post production","media and entertainment"],"themes":["Digital","Exports"]},"b-tv-broadcasting-and-software-production":{"simplifiedExplanation":"These companies run TV channels, deliver them to homes through cable and DTH, or produce TV serials and shows (called 'software' in industry language).","productsAndServices":["General entertainment and regional TV channels","Movie and sports channels","Cable TV and broadband","DTH satellite TV","TV serial and show production","Streaming apps run by broadcasters"],"valueChainPosition":"Producers are upstream making shows, broadcasters package channels in the middle, and cable operators, MSOs and DTH firms are downstream, delivering signals to homes.","howTheyMakeMoney":"Broadcasters earn advertising plus subscription fees passed on by distributors. Cable and DTH firms keep part of what households pay and earn carriage and placement fees from channels and broadband income; producers earn per-episode fees.","revenueSources":["Advertising","Subscription fees","Carriage and placement fees","Broadband subscriptions","Content syndication and production fees"],"operatingCosts":["Programming and content costs","Sports and film rights","Set-top boxes and network upkeep","Pay-channel fees paid to broadcasters","Staff and marketing"],"customersAndEndMarkets":"Households paying for TV, advertisers across consumer categories, and streaming platforms that buy shows.","demandSupplyDrivers":"Ad spending and household TV subscriptions drive revenue, while younger and urban viewers are moving to streaming and free satellite TV, which slows pay-TV growth.","domesticInternationalExposure":"Mostly domestic; some channels earn from overseas Indian audiences and content sales abroad.","capexIntensity":"Medium","capexNote":"Broadcasters spend mainly on content, while cable and DTH operators need regular spend on set-top boxes and networks.","workingCapital":"Content and sports rights are paid upfront, and collections from local cable operators can be slow.","regulation":"TRAI tariff orders decide how channels are priced and bundled, the Ministry of Information & Broadcasting licenses channels and distribution platforms, and BARC measures ratings.","competitiveAdvantages":"Popular channels and content libraries, regional language leadership and large subscriber networks give bargaining power.","drivers":[{"factor":"Advertising spend","impact":"Ad budgets of consumer brands are a large part of broadcaster revenue."},{"factor":"Regulation","impact":"TRAI pricing rules shape subscription income and channel bundling."},{"factor":"Technology change","impact":"Streaming and smart TVs pull viewers away from cable and DTH."},{"factor":"Consumer demand","impact":"Household budgets decide how many pay-TV packs are bought."},{"factor":"Sports rights costs","impact":"Bidding wars for cricket and other sports raise content costs."}],"risks":[{"risk":"Cord-cutting","detail":"Homes dropping cable or DTH for streaming reduce subscriptions."},{"risk":"Tariff regulation","detail":"Changes in pricing rules can cut subscription income."},{"risk":"Content cost inflation","detail":"Costlier shows and sports rights squeeze margins."},{"risk":"Free TV competition","detail":"Free satellite platforms attract price-sensitive homes."}],"cyclicality":"Mixed","cyclicalityNote":"Subscription revenue is steady, but advertising moves with the economy.","metricSet":"media","relatedBasicIndustries":["b-electronic-media","b-media-and-entertainment","b-film-production-distribution-and-exhibition","b-telecom-cellular-and-fixed-line-services"],"aliases":["tv channel","broadcaster","television","cable tv","dth","mso","tv production","serials","pay tv"],"themes":["Digital"]},"b-printing-and-publication":{"simplifiedExplanation":"These companies publish books and learning material, print for others, or provide editing, typesetting and digital content services to publishers around the world.","productsAndServices":["School and college textbooks","Academic and professional publishing services","Typesetting and digital conversion","E-learning content and platforms","Book and commercial printing","Journals and magazines"],"valueChainPosition":"Midstream between authors or publishers and readers: they buy paper and content rights and supply books, print jobs or content services to schools, publishers and institutions.","howTheyMakeMoney":"Publishers earn from book and digital sales to schools and readers, printers charge per job, and content-service firms earn contract fees from global publishers and learning companies.","revenueSources":["Book and textbook sales","Publishing service contracts","Printing job work","Digital platform subscriptions","Rights and licensing"],"operatingCosts":["Paper and printing materials","Editorial and technical staff","Author royalties","Distribution and returns","Technology"],"customersAndEndMarkets":"Schools, students, libraries, global academic and education publishers, and corporate print buyers.","demandSupplyDrivers":"School enrolment, curriculum changes and outsourcing by global publishers drive demand, while the shift to digital formats reduces print volumes.","domesticInternationalExposure":"Content-service firms earn largely in foreign currency from overseas publishers; domestic publishers depend on Indian schools and paper prices.","capexIntensity":"Low","capexNote":"Printers need presses, but publishing and content services are mainly people- and software-based.","workingCapital":"Book publishers build inventory before the school season and face returns and slow dealer payments; service firms usually bill monthly.","regulation":"Copyright law protects content, and curriculum choices by NCERT, CBSE and state boards affect textbook demand.","competitiveAdvantages":"Long relationships with global publishers, owned titles and curriculum know-how are the main moats.","drivers":[{"factor":"Exports & global demand","impact":"Outsourcing budgets of global publishers drive content-service revenue."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the rupee value of export contracts."},{"factor":"Government policy","impact":"Curriculum reforms and textbook policies change what schools buy."},{"factor":"Commodity prices","impact":"Paper price swings change printing and book costs."},{"factor":"Technology change","impact":"AI tools and digital formats change the work publishers outsource."}],"risks":[{"risk":"Client concentration","detail":"A few large publishers may account for much of the revenue."},{"risk":"Digital disruption","detail":"Automation and digital formats can reduce demand for traditional services."},{"risk":"Paper cost","detail":"Sharp paper price rises squeeze print margins."},{"risk":"Curriculum shifts","detail":"Sudden syllabus changes can leave unsold stock."}],"cyclicality":"Mixed","cyclicalityNote":"Education demand is steady, but export services follow global publishers' budgets.","metricSet":"services-generic","relatedBasicIndustries":["b-print-media","b-paper-and-paper-products","b-e-learning","b-it-enabled-services","b-stationary"],"aliases":["publishing","book publisher","textbooks","printing press","publication","content services","typesetting"],"themes":["Exports"]},"b-residential-commercial-projects":{"simplifiedExplanation":"Real estate developers buy land, build homes, offices, malls or plots, and sell or lease them. Their fortunes follow the property cycle.","productsAndServices":["Apartments and villas","Plotted developments","Office buildings","Shopping malls","Warehouses and industrial parks","Joint development projects with landowners"],"valueChainPosition":"Downstream builders that buy land, construction materials (cement, steel, fittings) and contractor services, and sell finished space to home buyers, businesses and REITs.","howTheyMakeMoney":"Residential developers sell units, often collecting payments in stages during construction; commercial developers earn rent or sell completed buildings. Profit is the selling price minus land, construction and interest costs.","revenueSources":["Sale of homes and plots","Office and mall lease rentals","Sale of assets to REITs or investors","Development management fees","Land sales"],"operatingCosts":["Land and approval costs","Construction materials and contractors","Interest on borrowings","Marketing and broker fees","Stamp duty and taxes"],"customersAndEndMarkets":"Home buyers and investors (including NRIs), companies leasing offices, retailers in malls and logistics firms using warehouses.","demandSupplyDrivers":"Home demand responds to loan rates, incomes and confidence, while supply depends on land availability and approvals. Office demand follows hiring by IT, global capability centres and financial firms.","domesticInternationalExposure":"Mostly domestic; NRIs are an important buyer group and global companies drive office leasing.","capexIntensity":"High","capexNote":"Land and construction absorb large sums, though for sale projects this sits as inventory rather than fixed assets.","workingCapital":"Very heavy: land and unsold flats tie up money for years, partly offset by customer advances during construction.","regulation":"RERA requires project registration, a separate account for buyer money and timely delivery; state approvals, stamp duty and GST rules also matter.","competitiveAdvantages":"A trusted brand, low-cost land bank, strong balance sheet and on-time delivery record attract buyers and lenders.","drivers":[{"factor":"Interest rates","impact":"Lower home-loan and project-loan rates lift affordability and margins."},{"factor":"Real estate cycle","impact":"Prices and sales move in long up and down cycles."},{"factor":"Credit growth","impact":"Easy availability of home loans widens the buyer pool."},{"factor":"Government policy","impact":"Stamp duty cuts, approval reforms and housing schemes influence demand and launches."},{"factor":"Commodity prices","impact":"Cement, steel and labour costs affect construction margins."}],"risks":[{"risk":"Demand slowdown","detail":"Weak sales leave unsold inventory and stretched cash flows."},{"risk":"Execution delays","detail":"Late approvals or construction delays bring RERA penalties and buyer anger."},{"risk":"High debt","detail":"Borrowed land purchases become risky if sales slow."},{"risk":"Land title disputes","detail":"Legal challenges can freeze projects for years."}],"cyclicality":"Cyclical","cyclicalityNote":"Sales and prices move in long cycles with interest rates and buyer confidence.","metricSet":"realty","relatedBasicIndustries":["b-real-estate-investment-trusts-reits","b-real-estate-related-services","b-civil-construction","b-cement-and-cement-products","b-housing-finance-company"],"aliases":["real estate","realty","builder","property developer","housing","residential projects","commercial real estate","real estate developer"],"themes":["Housing","Urbanisation"]},"b-real-estate-related-services":{"simplifiedExplanation":"These firms support the property market without mainly building homes for sale - property brokerage, property and facility management, valuation and advice, and owning or running malls and land parcels for rent.","productsAndServices":["Property brokerage and leasing","Property and facility management","Mall and commercial space leasing","Valuation and advisory","Online property listings","Land development for others"],"valueChainPosition":"A service layer around the property market, working for developers, landlords, tenants and buyers.","howTheyMakeMoney":"Brokers earn commissions on sales and leases, managers charge fees for running buildings, and asset owners earn rent and maintenance charges.","revenueSources":["Brokerage commissions","Property management fees","Rental and maintenance income","Advisory and valuation fees"],"operatingCosts":["Staff and sales teams","Building maintenance and utilities","Marketing","Interest on property loans"],"customersAndEndMarkets":"Developers, landlords, corporate tenants, retailers and individual buyers or renters.","demandSupplyDrivers":"Activity rises with property transactions and office or retail leasing; brokerage is fragmented with many small local players.","domesticInternationalExposure":"Largely domestic, though leasing demand is influenced by multinational tenants.","capexIntensity":"Medium","capexNote":"Pure service firms need little capital, while those that own malls or land carry heavy assets.","workingCapital":"Service firms collect fees after deals close; property owners receive monthly rent and hold tenant security deposits.","regulation":"RERA requires real estate agents to register; state rules on stamp duty, leasing and land use apply.","competitiveAdvantages":"A network of clients, local market knowledge and well-located assets give an edge.","drivers":[{"factor":"Real estate cycle","impact":"Transaction volumes decide brokerage and advisory income."},{"factor":"Interest rates","impact":"Rates affect buyer activity and the cost of carrying owned property."},{"factor":"Consumer demand","impact":"Retail spending drives footfalls and rent at malls."},{"factor":"Office leasing demand","impact":"Corporate expansion lifts leasing and facility management work."}],"risks":[{"risk":"Transaction slowdown","detail":"Fewer deals mean lower commissions."},{"risk":"Vacancy","detail":"Empty space in owned malls or offices cuts rent."},{"risk":"Fragmentation","detail":"Many small brokers and online portals compete on fees."},{"risk":"Regulatory compliance","detail":"RERA and state rules add paperwork and liability."}],"cyclicality":"Cyclical","cyclicalityNote":"Income rises and falls with property transactions and leasing activity.","metricSet":"services-generic","relatedBasicIndustries":["b-residential-commercial-projects","b-real-estate-investment-trusts-reits","b-internet-and-catalogue-retail","b-diversified-commercial-services"],"aliases":["property services","real estate broker","property management","facility management","mall owner","property consultant","leasing"],"themes":[]},"b-real-estate-investment-trusts-reits":{"simplifiedExplanation":"A REIT is like a mutual fund that owns rent-earning buildings - mainly offices, malls and warehouses. Investors buy listed units and receive a regular share of the rent.","productsAndServices":["Office parks","Shopping malls","Warehouses and logistics parks","Hotels and mixed-use assets within the trust","Small and medium REIT schemes"],"valueChainPosition":"Owners at the end of the chain: they buy completed, leased buildings from developers (often their sponsors) and lease space to businesses.","howTheyMakeMoney":"They collect rent and maintenance charges from tenants, pay operating costs and interest, and pass most of the remaining cash to unitholders as distributions.","revenueSources":["Lease rentals","Maintenance and service charges","Parking and other income","Interest and dividends from asset-holding companies"],"operatingCosts":["Property maintenance","Manager and trustee fees","Interest on borrowings","Property taxes and insurance"],"customersAndEndMarkets":"Corporate tenants such as IT firms, global capability centres, banks and retailers; investors include mutual funds, institutions and retail unitholders.","demandSupplyDrivers":"Office absorption, rent growth, occupancy and new supply in each micro-market drive income, while interest rates affect both borrowing costs and how investors value the units.","domesticInternationalExposure":"Assets are in India, but tenants are often multinational firms and many investors are foreign institutions.","capexIntensity":"High","capexNote":"Buying and building assets needs large capital, funded by debt and new units.","workingCapital":"Light; rent is collected monthly and tenants pay security deposits.","regulation":"SEBI REIT Regulations set rules on borrowing, asset mix, valuation, governance and the mandatory distribution of most cash flows.","competitiveAdvantages":"Well-located assets, quality tenants on long leases and a sponsor pipeline of new buildings matter most.","drivers":[{"factor":"Interest rates","impact":"Lower rates cut borrowing costs and make distribution yields look more attractive."},{"factor":"Real estate cycle","impact":"Office demand and rents decide occupancy and income growth."},{"factor":"Exports & global demand","impact":"Hiring by global firms in India drives office leasing."},{"factor":"Capital market activity","impact":"Investor appetite decides how easily REITs raise money for new assets."},{"factor":"Regulation","impact":"SEBI and tax rules shape REIT structure and investor returns."}],"risks":[{"risk":"Vacancy","detail":"Tenant exits or new supply nearby can lower occupancy and rents."},{"risk":"Rate rises","detail":"Higher rates raise borrowing costs and weigh on unit prices."},{"risk":"Tenant concentration","detail":"A few large tenants or one sector may dominate income."},{"risk":"Changing work habits","detail":"Hybrid working can reduce office space demand."}],"cyclicality":"Mixed","cyclicalityNote":"Long leases with rent escalations steady the income, but occupancy and valuations follow the office cycle.","metricSet":"reit","relatedBasicIndustries":["b-residential-commercial-projects","b-real-estate-related-services","b-asset-management-company","b-investment-company"],"aliases":["reit","reits","real estate investment trust","sm reit","office reit","mall reit","rental yield"],"themes":[]},"b-hotels-and-resorts":{"simplifiedExplanation":"Hotel companies run hotels and resorts where travellers stay, eat and hold events. Some own the buildings; others manage or franchise hotels for owners and earn a fee.","productsAndServices":["Room stays","Restaurants and bars","Banquets, weddings and conferences","Resorts and holiday membership clubs","Hotel management and franchise services","Spa and leisure services"],"valueChainPosition":"Downstream service providers that buy food, utilities, linen and labour and sell stays to leisure travellers, corporates and travel platforms.","howTheyMakeMoney":"Owned hotels earn room rate times occupancy plus food and event income; management contracts and franchises earn fees on hotel revenue and profit; holiday clubs earn upfront membership fees.","revenueSources":["Room revenue","Food, beverage and banquets","Management and franchise fees","Holiday membership fees","Spa and other services"],"operatingCosts":["Staff wages","Power and fuel","Food and beverage inputs","Repairs and upkeep","Lease rentals and licence fees","Commissions to travel portals"],"customersAndEndMarkets":"Business and leisure travellers, wedding and conference organisers, airline crews and foreign tourists.","demandSupplyDrivers":"Demand comes from domestic travel, weddings, conferences and foreign tourists; new hotels take years to build, so room rates rise when demand outpaces supply.","domesticInternationalExposure":"Mostly domestic demand; foreign tourists and a few overseas properties add some currency exposure.","capexIntensity":"High","capexNote":"Building and renovating hotels is costly, which is why many groups now grow through asset-light management contracts.","workingCapital":"Light; guests pay quickly, though corporate and travel-agent dues take time, and demand is seasonal with stronger winter and wedding months.","regulation":"Hotels need FSSAI food licences, state liquor and fire licences and Ministry of Tourism star classification; GST rates on room tariffs affect pricing.","competitiveAdvantages":"Strong brands, prime locations, loyalty programmes and a pipeline of managed hotels support pricing power.","drivers":[{"factor":"Tourism & travel","impact":"Leisure, business and wedding travel fill rooms and banquet halls."},{"factor":"Consumer demand","impact":"Rising incomes increase spending on stays and dining out."},{"factor":"Infrastructure spending","impact":"New airports, roads and convention centres open new destinations."},{"factor":"Interest rates","impact":"Hotel owners carry large loans, so rates affect profits."},{"factor":"Government policy","impact":"GST, visa rules and tourism promotion shape demand."}],"risks":[{"risk":"Demand shocks","detail":"Pandemics, conflicts or disasters can empty hotels quickly."},{"risk":"Oversupply","detail":"Too many new rooms in a city push down room rates."},{"risk":"Cost inflation","detail":"Wages, power and food costs squeeze margins."},{"risk":"Debt burden","detail":"Owned-hotel models with high debt suffer in downturns."}],"cyclicality":"Cyclical","cyclicalityNote":"High fixed costs make profits swing sharply with occupancy and room rates.","metricSet":"hotels-leisure","relatedBasicIndustries":["b-restaurants","b-tour-travel-related-services","b-amusement-parks-other-recreation","b-airline","b-wellness"],"aliases":["hotel","hotels","resort","hospitality","holiday club","timeshare","luxury hotel","hotel chain"],"themes":["Tourism"]},"b-restaurants":{"simplifiedExplanation":"Restaurant companies run chains of pizza, burger, coffee and casual-dining outlets, often as franchisees of global brands, as well as food courts at airports and highways.","productsAndServices":["Quick-service restaurants","Casual and fine dining","Cafes and coffee chains","Home delivery","Airport and travel food courts","Own restaurant brands"],"valueChainPosition":"Downstream: they buy ingredients, rent outlets and serve consumers directly or through food delivery apps.","howTheyMakeMoney":"They earn the gap between menu prices and the cost of ingredients, rent and staff; profit grows when existing stores sell more and new stores mature.","revenueSources":["Dine-in sales","Delivery orders","Takeaway","Travel retail concessions","Franchise income from own brands"],"operatingCosts":["Food ingredients (dairy, chicken, flour, oil)","Rent","Staff","Royalties to brand owners","Delivery app commissions","Power and cooking gas"],"customersAndEndMarkets":"Urban families, young people and office workers, plus travellers at airports, railway stations and highways.","demandSupplyDrivers":"Eating out grows with incomes, urbanisation and delivery apps, but many new brands and cloud kitchens compete hard on price.","domesticInternationalExposure":"Mainly domestic; a few firms run outlets in neighbouring countries, and royalties flow to foreign brand owners.","capexIntensity":"Medium","capexNote":"Each new outlet needs fit-out and kitchen equipment, recovered over several years.","workingCapital":"Low or negative; customers pay immediately while suppliers give credit, and perishable inventory is small.","regulation":"FSSAI food safety licences, municipal and fire licences and GST on restaurant bills apply; bars need state liquor licences.","competitiveAdvantages":"Popular brands, efficient supply chains, store scale and good locations protect margins.","drivers":[{"factor":"Consumer demand","impact":"Spending on eating out and ordering in decides sales per store."},{"factor":"Commodity prices","impact":"Dairy, wheat, poultry and edible oil prices move food costs."},{"factor":"Technology change","impact":"Delivery apps widen reach but take a commission on each order."},{"factor":"Tourism & travel","impact":"Air and rail passenger traffic drives travel food outlets."}],"risks":[{"risk":"Weak same-store sales","detail":"Slower footfalls at existing outlets hurt margins quickly."},{"risk":"Ingredient inflation","detail":"Food costs can rise faster than menu prices."},{"risk":"Aggregator dependence","detail":"Delivery platforms control customer access and fees."},{"risk":"Franchise terms","detail":"Brand owners set royalties and can change agreements on renewal."}],"cyclicality":"Mixed","cyclicalityNote":"Small-ticket spending holds up better than big purchases, but footfalls dip when budgets tighten.","metricSet":"restaurants","relatedBasicIndustries":["b-hotels-and-resorts","b-packaged-foods","b-dairy-products","b-e-retail-e-commerce","b-meat-products-including-poultry"],"aliases":["qsr","quick service restaurant","fast food","restaurant chain","cafe","pizza chain","food service","casual dining"],"themes":["Urban consumption"]},"b-amusement-parks-other-recreation":{"simplifiedExplanation":"These businesses run amusement and water parks, theme parks, family entertainment centres and casinos - places people visit for fun.","productsAndServices":["Amusement and water parks","Theme parks","Resorts attached to parks","Casinos and gaming floors","Family entertainment centres","Snow parks and indoor attractions"],"valueChainPosition":"Downstream experience providers that buy rides, land and services and sell tickets and experiences to visitors.","howTheyMakeMoney":"They charge entry tickets and earn more from food, merchandise and stays inside the park; casinos earn the house margin on bets placed.","revenueSources":["Entry tickets","Food and beverage","Merchandise","Resort stays","Gaming revenue"],"operatingCosts":["Staff","Ride maintenance and safety","Electricity and water","Marketing","Licence fees and taxes"],"customersAndEndMarkets":"Families, school groups, tourists and corporate groups; casinos serve adult visitors and tourists.","demandSupplyDrivers":"Footfalls peak during school holidays and festivals and fall in heavy rain; new parks take years to build, which limits supply.","domesticInternationalExposure":"Visitors are mostly domestic; rides and equipment are often imported, so the rupee affects capex.","capexIntensity":"High","capexNote":"Land, rides and attractions need large upfront investment, plus regular new rides to keep visitors coming back.","workingCapital":"Very light; visitors pay upfront and inventory is small, but revenue is seasonal.","regulation":"Parks need state safety and entertainment licences; casinos operate only where state law allows them and face high GST on gaming.","competitiveAdvantages":"Large land parcels near cities, a strong brand, a good safety record and repeat-visit attractions are hard to copy.","drivers":[{"factor":"Tourism & travel","impact":"Tourist flows to a city or state lift park and casino visits."},{"factor":"Consumer demand","impact":"Spending on family outings decides footfalls and spend per visitor."},{"factor":"Weather & holidays","impact":"Monsoon rains and school calendars cause big seasonal swings."},{"factor":"Regulation","impact":"Casino licences and gaming taxes decide whether that business is viable."},{"factor":"Infrastructure spending","impact":"Better roads and transport widen the catchment area of parks."}],"risks":[{"risk":"Safety incidents","detail":"An accident can hurt the brand and bring shutdowns."},{"risk":"Weather","detail":"Unusually heavy rain or heat cuts visits."},{"risk":"Gaming tax and licence changes","detail":"Higher taxes or licence curbs can hurt casino profits."},{"risk":"Few locations","detail":"Dependence on a handful of parks concentrates risk."}],"cyclicality":"Cyclical","cyclicalityNote":"Visits are discretionary and drop quickly when consumers cut back.","metricSet":"hotels-leisure","relatedBasicIndustries":["b-hotels-and-resorts","b-film-production-distribution-and-exhibition","b-digital-entertainment","b-tour-travel-related-services"],"aliases":["amusement park","water park","theme park","casino","recreation","entertainment park","family entertainment centre"],"themes":["Tourism"]},"b-wellness":{"simplifiedExplanation":"Wellness companies help people stay healthy outside regular hospitals - through Ayurveda and traditional medicine clinics, spas, fitness centres and lifestyle programmes.","productsAndServices":["Ayurveda clinics and hospitals","Traditional and herbal medicines","Spas and therapy centres","Fitness and weight-management programmes","Online consultations","Wellness retreats"],"valueChainPosition":"Downstream service providers that buy herbal inputs, medicines and premises and serve patients and consumers directly.","howTheyMakeMoney":"They earn consultation and treatment fees, sell programme packages and memberships, and sell medicines or products to their patients.","revenueSources":["Consultation and therapy fees","Medicine and product sales","Memberships and packages","Inpatient stays at wellness hospitals"],"operatingCosts":["Doctors, therapists and staff","Clinic rent","Herbal raw materials","Marketing and digital outreach","Medicine manufacturing"],"customersAndEndMarkets":"Health-conscious urban and semi-urban consumers, people with chronic lifestyle conditions and wellness tourists.","demandSupplyDrivers":"Rising awareness of lifestyle diseases and interest in traditional medicine support demand; the market is fragmented with many local practitioners.","domesticInternationalExposure":"Largely domestic, with some wellness tourism and export of herbal products.","capexIntensity":"Medium","capexNote":"Clinics and small hospitals need moderate spending on space and equipment.","workingCapital":"Light; clients pay upfront for treatments and packages, while medicine stocks need managing.","regulation":"AYUSH medicines need licences under the Drugs and Cosmetics Act from state authorities, overseen by the Ministry of Ayush, and advertisements claiming cures are restricted by law.","competitiveAdvantages":"Trust, practitioner quality, patient outcomes and a network of centres build loyalty.","drivers":[{"factor":"Healthcare spending","impact":"Household spending on health and prevention widens the customer base."},{"factor":"Consumer demand","impact":"Fitness and spa visits rise with incomes and lifestyle awareness."},{"factor":"Government policy","impact":"Official promotion of Ayush systems supports acceptance and insurance cover."},{"factor":"Regulation","impact":"Rules on ad claims and medicine licences limit how firms market themselves."}],"risks":[{"risk":"Advertising curbs","detail":"Action against misleading health claims can hit marketing."},{"risk":"Credibility","detail":"Doubts over treatment effectiveness can hurt demand."},{"risk":"Fragmented competition","detail":"Many local clinics and gyms compete on price."},{"risk":"Practitioner shortage","detail":"Finding trained doctors and therapists limits expansion."}],"cyclicality":"Mixed","cyclicalityNote":"Health-related spending is fairly steady, while spa and fitness spending is more discretionary.","metricSet":"healthcare-services","relatedBasicIndustries":["b-healthcare-service-provider","b-hospital","b-personal-care","b-hotels-and-resorts","b-pharmaceuticals"],"aliases":["wellness","ayurveda","ayush","spa","fitness","naturopathy","wellness clinic","traditional medicine"],"themes":["Healthcare"]},"b-tour-travel-related-services":{"simplifiedExplanation":"These companies help people plan and book travel - online travel portals, travel agents, tour operators, railway catering and ticketing, and cruise or boat services.","productsAndServices":["Flight, hotel and bus bookings","Holiday packages and tours","Travel distribution to agents","Railway ticketing and catering","Cruises and boat tours","Visa and forex services"],"valueChainPosition":"Intermediaries between travel suppliers (airlines, hotels, railways, bus operators) and travellers or travel agents.","howTheyMakeMoney":"They earn commissions and convenience fees on bookings, margins on packaged tours and service charges; some also run catering, drinking water or tourism concessions.","revenueSources":["Booking commissions and convenience fees","Package tour margins","Catering and on-board services","Advertising on travel platforms","Supplier incentives"],"operatingCosts":["Marketing and customer acquisition","Technology","Payment gateway charges","Staff","Discounts and cashbacks","Fees paid to concession owners"],"customersAndEndMarkets":"Leisure and business travellers, travel agents in India and overseas, pilgrims and corporate clients.","demandSupplyDrivers":"Travel demand grows with incomes, air and rail capacity and holidays; competition between platforms keeps discounts high.","domesticInternationalExposure":"Domestic travel dominates, but outbound tourism and global agent networks give some firms meaningful foreign revenue.","capexIntensity":"Low","capexNote":"Mostly technology and people; cruise and catering operations need more assets.","workingCapital":"Online platforms often collect money before paying suppliers, while firms selling to travel agents extend credit.","regulation":"GST, tax collected at source on overseas tour packages, Ministry of Tourism recognition and Indian Railways policies on ticketing and catering shape the business.","competitiveAdvantages":"Brand, app traffic, supplier relationships and technology scale help leading platforms; exclusive concession rights protect some services.","drivers":[{"factor":"Tourism & travel","impact":"Volumes of flights, hotel nights and train journeys drive bookings."},{"factor":"Consumer demand","impact":"Rising incomes increase holidays and outbound trips."},{"factor":"Technology change","impact":"Mobile booking shifts business from offline agents to apps."},{"factor":"Government policy","impact":"Railway concession terms and travel taxes affect margins."},{"factor":"Infrastructure spending","impact":"New airports, trains and routes expand travel options."}],"risks":[{"risk":"Travel disruptions","detail":"Pandemics, conflicts or airline failures cut bookings suddenly."},{"risk":"Supplier bargaining","detail":"Airlines and hotels push direct bookings and lower commissions."},{"risk":"Discount wars","detail":"Competing platforms spend heavily to win customers."},{"risk":"Concession changes","detail":"Changes in government contracts can reduce fees."}],"cyclicality":"Cyclical","cyclicalityNote":"Leisure travel is discretionary and quickly hit by economic or health shocks.","metricSet":"ecommerce","relatedBasicIndustries":["b-hotels-and-resorts","b-airline","b-e-retail-e-commerce","b-railways","b-amusement-parks-other-recreation"],"aliases":["online travel agency","ota","travel portal","tour operator","travel agent","railway catering","holiday packages","cruise"],"themes":["Tourism","Digital"]},"b-education":{"simplifiedExplanation":"Education companies teach students in physical centres - coaching and test preparation, vocational and IT training, corporate training, pre-schools and services to schools and colleges.","productsAndServices":["Coaching and test preparation","Vocational and skill training","IT and computer training","Corporate learning programmes","Pre-schools and school support services","Higher education services"],"valueChainPosition":"Service providers that hire teachers and develop content, and sell courses to students, parents, schools and companies.","howTheyMakeMoney":"They charge course fees, usually upfront, earn franchise fees from partner centres, and win contracts for corporate or government training.","revenueSources":["Student course fees","Franchise fees","Corporate training contracts","School service and content fees","Government skilling programmes"],"operatingCosts":["Teacher and trainer salaries","Centre rent","Marketing and student acquisition","Content development","Franchisee commissions"],"customersAndEndMarkets":"Students and parents, job seekers upgrading skills, and schools and companies outsourcing training, in India and abroad.","demandSupplyDrivers":"Exam competition, job market needs and parents' aspirations drive enrolments; supply is fragmented with many local coaching centres.","domesticInternationalExposure":"Mostly domestic, though some corporate training firms earn largely from global clients in foreign currency.","capexIntensity":"Low","capexNote":"Centres are usually rented; schools and campuses need far more capital.","workingCapital":"Usually negative because fees are collected before courses run; admissions follow the academic calendar.","regulation":"Schools need board affiliation and are run through not-for-profit trusts or societies; higher education is regulated by UGC and AICTE, and coaching centres face central guidelines and state rules.","competitiveAdvantages":"A results track record, brand among parents, quality faculty and a centre network create loyalty.","drivers":[{"factor":"Consumer demand","impact":"Families' willingness to spend on exams and careers drives enrolments."},{"factor":"Government policy","impact":"Education reforms and exam patterns change what courses are in demand."},{"factor":"Regulation","impact":"Rules on coaching, fees and affiliation limit how centres operate."},{"factor":"Technology change","impact":"Online learning competes with and complements classroom teaching."},{"factor":"Exports & global demand","impact":"Global corporate training budgets drive revenue for training outsourcers."}],"risks":[{"risk":"Regulatory curbs","detail":"Stricter rules on coaching or fees can cut enrolments or prices."},{"risk":"Faculty attrition","detail":"Star teachers leaving can take students with them."},{"risk":"Reputation","detail":"Poor results or student complaints spread fast."},{"risk":"Online competition","detail":"Cheaper online courses pull price-sensitive students away."}],"cyclicality":"Defensive","cyclicalityNote":"Families protect education spending even in slowdowns.","metricSet":"education","relatedBasicIndustries":["b-e-learning","b-printing-and-publication","b-it-enabled-services","b-other-consumer-services"],"aliases":["education","coaching","test prep","training institute","vocational training","skilling","school","corporate training"],"themes":[]},"b-e-learning":{"simplifiedExplanation":"E-learning companies teach through apps and websites - live and recorded classes, test-prep courses, online degree programmes and learning software for schools and companies.","productsAndServices":["Online test-prep courses","Live and recorded video classes","Online degree and certificate programmes with universities","Learning apps and subscriptions","Hybrid online-plus-centre courses","Learning platforms for institutions"],"valueChainPosition":"Digital education providers that create content and technology and sell directly to learners or through partner universities and institutions.","howTheyMakeMoney":"They earn course fees and subscriptions, share fees with partner universities, and sell platform licences to schools and companies.","revenueSources":["Course fees","Subscriptions","University programme fee share","Institutional licences","Books and test series"],"operatingCosts":["Faculty and content creators","Marketing and customer acquisition","Technology and cloud","Counselling and sales teams","Rent for offline centres in hybrid models"],"customersAndEndMarkets":"Students preparing for exams, working professionals upskilling, and schools, colleges and companies.","demandSupplyDrivers":"Smartphone reach and low prices widen access, but low entry barriers and free content mean intense competition and high marketing costs.","domesticInternationalExposure":"Mainly domestic; some platforms reach Indian learners abroad or partner with foreign universities.","capexIntensity":"Low","capexNote":"Spending goes mainly into content, technology and marketing rather than physical assets.","workingCapital":"Fees are collected upfront and recognised over the course, creating deferred revenue that funds operations.","regulation":"UGC rules govern online degrees, consumer protection rules cover misleading claims and refunds, and data protection law covers student data.","competitiveAdvantages":"Popular teachers, an exam-result track record, low-cost content and brand trust bring organic sign-ups.","drivers":[{"factor":"Technology change","impact":"Cheap smartphones, data and AI tools change how learning is delivered."},{"factor":"Consumer demand","impact":"Spending on exam prep and upskilling decides paid enrolments."},{"factor":"Regulation","impact":"Rules on online degrees and refunds shape what can be sold."},{"factor":"Customer acquisition cost","impact":"Marketing spend needed to win each learner decides profitability."}],"risks":[{"risk":"High marketing spend","detail":"Paid advertising to win learners can wipe out margins."},{"risk":"Return to classrooms","detail":"Learners may prefer physical classes, reducing online demand."},{"risk":"Regulatory scrutiny","detail":"Complaints over sales practices invite tighter rules."},{"risk":"Teacher exits","detail":"Popular teachers leaving can move students to rivals."}],"cyclicality":"Mixed","cyclicalityNote":"Learning demand is steady, but paid online courses are more discretionary and competitive.","metricSet":"education","relatedBasicIndustries":["b-education","b-software-products","b-web-based-media-and-service","b-printing-and-publication"],"aliases":["edtech","ed tech","e-learning","online learning","online courses","online coaching","digital education"],"themes":["Digital"]},"b-food-storage-facilities":{"simplifiedExplanation":"These companies run cold storages, warehouses and silos where farmers, traders and food companies store fruits, vegetables, grain, dairy and frozen food so it does not spoil.","productsAndServices":["Cold storage for fruits and vegetables","Frozen and chilled warehousing","Grain silos and warehouses","Refrigerated transport","Ripening chambers","Warehouse receipts used for crop loans"],"valueChainPosition":"A midstream link between farms and food processors, retailers and exporters.","howTheyMakeMoney":"They charge rent for the space or weight stored over a period, plus fees for handling, transport and value-added services.","revenueSources":["Storage rental","Handling and processing charges","Refrigerated transport","Government warehousing contracts"],"operatingCosts":["Electricity for refrigeration","Depreciation on facilities","Staff","Maintenance","Interest on project loans"],"customersAndEndMarkets":"Farmers, traders, food processors, restaurant chains, organised retailers, exporters and government procurement agencies.","demandSupplyDrivers":"Harvest size and crop seasons decide how full storages are; organised retail, frozen foods and exports add demand, while capacity is uneven across regions.","domesticInternationalExposure":"Domestic, though farm and seafood exports depend on cold-chain storage.","capexIntensity":"High","capexNote":"Insulated buildings, refrigeration plants and land need large upfront capital.","workingCapital":"Moderate; rent is often collected when goods are taken out, so collections bunch at the end of each season.","regulation":"Food storage follows FSSAI rules, warehouse receipts are regulated by WDRA, and government schemes offer subsidies for cold-chain projects.","competitiveAdvantages":"Locations near farm clusters or cities, energy-efficient plants and long-term contracts with food companies give an edge.","drivers":[{"factor":"Monsoon & agriculture","impact":"Harvest size decides how much produce needs storage."},{"factor":"Power tariffs","impact":"Electricity is the biggest running cost of refrigeration."},{"factor":"Government policy","impact":"Cold-chain subsidies and procurement policies support new capacity."},{"factor":"Consumer demand","impact":"Growth of frozen foods and organised retail needs more chilled storage."},{"factor":"Exports & global demand","impact":"Food and seafood exports need cold-chain capacity near ports."}],"risks":[{"risk":"Crop failure or glut","detail":"Poor harvests leave space empty; gluts crash prices and storers may abandon stock."},{"risk":"Power costs","detail":"Tariff hikes or outages raise costs and spoilage risk."},{"risk":"Under-utilisation","detail":"Seasonal demand leaves capacity idle part of the year."},{"risk":"Spoilage claims","detail":"Equipment failure can damage stored goods and invite claims."}],"cyclicality":"Mixed","cyclicalityNote":"Utilisation follows harvest cycles more than the broader economy.","metricSet":"logistics-transport","relatedBasicIndustries":["b-logistics-solution-provider","b-other-agricultural-products","b-packaged-foods","b-seafood","b-transport-related-services"],"aliases":["cold storage","cold chain","warehousing","food warehouse","silos","agri storage","refrigerated warehouse"],"themes":["Agriculture"]},"b-other-consumer-services":{"simplifiedExplanation":"This catch-all group covers service businesses that do not fit elsewhere - for example private security, facility management, cash logistics, and personal or household services.","productsAndServices":["Security guarding","Facility management and housekeeping","Cash logistics","Pest control","Personal and household services","Electronic security and monitoring"],"valueChainPosition":"Downstream service providers that supply trained staff and equipment to offices, homes, factories, banks and institutions.","howTheyMakeMoney":"They bill clients monthly per guard or per service contract, earning a margin over wages and statutory costs.","revenueSources":["Monthly service contracts","Per-staff billing","Equipment and monitoring fees","One-time service charges"],"operatingCosts":["Wages and statutory benefits","Training and recruitment","Uniforms, equipment and vehicles","Insurance","Administration"],"customersAndEndMarkets":"Companies, banks, hospitals, factories, housing societies and government bodies.","demandSupplyDrivers":"Demand grows as businesses outsource non-core work and safety awareness rises; the market is fragmented with many small unorganised players.","domesticInternationalExposure":"Mostly domestic; a few firms also operate overseas, which adds currency exposure.","capexIntensity":"Low","capexNote":"People-heavy businesses with limited investment in equipment and vehicles.","workingCapital":"Heavy for staffing models: wages are paid monthly while large and government clients often pay late.","regulation":"Private security agencies are licensed under PSARA, and labour codes, minimum wage notifications and provident fund rules drive costs.","competitiveAdvantages":"Scale, compliance record, client relationships and the ability to recruit and train large workforces matter most.","drivers":[{"factor":"Government policy","impact":"Minimum wage revisions and labour codes raise costs that must be passed on to clients."},{"factor":"Outsourcing of services","impact":"Companies handing over security and upkeep to specialists widens the market."},{"factor":"Regulation","impact":"Licensing and labour compliance favour larger organised firms."},{"factor":"Real estate cycle","impact":"New offices, malls and housing complexes need guarding and facility services."}],"risks":[{"risk":"Thin margins","detail":"Small mistakes in pricing contracts wipe out profit."},{"risk":"Wage inflation","detail":"Wage hikes may not be passed on quickly."},{"risk":"Receivable delays","detail":"Slow-paying clients force borrowing to pay salaries."},{"risk":"Labour compliance","detail":"Lapses in statutory payments bring penalties."}],"cyclicality":"Defensive","cyclicalityNote":"Security and facility services are essential and contracted, so demand is steady.","metricSet":"services-generic","relatedBasicIndustries":["b-diversified-commercial-services","b-education","b-real-estate-related-services","b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo"],"aliases":["security services","facility management","cash logistics","manpower services","housekeeping","consumer services","pest control"],"themes":["Formalisation"]},"b-speciality-retail":{"simplifiedExplanation":"Speciality retailers run chains of stores focused on one category - such as ethnic wear, fashion, footwear, eyewear, electronics, home decor or beauty.","productsAndServices":["Ethnic and wedding wear stores","Apparel and fashion chains","Electronics and mobile stores","Eyewear and beauty stores","Home decor and furnishing","Own-brand and franchise outlets"],"valueChainPosition":"Downstream: they buy from brands or contract manufacturers, or design private labels, and sell to consumers through stores and websites.","howTheyMakeMoney":"They earn a gross margin on goods sold, higher on own brands; profit grows when sales per store rise faster than rent and staff costs.","revenueSources":["Store sales","Online sales","Franchise and distributor sales","Private-label products"],"operatingCosts":["Cost of goods","Store rent","Staff","Marketing","Logistics and warehousing"],"customersAndEndMarkets":"Urban and semi-urban shoppers buying for weddings, festivals and lifestyle needs.","demandSupplyDrivers":"Wedding and festive seasons, rising incomes and brand awareness drive sales, while online and fast-delivery channels compete strongly in many categories.","domesticInternationalExposure":"Sales are domestic; electronics and some premium brands are imported, so the rupee affects costs.","capexIntensity":"Medium","capexNote":"Each new store needs fit-outs and rent deposits; franchise models need less capital.","workingCapital":"Inventory-heavy, built up ahead of festive and wedding seasons, with the risk of discounting unsold stock.","regulation":"Shops and Establishments Acts, Legal Metrology labelling rules, GST and FDI rules for single-brand retail apply.","competitiveAdvantages":"Strong brands, design and sourcing skills, prime store locations and inventory discipline separate leaders.","drivers":[{"factor":"Consumer demand","impact":"Discretionary spending on fashion and lifestyle decides store sales."},{"factor":"Wedding & festive season","impact":"A large share of annual sales comes in festival and wedding months."},{"factor":"Technology change","impact":"Online shopping takes share but also lets chains sell beyond their stores."},{"factor":"Real estate cycle","impact":"Mall supply and rents decide where and how cheaply stores can open."}],"risks":[{"risk":"Fashion risk","detail":"Misjudging trends leaves unsold stock."},{"risk":"Rent escalation","detail":"Rising mall and high-street rents squeeze margins."},{"risk":"Online competition","detail":"Marketplaces and brand websites undercut store prices."},{"risk":"Discounting","detail":"End-of-season sales erode margins."}],"cyclicality":"Cyclical","cyclicalityNote":"Spending on fashion and lifestyle goods is easily postponed in hard times.","metricSet":"retail","relatedBasicIndustries":["b-diversified-retail","b-garments-and-apparels","b-footwear","b-gems-jewellery-and-watches","b-e-retail-e-commerce"],"aliases":["speciality retail","specialty retail","retail chain","ethnic wear retail","fashion retail","electronics retail","eyewear","store chain"],"themes":["Urban consumption"]},"b-pharmacy-retail":{"simplifiedExplanation":"Pharmacy retailers run chains of chemist shops and online pharmacies that sell medicines, health products and diagnostic tests; some also distribute medicines to other pharmacies.","productsAndServices":["Prescription medicines","Over-the-counter and wellness products","Private-label generic medicines","Online medicine delivery","Diagnostic tests","Wholesale distribution to chemists and hospitals"],"valueChainPosition":"A downstream link between drug makers and distributors on one side and patients on the other.","howTheyMakeMoney":"They earn the trade margin between the price paid to manufacturers or distributors and the retail price, with higher margins on private-label generics and health products.","revenueSources":["Medicine sales","Private-label products","FMCG and wellness products","Diagnostics","Distribution to other pharmacies"],"operatingCosts":["Cost of medicines","Store rent","Pharmacists and staff","Logistics and cold chain","Inventory technology"],"customersAndEndMarkets":"Patients with chronic and acute needs, households, hospitals and independent chemists.","demandSupplyDrivers":"Medicine demand is steady and grows with ageing and lifestyle diseases; organised chains gain from independent chemists but face online discounting.","domesticInternationalExposure":"Sales are purely domestic; imported drug ingredients can affect availability of some medicines.","capexIntensity":"Low","capexNote":"Small stores and warehouses need modest investment.","workingCapital":"Thousands of items must be stocked and expiry dates managed; retail customers pay cash, while distribution arms give credit.","regulation":"Pharmacies need drug licences and registered pharmacists under the Drugs and Cosmetics Act, NPPA price controls cap prices of many medicines, and online pharmacy rules are still evolving.","competitiveAdvantages":"Store density, supply-chain efficiency, private labels and customer trust support margins.","drivers":[{"factor":"Healthcare spending","impact":"Steady medicine needs, especially for chronic illness, keep sales growing."},{"factor":"Regulation","impact":"Drug price controls and licensing rules limit margins and expansion speed."},{"factor":"Technology change","impact":"E-pharmacies and app-based ordering compete on price and convenience."},{"factor":"Government policy","impact":"Government generic-medicine stores and price caps affect what customers pay."}],"risks":[{"risk":"Price controls","detail":"New price caps reduce margins on key medicines."},{"risk":"Online discounting","detail":"Deep discounts by e-pharmacies pressure store pricing."},{"risk":"Regulatory change","detail":"New rules on online sales or prescriptions can change the model."},{"risk":"Inventory expiry","detail":"Unsold medicines past expiry become losses."}],"cyclicality":"Defensive","cyclicalityNote":"People keep buying medicines whatever the economy is doing.","metricSet":"retail","relatedBasicIndustries":["b-pharmaceuticals","b-healthcare-service-provider","b-diversified-retail","b-e-retail-e-commerce","b-trading-and-distributors"],"aliases":["pharmacy","chemist","medical store","drug store","e-pharmacy","online pharmacy","medicine retail","pharma distribution"],"themes":["Healthcare"]},"b-diversified-retail":{"simplifiedExplanation":"Diversified retailers sell many categories under one roof - groceries, clothing, household goods and more - through supermarkets, hypermarkets, value stores and department stores.","productsAndServices":["Supermarkets and hypermarkets","Value fashion and general merchandise stores","Department stores","Groceries and staples","Private-label goods","Online ordering and home delivery"],"valueChainPosition":"Downstream: they buy from FMCG companies, apparel makers, farmers and wholesalers, and sell to households.","howTheyMakeMoney":"They make thin margins on groceries and higher margins on clothing and general merchandise; profit comes from high sales per square foot, low costs and fast stock turns.","revenueSources":["Groceries and staples","Apparel and general merchandise","Private labels","Space and concession income","Online orders"],"operatingCosts":["Cost of goods","Store rent or ownership costs","Staff","Logistics and warehousing","Power"],"customersAndEndMarkets":"Middle-class families in cities and smaller towns doing monthly shopping and buying value fashion.","demandSupplyDrivers":"Household consumption and the shift from kirana and unorganised shops drive growth, while quick-commerce apps and online grocery compete for urban shoppers.","domesticInternationalExposure":"Domestic, with little import exposure beyond some general merchandise.","capexIntensity":"Medium","capexNote":"Large-format stores need space and fit-outs; retailers that own their stores need more capital.","workingCapital":"Fast inventory turns and supplier credit keep needs moderate, though fashion stock is seasonal.","regulation":"FDI in multi-brand retail is restricted, and Legal Metrology, FSSAI rules for food and Shops and Establishments Acts apply.","competitiveAdvantages":"Low-cost operations, buying scale, private labels and a trusted value image are the key moats.","drivers":[{"factor":"Consumer demand","impact":"Household budgets decide basket size and visit frequency."},{"factor":"Rural demand","impact":"Spending in smaller towns supports expansion of value formats."},{"factor":"Technology change","impact":"Quick-commerce and online grocery compete for city shoppers."},{"factor":"Commodity prices","impact":"Food inflation affects grocery prices, margins and shopper behaviour."}],"risks":[{"risk":"Quick-commerce competition","detail":"Fast-delivery apps pull away top-up and urban shopping."},{"risk":"Margin squeeze","detail":"Price matching on staples keeps margins thin."},{"risk":"Expansion missteps","detail":"Poor store locations drag returns for years."},{"risk":"Inventory markdowns","detail":"Unsold fashion and general merchandise needs discounting."}],"cyclicality":"Mixed","cyclicalityNote":"Grocery sales are steady, while apparel and general merchandise move with discretionary spending.","metricSet":"retail","relatedBasicIndustries":["b-speciality-retail","b-e-retail-e-commerce","b-pharmacy-retail","b-packaged-foods","b-garments-and-apparels"],"aliases":["supermarket","hypermarket","department store","value retail","grocery retail","modern trade","organised retail","big box retail"],"themes":["Urban consumption"]},"b-e-retail-e-commerce":{"simplifiedExplanation":"E-commerce companies sell goods and services through apps and websites - online marketplaces, food delivery, quick-commerce grocery, beauty and fashion platforms, and online car and home-services platforms.","productsAndServices":["Online marketplaces","Food delivery","Quick-commerce grocery delivery","Beauty and fashion e-commerce","Online auto marketplaces","Home services booking"],"valueChainPosition":"Downstream platforms connecting sellers, restaurants and service providers with consumers, with delivery networks in between.","howTheyMakeMoney":"They earn commissions from sellers or restaurants, delivery and platform fees from customers, advertising from brands, and margins on goods where they own the inventory.","revenueSources":["Commissions (take rate)","Delivery and platform fees","Advertising","Own-inventory sales and private labels","Subscriptions"],"operatingCosts":["Delivery partner payouts","Discounts and marketing","Technology","Warehouses and dark stores","Payment gateway fees","Staff"],"customersAndEndMarkets":"Smartphone users in cities and increasingly in smaller towns, plus sellers, restaurants and brands that pay for reach.","demandSupplyDrivers":"Internet users, convenience and fast delivery drive order growth, while heavy competition and discounting keep profitability under pressure.","domesticInternationalExposure":"Customers are domestic; many firms rely on foreign capital, and some goods sold are imported.","capexIntensity":"Medium","capexNote":"Platforms are tech-led, but warehouses and dark stores for fast delivery need growing investment.","workingCapital":"Often negative because customers pay upfront and sellers are paid later; inventory-led models carry more stock.","regulation":"FDI rules bar foreign-funded marketplaces from owning inventory; Consumer Protection (E-Commerce) Rules, data protection law, CCI scrutiny and gig-worker welfare rules apply.","competitiveAdvantages":"Network effects, delivery density, brand recall and customer data protect leaders.","drivers":[{"factor":"Consumer demand","impact":"Urban spending and convenience drive order volumes."},{"factor":"Technology change","impact":"Faster delivery and better apps keep shifting shopping online."},{"factor":"Regulation","impact":"FDI, competition and consumer rules decide which business models are allowed."},{"factor":"Capital market activity","impact":"Access to funding decides how long loss-making growth can continue."},{"factor":"Government policy","impact":"Welfare rules for gig workers can raise delivery costs."}],"risks":[{"risk":"Cash burn","detail":"Discounts and expansion can keep a platform loss-making."},{"risk":"Regulatory change","detail":"New FDI or marketplace rules can force model changes."},{"risk":"Competition","detail":"Well-funded rivals fight for the same customers."},{"risk":"Delivery costs","detail":"Higher rider pay and fuel prices raise the cost per order."}],"cyclicality":"Mixed","cyclicalityNote":"Daily-needs orders are steady, while fashion and discretionary purchases swing with sentiment.","metricSet":"ecommerce","relatedBasicIndustries":["b-internet-and-catalogue-retail","b-diversified-retail","b-speciality-retail","b-logistics-solution-provider","b-restaurants"],"aliases":["ecommerce","e-commerce","online shopping","quick commerce","food delivery","marketplace","online retail","internet company"],"themes":["Digital"]},"b-internet-and-catalogue-retail":{"simplifiedExplanation":"These companies run online directories and listings - local business search, supplier marketplaces for businesses, matrimony sites and catalogue or TV shopping - where buyers find sellers.","productsAndServices":["Local business search and listings","Business supplier marketplaces","Online matrimony services","Online classifieds","Catalogue and TV shopping","Software tools for small businesses"],"valueChainPosition":"Intermediary platforms that connect buyers with sellers or matches and rarely hold goods themselves.","howTheyMakeMoney":"They sell paid listings and subscription packages to businesses or users who want more visibility, plus advertising; catalogue sellers earn product margins.","revenueSources":["Business subscriptions and paid listings","Premium user memberships","Advertising","Lead-generation fees","Product sales in catalogue models"],"operatingCosts":["Sales and customer support staff","Marketing","Technology","Content and profile verification"],"customersAndEndMarkets":"Small and medium businesses seeking customers, families looking for matches and consumers searching for local services.","demandSupplyDrivers":"Small businesses going online and internet growth drive paid listings; search engines, social media and free apps compete for the same users.","domesticInternationalExposure":"Mostly domestic, with some revenue from Indians living abroad.","capexIntensity":"Low","capexNote":"Asset-light platforms; investment is mainly in software and people.","workingCapital":"Negative, as subscriptions are paid upfront and recognised over time.","regulation":"The IT Act and IT Rules for intermediaries, data protection law and consumer protection rules apply.","competitiveAdvantages":"Large databases of listings, network effects, brand trust and a base of paying subscribers are hard to replicate.","drivers":[{"factor":"Technology change","impact":"Search engines, social media and AI tools change how buyers find sellers."},{"factor":"Small business digitisation","impact":"More small firms paying to be found online widens the customer base."},{"factor":"Consumer demand","impact":"User activity on the platform makes listings worth paying for."},{"factor":"Regulation","impact":"Data protection rules shape how user data can be used."}],"risks":[{"risk":"Big-tech competition","detail":"Free search and social platforms offer similar discovery."},{"risk":"Subscriber churn","detail":"Small businesses drop paid plans when leads disappoint."},{"risk":"Data privacy","detail":"Leaks or misuse of personal data hurt trust."},{"risk":"Fraud and fake listings","detail":"Fake profiles or sellers damage the platform's reputation."}],"cyclicality":"Mixed","cyclicalityNote":"Subscription revenue is sticky, but small businesses trim spending in slowdowns.","metricSet":"ecommerce","relatedBasicIndustries":["b-e-retail-e-commerce","b-web-based-media-and-service","b-advertising-and-media-agencies","b-software-products"],"aliases":["online classifieds","local search","online directory","matrimony","teleshopping","catalogue retail","listing platform","online marketplace for businesses"],"themes":["Digital"]},"b-distributors":{"simplifiedExplanation":"Distributors buy consumer products in bulk from manufacturers and supply them to retailers and dealers, handling storage, delivery and credit. They do not make the products.","productsAndServices":["Mobile phone and electronics distribution","Consumer durables distribution","FMCG distribution","Apparel and lifestyle brand distribution","Warehousing and last-mile delivery","After-sales service support"],"valueChainPosition":"A midstream link between brand owners or importers and retailers, both online and offline.","howTheyMakeMoney":"They earn a thin margin between the buying price and the price charged to retailers, plus incentives from brands for meeting sales targets.","revenueSources":["Product resale margins","Brand volume incentives","Logistics and service fees"],"operatingCosts":["Cost of goods bought","Warehousing and freight","Sales staff","Interest on working capital","Bad debts"],"customersAndEndMarkets":"Retail shops, modern trade chains, e-commerce sellers and dealers across cities and towns.","demandSupplyDrivers":"Volumes follow consumer demand for the brands carried and new product launches; brands that sell direct to retailers or online can bypass distributors.","domesticInternationalExposure":"Sales are domestic, but many electronics products are imported, so the rupee and import duties affect prices.","capexIntensity":"Low","capexNote":"Mainly warehouses and vehicles, which are often leased.","workingCapital":"Heavy: stock must be held and retailers given credit, so borrowing costs matter.","regulation":"Light, general business regulation, plus GST and customs duty rules on imported goods.","competitiveAdvantages":"Exclusive brand tie-ups, wide retail reach, efficient logistics and tight credit control are the main edges.","drivers":[{"factor":"Consumer demand","impact":"Retail sales of the brands carried decide distributor volumes."},{"factor":"Interest rates","impact":"Higher rates raise the cost of funding stock and retailer credit."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the cost of imported products."},{"factor":"Technology change","impact":"Direct-to-retailer apps and e-commerce can bypass traditional distributors."}],"risks":[{"risk":"Brand contract loss","detail":"Losing a major brand's distribution rights hits volumes."},{"risk":"Thin margins","detail":"Small cost overruns can wipe out profit."},{"risk":"Credit losses","detail":"Retailers defaulting on dues cause write-offs."},{"risk":"Disintermediation","detail":"Brands may cut out the middle layer."}],"cyclicality":"Mixed","cyclicalityNote":"Volumes follow consumer demand for the brands carried, while margins stay thin through the cycle.","metricSet":"trading-distribution","relatedBasicIndustries":["b-trading-and-distributors","b-diversified-retail","b-consumer-electronics","b-e-retail-e-commerce"],"aliases":["distributor","distribution","consumer distribution","wholesale","fmcg distributor","mobile distributor","electronics distributor"],"themes":[]},"b-gas-transmission-marketing":{"simplifiedExplanation":"These companies own the long-distance pipelines that carry natural gas across India, and buy gas (domestic or imported LNG) to resell to factories, power plants, fertilizer units and city gas companies.","productsAndServices":["Gas transmission through trunk pipelines","Natural gas marketing and trading","LNG sourcing and regasification capacity bookings","LPG and liquid hydrocarbons extracted from gas","Gas-based petrochemicals (in some companies)","City gas distribution through subsidiaries or joint ventures"],"valueChainPosition":"Midstream: they take gas from domestic producers and LNG terminals and deliver it to city gas distributors, fertilizer plants, power stations, refineries and industrial users.","howTheyMakeMoney":"Pipeline businesses earn a regulated tariff for each unit of gas carried. Marketing businesses earn the spread between the price paid under supply contracts and the price charged to customers.","revenueSources":["Pipeline transmission tariffs","Gas marketing margins","LPG and petrochemical sales","Income and dividends from city gas ventures"],"operatingCosts":["Cost of purchased gas and LNG","Pipeline operation and maintenance","Fuel and power for compressor stations","Employee costs","Depreciation on pipelines"],"customersAndEndMarkets":"Fertilizer, power, refinery, petrochemical and city gas companies, plus large industrial users such as steel, glass and ceramics plants.","demandSupplyDrivers":"Demand rises when gas is cheap compared with naphtha, fuel oil or coal, and as new pipelines link more cities and industrial clusters. Supply depends on domestic field output and the availability of imported LNG cargoes.","domesticInternationalExposure":"Operations are domestic, but much of the gas sold is imported LNG priced against global gas or crude benchmarks, so international prices and the rupee affect marketing margins and customer demand.","capexIntensity":"High","capexNote":"Cross-country pipelines and compressor stations need large upfront spending that is recovered over decades.","workingCapital":"Moderate: gas is billed on short credit cycles, but long-term LNG purchase commitments and occasional dues from government-linked buyers can tie up cash.","regulation":"PNGRB authorises pipelines and fixes transmission tariffs; the Ministry of Petroleum and Natural Gas sets domestic gas pricing and decides which sectors get priority allocation.","competitiveAdvantages":"An existing pipeline network with rights of way is very hard to replicate, and large long-term supply contracts give scale advantages in sourcing gas.","drivers":[{"factor":"Government policy","impact":"Domestic gas pricing, priority allocation and tariff reforms directly shape volumes carried and marketing margins."},{"factor":"Commodity prices","impact":"Global LNG prices decide how competitive gas is against other fuels and how much marketing margin can be earned."},{"factor":"Infrastructure spending","impact":"New trunk lines and LNG terminals open up fresh demand centres along the route."},{"factor":"Capacity utilisation","impact":"Pipeline profits rise as more gas flows through a network whose costs are largely fixed."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the rupee cost of imported LNG and can dampen demand."}],"risks":[{"risk":"Tariff regulation","detail":"Lower-than-expected tariff orders can cut returns on pipeline investments."},{"risk":"LNG price spikes","detail":"Costly imported gas can push customers to cheaper fuels and squeeze marketing spreads."},{"risk":"Under-used pipelines","detail":"New lines may carry little gas for years if supply or customers lag."},{"risk":"Take-or-pay commitments","detail":"Long-term LNG contracts can become a burden when demand or prices weaken."}],"cyclicality":"Mixed","cyclicalityNote":"Pipeline tariffs give steady income, while gas marketing and petrochemical profits swing with energy prices.","metricSet":"gas-utilities","relatedBasicIndustries":["b-lpg-cng-png-lng-supplier","b-oil-exploration-and-production","b-fertilizers","b-petrochemicals","b-power-generation"],"aliases":["gas pipeline","natural gas transmission","gas marketing","trunk pipeline","LNG","gas utility","midstream gas"],"themes":["Energy transition","Infrastructure"]},"b-lpg-cng-png-lng-supplier":{"simplifiedExplanation":"These companies sell gas straight to end users: CNG at fuel stations for vehicles, piped natural gas (PNG) to kitchens, hotels and factories, and in some cases LPG cylinders, auto-LPG or LNG for trucks.","productsAndServices":["CNG for cars, autos, buses and trucks","Domestic PNG for cooking","Commercial and industrial PNG","LPG cylinders and auto-LPG dispensing","LNG for trucks and off-pipeline users","New gas connections and network services"],"valueChainPosition":"Downstream: they buy gas from producers, marketers and LNG importers, move it through city pipe networks or cylinders, and sell it to households, vehicle owners and businesses.","howTheyMakeMoney":"They earn the spread between gas purchase cost and the retail price on every unit sold, plus connection charges. LPG players earn bottling and distribution margins.","revenueSources":["CNG sales at fuel stations","PNG sales to homes, commercial and industrial users","LPG cylinder and auto-LPG sales","Connection and service charges"],"operatingCosts":["Cost of gas (domestic allocation and imported LNG)","Pipeline transport charges","Network operation and maintenance","Power for CNG compression","Staff costs and dealer commissions"],"customersAndEndMarkets":"Households, auto-rickshaw, taxi, bus and truck operators, hotels and restaurants, and small and large factories within each licensed city or district.","demandSupplyDrivers":"Volumes grow as networks reach new homes and stations open, and when CNG stays cheaper than petrol and diesel. Margins depend on the mix of cheaper domestic gas and costlier imported LNG in the supply.","domesticInternationalExposure":"Sales are entirely domestic, but a rising share of input gas is imported LNG, so global gas prices and the rupee affect costs and pricing power.","capexIntensity":"High","capexNote":"Steel and polyethylene pipe networks, compressor stations and CNG outlets need steady investment in every licence area.","workingCapital":"Light: CNG sales are cash or near-cash and household PNG is billed in short cycles, though industrial customers get some credit.","regulation":"PNGRB awards city gas areas with a period of exclusivity and sets network and safety rules; the government decides domestic gas allocation for CNG and household PNG. LPG bottling needs PESO safety licences.","competitiveAdvantages":"Exclusive licence areas, an installed pipe network and connected customers create a local near-monopoly while exclusivity lasts.","drivers":[{"factor":"Government policy","impact":"Allocation of cheaper domestic gas to CNG and household PNG keeps costs low; any cut forces use of pricier gas."},{"factor":"Crude oil prices","impact":"Higher petrol and diesel prices widen CNG's cost advantage and encourage vehicle conversions."},{"factor":"Commodity prices","impact":"Imported LNG prices set the cost of gas for industrial PNG and for any shortfall in domestic supply."},{"factor":"Infrastructure spending","impact":"New licence areas and pipeline connectivity let networks expand into more cities."},{"factor":"Technology change","impact":"Electric buses, cars and three-wheelers compete directly with CNG vehicles."}],"risks":[{"risk":"Gas allocation cuts","detail":"Lower domestic gas allocation raises costs and squeezes margins if prices cannot be raised fast enough."},{"risk":"Electric vehicle adoption","detail":"Faster EV uptake among taxis, autos and buses can slow CNG volume growth."},{"risk":"End of exclusivity","detail":"Once marketing exclusivity ends, other suppliers may sell gas through the same network."},{"risk":"Loss of price edge","detail":"Costly LNG can push industrial users back to alternative fuels."}],"cyclicality":"Defensive","cyclicalityNote":"Household and transport gas use is steady, though margins move with gas costs and industrial demand.","metricSet":"gas-utilities","relatedBasicIndustries":["b-gas-transmission-marketing","b-trading-gas","b-passenger-cars-and-utility-vehicles","b-commercial-vehicles","b-ceramics"],"aliases":["city gas distribution","CGD","CNG","PNG","piped gas","LPG","auto LPG","LNG supplier","city gas"],"themes":["Energy transition","Infrastructure"]},"b-trading-gas":{"simplifiedExplanation":"These are traders and distributors: they buy gas products such as LPG, propane, butane or LNG from suppliers and resell them, often using import terminals and logistics, instead of producing the gas themselves.","productsAndServices":["Import and resale of LPG, propane and butane","Sourcing and trading of LNG cargoes","Bulk and packed LPG distribution","Industrial fuel gas supply to factories","Supply to cylinder and auto-LPG dealers"],"valueChainPosition":"Intermediaries in the middle of the chain: they source from international suppliers or domestic producers and sell to oil marketing companies, bottlers, factories and dealers.","howTheyMakeMoney":"They earn a trading margin per tonne between purchase and selling price, plus sourcing, handling or logistics fees when they arrange supplies for others.","revenueSources":["Margins on gas product trading","Sourcing and handling fees","Distribution and logistics charges"],"operatingCosts":["Cost of gas products bought","Ocean freight and terminal charges","Storage and handling","Hedging and trade finance costs","Employee costs"],"customersAndEndMarkets":"Oil marketing companies, LPG bottlers, ceramic, glass, steel and chemical factories, and auto-LPG and commercial users.","demandSupplyDrivers":"Demand follows household LPG and industrial fuel use, which domestic refineries cannot fully meet. Volumes and margins depend on global cargo availability and price gaps between regions.","domesticInternationalExposure":"Highly import-linked: purchases are priced off international benchmarks and paid in dollars, so global prices, freight rates and the rupee matter a lot.","capexIntensity":"Low","capexNote":"Pure trading needs little fixed capital, though players that also own terminals or storage carry more assets.","workingCapital":"Can be heavy: cargoes are paid for upfront or through letters of credit, and price swings during shipping change the value of stock held.","regulation":"Light, general business regulation for trading itself; storage and handling of LPG need PESO safety licences, and import rules are set by the Ministry of Petroleum and Natural Gas.","competitiveAdvantages":"Access to import terminals, long-standing supplier ties and strong bank credit lines let established traders source cargoes on better terms.","drivers":[{"factor":"Commodity prices","impact":"International LPG and LNG prices change both the value of inventory and buyers' appetite."},{"factor":"Currency (INR)","impact":"Dollar-priced purchases cost more in rupees when the rupee weakens."},{"factor":"Consumer demand","impact":"Household cooking-gas and auto-LPG use drives baseline volumes."},{"factor":"Import dependence","impact":"India's shortfall in domestic LPG and gas creates steady demand for imported supplies that traders handle."}],"risks":[{"risk":"Price volatility","detail":"Sharp moves between buying and selling a cargo can wipe out a thin margin."},{"risk":"Thin spreads","detail":"Small drops in volume or rises in cost hit profits hard."},{"risk":"Credit risk","detail":"Large dues from industrial buyers can turn bad in a downturn."},{"risk":"Policy changes","detail":"Changes to import rules or duties on LPG can alter the trade."}],"cyclicality":"Mixed","cyclicalityNote":"Cooking-gas volumes are steady, but industrial demand and trading margins rise and fall with energy prices.","metricSet":"trading-distribution","relatedBasicIndustries":["b-lpg-cng-png-lng-supplier","b-gas-transmission-marketing","b-oil-storage-and-transportation","b-port-and-port-services"],"aliases":["gas trading","LPG trading","LPG import","propane","butane","gas distributor","LNG trading"],"themes":[]},"b-oil-exploration-and-production":{"simplifiedExplanation":"These companies search for oil and gas under land and sea, drill wells and produce crude oil and natural gas, which they sell to refineries and gas buyers.","productsAndServices":["Crude oil","Natural gas","Condensate","LPG and other products extracted from gas","Stakes in domestic and overseas oil and gas blocks"],"valueChainPosition":"Upstream: they hold exploration blocks and supply crude to refineries and gas to pipeline and marketing companies, hiring drilling contractors and oilfield service firms to do much of the field work.","howTheyMakeMoney":"They sell oil and gas at prices linked to global crude benchmarks or government-set gas formulas. Profit is the realised price minus lifting cost, royalties, taxes and the write-down of exploration spending.","revenueSources":["Crude oil sales","Natural gas sales","Condensate and value-added product sales","Share of profits from joint-venture or overseas blocks"],"operatingCosts":["Royalties and cess paid to government","Field operating (lifting) costs","Drilling and oilfield service contracts","Write-offs of dry wells","Depreciation and depletion","Employee costs"],"customersAndEndMarkets":"Domestic refineries buy the crude; gas goes to fertilizer, power, city gas and industrial users through marketers and pipelines.","demandSupplyDrivers":"India imports most of its oil, so domestic output is easily absorbed; earnings move mainly with crude and gas prices and with production from ageing and newly developed fields.","domesticInternationalExposure":"Production is largely domestic, but crude is priced off international benchmarks in dollars, and some companies also own fields abroad.","capexIntensity":"High","capexNote":"Seismic surveys, exploration wells and offshore platforms need heavy, risky spending long before any oil flows.","workingCapital":"Usually light, as refiners pay on short cycles, though government-directed subsidy sharing or dues can occasionally tie up cash.","regulation":"Blocks are awarded under government licensing policies (HELP / OALP) overseen by the Directorate General of Hydrocarbons; the government sets domestic gas price formulas and ceilings and has used windfall-style levies on crude.","competitiveAdvantages":"Proven reserves, existing infrastructure in producing basins and technical expertise in difficult fields are hard for newcomers to match.","drivers":[{"factor":"Crude oil prices","impact":"Global crude prices feed almost directly into realisations, so rises lift profits and falls cut them quickly."},{"factor":"Government policy","impact":"Gas price formulas, price caps, royalties, cess and windfall levies decide how much of a price rise producers keep."},{"factor":"Currency (INR)","impact":"Dollar-linked prices mean a weaker rupee raises rupee revenue."},{"factor":"Reserve replacement","impact":"New discoveries and field development are needed to offset the natural decline of old fields."},{"factor":"Technology change","impact":"Enhanced recovery methods can slow output decline in mature fields."}],"risks":[{"risk":"Crude price crash","detail":"A sharp fall in global oil prices lowers revenue with little offset in costs."},{"risk":"Fiscal changes","detail":"Windfall levies, higher cess or price caps can take away gains from high prices."},{"risk":"Declining fields","detail":"Ageing fields produce less each year unless new wells are drilled."},{"risk":"Dry wells","detail":"Spending on unsuccessful exploration wells has to be written off."},{"risk":"Operational accidents","detail":"Blowouts, fires or spills can halt output and bring penalties."}],"cyclicality":"Cyclical","cyclicalityNote":"Profits rise and fall closely with global crude and gas prices.","metricSet":"oil-upstream","relatedBasicIndustries":["b-refineries-and-marketing","b-gas-transmission-marketing","b-offshore-support-solution-drilling","b-oil-equipment-and-services"],"aliases":["upstream oil","E&P","oil and gas producer","crude oil production","oil exploration","natural gas production","oilfield"],"themes":["Energy security"]},"b-offshore-support-solution-drilling":{"simplifiedExplanation":"These companies own or run drilling rigs, offshore vessels and marine support services that oil and gas producers hire to drill wells and keep operations at sea running.","productsAndServices":["Offshore jack-up drilling rigs on charter","Onshore drilling services","Offshore support and supply vessels","Diving and underwater services","Marine construction and repair support","Rig management services"],"valueChainPosition":"Upstream service providers: they supply rigs, vessels and crews to oil and gas explorers, and buy vessels, equipment and spares from shipyards and manufacturers.","howTheyMakeMoney":"They charge day rates or fixed contract fees for rigs, vessels and crews over multi-year charters, so income depends on how many days assets are on hire and at what rate.","revenueSources":["Rig charter day rates","Vessel charter hire","Drilling and well service fees","Diving, repair and project contracts"],"operatingCosts":["Crew salaries and offshore allowances","Repairs, dry-docking and maintenance","Fuel and consumables","Insurance","Depreciation and interest on rigs and vessels"],"customersAndEndMarkets":"Mainly state-owned and private oil and gas producers, contracted through competitive tenders, with a handful of large clients.","demandSupplyDrivers":"Demand follows offshore exploration and production budgets, which grow when crude prices are firm. The worldwide supply of rigs and vessels sets the day rates that can be charged.","domesticInternationalExposure":"Work is mostly in Indian waters, but rigs and vessels are global assets whose rates and resale values follow the worldwide offshore cycle; equipment is often imported and priced in dollars.","capexIntensity":"High","capexNote":"Rigs and vessels are costly assets that also need periodic dry-docking and upgrades.","workingCapital":"Moderate: dues from oil companies can be large, and idle periods between contracts still carry fixed crew and maintenance costs.","regulation":"Contracts follow oil company tender rules; offshore operations follow safety standards of the Oil Industry Safety Directorate and DGH, and vessels follow Directorate General of Shipping norms.","competitiveAdvantages":"A long track record and safety record with major oil companies, and owning rigs or vessels that meet tender specifications, are key to winning work.","drivers":[{"factor":"Crude oil prices","impact":"Firm crude prices encourage producers to drill more offshore wells, lifting demand for rigs and vessels."},{"factor":"Capacity utilisation","impact":"Profit depends on keeping each rig or vessel on hire with little idle time."},{"factor":"Government policy","impact":"The push for higher domestic oil and gas output and new block awards supports drilling demand."},{"factor":"Global offshore cycle","impact":"Worldwide rig and vessel supply shapes the day rates Indian contracts can command."},{"factor":"Currency (INR)","impact":"Dollar-linked charter rates and imported equipment make earnings sensitive to the rupee."}],"risks":[{"risk":"Contract roll-off","detail":"A rig or vessel coming off contract may sit idle or be re-hired at lower rates."},{"risk":"Client concentration","detail":"A few producers give most of the work and hold strong bargaining power."},{"risk":"Operational hazards","detail":"Accidents, bad weather and breakdowns cause downtime and penalties."},{"risk":"High debt","detail":"Borrowings taken to buy assets weigh heavily in weak cycles."}],"cyclicality":"Cyclical","cyclicalityNote":"Demand and day rates follow oil companies' spending, which tracks the crude price cycle.","metricSet":"oilfield-services","relatedBasicIndustries":["b-oil-exploration-and-production","b-oil-equipment-and-services","b-shipping","b-ship-building-and-allied-services"],"aliases":["offshore drilling","drilling rigs","jack-up rig","offshore support vessel","OSV","drilling contractor","oil rig"],"themes":["Energy security"]},"b-oil-storage-and-transportation":{"simplifiedExplanation":"These companies run tank farms, port terminals and pipelines that store and move crude oil, fuels, chemicals, LPG and other liquids for a fee, without owning the products.","productsAndServices":["Liquid storage tanks at ports","Crude and product pipelines","Chemical and LPG storage terminals","Jetty and pipeline handling services","Road and rail tanker logistics","Blending, heating and throughput services"],"valueChainPosition":"Midstream logistics: they sit between importers, refiners and chemical makers on one side and buyers of fuels and chemicals on the other, renting out capacity rather than trading the cargo.","howTheyMakeMoney":"They charge storage rent for tank space and throughput or handling fees for every tonne moved, often under contracts with minimum guaranteed charges.","revenueSources":["Tank storage rentals","Throughput and handling fees","Pipeline transport charges","Ancillary services such as blending and heating"],"operatingCosts":["Port land lease and waterfront charges","Power and utilities","Maintenance and fire-safety systems","Employee costs","Depreciation and interest on terminals"],"customersAndEndMarkets":"Refiners, oil marketing companies, chemical and petrochemical makers and traders, edible oil importers and LPG distributors.","demandSupplyDrivers":"Demand grows with imports and exports of liquids through ports and with fuel and chemical consumption. New supply is limited by scarce port land and waterfront at each location.","domesticInternationalExposure":"Income is in rupees, but volumes depend on India's trade in crude, products, chemicals and LPG, which follows global trade flows.","capexIntensity":"High","capexNote":"Tanks, jetties and pipelines at ports need large upfront investment that earns rent for many years.","workingCapital":"Light: customers pay storage fees regularly and the company does not carry the stored product as inventory.","regulation":"Storage of petroleum and chemicals needs PESO licences and OISD safety standards; port terminals depend on port authority land leases, and pipelines may need PNGRB authorisation.","competitiveAdvantages":"Scarce port land and waterfront, pipeline links to jetties and long customer contracts make established terminals hard to copy.","drivers":[{"factor":"Capacity utilisation","impact":"The share of tankage rented out drives profit because most costs are fixed."},{"factor":"Exports & global demand","impact":"Trade in crude, chemicals and LPG through Indian ports sets the volumes handled."},{"factor":"Infrastructure spending","impact":"Port expansions and new pipelines create room for more terminals."},{"factor":"Interest rates","impact":"Long-life terminals are usually debt-funded, so borrowing costs affect returns."}],"risks":[{"risk":"Lease renewal","detail":"Port land leases may be renewed on tougher terms or not at all."},{"risk":"Safety incidents","detail":"Fires or leaks can force shutdowns and create liabilities."},{"risk":"Customer shifts","detail":"Big clients may build their own storage or move to another port."},{"risk":"Local overcapacity","detail":"New terminals at the same port can push rental rates down."}],"cyclicality":"Mixed","cyclicalityNote":"Contracted rentals are steady, while utilisation and throughput move with trade flows.","metricSet":"transport-assets","relatedBasicIndustries":["b-port-and-port-services","b-trading-gas","b-refineries-and-marketing","b-commodity-chemicals","b-edible-oil"],"aliases":["tank farm","liquid storage","oil terminal","tankage","oil pipeline","liquid logistics","LPG terminal"],"themes":["Infrastructure"]},"b-oil-equipment-and-services":{"simplifiedExplanation":"These companies supply the equipment and on-site services oil and gas producers need on land, such as gas compression, workover rigs, seismic surveys and well services.","productsAndServices":["Gas compression and dehydration services","Workover and onshore drilling rigs","Seismic data acquisition and processing","Well testing and stimulation services","Oilfield equipment such as wellheads, valves and pumps","Operation and maintenance of oil and gas facilities"],"valueChainPosition":"Upstream service providers: they work for oil and gas producers and buy equipment and spares from manufacturers, many of them overseas.","howTheyMakeMoney":"They earn contract revenue for services over multi-year deals, hire charges for equipment, or margins on manufactured equipment sold.","revenueSources":["Service contracts with oil producers","Equipment hire charges","Equipment sales","Survey and project fees"],"operatingCosts":["Technical staff and field crews","Equipment maintenance and spares","Fuel and logistics","Depreciation on rigs and compressors","Subcontracting costs"],"customersAndEndMarkets":"State-owned and private oil and gas producers in India, and sometimes overseas, mostly through tenders.","demandSupplyDrivers":"Work depends on how much producers spend on exploration, new wells and keeping mature fields running; the government's push for more domestic output supports this spending.","domesticInternationalExposure":"Mostly domestic contracts with some overseas projects; much equipment is imported and some contracts are linked to the dollar.","capexIntensity":"Medium","capexNote":"Firms must own rigs, compressors and survey gear, though usually less capital is tied up than for offshore drillers.","workingCapital":"Moderate to heavy: payments from oil companies and project milestones can stretch receivables.","regulation":"Contracts follow the tender norms of oil companies; field operations follow OISD safety standards and DGH rules for upstream activity.","competitiveAdvantages":"Technical qualifications, a proven record and pre-qualification in oil company tenders keep inexperienced players out.","drivers":[{"factor":"Crude oil prices","impact":"Higher oil prices lift producers' spending on wells and field services."},{"factor":"Government policy","impact":"Policies to raise domestic oil and gas output and new block awards create service demand."},{"factor":"Capacity utilisation","impact":"Keeping rigs and compressors deployed on contracts drives profitability."},{"factor":"Technology change","impact":"Newer methods such as enhanced recovery and digital surveys open new service lines."}],"risks":[{"risk":"Tender pricing","detail":"Aggressive bidding can lock in thin margins for years."},{"risk":"Client concentration","detail":"Reliance on a few state-owned producers creates payment and renewal risk."},{"risk":"Spending cuts","detail":"Low crude prices can make producers defer projects."},{"risk":"Execution risk","detail":"Delays or breakdowns can trigger contract penalties."}],"cyclicality":"Cyclical","cyclicalityNote":"Order flow follows producers' capital spending, which moves with oil prices.","metricSet":"oilfield-services","relatedBasicIndustries":["b-oil-exploration-and-production","b-offshore-support-solution-drilling","b-compressors-pumps-and-diesel-engines","b-gas-transmission-marketing"],"aliases":["oilfield services","gas compression","workover rig","seismic survey","oilfield equipment","OFS","well services"],"themes":["Energy security"]},"b-refineries-and-marketing":{"simplifiedExplanation":"These companies buy crude oil, refine it into fuels such as petrol, diesel, jet fuel and LPG, and sell them through petrol pumps, to industry or to buyers abroad.","productsAndServices":["Petrol and diesel","Aviation turbine fuel","LPG for cooking","Naphtha, fuel oil and bitumen","Petrochemicals such as polymers (in integrated refiners)","Retail fuel stations"],"valueChainPosition":"Midstream to downstream: they process crude from producers and importers and supply fuels to motorists, airlines, industry, petrochemical plants and export markets.","howTheyMakeMoney":"Refiners earn the gross refining margin, the gap between the value of products made and the cost of crude. Marketers add a margin on each litre sold, which depends on how pump prices are set against costs.","revenueSources":["Domestic sales of refined fuels","Exports of refined products","Retail fuel marketing margins","Petrochemical sales","LPG sales, at times with government compensation"],"operatingCosts":["Crude oil purchases (the largest cost)","Fuel and power used in refining","Crude shipping and freight","Maintenance and employee costs","Interest and depreciation"],"customersAndEndMarkets":"Motorists and households, transport fleets, airlines, factories, petrochemical makers and overseas fuel buyers.","demandSupplyDrivers":"Demand follows vehicle use, freight, flying and industrial activity. Margins depend on global product spreads (cracks), the crude discounts a refiner can secure and how retail prices are adjusted.","domesticInternationalExposure":"Highly exposed to global markets: most crude is imported in dollars and product prices track international benchmarks; some refiners export a large part of their output.","capexIntensity":"High","capexNote":"Building, expanding and upgrading refineries for cleaner fuel standards needs very large investment.","workingCapital":"Big crude and product stocks mean fast price swings create inventory gains or losses, and pending government compensation on LPG can add to receivables.","regulation":"The Ministry of Petroleum and Natural Gas influences retail fuel and LPG pricing; excise and export duty changes affect margins; fuel quality must meet Bharat Stage norms and outlets need PESO licences.","competitiveAdvantages":"Scale, complex refineries that can run cheaper crude grades, petrochemical integration and an established retail network give lasting cost advantages.","drivers":[{"factor":"Crude oil prices","impact":"Crude cost and its swings drive margins and create inventory gains or losses."},{"factor":"Government policy","impact":"Decisions on pump prices, LPG pricing, excise and export duties decide marketing margins."},{"factor":"Exports & global demand","impact":"Global product spreads set refining margins for both domestic and export sales."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the rupee cost of imported crude."},{"factor":"Consumer demand","impact":"Fuel use by vehicles, freight and aviation sets volumes sold."}],"risks":[{"risk":"Retail price freezes","detail":"When pump prices are held while crude rises, marketing margins can turn negative."},{"risk":"Inventory losses","detail":"A quick fall in crude cuts the value of stock bought earlier."},{"risk":"Energy transition","detail":"Electric vehicles and alternative fuels may slow long-term fuel demand."},{"risk":"Refinery outages","detail":"Planned shutdowns or accidents reduce throughput."},{"risk":"Special levies","detail":"Extra duties on exports or high margins can cap profits."}],"cyclicality":"Cyclical","cyclicalityNote":"Refining and marketing margins swing widely with crude prices, global cracks and pricing policy.","metricSet":"refining-marketing","relatedBasicIndustries":["b-oil-exploration-and-production","b-petrochemicals","b-lubricants","b-oil-storage-and-transportation"],"aliases":["refinery","oil marketing company","OMC","petrol pump","fuel retail","oil refining","downstream oil","GRM"],"themes":["Energy security"]},"b-lubricants":{"simplifiedExplanation":"These companies blend base oil with additives to make engine oils, gear oils, greases and industrial oils; some also make specialty petroleum products such as white oils and transformer oils.","productsAndServices":["Engine oils for two-wheelers, cars and trucks","Industrial and hydraulic oils","Greases and gear oils","Transformer oils","White oils and petroleum jelly","Coolants and specialty fluids"],"valueChainPosition":"Downstream processors: they buy base oil from refiners or imports and additives from chemical companies, and sell through mechanics and dealers, to vehicle makers and to industry.","howTheyMakeMoney":"They earn a margin per litre between the selling price and the cost of base oil, additives and packaging. Branded retail packs earn more than bulk industrial supply.","revenueSources":["Branded automotive lubricants through retail","Factory-fill supply to vehicle makers","Industrial and institutional lubricants","Specialty oils such as transformer and white oils","Exports"],"operatingCosts":["Base oil and additives","Packaging","Advertising and mechanic or dealer incentives","Freight and distribution","Employee costs"],"customersAndEndMarkets":"Vehicle owners through workshops and retail shops, vehicle and equipment makers, power transformer makers, cosmetic and pharma makers (for white oils) and industrial plants.","demandSupplyDrivers":"Demand follows the number of vehicles on the road, distance driven and factory activity; margins depend on how quickly companies pass on changes in base oil prices.","domesticInternationalExposure":"Base oil and additives are often imported and priced in dollars, so crude prices and the rupee move costs; some makers export specialty oils.","capexIntensity":"Low","capexNote":"Blending plants are relatively cheap; most spending goes into brands and distribution.","workingCapital":"Moderate: companies hold base oil and finished stock and give credit to distributors and industrial buyers.","regulation":"Light, general business regulation; products follow BIS and industry performance specifications, and used-oil handling falls under hazardous waste rules.","competitiveAdvantages":"Trusted brands, mechanic loyalty, wide distribution and approvals from vehicle makers make shelf space hard for newcomers to win.","drivers":[{"factor":"Crude oil prices","impact":"Base oil prices follow crude, so sharp rises squeeze margins until price hikes stick."},{"factor":"Consumer demand","impact":"Vehicle sales and usage drive the replacement lubricant market."},{"factor":"Rural demand","impact":"Two-wheeler, tractor and pump-set use in villages supports volumes."},{"factor":"Currency (INR)","impact":"Imported base oil and additives cost more when the rupee weakens."},{"factor":"Technology change","impact":"Electric vehicles need far less engine oil, and longer drain intervals reduce volumes."}],"risks":[{"risk":"EV shift","detail":"Growth of electric two-wheelers and cars reduces engine-oil demand over time."},{"risk":"Base oil spikes","detail":"Sudden input cost jumps can hurt margins before prices are raised."},{"risk":"Intense competition","detail":"State-owned oil companies and global brands compete hard on price and promotion."},{"risk":"Counterfeits","detail":"Fake products in the market can damage brand trust."}],"cyclicality":"Mixed","cyclicalityNote":"Replacement demand is steady, but margins swing with base oil prices.","metricSet":"chemicals","relatedBasicIndustries":["b-refineries-and-marketing","b-specialty-chemicals","b-2-3-wheelers","b-commercial-vehicles"],"aliases":["lube oil","lubes","engine oil","grease","base oil","white oil","transformer oil","automotive lubricants"],"themes":["EV"]},"b-coal":{"simplifiedExplanation":"These companies dig coal out of the ground and sell it to power stations, steel, cement and other industries. The group also includes contractors that develop and run mines or move coal for mine owners.","productsAndServices":["Non-coking (thermal) coal for power plants","Coking coal for steel making","Washed and sized coal","Mine development and operation services","Coal transport and handling","Coal bed methane (in some companies)"],"valueChainPosition":"Upstream: they extract coal and supply power utilities, steel, sponge iron, cement, aluminium and other industries, relying on railways and roads for delivery.","howTheyMakeMoney":"Most coal is sold under long-term fuel supply agreements at notified or contracted prices, and the rest through e-auctions at market-linked premiums. Contractors earn per-tonne fees for mining or handling.","revenueSources":["Coal sold under fuel supply agreements","E-auction sales","Premiums on washed coal","Mining and logistics contract fees"],"operatingCosts":["Wages and employee benefits","Contractor payments for overburden removal","Diesel and explosives","Royalties and other levies","Land, rehabilitation and mine closure costs","Transport to rail sidings"],"customersAndEndMarkets":"Thermal power plants are the biggest buyers, followed by steel, sponge iron, cement, aluminium, fertilizer and brick industries.","demandSupplyDrivers":"Demand follows electricity use, the share of it met by thermal plants and industrial output. Supply depends on mine approvals, land acquisition and rail capacity to move coal out.","domesticInternationalExposure":"Sales are domestic, but imported coal prices influence auction premiums and how much power and industrial buyers source locally.","capexIntensity":"Medium","capexNote":"New mines, machinery, washeries and rail links need steady investment, though much mining work is outsourced to contractors.","workingCapital":"Usually manageable, but dues from state power utilities can build up, and coal stocks swing with seasonal demand and monsoon disruptions.","regulation":"The Ministry of Coal allocates and auctions blocks under the Coal Mines (Special Provisions) Act and the MMDR Act; mines need environment and forest clearances from MoEFCC, and royalties are set by government.","competitiveAdvantages":"Large, low-cost reserves close to rail lines and existing supply agreements with power plants are hard for others to replicate.","drivers":[{"factor":"Electricity demand","impact":"Higher power demand raises coal offtake by thermal plants."},{"factor":"Government policy","impact":"Block auctions, pricing decisions and import-substitution goals shape volumes and prices."},{"factor":"Commodity prices","impact":"International coal prices affect e-auction premiums and competition from imports."},{"factor":"Infrastructure spending","impact":"Rail lines and conveyor links decide how much coal can leave the mines."},{"factor":"Monsoon disruption","impact":"Heavy rains slow mining and dispatches during the monsoon months."}],"risks":[{"risk":"Energy transition","detail":"More solar and wind power may slow long-term growth in coal demand."},{"risk":"Cost inflation","detail":"Wage revisions and diesel prices can raise costs faster than selling prices."},{"risk":"Clearance delays","detail":"Land acquisition and environmental approvals can hold up new mines."},{"risk":"Price control","detail":"Notified prices may not keep pace with rising costs."},{"risk":"Safety and pollution","detail":"Accidents, mine fires and pollution issues can disrupt operations."}],"cyclicality":"Mixed","cyclicalityNote":"Power-sector demand keeps volumes steady, while auction premiums swing with global coal prices.","metricSet":"coal","relatedBasicIndustries":["b-trading-coal","b-power-generation","b-iron-and-steel","b-cement-and-cement-products","b-sponge-iron"],"aliases":["coal mining","thermal coal","coking coal","coal miner","MDO","mine developer and operator","commercial coal mining"],"themes":["Energy security"]},"b-trading-coal":{"simplifiedExplanation":"These are traders, not miners: they buy coal, mostly imported, and resell it to power plants, factories and smaller users, handling shipping, port clearance and delivery.","productsAndServices":["Imported thermal coal","Imported coking coal and coke","Domestic coal bought through auctions","Coal blending and sizing","Port-to-plant logistics"],"valueChainPosition":"Intermediaries between overseas mines or domestic auctions and end users such as power, cement, sponge iron and textile units.","howTheyMakeMoney":"They earn a margin per tonne over the landed cost of coal, plus fees for logistics, blending and handling.","revenueSources":["Coal trading margins","Logistics and handling charges","Blending services"],"operatingCosts":["Cost of coal bought","Ocean freight and port charges","Rail and road freight inside India","Finance costs on cargoes","Stockyard storage and handling"],"customersAndEndMarkets":"Coastal power plants, cement, sponge iron, steel, paper, textile and brick units, and small and medium factories.","demandSupplyDrivers":"Demand rises when domestic coal falls short or buyers need particular grades, and falls when local supply improves or import prices climb.","domesticInternationalExposure":"Strongly tied to international coal prices, ocean freight and the rupee, since most of the coal handled is imported.","capexIntensity":"Low","capexNote":"Trading needs little fixed investment beyond stockyards and handling equipment.","workingCapital":"Heavy: cargoes are financed through letters of credit and buyers often take credit, so borrowing lines matter.","regulation":"Light, general business regulation; imports follow customs and import policy, and stockyards need pollution control consents.","competitiveAdvantages":"Supplier relationships, access to trade finance and efficient port logistics set established traders apart.","drivers":[{"factor":"Commodity prices","impact":"Global coal prices change landed cost, buyer demand and the value of stock in hand."},{"factor":"Currency (INR)","impact":"Coal is bought in dollars, so a weaker rupee raises landed cost."},{"factor":"Government policy","impact":"The push to replace imports with domestic coal can shrink import volumes."},{"factor":"Electricity demand","impact":"Peak power demand lifts imported coal use by coastal plants."}],"risks":[{"risk":"Price swings","detail":"Prices falling while a cargo is at sea can cause inventory losses."},{"risk":"Thin margins","detail":"Small spreads leave little room for cost overruns."},{"risk":"Counterparty credit","detail":"Late payments by buyers can strain bank lines."},{"risk":"Policy shifts","detail":"Import restrictions or blending mandates can change demand quickly."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and margins follow global coal prices and the domestic supply gap.","metricSet":"trading-distribution","relatedBasicIndustries":["b-coal","b-shipping","b-port-and-port-services","b-power-generation","b-sponge-iron"],"aliases":["coal trading","coal import","imported coal","coal trader","coal supplier"],"themes":[]},"b-power-generation":{"simplifiedExplanation":"These companies own power plants that make electricity from coal, gas, water, sun or wind and sell it to state electricity distributors, industries or power exchanges.","productsAndServices":["Thermal power from coal or gas","Hydroelectric power","Solar power","Wind power","Hybrid and round-the-clock renewable supply","Captive and group-captive power for industries","Battery and pumped-storage capacity"],"valueChainPosition":"Upstream in the electricity chain: they buy fuel and equipment and sell power to distribution companies, industries and traders, using transmission networks to deliver it.","howTheyMakeMoney":"Most power is sold under long-term power purchase agreements, either cost-plus with a regulated return or at a fixed tariff won in bidding. Some is sold short-term on exchanges at market prices.","revenueSources":["Capacity (fixed) charges under PPAs","Energy charges per unit generated","Fixed-tariff renewable PPAs","Merchant and exchange sales","Renewable energy certificates and carbon credits"],"operatingCosts":["Coal or gas (thermal plants)","Operation and maintenance","Employee costs","Interest on project debt","Depreciation","Transmission and scheduling charges"],"customersAndEndMarkets":"State distribution companies are the main buyers, followed by industries buying open-access or captive power, power traders and exchanges.","demandSupplyDrivers":"Demand follows economic activity, summer cooling and farm pumping. Supply depends on new capacity, fuel availability and how much sun, wind and water is available.","domesticInternationalExposure":"Power is sold within India, but imported coal, gas and solar equipment tie costs to global prices and the rupee.","capexIntensity":"High","capexNote":"Each plant needs large upfront investment, usually funded with long-term debt.","workingCapital":"Can be stretched by slow payments from state distributors, though late-payment surcharge rules have improved collections; thermal plants also hold fuel stocks.","regulation":"CERC and SERCs set or approve tariffs under the Electricity Act; renewables follow central bidding guidelines, renewable purchase obligations and the ALMM list for solar modules; thermal plants must meet MoEFCC emission norms.","competitiveAdvantages":"Secure low-cost fuel, long-term PPAs, good sites with grid access and a strong execution record protect established generators.","drivers":[{"factor":"Electricity demand","impact":"Rising demand lifts plant load factors and short-term power prices."},{"factor":"Government policy","impact":"Renewable targets, bidding rules and payment security measures shape growth and returns."},{"factor":"Commodity prices","impact":"Coal, gas and solar module prices decide fuel cost and project cost."},{"factor":"Interest rates","impact":"Debt-heavy projects become more or less profitable as borrowing costs move."},{"factor":"Regulation","impact":"Tariff orders and return norms from CERC and SERCs set earnings on regulated plants."}],"risks":[{"risk":"Payment delays","detail":"Late payments from state distributors tie up cash and raise borrowing."},{"risk":"Fuel shortages","detail":"Coal or gas supply gaps can cut output or force costly imports."},{"risk":"Merchant price swings","detail":"Uncontracted capacity earns less when exchange prices fall."},{"risk":"Weather variability","detail":"Weak wind, cloudy spells or poor rainfall reduce renewable and hydro output."},{"risk":"Project delays","detail":"Land, grid connection or approval delays push back new capacity."}],"cyclicality":"Mixed","cyclicalityNote":"Long-term PPAs give stable income, while merchant sales, fuel costs and new-project returns move with the power cycle.","metricSet":"power-generation","relatedBasicIndustries":["b-integrated-power-utilities","b-power-transmission","b-power-trading","b-coal","b-heavy-electrical-equipment"],"aliases":["power producer","IPP","independent power producer","thermal power","renewable energy","solar power","wind power","hydro power","electricity generation","genco"],"themes":["Renewable energy","Energy transition","Infrastructure"]},"b-integrated-power-utilities":{"simplifiedExplanation":"These companies run more than one part of the electricity business - typically making power and also supplying it to homes and businesses in licensed cities or areas, sometimes with transmission and trading as well.","productsAndServices":["Electricity supply to consumers in licensed areas","Power generation from thermal and renewable plants","Transmission lines","Distribution franchise services","Power trading","EPC and smart metering services (in some)"],"valueChainPosition":"Span the chain from the power plant to the consumer's meter, buying fuel and extra power from others and selling directly to end users.","howTheyMakeMoney":"Regulated distribution and transmission earn an allowed return on equity through tariffs approved by regulators, while generation earns PPA or merchant income. Beating the regulator's efficiency and loss norms adds to profit.","revenueSources":["Retail electricity bills from consumers","Sale of power from own plants","Transmission charges","Franchise and trading income"],"operatingCosts":["Power bought from other generators","Fuel for own plants","Network operation and maintenance","Employee costs","Interest and depreciation"],"customersAndEndMarkets":"Households, shops, offices and factories inside licensed areas, plus state distributors and industries buying surplus generation.","demandSupplyDrivers":"Demand grows with urban consumption, commercial activity and hot weather; supply cost depends on own generation, fuel prices and power purchase contracts.","domesticInternationalExposure":"Mostly domestic; imported fuel and equipment link some costs to global coal prices and the rupee.","capexIntensity":"High","capexNote":"Generation, network upgrades and new connections all need continuous investment.","workingCapital":"Retail billing brings steady cash, but regulatory assets (approved costs not yet recovered through tariffs) can build up and need funding.","regulation":"SERCs approve retail tariffs and allowed returns, and CERC covers inter-state matters, under the Electricity Act; open access and cross-subsidy rules affect large customers.","competitiveAdvantages":"Distribution licences in dense cities, low-cost own generation and efficient networks with low losses are durable advantages.","drivers":[{"factor":"Regulation","impact":"Tariff orders and allowed returns from state regulators set core earnings."},{"factor":"Electricity demand","impact":"Growth in urban consumption increases units sold and network use."},{"factor":"Commodity prices","impact":"Fuel and purchased power costs hurt profits when tariff pass-through lags."},{"factor":"Government policy","impact":"Open access, licensing reforms and renewable mandates can reshape the customer base."},{"factor":"Interest rates","impact":"Large debt-funded capital spending makes borrowing costs important."}],"risks":[{"risk":"Regulatory assets","detail":"Slow recovery of approved costs can strain cash flow."},{"risk":"Open access losses","detail":"Large industrial users may buy cheaper power directly from others."},{"risk":"Fuel cost spikes","detail":"Cost rises passed on with a delay hit near-term profit."},{"risk":"Licence competition","detail":"Reforms allowing several suppliers in one area could reduce exclusivity."}],"cyclicality":"Defensive","cyclicalityNote":"Regulated returns and essential demand keep earnings relatively stable.","metricSet":"power-networks","relatedBasicIndustries":["b-power-generation","b-power-distribution","b-power-transmission","b-power-trading"],"aliases":["integrated utility","power utility","electricity company","distribution licensee","generation and distribution","private discom"],"themes":["Infrastructure","Energy transition"]},"b-power-trading":{"simplifiedExplanation":"These companies buy electricity from generators and sell it on to distribution companies, industries or neighbouring countries, acting as a middleman for a small fee on every unit.","productsAndServices":["Short-term bilateral power trading","Back-to-back long-term power sale arrangements","Cross-border electricity trade","Trading on power exchanges for clients","Green power and renewable certificate trading","Advisory on power procurement"],"valueChainPosition":"Midstream intermediaries between generators (sellers) and distribution companies, industries and exchanges (buyers); they own little or no generation.","howTheyMakeMoney":"They earn a trading margin per unit traded, which CERC caps, plus late-payment surcharges and advisory fees.","revenueSources":["Trading margin on units sold","Late-payment surcharges","Cross-border trade income","Advisory and consulting fees"],"operatingCosts":["Cost of power bought (largely passed through)","Employee costs","Interest on working capital","Provisions for bad debts"],"customersAndEndMarkets":"State distribution companies, industrial and commercial open-access buyers, and utilities in neighbouring countries.","demandSupplyDrivers":"Volumes rise when demand outruns contracted supply or renewable output fluctuates, creating need for short-term balancing; growth of exchanges can take share from bilateral deals.","domesticInternationalExposure":"Mostly domestic, with some cross-border trade with neighbouring countries.","capexIntensity":"Low","capexNote":"Trading is asset-light and needs mainly working capital and trading systems.","workingCapital":"Heavy: traders often pay generators before collecting from state distributors, so receivables and borrowings can pile up.","regulation":"CERC grants trading licences, sets net-worth norms and caps trading margins under the Electricity Act; cross-border trade follows Ministry of Power guidelines.","competitiveAdvantages":"Long relationships with state utilities, a higher licence category and a balance sheet able to carry receivables protect larger traders.","drivers":[{"factor":"Electricity demand","impact":"Peak demand and supply gaps raise short-term traded volumes."},{"factor":"Regulation","impact":"CERC margin caps and market rules limit what can be earned per unit."},{"factor":"Government policy","impact":"Market coupling, exchange reforms and cross-border policies change how power is traded."},{"factor":"Discom finances","impact":"Weak state distributor finances raise the risk of delayed payments."}],"risks":[{"risk":"Receivable risk","detail":"Slow payments by distributors can strain working capital."},{"risk":"Margin caps","detail":"Low regulated margins leave little cushion for losses."},{"risk":"Exchange competition","detail":"More trade moving to power exchanges can shrink bilateral volumes."},{"risk":"Counterparty default","detail":"A generator or buyer failing to perform leaves the trader exposed."}],"cyclicality":"Mixed","cyclicalityNote":"Volumes rise in tight power markets, but per-unit margins are small and regulated.","metricSet":"power-trading","relatedBasicIndustries":["b-exchange-and-data-platform","b-power-generation","b-power-distribution","b-integrated-power-utilities"],"aliases":["electricity trading","power trader","short-term power","bilateral power trading","cross-border power","energy trading"],"themes":[]},"b-power-transmission":{"simplifiedExplanation":"These companies build and run the high-voltage lines and substations that carry electricity from power plants across states to local distribution networks.","productsAndServices":["Inter-state transmission lines","Intra-state transmission lines","Substations","Green energy corridors for renewable power","Fibre leasing on transmission towers","Transmission consulting and project services"],"valueChainPosition":"Midstream in the electricity chain: they connect generators to distributors, buying towers, conductors, transformers and cables from equipment makers.","howTheyMakeMoney":"Older assets earn a regulated return on equity under cost-plus tariffs set by CERC; projects won through competitive bidding earn a fixed yearly charge over a long concession, mainly for keeping lines available.","revenueSources":["Regulated or bid-based transmission charges","Incentives for high line availability","Consultancy and project fees","Telecom fibre leasing"],"operatingCosts":["Operation and maintenance of lines and substations","Employee costs","Interest on project debt","Depreciation","Right-of-way and crop compensation during construction"],"customersAndEndMarkets":"Grid users such as state distribution companies pay through a central pooling and billing mechanism, so state utilities are the ultimate payers.","demandSupplyDrivers":"New work comes from capacity additions, especially solar and wind in remote areas that need new corridors; earnings depend on line availability, not on how much power flows.","domesticInternationalExposure":"Operations are domestic; costs of conductors, towers and transformers follow global metal prices.","capexIntensity":"High","capexNote":"Each project needs heavy upfront spending on towers, lines and substations, recovered over decades.","workingCapital":"Light: pooled billing and payment security mechanisms support collections, though weaker states can still pay late.","regulation":"CERC sets inter-state tariffs and return norms and SERCs handle intra-state lines; new projects are awarded through tariff-based competitive bidding under Ministry of Power guidelines.","competitiveAdvantages":"Large operating networks, execution skill, low cost of capital and a strong availability record help win bids and earn incentives.","drivers":[{"factor":"Infrastructure spending","impact":"National transmission plans create a steady pipeline of projects to bid for."},{"factor":"Government policy","impact":"Renewable energy targets require large new corridors to connect solar and wind zones."},{"factor":"Interest rates","impact":"Lower borrowing costs improve returns on long-life, fixed-charge projects."},{"factor":"Regulation","impact":"Return norms and bidding rules decide project profitability."},{"factor":"Electricity demand","impact":"Higher demand and inter-regional power flows justify new lines and upgrades."}],"risks":[{"risk":"Right-of-way delays","detail":"Land and forest issues can delay projects and raise costs."},{"risk":"Aggressive bidding","detail":"Winning bids at low tariffs can leave thin returns."},{"risk":"Return resets","detail":"Lower allowed returns at a tariff review cut earnings on regulated assets."},{"risk":"Equipment costs","detail":"Price rises for conductors and transformers can squeeze project margins."}],"cyclicality":"Defensive","cyclicalityNote":"Availability-based charges keep income stable whatever the power flow.","metricSet":"power-networks","relatedBasicIndustries":["b-power-distribution","b-power-generation","b-heavy-electrical-equipment","b-cables-electricals","b-civil-construction"],"aliases":["transmission lines","power grid","transco","substations","TBCB","green energy corridor","high voltage transmission"],"themes":["Infrastructure","Renewable energy"]},"b-power-distribution":{"simplifiedExplanation":"These companies run the local wires, transformers and meters that deliver electricity to homes, shops and factories and bill customers for it; some also install and run smart meters for state utilities.","productsAndServices":["Retail electricity supply","Local distribution network operation","New connections and meter services","Smart metering under long service contracts","Distribution franchises","Network upgrade works"],"valueChainPosition":"Downstream: they buy power from generators and traders, pay transmission charges and sell to end consumers.","howTheyMakeMoney":"Licensees earn an allowed return on regulated equity through tariffs approved by the state regulator, plus gains from cutting losses below targets. Smart metering firms earn a fixed monthly fee per meter over the contract.","revenueSources":["Consumer electricity bills","Regulated return on network investment","Smart metering service fees","Connection and service charges"],"operatingCosts":["Power purchase (the largest cost)","Transmission charges","Network repairs and maintenance","Employee costs","Interest and depreciation on networks and meters"],"customersAndEndMarkets":"Households, farmers, shops, offices and industries in the licence area; for smart metering, state distribution companies are the clients.","demandSupplyDrivers":"Units billed grow with urban and industrial use, summer cooling and farm pumping; profits depend on cutting technical and commercial losses and on timely tariff revisions.","domesticInternationalExposure":"Almost wholly domestic; meters and electronic parts may be imported.","capexIntensity":"High","capexNote":"Network strengthening, new connections and meter roll-outs need continuous investment.","workingCapital":"Monthly billing gives regular cash, but delayed state subsidies and regulatory assets can stretch working capital.","regulation":"SERCs set retail tariffs, loss targets and allowed returns under the Electricity Act; central schemes such as the Revamped Distribution Sector Scheme fund smart meters and loss reduction.","competitiveAdvantages":"An exclusive licence area, low loss levels and efficient billing and collection make good operators hard to displace.","drivers":[{"factor":"Regulation","impact":"Tariff orders and loss targets from state regulators decide earnings."},{"factor":"Electricity demand","impact":"Higher consumption increases units billed."},{"factor":"Government policy","impact":"Smart meter programmes, privatisation and franchise models create new opportunities."},{"factor":"Technology change","impact":"Smart meters and digital billing cut theft and improve collections."}],"risks":[{"risk":"Tariff delays","detail":"Late or inadequate tariff revisions leave costs unrecovered."},{"risk":"Subsidy dues","detail":"Slow state subsidy payments for farm or household supply strain cash."},{"risk":"Rooftop solar and open access","detail":"Large users making or buying their own power can cut high-paying sales."},{"risk":"Political pressure","detail":"Promises of free or cheap power complicate tariff setting and collections."}],"cyclicality":"Defensive","cyclicalityNote":"Electricity is essential and returns are regulated, so earnings are relatively stable.","metricSet":"power-networks","relatedBasicIndustries":["b-power-transmission","b-integrated-power-utilities","b-other-electrical-equipment","b-cables-electricals","b-power-trading"],"aliases":["discom","power distribution","electricity distribution","distribution licensee","smart meters","electricity supply","AMISP"],"themes":["Infrastructure","Smart metering"]},"b-water-supply-and-management":{"simplifiedExplanation":"These companies design, build and run plants and pipelines that clean, supply and recycle water - drinking water, sewage treatment, desalination and factory effluent treatment. Some also make the equipment and chemicals used.","productsAndServices":["Drinking water treatment plants","Sewage and wastewater treatment plants","Desalination plants","Industrial effluent treatment and zero liquid discharge systems","Water supply pipelines and pumping stations","Water treatment chemicals, resins and membranes","Operation and maintenance contracts"],"valueChainPosition":"Midstream engineering and service providers: they buy pumps, pipes, membranes and civil works and deliver plants and services to municipal bodies, state water boards and industries.","howTheyMakeMoney":"They earn construction revenue as project milestones are met, recurring income from multi-year operation and maintenance contracts, and product margins on chemicals and equipment.","revenueSources":["EPC contracts for water and wastewater plants","Operation and maintenance fees","Hybrid annuity payments on public projects","Sales of chemicals, resins and membranes","Industrial water services"],"operatingCosts":["Equipment and materials","Civil and subcontracting work","Engineering and site staff","Power and chemicals for running plants","Interest on project funding"],"customersAndEndMarkets":"Municipal corporations, state water boards and central missions, and industries such as power, refining, steel, chemicals, pharma and textiles.","demandSupplyDrivers":"Demand comes from government water and sanitation programmes, urban growth, water scarcity and stricter discharge rules for factories; competition for tenders sets pricing.","domesticInternationalExposure":"Mainly domestic, though some players win overseas projects, often backed by multilateral funding; some membranes and equipment are imported.","capexIntensity":"Low","capexNote":"Engineering and construction work is asset-light, though annuity or build-operate projects need some equity investment.","workingCapital":"Heavy: public projects tie up cash in receivables, retention money and unbilled work, and payments depend on government budgets.","regulation":"Projects are funded under central missions such as Jal Jeevan Mission, AMRUT and Namami Gange; industrial discharge is governed by CPCB and state pollution control board norms.","competitiveAdvantages":"Treatment technology know-how, references from completed plants and pre-qualification for large tenders keep smaller players out of big projects.","drivers":[{"factor":"Government policy","impact":"Central and state water and sanitation missions drive project tenders."},{"factor":"Infrastructure spending","impact":"Urban infrastructure budgets set the pace of new plants and pipelines."},{"factor":"Regulation","impact":"Stricter discharge and water-reuse norms push factories to invest in treatment."},{"factor":"Water scarcity","impact":"Shortages in cities and industrial zones raise demand for recycling and desalination."},{"factor":"Interest rates","impact":"Funding costs matter for annuity-based projects and for carrying large receivables."}],"risks":[{"risk":"Payment delays","detail":"Slow payments by municipal and state clients can strain cash flow."},{"risk":"Fixed-price execution","detail":"Cost overruns on fixed-price contracts eat into margins."},{"risk":"Funding cuts","detail":"Lower allocations to water missions can slow new orders."},{"risk":"Bid competition","detail":"Aggressive bidding for public tenders can push margins down."}],"cyclicality":"Mixed","cyclicalityNote":"Water is an essential need, but new orders follow government budgets and industrial capital spending.","metricSet":"utilities-other","relatedBasicIndustries":["b-waste-management","b-civil-construction","b-compressors-pumps-and-diesel-engines","b-specialty-chemicals","b-urban-local-bodies"],"aliases":["water treatment","wastewater","sewage treatment","STP","ETP","desalination","water infrastructure","zero liquid discharge","ZLD"],"themes":["Infrastructure","ESG"]},"b-waste-management":{"simplifiedExplanation":"These companies collect, transport, treat and dispose of waste - city garbage, industrial and hazardous waste, hospital waste - and some recycle it into compost, fuel, energy or reusable materials.","productsAndServices":["Door-to-door municipal waste collection and transport","Waste processing and composting","Refuse-derived fuel and waste-to-energy plants","Engineered landfills and old dumpsite clearing (bio-mining)","Hazardous and biomedical waste treatment","Recycling of plastics, e-waste and batteries","Sewerage and wastewater projects (in some companies)"],"valueChainPosition":"Downstream service providers to municipal bodies and industries, who also supply recovered materials, fuel or power to recyclers, cement plants and the grid.","howTheyMakeMoney":"They earn per-tonne or per-household fees under long municipal contracts, treatment charges from factories and hospitals, and income from selling compost, recyclables, fuel, power or EPR certificates.","revenueSources":["Collection and transport fees from municipalities","Tipping and processing fees","Industrial and biomedical treatment charges","Sale of recyclables, compost, refuse-derived fuel or power","EPR credits sold to producers"],"operatingCosts":["Fleet fuel and maintenance","Labour for collection and sorting","Plant operation and power","Landfill and site costs","Interest and depreciation on vehicles and plants"],"customersAndEndMarkets":"Urban local bodies, factories generating hazardous waste, hospitals, brand owners needing EPR compliance, and cement and power buyers of waste-derived fuel.","demandSupplyDrivers":"Demand grows with city populations, consumption and tighter enforcement of waste rules; contract wins depend on municipal tenders and budgets.","domesticInternationalExposure":"Largely domestic; prices of recovered plastics, metals and fuels can follow global commodity markets.","capexIntensity":"Medium","capexNote":"Collection fleets, processing plants and landfills need regular investment, often tied to contract terms.","workingCapital":"Heavy where municipalities pay late; receivables are the main pressure point, while inventory is small.","regulation":"The Solid Waste, Hazardous Waste, Bio-Medical Waste, Plastic Waste and E-Waste rules are enforced by CPCB and state pollution control boards; Swachh Bharat Mission funds city projects and EPR rules create recycling demand.","competitiveAdvantages":"Long municipal contracts, permitted treatment sites and pollution consents are hard to obtain and protect incumbents.","drivers":[{"factor":"Government policy","impact":"Swachh Bharat Mission and municipal budgets drive collection and processing contracts."},{"factor":"Regulation","impact":"Waste rules and EPR obligations make industries and brand owners pay for proper treatment and recycling."},{"factor":"Urbanisation","impact":"More city residents and higher consumption create more waste to handle."},{"factor":"Commodity prices","impact":"Prices of recycled plastics, metals and fuels affect income from recovered materials."}],"risks":[{"risk":"Municipal payment delays","detail":"Late payments from city bodies strain working capital."},{"risk":"Contract loss","detail":"Losing a large city contract can sharply cut revenue."},{"risk":"Local opposition","detail":"Residents may oppose landfills or plants near their homes."},{"risk":"Environmental liability","detail":"Leaks, fires or non-compliance can bring penalties or closure."}],"cyclicality":"Defensive","cyclicalityNote":"Waste is produced every day regardless of the economic cycle.","metricSet":"utilities-other","relatedBasicIndustries":["b-water-supply-and-management","b-urban-local-bodies","b-power-generation","b-civil-construction"],"aliases":["solid waste","MSW","garbage collection","waste to energy","recycling","biomedical waste","hazardous waste","EPR","landfill"],"themes":["ESG","Circular economy"]},"b-emergency-services":{"simplifiedExplanation":"This group covers businesses that provide emergency response, such as ambulance networks, emergency call and dispatch centres, and fire and rescue services, usually under contracts with governments or large institutions.","productsAndServices":["Emergency ambulance services","Patient transport services","Emergency call and dispatch centres","Fire and rescue services","Disaster response support","Industrial emergency response teams"],"valueChainPosition":"Downstream service providers to state governments, health departments, hospitals and industries; they buy vehicles, medical equipment and communication systems.","howTheyMakeMoney":"They are usually paid a fixed monthly fee per vehicle, or per trip or kilometre, under multi-year government or institutional contracts, with deductions for missing response-time targets.","revenueSources":["Government service contracts","Per-trip or per-kilometre fees","Private and corporate emergency contracts","Training and consulting"],"operatingCosts":["Paramedics, drivers and call-centre staff","Fuel and vehicle maintenance","Medical supplies and equipment","Dispatch and tracking technology","Vehicle depreciation and finance costs"],"customersAndEndMarkets":"State governments and health departments, hospitals, industrial parks and corporates.","demandSupplyDrivers":"Demand depends on public health budgets, coverage targets set by states and the growing need for road and industrial safety response; contract terms are set through tenders.","domesticInternationalExposure":"A domestic, contract-driven business with little direct link to global markets.","capexIntensity":"Medium","capexNote":"Vehicle fleets and equipment need regular replacement, though some government clients supply the vehicles.","workingCapital":"Can be heavy because payments come from government budgets and may be delayed.","regulation":"Governed mainly by state health department contract terms and national health programme funding; vehicles and equipment must meet transport and medical standards.","competitiveAdvantages":"Experience running large fleets, dispatch technology and a record of meeting service levels help win and renew contracts.","drivers":[{"factor":"Healthcare spending","impact":"Central and state health budgets fund ambulance and emergency coverage."},{"factor":"Government policy","impact":"Public-private partnership models and coverage targets decide how many contracts are tendered."},{"factor":"Road safety needs","impact":"More vehicles and highways increase the need for fast emergency response."},{"factor":"Crude oil prices","impact":"Fuel costs hit margins when contracts lack fuel-price escalation."}],"risks":[{"risk":"Payment delays","detail":"Late payments from state governments can strain cash flow."},{"risk":"Contract renewal","detail":"Losing a state tender can remove a large share of revenue."},{"risk":"Service penalties","detail":"Missing response-time targets leads to deductions from payments."},{"risk":"Reputation risk","detail":"Incidents of poor service attract public and political scrutiny."}],"cyclicality":"Defensive","cyclicalityNote":"Emergency services are essential and funded from government budgets.","metricSet":"utilities-other","relatedBasicIndustries":["b-healthcare-service-provider","b-hospital","b-diversified-commercial-services"],"aliases":["ambulance services","emergency response","EMS","emergency medical services","fire and rescue","disaster management","dispatch centre"],"themes":[]},"b-multi-utilities":{"simplifiedExplanation":"These companies provide more than one essential utility service together - for example electricity along with gas, water or waste services - often to a city, township, industrial park or special economic zone.","productsAndServices":["Electricity supply within parks or zones","Water supply and treatment","Piped gas supply","Sewage and waste handling","Steam, cooling or compressed air for industry","Operation and maintenance of utility networks"],"valueChainPosition":"Downstream: they buy power, gas and water inputs and deliver bundled services to residents, businesses and factories in their service area.","howTheyMakeMoney":"They charge tariffs or service fees for each utility supplied, often at regulated rates or under long-term agreements with park developers and occupants.","revenueSources":["Electricity charges","Water and sewerage charges","Gas supply charges","Facility and utility service fees"],"operatingCosts":["Purchased power, gas and water","Network maintenance","Employee costs","Interest and depreciation on networks"],"customersAndEndMarkets":"Residents, commercial units and factories inside industrial parks, SEZs, townships or cities.","demandSupplyDrivers":"Demand grows as parks and townships fill with occupants; costs follow the input prices of power, gas and water.","domesticInternationalExposure":"Domestic, with input costs indirectly influenced by global fuel prices.","capexIntensity":"High","capexNote":"Building several utility networks at once needs large upfront investment.","workingCapital":"Usually moderate, since users are billed regularly; strain appears when occupancy is slow or tariffs lag costs.","regulation":"Each service is regulated separately: electricity by SERCs, piped gas by PNGRB, and water and waste by state and municipal rules and pollution control boards.","competitiveAdvantages":"Exclusive rights to serve a park or township and shared infrastructure across services give cost and access advantages.","drivers":[{"factor":"Government policy","impact":"Industrial park, SEZ and urban development policies create new service areas."},{"factor":"Electricity demand","impact":"Occupants' power use is often the largest source of revenue."},{"factor":"Real estate cycle","impact":"How fast parks and townships fill up decides network utilisation."},{"factor":"Commodity prices","impact":"Fuel and gas costs feed into input prices and margins."}],"risks":[{"risk":"Low occupancy","detail":"Under-used networks earn little against high fixed costs."},{"risk":"Multiple regulators","detail":"Separate rules for each service add compliance and tariff risk."},{"risk":"Tariff lag","detail":"Rates that trail cost increases squeeze margins."}],"cyclicality":"Defensive","cyclicalityNote":"Essential services with regular billing give stable demand once areas are occupied.","metricSet":"utilities-other","relatedBasicIndustries":["b-integrated-power-utilities","b-water-supply-and-management","b-lpg-cng-png-lng-supplier","b-waste-management"],"aliases":["multi utility","multi-utility","integrated utilities","industrial park utilities","SEZ utilities","township utilities"],"themes":["Infrastructure"]},"b-other-utilities":{"simplifiedExplanation":"A catch-all group for utility businesses that do not fit power, gas, water, waste or emergency services, such as industrial steam or cooling supply, street lighting and outsourced utility operations.","productsAndServices":["Industrial steam and process heat supply","District cooling and chilled water","Compressed air and other plant utilities","Operation and maintenance of utility assets","Metering and billing services","Street lighting services"],"valueChainPosition":"Downstream service providers that buy fuel, power or equipment and deliver a utility service to factories, campuses, municipalities or communities.","howTheyMakeMoney":"They earn fees under long-term supply or service agreements, often a fixed capacity charge plus a usage-based charge.","revenueSources":["Fixed capacity or service charges","Usage-based charges","Operation and maintenance contracts","Project or installation fees"],"operatingCosts":["Fuel and power","Equipment maintenance","Staff costs","Interest and depreciation"],"customersAndEndMarkets":"Industrial clusters, campuses, commercial buildings, municipal bodies and government agencies.","demandSupplyDrivers":"Demand depends on industrial activity, urban infrastructure projects and customers' willingness to outsource utility needs instead of running them in-house.","domesticInternationalExposure":"Domestic, with fuel and equipment costs linked to global prices.","capexIntensity":"Medium","capexNote":"Plants and networks are often built for specific clients and paid back through long contracts.","workingCapital":"Moderate: regular billing under contracts, though public-sector clients may pay slowly.","regulation":"Depends on the service; pollution control consents and state or municipal rules usually apply, otherwise light, general business regulation.","competitiveAdvantages":"Long contracts with anchor customers and site-specific infrastructure make switching costly for clients.","drivers":[{"factor":"Infrastructure spending","impact":"Urban and industrial infrastructure creates demand for outsourced utility services."},{"factor":"Government policy","impact":"Energy-efficiency and clean-energy policies can favour shared utility systems."},{"factor":"Commodity prices","impact":"Fuel and power prices affect costs and depend on pass-through terms in contracts."},{"factor":"Capacity utilisation","impact":"Returns depend on how fully clients use the contracted capacity."}],"risks":[{"risk":"Customer concentration","detail":"Reliance on a few anchor clients leaves revenue exposed to their slowdowns or closures."},{"risk":"Cost pass-through","detail":"Contracts that do not adjust for fuel costs can squeeze margins."},{"risk":"Small scale","detail":"Niche operators may struggle to raise funds and win large contracts."}],"cyclicality":"Mixed","cyclicalityNote":"Contracted fees are steady, but demand from industrial clients follows the business cycle.","metricSet":"utilities-other","relatedBasicIndustries":["b-multi-utilities","b-water-supply-and-management","b-waste-management","b-power-distribution"],"aliases":["other utility","utility services","district cooling","industrial steam","utility O&M","street lighting"],"themes":[]},"b-financial-institution":{"simplifiedExplanation":"Mostly government-owned lenders set up to finance national priorities such as power, railways, renewable energy, infrastructure, exports or small industry. They raise money mainly by selling bonds and lend large amounts for long periods.","productsAndServices":["Long-term loans to state and central power utilities","Renewable energy project loans","Infrastructure project finance","Leasing of assets to government users","Refinance to banks and other lenders","Capital-gains and other retail bonds"],"valueChainPosition":"Wholesale financiers between the bond market (insurers, pension funds, banks, retail bondholders) and large public-sector or infrastructure borrowers. Several also act as nodal agencies that route government schemes in their sector.","howTheyMakeMoney":"They earn a thin but steady spread between lending rates and bond borrowing costs, made possible by strong credit ratings linked to government ownership. Some lease assets to government users on a cost-plus basis.","revenueSources":["Interest on utility and project loans","Lease income","Fees for scheme management and loan syndication","Treasury income"],"operatingCosts":["Interest on bonds and bank borrowings","Provisions on stressed projects","Hedging costs on foreign-currency borrowings","A small employee base (low operating costs)"],"customersAndEndMarkets":"State electricity distribution and generation companies, central PSUs, railways, renewable and infrastructure developers, and other lenders seeking refinance.","demandSupplyDrivers":"Lending follows government capex plans in power, transmission, railways and renewables, and the financial health of state utilities. Bond-market rates and investor appetite decide funding costs.","domesticInternationalExposure":"Lending is domestic; some raise foreign-currency loans or bonds and manage currency and rate risk with hedges.","capexIntensity":"Low","capexNote":"They own few physical assets beyond leased ones; the balance sheet itself is the business.","workingCapital":"Asset-liability management is central: very long loans are funded by bonds of mixed maturities, so refinancing and rate risk are watched closely.","regulation":"RBI regulates them as infrastructure-finance NBFCs or all-India financial institutions, with exposure and provisioning norms; the government as owner sets mandates, dividends and board appointments.","competitiveAdvantages":"Sovereign-linked ratings give low borrowing costs, and sector expertise plus policy roles are hard for private lenders to match.","drivers":[{"factor":"Government policy","impact":"Central schemes for power, railways and green energy decide how much these lenders disburse."},{"factor":"Infrastructure spending","impact":"Higher public capex means bigger loan books and more project pipelines."},{"factor":"Interest rates","impact":"Bond yields set their cost of funds and therefore their spread."},{"factor":"Electricity demand","impact":"Rising power demand pushes utilities to borrow for generation, transmission and distribution."},{"factor":"State utility finances","impact":"Timely payments by state discoms keep asset quality healthy."}],"risks":[{"risk":"Borrower concentration","detail":"Heavy exposure to a few state utilities or government users magnifies any payment delay."},{"risk":"Policy dependence","detail":"Changes in government priorities or scheme design can slow lending."},{"risk":"Spread squeeze","detail":"Margins narrow if borrowing costs rise faster than loans can be repriced."},{"risk":"Project stress","detail":"Private infrastructure or renewable projects can turn into bad loans."},{"risk":"Stake sales","detail":"Government share sales add supply of shares in the market."}],"cyclicality":"Mixed","cyclicalityNote":"Lending is driven by multi-year government programmes rather than the consumer cycle, but asset quality depends on state finances and project execution.","metricSet":"nbfc","relatedBasicIndustries":["b-non-banking-financial-company-nbfc","b-public-sector-bank","b-integrated-power-utilities","b-power-generation","b-railways"],"aliases":["financial institution","development financial institution","dfi","infrastructure finance company","nbfc-ifc","power finance","psu financier","aifi","railway finance"],"themes":["PSU","Infrastructure","Renewable energy"]},"b-housing-finance-company":{"simplifiedExplanation":"Lenders that specialise in loans to buy, build or repair homes, plus loans against property. They are not banks, so they fund themselves by borrowing from banks and the bond market instead of from savings accounts.","productsAndServices":["Home loans for salaried and self-employed borrowers","Affordable housing loans in smaller towns","Loans against property (LAP)","Construction finance to developers","Home improvement and plot loans","Public deposits (deposit-taking HFCs only)"],"valueChainPosition":"Downstream of the real estate market: they finance home buyers and developers, and are funded by banks, mutual funds, insurers, National Housing Bank refinance and depositors.","howTheyMakeMoney":"They earn the spread between home-loan rates and their borrowing cost over very long tenures, plus processing fees and gains from selling loan pools. Home loans are secured, so credit losses are usually low but spreads are thin.","revenueSources":["Interest on home loans and LAP","Interest on developer loans","Processing and other fees","Gains on assignment or securitisation of loans","Insurance cross-sell commissions"],"operatingCosts":["Interest on borrowings","Employee and branch costs","Sourcing payouts to loan agents and connectors","Credit provisions","Legal and valuation checks on properties"],"customersAndEndMarkets":"Individual home buyers, including low and middle-income families with informal incomes, and real estate developers needing project finance.","demandSupplyDrivers":"Housing demand, property prices, incomes and interest rates set loan demand, and government affordable-housing schemes add support. Banks offering cheaper home loans are the main competitive pressure.","domesticInternationalExposure":"Purely domestic lending; some raise funds through external commercial borrowings or foreign investors.","capexIntensity":"Low","capexNote":"Spending goes mainly on branches and loan-origination technology.","workingCapital":"Long loans funded by shorter borrowings create an asset-liability mismatch, so liquidity buffers and steady access to bonds and bank lines are critical.","regulation":"RBI regulates HFCs, with the National Housing Bank handling supervision and refinance; rules cover capital, loan-to-value limits and deposits. RERA affects developer lending and tax benefits on home-loan interest support demand.","competitiveAdvantages":"Low funding cost from a strong parent or rating, skill in assessing informal-income borrowers and branch reach in small towns.","drivers":[{"factor":"Interest rates","impact":"Lower rates cut funding costs and make EMIs affordable; rising rates do the opposite."},{"factor":"Real estate cycle","impact":"Home sales and prices drive loan demand and the safety of developer loans."},{"factor":"Government policy","impact":"Affordable-housing subsidies and tax breaks on home loans widen the borrower base."},{"factor":"Credit growth","impact":"Bank appetite to lend to HFCs and to buy their loan pools sets funding availability."},{"factor":"Consumer demand","impact":"Job security and income growth decide how many families buy homes."}],"risks":[{"risk":"Bank competition","detail":"Banks lure good borrowers away with cheaper balance-transfer offers."},{"risk":"Funding shock","detail":"A freeze in bond or bank funding can stall lending and raise costs."},{"risk":"Developer loan stress","detail":"Stalled projects make construction loans the riskiest part of the book."},{"risk":"Rate spikes","detail":"Higher EMIs slow new demand and stretch weaker borrowers."}],"cyclicality":"Mixed","cyclicalityNote":"Retail home loans tend to be resilient, but growth and developer exposure follow the property cycle and interest rates.","metricSet":"housing-finance","relatedBasicIndustries":["b-private-sector-bank","b-non-banking-financial-company-nbfc","b-residential-commercial-projects","b-securitisation"],"aliases":["hfc","housing finance","home loan company","mortgage lender","home finance","affordable housing finance","loan against property"],"themes":["Affordable housing"]},"b-investment-company":{"simplifiedExplanation":"Companies whose main business is holding and managing investments - shares, bonds, government securities or stakes in other businesses - rather than making products or giving retail loans. Their value largely tracks what they own.","productsAndServices":["Portfolios of listed and unlisted shares","Government securities underwriting and dealing (primary dealers)","Bond and money-market investments","Stakes in financial-services subsidiaries","Inter-corporate loans and deposits","Treasury management"],"valueChainPosition":"Investors in the capital market rather than service providers: they deploy their own or group capital into securities and businesses. Primary dealers underwrite and trade government bonds at RBI auctions.","howTheyMakeMoney":"Through dividends, interest, trading gains and fair-value changes on holdings; primary dealers also earn underwriting commissions. Reported profit can jump around with market prices.","revenueSources":["Dividend income","Interest on bonds and loans","Gains on sale of investments","Fair-value (mark-to-market) gains","Underwriting commissions (gilt dealers)"],"operatingCosts":["Interest on borrowings for leveraged portfolios","Employee and management costs","Mark-to-market losses","Taxes on gains and dividends"],"customersAndEndMarkets":"Few outside customers: the business is investing in companies and the bond market, and shareholders benefit through dividends and the value of holdings.","demandSupplyDrivers":"Earnings and book value follow equity prices, interest rates and the results of investee companies. For gilt dealers, the size of government borrowing and the direction of rates matter most.","domesticInternationalExposure":"Holdings are mainly Indian; global sentiment and foreign flows move the value of listed holdings.","capexIntensity":"Low","capexNote":"Almost no physical assets; capital sits in securities.","workingCapital":"Liquidity of holdings matters; gilt dealers run large bond books funded short-term, which are sensitive to rate moves.","regulation":"Most are RBI-registered NBFCs (investment and credit companies, core investment companies or primary dealers) with capital and leverage norms; SEBI listing rules apply.","competitiveAdvantages":"Quality and liquidity of holdings, low leverage and a strong parent; for primary dealers, RBI authorisation and bond-market skill.","drivers":[{"factor":"Capital market activity","impact":"Rising share prices lift portfolio values and trading gains."},{"factor":"Interest rates","impact":"Falling yields raise bond values; rising yields cause mark-to-market losses."},{"factor":"Investee performance","impact":"Dividends and value depend on how the companies held perform."},{"factor":"Regulation","impact":"RBI rules on leverage and investments limit how the portfolio can be run."}],"risks":[{"risk":"Market swings","detail":"A falling market cuts both profits and book value quickly."},{"risk":"Holding discount","detail":"Shares often trade well below the value of the investments held."},{"risk":"Rate risk","detail":"Bond-heavy books lose value when yields rise."},{"risk":"Related-party dealings","detail":"Loans or investments in group firms may not serve minority shareholders."},{"risk":"Low liquidity","detail":"Many such shares trade thinly, so prices can be erratic."}],"cyclicality":"Cyclical","cyclicalityNote":"Profits and net worth move with equity and bond markets.","metricSet":"holding-company","relatedBasicIndustries":["b-holding-company","b-asset-management-company","b-non-banking-financial-company-nbfc","b-stockbroking-and-allied"],"aliases":["investment company","nbfc-ic","investment and credit company","primary dealer","gilt company","treasury company","investment firm"],"themes":[]},"b-non-banking-financial-company-nbfc":{"simplifiedExplanation":"Lending companies registered with the RBI that are not banks. They give loans for vehicles, gold, consumer goods, small businesses and personal needs, often to customers banks serve poorly, and fund themselves through borrowings.","productsAndServices":["Vehicle loans (new and used cars, two-wheelers, trucks, tractors)","Gold loans","Personal and consumer-durable loans","MSME and business loans","Loans against property","Co-branded credit cards and digital loans with partners","Equipment finance and leasing"],"valueChainPosition":"Midstream credit providers: they borrow wholesale from banks, mutual funds and bond investors (some also take public deposits) and lend retail, sourcing through dealers, retailers and fintech partners and often co-lending with banks.","howTheyMakeMoney":"Their loans carry higher rates than bank loans, so the spread over their higher borrowing cost is wider. Fees, insurance cross-sell and gains on selling loan pools add income, while credit losses are the main swing factor.","revenueSources":["Interest on loans","Processing and late-payment fees","Insurance and cross-sell commissions","Gains on loan assignment and co-lending","Collection and other charges"],"operatingCosts":["Interest on borrowings","Credit losses and write-offs","Employee and branch costs","Sourcing commissions to dealers and partners","Collection and recovery costs","Technology"],"customersAndEndMarkets":"Retail borrowers, self-employed people, small transport operators, farmers, small businesses and new-to-credit customers across urban and rural India.","demandSupplyDrivers":"Consumption, vehicle sales, rural incomes and MSME activity drive loan demand, while the cost and availability of bank and bond funding drive supply. Gold-loan demand also moves with gold prices.","domesticInternationalExposure":"Domestic lending; some raise foreign-currency loans or bonds.","capexIntensity":"Low","capexNote":"Branches and underwriting and collection technology need modest spending; capital is the real requirement for growth.","workingCapital":"Borrowing tenures must match loan tenures; reliance on short-term commercial paper has caused liquidity crises before, so diversified funding matters.","regulation":"RBI's scale-based regulation (base, middle, upper and top layers) sets capital, provisioning, governance and lending norms; RBI digital-lending and fair-practice rules and bank risk weights on loans to NBFCs also matter.","competitiveAdvantages":"Niche underwriting skill, local collection teams, cheap funding from a strong parent or rating, and dealer and partner relationships.","drivers":[{"factor":"Credit growth","impact":"Strong demand for retail and MSME credit expands loan books."},{"factor":"Interest rates","impact":"Borrowing costs rise and fall faster than many fixed-rate loans reprice, moving margins."},{"factor":"Consumer demand","impact":"Vehicle, durable and personal spending create loan demand."},{"factor":"Rural demand","impact":"Farm incomes drive tractor, two-wheeler and gold-loan demand and repayments."},{"factor":"Regulation","impact":"RBI curbs on unsecured or digital lending can slow growth quickly."},{"factor":"Gold prices","impact":"Higher gold prices let gold lenders lend more against the same jewellery."}],"risks":[{"risk":"Liquidity crunch","detail":"A loss of lender confidence can choke funding and force a growth slowdown."},{"risk":"Asset quality","detail":"Defaults rise quickly in unsecured and small-ticket loans during stress."},{"risk":"Regulatory action","detail":"RBI can restrict products, pricing or sourcing practices."},{"risk":"Competition","detail":"Banks and fintech lenders compete for the best borrowers."},{"risk":"Concentration","detail":"Dependence on one product or region magnifies local shocks."}],"cyclicality":"Cyclical","cyclicalityNote":"Loan growth and credit losses follow consumption, vehicle sales and funding conditions.","metricSet":"nbfc","relatedBasicIndustries":["b-private-sector-bank","b-housing-finance-company","b-microfinance-institutions","b-2-3-wheelers","b-commercial-vehicles"],"aliases":["nbfc","non banking financial company","non-banking finance company","finance company","vehicle finance","gold loan company","consumer finance","msme lender","shadow bank"],"themes":["Rural demand"]},"b-other-financial-services":{"simplifiedExplanation":"A catch-all for financial businesses that are neither banks nor regular lenders - for example asset reconstruction companies that buy bad loans, factoring and forex firms, gift-voucher platforms, advisory boutiques and app-based credit businesses.","productsAndServices":["Purchase and recovery of stressed loans (asset reconstruction)","Factoring and bill discounting","Foreign exchange and money changing","Gift cards, vouchers and rewards programmes","Corporate finance advisory","Buy-now-pay-later and small digital credit"],"valueChainPosition":"Specialists at the edges of the lending system: asset reconstruction companies take bad loans off bank books, factors finance suppliers' invoices to large buyers, and voucher or rewards platforms serve corporates and banks.","howTheyMakeMoney":"It depends on the model: asset reconstruction companies earn management fees plus a share of recoveries above the purchase price, factors and digital lenders earn interest spreads, and voucher, forex and advisory firms earn margins or fees.","revenueSources":["Recoveries and management fees on stressed assets","Interest and discount income","Forex spreads and commissions","Voucher and rewards margins","Advisory fees"],"operatingCosts":["Borrowing costs","Legal and resolution expenses","Staff and technology","Customer acquisition and partner payouts","Credit losses"],"customersAndEndMarkets":"Banks and NBFCs selling bad loans, MSME suppliers, corporates running reward schemes, travellers and students needing forex, and retail app users.","demandSupplyDrivers":"Asset reconstruction depends on how many bad loans banks sell and how fast recoveries happen under IBC and SARFAESI; the other models follow consumer spending, trade flows and deal activity.","domesticInternationalExposure":"Mostly domestic; forex businesses depend on outbound travel and overseas education and are affected by rupee moves.","capexIntensity":"Low","capexNote":"The needs are people, technology and capital to buy assets, not plants.","workingCapital":"Asset reconstruction needs patient capital because recoveries take years; factors and short-term lenders turn money over quickly but rely on bank lines.","regulation":"RBI regulates asset reconstruction companies under the SARFAESI Act, as well as factors, money changers and digital lending; the Insolvency and Bankruptcy Code shapes recovery timelines; SEBI covers advisory and merchant banking.","competitiveAdvantages":"Capital, recovery skill and bank relationships for reconstruction firms; partner networks and technology for platform models.","drivers":[{"factor":"Regulation","impact":"RBI and insolvency rules decide how bad loans are sold, priced and resolved."},{"factor":"Bad-loan sales by banks","impact":"More stressed loans for sale means more buying opportunities for reconstruction firms."},{"factor":"Credit growth","impact":"Faster economic activity raises demand for invoice finance and small credit."},{"factor":"Consumer demand","impact":"Spending on gifting, rewards and travel drives voucher and forex volumes."},{"factor":"Interest rates","impact":"Funding costs set margins for factoring and lending models."}],"risks":[{"risk":"Slow recoveries","detail":"Court and insolvency delays can erode the value of stressed assets bought."},{"risk":"Rule changes","detail":"RBI tightening on stressed-asset deals or digital credit can reshape the business."},{"risk":"Credit losses","detail":"Small-ticket digital and invoice loans can default in bulk."},{"risk":"Partner dependence","detail":"Platform models often rely on a few banks or corporate clients."}],"cyclicality":"Mixed","cyclicalityNote":"Reconstruction firms find more assets in bad times, while consumer-linked models do better in good times.","metricSet":"nbfc","relatedBasicIndustries":["b-non-banking-financial-company-nbfc","b-securitisation","b-public-sector-bank","b-financial-technology-fintech","b-other-capital-market-related-services"],"aliases":["other financial services","asset reconstruction company","arc","factoring","forex dealer","money changer","gift card company","bnpl"],"themes":[]},"b-holding-company":{"simplifiedExplanation":"Companies that exist mainly to own large or controlling stakes in a business group's operating companies. They do little business of their own; their worth comes from those stakes.","productsAndServices":["Stakes in listed group companies","Stakes in unlisted subsidiaries","Brand ownership and royalty arrangements","Group treasury and inter-company loans","Some house financial-services subsidiaries (broking, lending, advisory)"],"valueChainPosition":"At the top of a business group's ownership chain, between the promoter family and the operating companies.","howTheyMakeMoney":"Dividends from group companies, interest on loans to them, occasional brand fees and gains when stakes are sold. Consolidated results mirror the subsidiaries.","revenueSources":["Dividends from investee companies","Interest on inter-corporate loans","Brand or management fees","Gains on stake sales"],"operatingCosts":["Small head-office and staff costs","Interest on any borrowings","Taxes on dividends and gains"],"customersAndEndMarkets":"Their main counterparties are their own group companies; investors buy them as an indirect route into the group's businesses.","demandSupplyDrivers":"Value depends on the market price of the stakes held, the dividends paid and whether the gap to underlying value narrows or widens, for example on restructuring, mergers or buybacks.","domesticInternationalExposure":"Follows the businesses owned; some group companies operate globally.","capexIntensity":"Low","capexNote":"Capital is tied up in shareholdings, not physical assets.","workingCapital":"Minimal; cash flow is lumpy and depends on when group companies pay dividends.","regulation":"Those mainly holding group-company shares may need RBI registration as core investment companies with leverage limits; SEBI takeover and listing rules govern stake changes; dividend taxation affects how much value passes through.","competitiveAdvantages":"There is no operating moat of its own; quality of the underlying companies and promoter governance are what count.","drivers":[{"factor":"Capital market activity","impact":"Prices of the listed stakes drive the value of the holding company."},{"factor":"Group company performance","impact":"Profits and dividends of investees flow up as income."},{"factor":"Group restructuring","impact":"Mergers, demergers or simplification can narrow the holding discount."},{"factor":"Regulation","impact":"Tax and RBI rules on core investment companies shape payouts and borrowing."}],"risks":[{"risk":"Holding discount","detail":"Shares often trade far below the value of the stakes held."},{"risk":"Low liquidity","detail":"Thin trading makes prices volatile and exits hard."},{"risk":"Governance","detail":"Decisions may favour the promoter group over minority holders."},{"risk":"Concentration","detail":"Value often rests on one or two group companies."},{"risk":"Tax leakage","detail":"Dividends taxed at several layers reduce what reaches shareholders."}],"cyclicality":"Mixed","cyclicalityNote":"It mirrors the industries of the companies held - steady if they are stable, cyclical if they are not.","metricSet":"holding-company","relatedBasicIndustries":["b-investment-company","b-diversified","b-asset-management-company","b-stockbroking-and-allied"],"aliases":["holding company","holdco","promoter holding company","group holding company","core investment company","cic","investment holding company"],"themes":[]},"b-microfinance-institutions":{"simplifiedExplanation":"Lenders that give small loans without collateral, mainly to women in low-income households, usually through groups that meet regularly and repay in small, frequent instalments.","productsAndServices":["Joint liability group (JLG) loans","Individual micro-enterprise loans","Income-generation and livestock loans","Small loans for home repair, sanitation or solar products","Credit-linked life insurance","Small MSME loans for graduating borrowers"],"valueChainPosition":"Last-mile lenders funded by banks, development financiers and bond investors; field staff meet borrowers in their villages and neighbourhoods to disburse and collect.","howTheyMakeMoney":"Relatively high lending rates pay for a costly field-staff model and credit losses; profit is the spread left after these costs. Selling loan pools to banks, which count them as priority-sector loans, helps fund growth.","revenueSources":["Interest on microloans","Processing fees","Insurance commissions","Gains on securitisation and assignment of loans"],"operatingCosts":["Interest on borrowings","Salaries of a large field staff","Credit losses","Branch and travel costs","Collection technology"],"customersAndEndMarkets":"Low-income women, rural households, small traders, artisans and farm-linked micro-businesses.","demandSupplyDrivers":"Credit demand from under-banked households is large; supply depends on bank funding and investor confidence. Several lenders chasing the same borrower is the main danger to the whole system.","domesticInternationalExposure":"Domestic lending; foreign impact investors sometimes provide equity or debt.","capexIntensity":"Low","capexNote":"Branches are small and simple; spending goes mainly on people and collection technology.","workingCapital":"Short loan tenures with frequent repayments roughly match their borrowings, so collection efficiency directly drives liquidity.","regulation":"RBI's microfinance framework defines microloans by household income, caps repayment burden relative to income and sets fair-practice rules; industry self-regulatory guardrails limit the number of lenders per borrower.","competitiveAdvantages":"Dense field networks, borrower relationships, credit-bureau discipline and wide geographic spread; scale lowers funding cost.","drivers":[{"factor":"Rural demand","impact":"Village incomes drive both demand for loans and ability to repay."},{"factor":"Monsoon & agriculture","impact":"A poor monsoon hurts farm-linked borrowers and collections."},{"factor":"Borrower over-indebtedness","impact":"Borrowers juggling several lenders push defaults up across the industry."},{"factor":"Regulation","impact":"RBI and self-regulatory limits shape loan size, pricing and lender count per borrower."},{"factor":"Credit growth","impact":"Bank appetite to lend to MFIs or buy their pools governs growth."}],"risks":[{"risk":"Over-lending cycle","detail":"Rapid industry growth can end in sharp spikes in defaults."},{"risk":"Local disruptions","detail":"Floods, elections, unrest or local laws can halt collections in a region."},{"risk":"Political risk","detail":"Loan-waiver talk or state action can make borrowers stop repaying."},{"risk":"Funding","detail":"Banks pull back from the segment during stress, raising costs."},{"risk":"State concentration","detail":"Heavy exposure to a few states magnifies local shocks."}],"cyclicality":"Cyclical","cyclicalityNote":"Credit costs jump during rural shocks or over-lending phases and then normalise.","metricSet":"microfinance","relatedBasicIndustries":["b-other-bank","b-non-banking-financial-company-nbfc","b-private-sector-bank","b-securitisation"],"aliases":["mfi","microfinance","micro finance","nbfc-mfi","microlender","jlg loans","group lending","micro credit"],"themes":["Financial inclusion","Rural demand"]},"b-securitisation":{"simplifiedExplanation":"Securitisation turns a pool of loans (vehicle, home, microfinance or other loans) into securities that investors can buy. Entities here are mostly special-purpose trusts or companies that hold such pools and pass the borrowers' repayments to investors.","productsAndServices":["Pass-through certificates (PTCs) backed by loan pools","Listed securitised debt instruments","Security receipts on stressed assets","Senior and junior tranches with credit enhancement","Servicing and collection of pooled loans"],"valueChainPosition":"Sits between loan originators (banks, NBFCs, HFCs, MFIs) and investors (banks, mutual funds, insurers); rating agencies rate the tranches and trustees oversee the trust.","howTheyMakeMoney":"The vehicle itself is built to pass cash through rather than earn a profit. The originator keeps any excess spread and servicing fees, investors earn the coupon, and arrangers and trustees earn fees.","revenueSources":["Interest and principal from the loan pool (passed to investors)","Excess spread retained for the originator","Servicing fees","Structuring and trustee fees"],"operatingCosts":["Payouts to investors","Servicing and collection costs","Rating, trustee and legal fees","Losses absorbed by credit enhancement"],"customersAndEndMarkets":"Banks buying retail or priority-sector pools, mutual funds, insurers and other fixed-income investors; originators use it to raise funds and free up capital.","demandSupplyDrivers":"Issuance rises when lenders need funding beyond bank loans or want to sell priority-sector pools; investor appetite depends on interest rates and how earlier pools performed.","domesticInternationalExposure":"A domestic market; foreign portfolio investors take part occasionally.","capexIntensity":"Low","capexNote":"These are legal structures with no physical assets.","workingCapital":"Borrower collections are passed to investors on a fixed schedule; shortfalls hit the junior tranche and credit enhancement first.","regulation":"RBI's securitisation directions set minimum holding periods, minimum retention by the originator and allowed structures; SEBI rules govern listed securitised debt; security receipts fall under the SARFAESI Act.","competitiveAdvantages":"Originator quality, a clean pool-performance record and high ratings decide pricing; for equity investors this is rarely a listed operating business.","drivers":[{"factor":"Interest rates","impact":"Rate levels decide the yield investors demand and whether deals make sense for originators."},{"factor":"Credit growth","impact":"Fast retail lending creates more pools to sell."},{"factor":"Regulation","impact":"RBI holding-period and retention rules shape deal volumes."},{"factor":"Pool asset quality","impact":"Defaults in underlying loans decide tranche losses and future appetite."}],"risks":[{"risk":"Pool defaults","detail":"Borrower stress can exhaust credit enhancement and hit investors."},{"risk":"Prepayment","detail":"Early repayments shorten the life and yield of the securities."},{"risk":"Rule changes","detail":"New RBI or SEBI norms can make structures uneconomic."},{"risk":"Thin secondary market","detail":"Investors may struggle to sell before maturity."}],"cyclicality":"Cyclical","cyclicalityNote":"Issuance and pool performance follow the credit cycle and funding conditions.","metricSet":"nbfc","relatedBasicIndustries":["b-non-banking-financial-company-nbfc","b-housing-finance-company","b-microfinance-institutions","b-other-financial-services","b-ratings"],"aliases":["securitisation","securitization","ptc","pass through certificate","securitised debt instrument","sdi","asset backed securities","abs"],"themes":[]},"b-public-sector-bank":{"simplifiedExplanation":"Banks in which the Government of India holds a majority stake. They take deposits from the public and lend to individuals, businesses, farmers and the government through large branch networks that reach small towns and villages.","productsAndServices":["Savings, current and fixed deposits","Corporate and infrastructure loans","Agricultural and MSME loans","Home, vehicle and personal loans","Government business and welfare payments","Treasury and government bond investments","Insurance and mutual fund sales through branches"],"valueChainPosition":"Core of India's credit system: they collect household savings and channel them to companies, small businesses, farmers and the government (through bond holdings), and act as bankers to central and state governments.","howTheyMakeMoney":"Mainly the spread between interest earned on loans and bonds and interest paid on deposits. Fees and cross-selling add income, and treasury gains or losses on bonds can swing profits when rates move.","revenueSources":["Interest on loans","Interest on government and other bonds","Fees and commissions","Treasury (bond trading) gains","Recoveries from written-off loans"],"operatingCosts":["Interest on deposits and borrowings","Employee salaries and pensions","Provisions for bad loans","Branch network and technology","Deposit insurance premium"],"customersAndEndMarkets":"Retail savers across urban and rural India, large corporates and PSUs, MSMEs, farmers and government departments.","demandSupplyDrivers":"Loan demand follows economic activity, corporate investment and government infrastructure spending; deposit growth depends on household savings and competition from mutual funds and small-savings schemes. RBI rate changes reprice loans faster than deposits, moving margins.","domesticInternationalExposure":"Mostly domestic; some run overseas branches and GIFT City units serving Indian businesses and the diaspora. Global rates matter through bond yields.","capexIntensity":"Low","capexNote":"Branches and core-banking IT are modest next to the balance sheet; growth instead consumes regulatory capital from retained profit, share sales or the government.","workingCapital":"The usual working-capital idea does not apply; what matters is liquidity (cash and bonds held under CRR, SLR and liquidity-coverage rules) and matching loan and deposit maturities.","regulation":"RBI regulates them under the Banking Regulation Act (capital, CRR/SLR, priority-sector lending, NPA recognition, prompt corrective action); the government as owner appoints top management, injects capital and may steer policy lending.","competitiveAdvantages":"A huge low-cost deposit base, deep rural reach, government business and the trust that comes with state ownership; slower decisions and technology catch-up are common weaknesses.","drivers":[{"factor":"Interest rates","impact":"RBI rate moves change loan yields, deposit costs and the value of large bond holdings."},{"factor":"Credit growth","impact":"Corporate and infrastructure borrowing revive loan books in an upswing."},{"factor":"Government policy","impact":"Recapitalisation, mergers, stake sales and directed lending shape returns."},{"factor":"Infrastructure spending","impact":"Public capex creates demand for project and working-capital loans."},{"factor":"Asset quality cycle","impact":"Recoveries lift profits; new stress forces heavy provisions."}],"risks":[{"risk":"Bad loans","detail":"Corporate or farm stress can raise NPAs and provisions quickly."},{"risk":"Government directives","detail":"Policy lending, loan waivers or forced mergers can hurt minority shareholders."},{"risk":"Bond-yield spikes","detail":"Rising yields cause mark-to-market losses on big bond portfolios."},{"risk":"Deposit competition","detail":"Savers moving to markets or private banks raise funding costs."},{"risk":"Equity dilution","detail":"New share issues to fund growth or meet capital rules dilute holders."}],"cyclicality":"Cyclical","cyclicalityNote":"Profits swing with the credit cycle - strong when bad loans recover, weak when they pile up.","metricSet":"bank","relatedBasicIndustries":["b-private-sector-bank","b-other-bank","b-financial-institution","b-life-insurance","b-non-banking-financial-company-nbfc"],"aliases":["psu bank","public sector bank","psb","nationalised bank","nationalized bank","government bank","state-owned bank","public bank"],"themes":["PSU"]},"b-private-sector-bank":{"simplifiedExplanation":"Banks owned mainly by private shareholders - promoters, institutions and the public. They do the same basic job as public banks but usually lean more on retail customers, fee products and digital channels.","productsAndServices":["Savings, current and term deposits","Home, auto and personal loans and credit cards","Business banking and working-capital loans","Corporate and transaction banking","Wealth management and third-party product sales","Mobile and internet banking"],"valueChainPosition":"Intermediaries between savers and borrowers, competing with public banks for deposits and with NBFCs and fintechs for retail and small-business loans; many own insurance, asset management and broking subsidiaries.","howTheyMakeMoney":"Net interest income is the main engine, backed by a large fee stream from cards, payments and sales of insurance and mutual funds. Higher-yield retail and unsecured loans lift margins but add credit risk.","revenueSources":["Interest on retail and corporate loans","Investment income on bonds","Card, payment and transaction fees","Insurance and mutual fund distribution commissions","Forex and treasury income"],"operatingCosts":["Interest on deposits and borrowings","Employee salaries and incentives","Loan-loss provisions","Technology, cybersecurity and branch expansion","Customer acquisition and marketing"],"customersAndEndMarkets":"Urban and semi-urban retail customers, salaried professionals, SMEs and corporates; older regional private banks often have a loyal home-state base.","demandSupplyDrivers":"Retail credit demand, business working-capital needs and the ability to raise deposits drive growth. The fight for low-cost CASA deposits and RBI rules on unsecured lending set how fast they can grow.","domesticInternationalExposure":"Business is largely domestic, but foreign investors often own large stakes, so global fund flows affect valuations.","capexIntensity":"Low","capexNote":"Spending goes on branches and technology; capital from profits and share issues is the real constraint on growth.","workingCapital":"Judged through liquidity and the loan-to-deposit ratio rather than inventory; fast loan growth without matching deposits strains funding.","regulation":"RBI licensing and supervision cover capital, CRR/SLR, priority-sector targets, promoter-holding limits and approval of top management; foreign-ownership limits are set by the government.","competitiveAdvantages":"Strong brands, low-cost deposit franchises, technology, cross-selling and underwriting discipline protect the leaders; smaller banks rely on regional relationships.","drivers":[{"factor":"Credit growth","impact":"Retail and SME loan demand sets the pace of balance-sheet growth."},{"factor":"Interest rates","impact":"Rate cuts reprice floating-rate loans faster than deposits, squeezing margins for a while."},{"factor":"Consumer demand","impact":"Spending on homes, cars and cards drives fee and loan growth."},{"factor":"Deposit competition","impact":"The cost of attracting savings decides how cheaply they can fund loans."},{"factor":"Regulation","impact":"Higher risk weights or curbs on certain loans can slow growth."},{"factor":"Technology change","impact":"Digital channels cut costs but raise competition from fintechs."}],"risks":[{"risk":"Unsecured loan stress","detail":"Credit card and personal loan defaults can rise fast in a slowdown."},{"risk":"Deposit squeeze","detail":"Slow deposit growth forces costlier funding or slower lending."},{"risk":"Governance and leadership","detail":"RBI scrutiny or management change can shake confidence."},{"risk":"Tech outages","detail":"Repeated outages can lead RBI to restrict new customers or products."},{"risk":"Regional concentration","detail":"Smaller banks depend heavily on one or two states."}],"cyclicality":"Cyclical","cyclicalityNote":"Loan growth and credit costs move with the economy, though strong franchises tend to stay profitable through it.","metricSet":"bank","relatedBasicIndustries":["b-public-sector-bank","b-other-bank","b-non-banking-financial-company-nbfc","b-life-insurance","b-asset-management-company"],"aliases":["private bank","private sector bank","new generation bank","old private bank","commercial bank","retail bank","scheduled bank"],"themes":[]},"b-other-bank":{"simplifiedExplanation":"Banks with special, narrower licences - mainly small finance banks, which lend to small borrowers and the underbanked, and payments banks, which take small deposits and handle payments but cannot lend.","productsAndServices":["Microfinance (group) loans","Small business and MSME loans","Affordable home, vehicle and gold loans","Savings accounts and fixed deposits","Remittances, bill payments and cash withdrawal at agent points","Debit cards, wallets and UPI services"],"valueChainPosition":"The last mile of the banking system, serving rural and semi-urban customers that larger banks find costly to reach. Many began as microfinance NBFCs and became banks to tap deposits.","howTheyMakeMoney":"Small finance banks earn wide spreads because their loans carry higher rates, offset by higher operating and credit costs. Payments banks earn transaction and remittance fees plus interest on the government securities where they must park deposits.","revenueSources":["Interest on small loans","Interest on government securities","Processing and transaction fees","Commissions on insurance and other products","Merchant and remittance fees"],"operatingCosts":["Interest on deposits, often priced higher to attract savers","Field staff and branch network","Credit losses on unsecured loans","Technology and agent commissions","Compliance and deposit insurance"],"customersAndEndMarkets":"Low-income households, women borrower groups, micro-entrepreneurs, small traders and farmers; payments banks also serve migrant workers and merchants.","demandSupplyDrivers":"Demand for small loans is large and under-served; growth depends on raising deposits cheaply and keeping collections steady. Rural incomes and competition from fintech lenders also matter.","domesticInternationalExposure":"Entirely domestic business.","capexIntensity":"Low","capexNote":"Branch and agent expansion and core-banking systems need steady spending, but capital adequacy is the bigger constraint.","workingCapital":"Liquidity and deposit stability matter most; reliance on bulk or high-cost deposits makes funding sensitive to confidence.","regulation":"RBI's differentiated licences: small finance banks must meet priority-sector and small-loan requirements, payments banks cannot lend and have caps on balances per customer, and moving to a universal licence needs RBI approval.","competitiveAdvantages":"Deep local knowledge, field collection processes and low-cost reach to remote areas; building a trusted deposit franchise is the main barrier.","drivers":[{"factor":"Rural demand","impact":"Rural incomes decide loan demand and repayment capacity."},{"factor":"Monsoon & agriculture","impact":"Farm stress quickly shows up in small-loan collections."},{"factor":"Interest rates","impact":"Deposit rates they must offer set the cost of funding."},{"factor":"Regulation","impact":"Licence conditions limit products and decide when they can graduate to full banks."},{"factor":"Credit growth","impact":"Formal credit reaching new borrowers expands their market."}],"risks":[{"risk":"Microfinance stress","detail":"Over-indebted borrowers or local disruptions can spike defaults."},{"risk":"High funding cost","detail":"Smaller brands must pay more for deposits than large banks."},{"risk":"Geographic concentration","detail":"Many depend on a few states."},{"risk":"Regulatory action","detail":"RBI restrictions can halt new accounts or products."},{"risk":"Fintech competition","detail":"Apps compete for payments and small-ticket credit."}],"cyclicality":"Cyclical","cyclicalityNote":"Asset quality is sensitive to rural incomes, local events and borrower over-borrowing.","metricSet":"bank","relatedBasicIndustries":["b-microfinance-institutions","b-private-sector-bank","b-public-sector-bank","b-financial-technology-fintech","b-non-banking-financial-company-nbfc"],"aliases":["small finance bank","sfb","payments bank","payment bank","differentiated bank","local area bank","co-operative bank"],"themes":["Financial inclusion","Rural demand"]},"b-asset-management-company":{"simplifiedExplanation":"Companies that run mutual funds and other investment pools for investors. They pool money from many people, invest it in shares, bonds or other assets, and charge a fee based on the money they manage.","productsAndServices":["Equity, debt and hybrid mutual funds","Index funds and ETFs","Systematic investment plans (SIPs)","Portfolio management services (PMS)","Alternative investment funds (AIFs)","Offshore and advisory mandates"],"valueChainPosition":"They manufacture investment products; distributors, banks, brokers and online platforms sell them, while registrars, custodians and depositories handle records and safekeeping.","howTheyMakeMoney":"A management fee charged as a share of assets under management, within SEBI's limits on scheme expense ratios. Equity funds earn higher fees than debt or index funds, so the product mix matters as much as total AUM.","revenueSources":["Management fees on mutual fund AUM","PMS and AIF fees, including performance fees","Advisory fees on offshore mandates","Returns on own investments"],"operatingCosts":["Employee costs for fund managers and sales","Distributor commissions not borne by schemes","Marketing and investor education","Technology and registrar charges","Regulatory fees"],"customersAndEndMarkets":"Retail investors (often via SIPs), wealthy individuals, corporates, banks, insurers and retirement funds.","demandSupplyDrivers":"Inflows depend on households shifting savings from deposits and gold to market products, SIP habits, fund returns and distributor reach. Market levels change AUM even without new money.","domesticInternationalExposure":"Mostly Indian investors and assets; some manage offshore funds or advise global investors on Indian equities.","capexIntensity":"Low","capexNote":"A people-and-technology business with little physical capital.","workingCapital":"Fees are taken from scheme assets on a running basis, so receivables are low and cash generation is strong.","regulation":"SEBI mutual fund rules govern expense-ratio caps, scheme categories, skin-in-the-game requirements and disclosures; AMFI sets distributor norms; changes in tax on fund gains affect demand.","competitiveAdvantages":"Brand, long performance records, distribution reach and scale (low cost per rupee managed); the move to passive funds pressures fees.","drivers":[{"factor":"Capital market activity","impact":"Rising markets lift AUM and attract fresh equity inflows."},{"factor":"Household savings shift","impact":"Savings moving from deposits and gold into funds widens the base."},{"factor":"Regulation","impact":"Changes to expense-ratio caps or commissions reset fee yields."},{"factor":"Interest rates","impact":"Rate moves shift money between debt funds, deposits and equities."},{"factor":"Tax rules","impact":"Changes in tax on fund gains alter the appeal of debt and equity schemes."}],"risks":[{"risk":"Market downturn","detail":"Falling prices shrink AUM and can trigger redemptions."},{"risk":"Fee cuts","detail":"Lower allowed expense ratios reduce revenue per rupee managed."},{"risk":"Weak fund performance","detail":"Lagging returns push investors to rival fund houses."},{"risk":"Passive shift","detail":"Growth of low-fee index funds compresses margins."},{"risk":"Key-person risk","detail":"Exit of star fund managers can cause outflows."}],"cyclicality":"Mixed","cyclicalityNote":"AUM and fees follow markets, but recurring SIP flows and sticky assets soften the swings.","metricSet":"capital-markets","relatedBasicIndustries":["b-financial-products-distributor","b-depositories-clearing-houses-and-other-intermediaries","b-stockbroking-and-allied","b-life-insurance","b-exchange-and-data-platform"],"aliases":["amc","asset management company","mutual fund house","fund house","asset manager","mutual fund company","investment manager","pms"],"themes":["Financialisation of savings"]},"b-depositories-clearing-houses-and-other-intermediaries":{"simplifiedExplanation":"The back-office plumbing of the market: depositories hold shares and bonds in electronic (demat) form, and registrars keep investor records for mutual funds and companies. They earn small fees on a very large number of accounts and transactions.","productsAndServices":["Demat holding and transfer of securities","Corporate actions and e-voting","KYC registration (KRA) services","Mutual fund registrar and transfer agency","Share registry and IPO processing for companies","Investor statements, data and technology services","Insurance repository and other record-keeping"],"valueChainPosition":"Market infrastructure used by exchanges, brokers, depository participants, fund houses and listed companies; they serve the whole market rather than competing for end investors.","howTheyMakeMoney":"Depositories charge annual fees to issuers, charges on debit transactions and fees for KYC, e-voting and data; registrars charge fund houses fees linked to assets or folios. Costs are largely fixed, so higher volumes lift margins.","revenueSources":["Annual issuer charges","Transaction and settlement charges","KYC and account-related fees","Registrar fees from mutual funds and companies","E-voting, data and technology services"],"operatingCosts":["Technology and data centres","Cybersecurity and disaster recovery","Employee costs","Regulatory and investor-protection fund contributions"],"customersAndEndMarkets":"Listed and unlisted companies, mutual funds, depository participants (brokers and banks), exchanges and, indirectly, every investor.","demandSupplyDrivers":"Growth in demat accounts, trading activity, new listings and mutual fund folios drives revenue, while SEBI pricing decisions can reset fee levels.","domesticInternationalExposure":"Domestic; some sell software or services abroad and in GIFT City.","capexIntensity":"Medium","capexNote":"Resilient systems, data centres and security need continuous investment.","workingCapital":"Light; most fees are collected in advance or quickly.","regulation":"SEBI recognises depositories and clearing corporations as market infrastructure institutions and registers registrars and KRAs, controlling ownership, governance and fees.","competitiveAdvantages":"Regulatory licences, network effects, high switching costs for fund houses and issuers, and very few competitors.","drivers":[{"factor":"Capital market activity","impact":"More trading, IPOs and new investors raise transaction and account fees."},{"factor":"Mutual fund growth","impact":"Rising fund AUM and folios lift registrar income."},{"factor":"Regulation","impact":"SEBI decisions on fees and processes directly change revenue."},{"factor":"Technology change","impact":"New digital services (KYC, data, e-voting) add income but need investment."}],"risks":[{"risk":"Fee cuts","detail":"SEBI can lower or restructure charges paid by investors and issuers."},{"risk":"Market slowdown","detail":"Fewer transactions and listings reduce variable income."},{"risk":"System outages","detail":"Failures invite penalties and reputational damage."},{"risk":"Client concentration","detail":"Registrars depend on a limited number of large fund houses."}],"cyclicality":"Mixed","cyclicalityNote":"Annual and record-keeping fees are steady, while transaction and IPO income follows market activity.","metricSet":"capital-markets","relatedBasicIndustries":["b-exchange-and-data-platform","b-stockbroking-and-allied","b-asset-management-company","b-data-processing-services"],"aliases":["depository","demat","registrar and transfer agent","rta","kra","clearing corporation","clearing house","market infrastructure institution"],"themes":["Financialisation of savings","Digital"]},"b-financial-products-distributor":{"simplifiedExplanation":"Firms that sell and advise on investment products made by others - mainly mutual funds, plus insurance, bonds, PMS and AIFs. Wealth managers in this group look after the money of affluent families.","productsAndServices":["Mutual fund distribution","Wealth management for affluent families","Insurance distribution","Bonds, structured products and fixed deposits","PMS and AIF distribution","Online platforms for sub-distributors and advisers"],"valueChainPosition":"Downstream of fund houses and insurers, linking product makers to investors through relationship managers, partner networks or digital platforms.","howTheyMakeMoney":"Mostly trail commissions paid by fund houses as a share of client assets, so income grows with the assets they influence; wealth managers also earn on structured products and advisory fees.","revenueSources":["Trail commissions on mutual fund assets","Fees on structured products","Insurance commissions","Advisory and platform fees"],"operatingCosts":["Relationship manager salaries and incentives","Payouts to sub-distributors and partners","Technology platforms","Compliance and marketing"],"customersAndEndMarkets":"Retail investors in smaller towns reached through partner networks, affluent and high-net-worth families, and independent advisers using their platforms.","demandSupplyDrivers":"Market levels, SIP flows and the shift of savings to market products drive assets; investors moving to direct plans or fee-only advisers shrink the commission pool.","domesticInternationalExposure":"Domestic; some also serve non-resident Indians.","capexIntensity":"Low","capexNote":"A people-driven business with light technology spend.","workingCapital":"Light; commissions arrive regularly from product makers.","regulation":"AMFI registration and SEBI rules on distributors, separation of advice from distribution, commission disclosure and expense-ratio limits; IRDAI governs insurance commissions.","competitiveAdvantages":"Sticky client relationships, trust, adviser networks and broad product shelves; low-cost platforms compete on price.","drivers":[{"factor":"Capital market activity","impact":"Rising markets increase client assets and trail income."},{"factor":"Household savings shift","impact":"More families investing in funds enlarges the client base."},{"factor":"Regulation","impact":"Rules on commissions and advice can change how they are paid."},{"factor":"Technology change","impact":"Direct and app-based investing competes with commission-based distribution."}],"risks":[{"risk":"Commission cuts","detail":"Lower expense ratios flow through to lower trail payouts."},{"risk":"Direct plans","detail":"Investors bypassing distributors shrink the paying base."},{"risk":"Market fall","detail":"Asset-linked income falls with prices."},{"risk":"Banker attrition","detail":"Relationship managers leaving can take clients with them."},{"risk":"Mis-selling","detail":"Unsuitable product sales invite penalties and reputational harm."}],"cyclicality":"Cyclical","cyclicalityNote":"Income tracks market values and investor sentiment.","metricSet":"capital-markets","relatedBasicIndustries":["b-asset-management-company","b-stockbroking-and-allied","b-insurance-distributors","b-depositories-clearing-houses-and-other-intermediaries"],"aliases":["mutual fund distributor","mfd","wealth manager","wealth management","financial advisor","investment adviser","financial planner","distribution platform"],"themes":["Financialisation of savings"]},"b-ratings":{"simplifiedExplanation":"Credit rating agencies give opinions, as letter grades, on how likely a borrower is to repay its debt. Companies and lenders pay for ratings because banks, regulators and bond investors rely on them.","productsAndServices":["Ratings on bonds, debentures and commercial paper","Bank loan ratings","Securitisation and structured finance ratings","Ratings for SMEs, infrastructure and municipal bonds","Research, industry reports and risk analytics","Outsourced analytics and ESG services"],"valueChainPosition":"Information intermediaries between borrowers (companies, NBFCs, municipalities) and lenders or investors; their grades decide bank capital needs and whether investors may buy a paper.","howTheyMakeMoney":"Mostly an issuer-pays model: an initial fee when a debt is rated and annual surveillance fees while it is outstanding. Research, analytics and outsourcing services add non-rating income.","revenueSources":["Initial rating fees","Annual surveillance fees","Research and data subscriptions","Analytics and outsourcing services"],"operatingCosts":["Analyst salaries (the main cost)","Technology and data","Compliance","Office costs"],"customersAndEndMarkets":"Corporates, banks, NBFCs, infrastructure projects and municipal bodies, plus investors and lenders who buy research.","demandSupplyDrivers":"Bond and commercial-paper issuance, bank credit growth and securitisation volumes drive new mandates, while surveillance fees on existing ratings give a recurring base.","domesticInternationalExposure":"Ratings are domestic; some have analytics or research arms serving global clients.","capexIntensity":"Low","capexNote":"An analyst-driven service business.","workingCapital":"Fees are collected upfront or yearly, so receivables are modest.","regulation":"SEBI's credit rating agency regulations cover conflicts of interest, disclosures and rating performance; RBI accreditation lets bank-loan ratings be used for capital calculations.","competitiveAdvantages":"Reputation, regulatory accreditation and long rating histories make entry hard; the industry has few players.","drivers":[{"factor":"Capital market activity","impact":"Busy bond and commercial-paper markets mean more instruments to rate."},{"factor":"Credit growth","impact":"Bank lending to rated borrowers drives bank-loan rating demand."},{"factor":"Interest rates","impact":"Lower rates encourage companies to issue more bonds."},{"factor":"Regulation","impact":"Rules requiring rated instruments create steady demand."}],"risks":[{"risk":"Issuance slowdown","detail":"Fewer bonds and loans mean fewer new mandates."},{"risk":"Rating failures","detail":"Missing a major default damages credibility."},{"risk":"Regulatory penalties","detail":"SEBI can fine or restrict agencies over lapses."},{"risk":"Fee competition","detail":"Agencies may undercut each other to win issuers."}],"cyclicality":"Mixed","cyclicalityNote":"Surveillance fees are steady, while new rating income follows borrowing and bond-market activity.","metricSet":"capital-markets","relatedBasicIndustries":["b-other-capital-market-related-services","b-securitisation","b-non-banking-financial-company-nbfc","b-consulting-services","b-exchange-and-data-platform"],"aliases":["credit rating agency","rating agency","cra","credit ratings","bond ratings","ratings company"],"themes":[]},"b-exchange-and-data-platform":{"simplifiedExplanation":"Exchanges are organised marketplaces where buyers and sellers trade shares, derivatives, commodities or electricity under set rules. They earn a small fee on each trade and charge for listings, data and technology access.","productsAndServices":["Equity cash and derivatives trading","Commodity futures and options","Electricity and energy-certificate trading","Listing services for companies and bonds","Market data feeds and index licensing","Co-location and trading technology","Clearing and settlement through clearing corporations"],"valueChainPosition":"Core market infrastructure: brokers bring orders, the exchange matches them, clearing corporations settle them and depositories record ownership; data goes to brokers, vendors and fund managers.","howTheyMakeMoney":"Transaction charges on traded value or option premium, plus listing fees, data and index licence fees, co-location charges and income on clearing funds. Costs are largely fixed, so higher volumes bring strong operating leverage.","revenueSources":["Transaction charges","Listing and annual fees","Data, index and licensing fees","Co-location and technology services","Clearing and settlement fees","Treasury income"],"operatingCosts":["Technology and software licences","SEBI regulatory fees","Settlement guarantee fund contributions","Employee costs","Investor protection and other mandated funds"],"customersAndEndMarkets":"Brokers and their clients (retail, institutional, proprietary traders), listed companies, power producers and distributors for power exchanges, and data users.","demandSupplyDrivers":"Volatility, retail participation, derivatives activity, IPO pipelines and gaps in power supply drive volumes; curbs on speculative trading can reduce them.","domesticInternationalExposure":"Domestic markets, with some international activity through GIFT City; global events drive volatility and volumes.","capexIntensity":"Medium","capexNote":"Trading systems, data centres and cybersecurity need constant upgrades.","workingCapital":"Light; fees are collected promptly, and member margins held for settlement are client money, not the exchange's own working capital.","regulation":"SEBI recognises and regulates stock and commodity exchanges, approving products and fees, capping ownership and setting guarantee-fund rules; power exchanges come under CERC, including any market-coupling decisions.","competitiveAdvantages":"Liquidity attracts more liquidity: network effects, licences and ownership caps make new entry very difficult.","drivers":[{"factor":"Capital market activity","impact":"More traders and higher volatility raise transaction volumes."},{"factor":"Regulation","impact":"SEBI or CERC changes to products, fees or trading rules move volumes directly."},{"factor":"Technology change","impact":"Faster, reliable systems and new products are needed to keep volumes."},{"factor":"Electricity demand","impact":"Supply shortages and price swings drive spot power trading."},{"factor":"IPO pipeline","impact":"New listings add listing fees and investor interest."}],"risks":[{"risk":"Derivatives curbs","detail":"Rules to cool retail F&O trading can cut the largest revenue stream."},{"risk":"Pricing pressure","detail":"Regulators or competition can force lower transaction charges."},{"risk":"System outages","detail":"Glitches bring penalties and loss of trust."},{"risk":"Market coupling","detail":"Pooling of power-exchange bids could weaken a leading exchange's edge."}],"cyclicality":"Mixed","cyclicalityNote":"Volumes jump in active markets and fade in quiet ones, but dominant exchanges stay profitable.","metricSet":"capital-markets","relatedBasicIndustries":["b-depositories-clearing-houses-and-other-intermediaries","b-stockbroking-and-allied","b-power-trading","b-asset-management-company"],"aliases":["stock exchange","commodity exchange","power exchange","energy exchange","bourse","derivatives exchange","market data","index provider"],"themes":["Financialisation of savings"]},"b-stockbroking-and-allied":{"simplifiedExplanation":"Brokers let investors buy and sell shares, derivatives and commodities on exchanges, and often add margin funding, research, wealth management and investment banking. They range from low-cost app-based brokers to full-service and wealth firms.","productsAndServices":["Equity, derivatives, currency and commodity broking","Margin trading funding (MTF)","Depository participant services","Mutual fund and IPO distribution","Research and advisory","Wealth management and investment banking","Institutional broking"],"valueChainPosition":"The front end of the market: they bring retail and institutional orders to exchanges and route settlement through clearing corporations and depositories.","howTheyMakeMoney":"Brokerage per order or as a share of trade value, interest on margin funding and on funds kept with exchanges, depository charges and distribution commissions; wealth firms earn fees on assets they manage or advise.","revenueSources":["Brokerage","Interest on margin funding","Depository charges","Distribution and advisory fees","Investment banking fees","Interest on exchange deposits"],"operatingCosts":["Exchange and clearing charges","Employee and sub-broker payouts","Marketing and client acquisition","Technology and cloud costs","Interest on borrowings for margin funding"],"customersAndEndMarkets":"Retail traders and investors, wealthy families, institutions such as mutual funds and foreign investors, and companies raising capital.","demandSupplyDrivers":"New investor accounts, retail derivatives trading, market sentiment and IPO activity drive revenue; competition and SEBI rules shape what brokers can charge.","domesticInternationalExposure":"Domestic; institutional brokers depend partly on foreign investor flows.","capexIntensity":"Low","capexNote":"Spending goes on trading apps and technology rather than physical assets.","workingCapital":"Client margins and settlement need large funds and bank guarantees, and margin-funding books are financed with borrowings, making part of the business lender-like.","regulation":"SEBI stock-broker rules govern client-fund handling, margins, the derivatives framework, charge disclosure and cybersecurity; exchange-level fee rules affect broker economics.","competitiveAdvantages":"Scale, brand and app experience for discount brokers; client relationships and research for full-service and wealth firms.","drivers":[{"factor":"Capital market activity","impact":"Bull markets bring new accounts and higher trading volumes."},{"factor":"Regulation","impact":"SEBI changes to derivatives, margins or client funds directly hit revenue."},{"factor":"Technology change","impact":"Low-cost apps have reshaped pricing and customer acquisition."},{"factor":"Interest rates","impact":"Rates set the yield on margin funding and the cost of borrowing for it."},{"factor":"Market volatility","impact":"Volatile phases raise derivatives activity."}],"risks":[{"risk":"F&O curbs","detail":"Restrictions on retail derivatives can sharply cut order volumes."},{"risk":"Market slump","detail":"Activity and new accounts drop in prolonged downturns."},{"risk":"Price wars","detail":"Zero or flat-fee brokerage compresses revenue per trade."},{"risk":"Tech glitches","detail":"App outages on busy days cause losses and complaints."},{"risk":"Client defaults","detail":"Sharp market moves can leave margin-funded clients unable to pay."}],"cyclicality":"Cyclical","cyclicalityNote":"Revenue rises sharply in bull markets and shrinks when trading activity dries up.","metricSet":"capital-markets","relatedBasicIndustries":["b-exchange-and-data-platform","b-depositories-clearing-houses-and-other-intermediaries","b-financial-products-distributor","b-financial-technology-fintech","b-asset-management-company"],"aliases":["stock broker","stockbroker","share broker","broking","discount broker","full-service broker","trading app","wealth management"],"themes":["Digital","Financialisation of savings"]},"b-other-capital-market-related-services":{"simplifiedExplanation":"Smaller specialists that help companies raise money or support market activity - merchant bankers and IPO lead managers (especially for SME IPOs), market makers, corporate advisers, debenture trustees and similar firms.","productsAndServices":["IPO and rights issue management","SME IPO lead management and market making","Corporate finance and M&A advisory","Debenture trustee and custody services","Valuation and registered research services","Proprietary investments"],"valueChainPosition":"Service providers to issuers and exchanges at the capital-raising end of the market, working alongside brokers, registrars, rating agencies and lawyers.","howTheyMakeMoney":"Issue-management fees (often a share of money raised), market-making spreads, advisory retainers and success fees; some also keep stakes in companies they bring to market.","revenueSources":["Issue management fees","Market-making and trading income","Advisory and success fees","Trustee and custody fees"],"operatingCosts":["Professional staff","Capital tied up in underwriting and market making","Legal and compliance","Marketing and deal sourcing"],"customersAndEndMarkets":"Small and mid-sized companies raising capital, their promoters, investors and bond issuers.","demandSupplyDrivers":"Business follows the IPO and fundraising cycle, especially on SME platforms; tighter SME listing norms reduce deal flow.","domesticInternationalExposure":"Domestic.","capexIntensity":"Low","capexNote":"Advisory work needs little fixed capital.","workingCapital":"Market making and underwriting tie up money in share inventory; fee receipts are lumpy and deal-based.","regulation":"SEBI merchant banker, debenture trustee and research analyst regulations, plus SME listing rules and exchange due-diligence requirements.","competitiveAdvantages":"Relationships, deal track record and SEBI registration; low entry barriers mean many small players.","drivers":[{"factor":"Capital market activity","impact":"Hot primary markets bring a flood of mandates."},{"factor":"IPO pipeline","impact":"The number of SME and mainboard issues sets fee income."},{"factor":"Regulation","impact":"SEBI tightening on SME IPOs or merchant bankers can cut deal flow."}],"risks":[{"risk":"Deal drought","detail":"Fee income can vanish in a weak market."},{"risk":"Regulatory action","detail":"SEBI scrutiny of SME issues can bring penalties or bans."},{"risk":"Reputation","detail":"Poor post-listing performance of their IPOs hurts future mandates."},{"risk":"Inventory losses","detail":"Shares held for market making can fall in value."}],"cyclicality":"Cyclical","cyclicalityNote":"Fee income booms in hot primary markets and dries up in downturns.","metricSet":"capital-markets","relatedBasicIndustries":["b-stockbroking-and-allied","b-exchange-and-data-platform","b-ratings","b-consulting-services"],"aliases":["merchant banker","investment banker","ipo lead manager","market maker","sme ipo","debenture trustee","capital market services"],"themes":[]},"b-general-insurance":{"simplifiedExplanation":"Insurers that cover non-life risks - motor, health, property, crops, travel and business liabilities - usually with one-year policies. They collect premiums upfront, pay claims when losses happen and invest the money in between.","productsAndServices":["Motor own-damage and third-party insurance","Health and personal accident insurance","Fire and property insurance","Crop insurance under government schemes","Marine, engineering and liability covers","Travel and home insurance","Reinsurance (for reinsurers)"],"valueChainPosition":"Risk carriers between customers (individuals, businesses, government schemes) and reinsurers; they sell through agents, brokers, banks, motor dealers and online aggregators.","howTheyMakeMoney":"Underwriting profit (earned premium minus claims and expenses) plus investment income on the float of premiums held before claims are paid. Many run close to break-even on underwriting and earn mainly from investments.","revenueSources":["Net earned premium","Investment income on the float","Gains on equity investments","Commission on business ceded to reinsurers"],"operatingCosts":["Claims paid and reserved","Commissions to agents, brokers and banks","Employee and management expenses","Reinsurance premiums ceded","Marketing and technology"],"customersAndEndMarkets":"Vehicle owners, families and employers buying health cover, businesses insuring assets and liabilities, and farmers through government crop schemes.","demandSupplyDrivers":"Vehicle sales, rising medical costs and awareness, credit-linked covers, economic activity and government schemes drive premiums; competition and pricing freedom set margins.","domesticInternationalExposure":"Risks are mainly Indian, but reinsurance links them to global reinsurers; reinsurers also write overseas business, so global catastrophe losses and pricing matter.","capexIntensity":"Low","capexNote":"Branches and technology; capital is held mainly to meet solvency rules.","workingCapital":"Premiums arrive before claims, creating a float; long-tail motor third-party and liability claims can take years to settle, so reserving discipline matters.","regulation":"IRDAI regulates product filing, solvency, expense limits, claims practices and investments; motor third-party premiums are set by the authorities rather than by insurers; GST applies to premiums.","competitiveAdvantages":"Pricing discipline, efficient claims handling, distribution tie-ups with banks and dealers, hospital networks and data-driven underwriting.","drivers":[{"factor":"Healthcare spending","impact":"Rising medical costs and awareness push health insurance demand."},{"factor":"Consumer demand","impact":"New vehicle sales drive motor premiums."},{"factor":"Regulation","impact":"IRDAI rules on pricing, expenses and products shape margins."},{"factor":"Interest rates","impact":"Bond yields decide investment income on the float."},{"factor":"Natural catastrophes","impact":"Floods, cyclones and other disasters drive spikes in claims."},{"factor":"Capital market activity","impact":"Equity gains boost investment income in good markets."}],"risks":[{"risk":"Catastrophe losses","detail":"A large disaster can wipe out a year's underwriting profit."},{"risk":"Claims inflation","detail":"Hospital and repair costs can rise faster than premiums."},{"risk":"Price wars","detail":"Aggressive pricing in group health and motor erodes margins."},{"risk":"Reserve shortfalls","detail":"Underestimated long-tail claims hit future profits."},{"risk":"Regulated pricing","detail":"Third-party motor rates may not keep up with claims."}],"cyclicality":"Mixed","cyclicalityNote":"Demand for cover is steady, but profits swing with claims experience, catastrophes and investment gains.","metricSet":"insurance-general","relatedBasicIndustries":["b-life-insurance","b-insurance-distributors","b-other-insurance-companies","b-passenger-cars-and-utility-vehicles","b-hospital"],"aliases":["general insurer","non-life insurance","health insurance","motor insurance","standalone health insurer","reinsurance","reinsurer","p&c insurance"],"themes":[]},"b-life-insurance":{"simplifiedExplanation":"Insurers that pay out on death or provide long-term savings and pensions. Customers pay premiums for many years, and the insurer invests that money and pays benefits as the policy promises.","productsAndServices":["Term (pure protection) plans","Non-participating savings plans with guaranteed returns","Participating (bonus) plans","Unit-linked insurance plans (ULIPs)","Annuity and pension products","Group term and credit-life cover","Group fund management for gratuity and superannuation"],"valueChainPosition":"Long-term savings managers and risk carriers; they sell mainly through bank partners (bancassurance), agents, brokers and online channels, and invest heavily in government bonds and equities.","howTheyMakeMoney":"Profit is earned over each policy's life from mortality margins (protection), investment spreads (savings and annuities) and fund charges (ULIPs). Accounting profit lags sales, so value of new business and embedded value are the main yardsticks.","revenueSources":["First-year and renewal premiums","Single premiums from annuities and group business","Investment income","Fund management charges on ULIPs"],"operatingCosts":["Benefits paid and reserves set aside","Commissions to banks, agents and brokers","Employee and branch costs","Hedging and reinsurance costs","Marketing"],"customersAndEndMarkets":"Salaried and self-employed families, retirees, borrowers needing loan cover and employers buying group schemes.","demandSupplyDrivers":"Rising incomes, a large protection gap, retirement needs, bank-partner reach, tax incentives and equity markets (for ULIPs) drive demand; interest rates affect guaranteed-product pricing and annuity appeal.","domesticInternationalExposure":"Business is domestic; foreign partners are common shareholders within government ownership limits, and global reinsurers take part of the mortality risk.","capexIntensity":"Low","capexNote":"Distribution and technology rather than physical assets; capital is held for solvency.","workingCapital":"Premiums arrive long before benefits are paid, building a large investment book; matching assets to guaranteed liabilities is critical.","regulation":"IRDAI regulates products, surrender values, commissions and expenses, solvency and investments; tax rules on premiums and maturity proceeds influence demand; GST applies to premiums.","competitiveAdvantages":"Access to distribution (especially bank tie-ups), brand trust, high persistency, product design and cost efficiency.","drivers":[{"factor":"Interest rates","impact":"Rates shape pricing of guaranteed plans, annuity demand and investment returns."},{"factor":"Capital market activity","impact":"Strong equity markets lift ULIP sales and fund-based income."},{"factor":"Regulation","impact":"IRDAI rules on surrender values and commissions change product margins."},{"factor":"Tax incentives","impact":"Changes in tax benefits on premiums or maturity alter savings-product appeal."},{"factor":"Consumer demand","impact":"Income growth and protection awareness drive term and savings sales."}],"risks":[{"risk":"Regulatory margin squeeze","detail":"New surrender-value or commission rules can cut new-business margins."},{"risk":"Tax changes","detail":"Withdrawal of tax benefits can hurt high-premium savings sales."},{"risk":"Rate risk","detail":"Falling rates make guaranteed promises costly if not hedged."},{"risk":"Bank partner dependence","detail":"Losing or sharing a bank channel can hit sales sharply."},{"risk":"Mis-selling and lapses","detail":"Poor persistency erodes profitability and invites regulatory action."}],"cyclicality":"Mixed","cyclicalityNote":"Protection and renewal premiums are steady, while ULIP sales and investment values follow equity markets.","metricSet":"insurance-life","relatedBasicIndustries":["b-general-insurance","b-insurance-distributors","b-asset-management-company","b-private-sector-bank","b-public-sector-bank"],"aliases":["life insurer","life insurance company","term insurance","ulip","pension plan","annuity","bancassurance","life cover"],"themes":["Financialisation of savings"]},"b-other-insurance-companies":{"simplifiedExplanation":"A small, residual bucket for insurance businesses that do not fit neatly into life or general insurance - for example specialist credit or export-credit covers, micro-insurance or holding structures that own insurers.","productsAndServices":["Trade credit, surety and export-credit covers","Micro-insurance for low-income groups","Specialist crop or weather covers","Stakes in insurance subsidiaries","Scheme administration for government programmes"],"valueChainPosition":"Niche risk carriers or owners of insurers, working with banks, exporters, government schemes and reinsurers.","howTheyMakeMoney":"Like other insurers, through underwriting margins and investment income on premiums held; holding structures earn dividends and value from the insurers they own.","revenueSources":["Premiums on specialist covers","Investment income","Dividends from insurance subsidiaries","Scheme administration fees"],"operatingCosts":["Claims","Reinsurance","Distribution commissions","Employee and administrative costs"],"customersAndEndMarkets":"Exporters, lenders, MSMEs, farmers in government schemes and low-income households.","demandSupplyDrivers":"Trade volumes, credit growth, government scheme design and awareness drive premiums; claims depend on default cycles and weather.","domesticInternationalExposure":"Export-credit and trade covers are tied to overseas buyer risk, and reinsurance links them to global markets.","capexIntensity":"Low","capexNote":"Capital is held for solvency rather than physical assets.","workingCapital":"Premium float as for other insurers; claims on credit-type covers can bunch together in downturns.","regulation":"IRDAI licensing, product approval and solvency rules; government-owned specialist insurers also follow ministry mandates.","competitiveAdvantages":"Specialist underwriting data, government backing or mandates and reinsurer relationships.","drivers":[{"factor":"Regulation","impact":"IRDAI product and solvency rules decide what niche covers can be offered."},{"factor":"Government policy","impact":"Scheme design and subsidies drive crop and export-credit volumes."},{"factor":"Exports & global demand","impact":"Trade activity and buyer defaults abroad move credit-cover premiums and claims."},{"factor":"Credit growth","impact":"More lending to small firms raises demand for credit guarantees."}],"risks":[{"risk":"Concentrated claims","detail":"Credit and weather covers can see many claims at once."},{"risk":"Policy dependence","detail":"Changes to government schemes can shrink the business."},{"risk":"Reinsurance cost","detail":"Global reinsurance price rises squeeze margins."},{"risk":"Thin market","detail":"Few comparable listed companies make valuation hard."}],"cyclicality":"Mixed","cyclicalityNote":"Premiums are fairly steady, but credit-type and weather-linked claims rise in bad years.","metricSet":"insurance-general","relatedBasicIndustries":["b-general-insurance","b-life-insurance","b-insurance-distributors"],"aliases":["other insurance","specialist insurer","credit insurance","surety insurance","export credit insurance","micro insurance","insurance holding company"],"themes":[]},"b-insurance-distributors":{"simplifiedExplanation":"Businesses that sell or service insurance without carrying the risk themselves - insurance brokers, corporate agents, online insurance marketplaces and third-party administrators (TPAs) that process health claims for insurers and employers.","productsAndServices":["Insurance broking for retail and corporate clients","Corporate agency distribution","Online insurance comparison and sales","Health claims processing and cashless hospital settlement (TPA)","Employee benefits administration","Reinsurance broking"],"valueChainPosition":"Between insurers and policyholders: they source policies and service claims, and TPAs connect insurers, hospitals and insured employees or families.","howTheyMakeMoney":"Commissions and brokerage as a share of premium sold, within IRDAI's overall expense limits for insurers, plus administration fees per policy or member for TPAs and fees for marketing or technology services.","revenueSources":["Brokerage and commissions","TPA administration fees","Marketing and rewards fees from insurers","Technology and consulting services"],"operatingCosts":["Employee and call-centre costs","Technology platforms","Marketing and customer acquisition","Medical review staff and hospital network management (TPAs)"],"customersAndEndMarkets":"Insurers, which pay commissions and fees; corporates buying group health and employee benefits; retail buyers; and hospitals in TPA networks.","demandSupplyDrivers":"Insurance penetration, employer group health cover, medical inflation and digital adoption drive volumes; insurers handling claims in-house and expense rules shape margins.","domesticInternationalExposure":"Mainly domestic; some brokers and TPAs serve overseas insurers or clients.","capexIntensity":"Low","capexNote":"Technology platforms and service centres need modest spending.","workingCapital":"Light; commissions and fees come from insurers on regular cycles, though some dues from insurers or government schemes can stretch.","regulation":"IRDAI regulates brokers, corporate agents, web aggregators and TPAs, and its limits on insurers' expenses cap what can be paid to distributors; health-claims rules shape TPA work.","competitiveAdvantages":"Scale in claims processing, hospital network relationships, insurer tie-ups, brand and low customer acquisition cost.","drivers":[{"factor":"Healthcare spending","impact":"More health cover and higher claims volumes raise TPA and broking income."},{"factor":"Regulation","impact":"IRDAI expense and distribution rules decide commission levels."},{"factor":"Technology change","impact":"Online buying and digital claims shift share to tech-led players."},{"factor":"Insurance penetration","impact":"More first-time buyers enlarge the market for distributors."}],"risks":[{"risk":"Commission pressure","detail":"Insurers or regulators can cut payouts to intermediaries."},{"risk":"Insurer in-sourcing","detail":"Insurers handling claims or sales themselves reduce TPA and broker roles."},{"risk":"Client concentration","detail":"A few large insurers or corporates may dominate revenue."},{"risk":"Data privacy","detail":"Health and personal data breaches bring legal and reputational damage."},{"risk":"Platform competition","detail":"A regulator-backed common insurance marketplace could reduce the role of private aggregators."}],"cyclicality":"Defensive","cyclicalityNote":"Insurance renewals and group health cover stay fairly steady through economic cycles.","metricSet":"insurance-distribution","relatedBasicIndustries":["b-general-insurance","b-life-insurance","b-financial-technology-fintech","b-healthcare-service-provider","b-financial-products-distributor"],"aliases":["insurance broker","insurance distributor","tpa","third party administrator","insurance aggregator","web aggregator","corporate agent","insurance marketplace"],"themes":["Digital"]},"b-financial-technology-fintech":{"simplifiedExplanation":"Technology companies that provide financial services or the systems behind them - digital payments, online lending and insurance marketplaces, payment card making, banking software and identity checks. Many earn small fees on very large volumes.","productsAndServices":["Payment gateway and aggregator services","Point-of-sale and QR payment solutions","Digital lending platforms with partner banks and NBFCs","Online insurance and loan marketplaces","Payment card manufacturing and personalisation","Banking, payment and KYC software","Bill payments and prepaid instruments"],"valueChainPosition":"The technology layer between banks, NBFCs and insurers and their customers or merchants; they run on bank partners, card networks and UPI rails and sell to merchants, consumers and financial institutions.","howTheyMakeMoney":"Fees on payments processed, commissions from lenders and insurers for customers sourced, software subscriptions or licences, sale of cards and devices, and interest where they lend. Scale lowers cost per transaction, so profits hinge on volume and pricing power.","revenueSources":["Payment processing fees","Loan and insurance distribution commissions","Software subscriptions and licences","Card and device sales","Interest income on loans or float"],"operatingCosts":["Payment network and bank charges","Marketing and customer acquisition","Technology, cloud and security","Employee costs including stock options","Credit losses where they share loan risk","Chips and materials for card makers"],"customersAndEndMarkets":"Merchants, consumers, banks, NBFCs, insurers and government agencies.","demandSupplyDrivers":"The shift from cash to digital payments, smartphone use, merchant digitisation and credit demand drive volumes; pricing is shaped by rules such as zero merchant fees on UPI.","domesticInternationalExposure":"Mostly domestic; some sell software, card or identity solutions abroad and handle cross-border payments.","capexIntensity":"Medium","capexNote":"Platforms need ongoing software and data-centre spending, and card or device makers need machinery.","workingCapital":"Payment firms hold settlement money that belongs to merchants; card makers carry chip inventory and bank receivables; lending models tie up capital in loans.","regulation":"RBI rules on payment aggregators, prepaid instruments, digital lending and default-loss guarantees, NPCI rules for UPI, IRDAI and SEBI rules for marketplaces, and the Digital Personal Data Protection Act.","competitiveAdvantages":"Network effects, merchant and bank relationships, licences, brand and data; low switching costs in payments keep pricing competitive.","drivers":[{"factor":"Technology change","impact":"New payment rails and mobile adoption expand what can be done digitally."},{"factor":"Regulation","impact":"RBI and NPCI rules decide pricing, licences and lending models."},{"factor":"Consumer demand","impact":"Online spending and digital habits drive transaction volumes."},{"factor":"Credit growth","impact":"Demand for digital loans raises distribution and lending income."},{"factor":"Government policy","impact":"Support for digital payments and public digital infrastructure lowers costs and widens reach."}],"risks":[{"risk":"Rule changes","detail":"Sudden licensing, pricing or lending rules can upend business models."},{"risk":"Thin margins","detail":"Zero-fee payment rails leave little room for profit."},{"risk":"Partner dependence","detail":"Loss of a bank or lender partner can halt products."},{"risk":"Fraud and cyber attacks","detail":"Breaches cause losses, penalties and loss of trust."},{"risk":"Cash burn","detail":"Loss-making firms depend on fresh funding to keep growing."}],"cyclicality":"Mixed","cyclicalityNote":"Payment volumes grow steadily, while lending and marketplace income follow the credit cycle.","metricSet":"fintech","relatedBasicIndustries":["b-it-enabled-services","b-software-products","b-other-bank","b-insurance-distributors","b-non-banking-financial-company-nbfc"],"aliases":["fintech","financial technology","payments company","payment gateway","payment aggregator","digital lending","card manufacturer","insurtech","wealthtech","upi"],"themes":["Digital","Financial inclusion"]},"b-edible-oil":{"simplifiedExplanation":"These companies make cooking oil by crushing oilseeds or refining imported crude palm, soybean and sunflower oil, then selling it in packs or in bulk.","productsAndServices":["Refined palm oil and palmolein","Soybean and sunflower oil","Mustard and groundnut oil","Vanaspati and bakery fats","Oilmeal (de-oiled cake)"],"valueChainPosition":"Midstream processor: buys oilseeds from farmers and crude oil from global suppliers, and supplies households, restaurants, bakeries and food makers through distributors and retailers.","howTheyMakeMoney":"They earn the gap between oilseed or crude oil cost and the refined oil price, plus oilmeal income; branded packs earn more than bulk sales.","revenueSources":["Branded consumer packs","Bulk oil to institutions and food makers","Oilmeal for animal feed","Specialty fats"],"operatingCosts":["Crude oil and oilseed purchases","Packaging","Port handling and freight","Power and fuel for refining","Brand advertising","Interest on inventory financing"],"customersAndEndMarkets":"Households, hotels and restaurants, bakeries, snack and vanaspati makers; oilmeal goes to animal feed producers.","demandSupplyDrivers":"Demand is steady and grows with population; supply and price follow domestic oilseed harvests and global palm and soybean oil output.","domesticInternationalExposure":"India relies heavily on imported edible oil, so global prices, freight and the rupee directly drive costs; oilmeal is exported when competitive.","capexIntensity":"Medium","capexNote":"Refineries, crushing units and port-side plants need steady investment, but working capital is the bigger need.","workingCapital":"Heavy: large stocks of crude oil and seeds are financed with short-term debt, and sudden price falls can cause inventory losses.","regulation":"The government changes edible oil import duties often and has used stock limits to control prices; FSSAI sets quality, fortification and labelling rules.","competitiveAdvantages":"Refining scale, port-based plants, sourcing skill, trusted consumer brands and wide distribution protect larger players.","drivers":[{"factor":"Commodity prices","impact":"Global palm and soybean oil prices set raw material cost and can create inventory gains or losses."},{"factor":"Government policy","impact":"Import duty changes quickly shift the cost of imported oil against domestic oil."},{"factor":"Currency (INR)","impact":"A weaker rupee raises the landed cost of imported crude oil."},{"factor":"Monsoon & agriculture","impact":"Domestic mustard, soybean and groundnut crops depend on rainfall and set local supply."}],"risks":[{"risk":"Inventory losses","detail":"A sharp fall in oil prices hurts margins on stock bought at higher prices."},{"risk":"Policy shocks","detail":"Sudden duty cuts or stock limits can squeeze refiners."},{"risk":"Thin margins","detail":"Bulk refining earns small spreads, leaving little room for error."},{"risk":"Supplier country actions","detail":"Export curbs or levies by producing countries can disrupt supply."}],"cyclicality":"Mixed","cyclicalityNote":"Volumes are defensive, but margins swing with global edible oil prices and duty changes.","metricSet":"agri-commodities","relatedBasicIndustries":["b-packaged-foods","b-animal-feed","b-other-agricultural-products","b-diversified-fmcg"],"aliases":["edible oil","cooking oil","refined oil","palm oil","soybean oil","sunflower oil","mustard oil","vanaspati","oilseed crushing"],"themes":["Import substitution"]},"b-sugar":{"simplifiedExplanation":"Sugar mills crush sugarcane from nearby farmers to make sugar, and most also turn by-products into ethanol, electricity and molasses.","productsAndServices":["White and raw sugar","Fuel ethanol","Molasses","Power from bagasse co-generation","Rectified spirit and extra neutral alcohol"],"valueChainPosition":"Midstream processor: buys cane from local farmers and sells sugar to traders and food makers, ethanol to oil marketing companies and power to state grids.","howTheyMakeMoney":"They earn the gap between the cane price paid to farmers and income from sugar, ethanol and power; integrated mills earn steadier income than sugar-only mills.","revenueSources":["Domestic sugar sales","Ethanol supplied to oil marketing companies","Power sold to the grid","Sugar exports when permitted","Molasses and alcohol sales"],"operatingCosts":["Sugarcane purchase (largest cost)","Seasonal labour","Chemicals and stores","Off-season repairs","Interest on sugar inventory"],"customersAndEndMarkets":"Bulk buyers such as drink, sweet and confectionery makers, households through traders, and fuel retailers for ethanol.","demandSupplyDrivers":"Supply depends on cane area, rainfall and yields, while sugar demand is steady. Diverting cane juice and molasses to ethanol reduces sugar supply.","domesticInternationalExposure":"Mostly domestic; exports happen only when government policy allows, so world sugar prices matter mainly in surplus years.","capexIntensity":"High","capexNote":"Mills run only during the crushing season, and adding distilleries or co-generation needs sizeable investment.","workingCapital":"Very heavy and seasonal: sugar made in a few months is sold through the year under release quotas, so stocks and debt peak after the crushing season.","regulation":"The Centre sets the Fair and Remunerative Price for cane (some states add a State Advised Price), a minimum sugar selling price, monthly sale quotas and export rules; ethanol prices follow the blending programme.","competitiveAdvantages":"Assured cane supply with good yields and sugar recovery, plus integration into ethanol and power, separate stronger mills from weaker ones.","drivers":[{"factor":"Monsoon & agriculture","impact":"Rainfall and irrigation decide cane output and the number of crushing days."},{"factor":"Government policy","impact":"Cane prices, sugar selling price, quotas and export rules set most of the economics."},{"factor":"Ethanol blending programme","impact":"Fuel ethanol demand gives a steadier outlet for cane juice and molasses."},{"factor":"Commodity prices","impact":"Domestic and global sugar prices drive realisations and export viability."}],"risks":[{"risk":"Cane cost increases","detail":"Higher cane prices without matching sugar price changes squeeze margins."},{"risk":"Drought","detail":"Poor rainfall cuts cane supply and leaves mill capacity idle."},{"risk":"Policy reversals","detail":"Changes in export, ethanol or diversion rules can upset plans."},{"risk":"Farmer dues","detail":"Late payments to cane farmers invite regulatory and political pressure."}],"cyclicality":"Cyclical","cyclicalityNote":"Earnings follow the cane and sugar price cycle, partly cushioned by ethanol and power income.","metricSet":"agri-commodities","relatedBasicIndustries":["b-breweries-and-distilleries","b-refineries-and-marketing","b-power-generation","b-other-beverages","b-packaged-foods"],"aliases":["sugar","sugar mill","sugarcane","ethanol","molasses","cogeneration","integrated sugar","chini mill"],"themes":["Ethanol blending","Renewable energy"]},"b-tea-and-coffee":{"simplifiedExplanation":"Tea and coffee estates that grow and process the crop, plus companies that blend and pack tea or make instant coffee for India and for export.","productsAndServices":["CTC and orthodox black tea","Green and specialty teas","Branded packaged tea","Instant and freeze-dried coffee","Private-label coffee for global brands"],"valueChainPosition":"Upstream estates grow leaf and beans and sell at auctions or to blenders; downstream processors blend, pack and supply retailers and global brand owners.","howTheyMakeMoney":"Estates earn the made-tea or coffee price minus costs that are mostly wages; packers and instant coffee makers earn a processing or brand margin over bought leaf or beans.","revenueSources":["Auction and private sales of made tea","Branded tea packs","Instant coffee exports","Contract manufacturing for global brands","Domestic coffee retail"],"operatingCosts":["Plantation wages","Bought green leaf or green coffee beans","Fertiliser and plant protection","Energy for drying and processing","Packaging and freight"],"customersAndEndMarkets":"Households, tea stalls and offices for tea; instant coffee goes mostly to overseas brand owners and retailers.","demandSupplyDrivers":"Tea drinking in India is steady, while supply swings with weather and pests; coffee processors depend on global bean prices and export orders.","domesticInternationalExposure":"Tea is mainly domestic with some exports; instant coffee makers are export-heavy, so global coffee prices and the rupee matter a lot.","capexIntensity":"Medium","capexNote":"Estates need replanting and factory upkeep, and instant coffee plants need investment in drying capacity.","workingCapital":"Seasonal: tea is plucked mostly in certain months and sold through auctions over time, while coffee processors hold bean stocks and export receivables.","regulation":"The Tea Board and Coffee Board oversee the sectors; estate wages and welfare follow plantation labour laws and state wage decisions; FSSAI governs food safety.","competitiveAdvantages":"Brands and blending skill for packers, global buyer relationships for instant coffee makers, and location and leaf quality for estates.","drivers":[{"factor":"Commodity prices","impact":"Auction tea prices and global coffee bean prices drive revenue and input cost."},{"factor":"Monsoon & agriculture","impact":"Rainfall, temperature and pests decide crop size and quality."},{"factor":"Exports & global demand","impact":"Export orders matter most to instant coffee makers and orthodox tea sellers."},{"factor":"Plantation wage revisions","impact":"State-set wage increases raise the largest cost for estates."}],"risks":[{"risk":"Labour costs","detail":"Wage hikes on estates are hard to pass on when auction prices are weak."},{"risk":"Weather","detail":"Drought or excess rain cuts output and quality."},{"risk":"Bean price spikes","detail":"Sharp rises in green coffee prices can squeeze processors."},{"risk":"Residue norms","detail":"Pesticide residue limits in export markets can block shipments."}],"cyclicality":"Mixed","cyclicalityNote":"Consumption is steady, but estate profits swing with crop prices and weather.","metricSet":"agri-commodities","relatedBasicIndustries":["b-packaged-foods","b-other-beverages","b-diversified-fmcg","b-other-agricultural-products"],"aliases":["tea","coffee","tea plantation","tea estate","instant coffee","chai","Assam tea","Darjeeling tea","coffee exporter"],"themes":["Exports"]},"b-other-agricultural-products":{"simplifiedExplanation":"A mixed group of companies that process and trade farm produce other than sugar, oil, tea and coffee, such as basmati rice, seeds, spices, pulses, cashews and grains.","productsAndServices":["Basmati and non-basmati rice","Hybrid and vegetable seeds","Spices","Pulses and grains","Cashew and dry fruits","Guar gum and other agri derivatives"],"valueChainPosition":"Midstream: buys crops from farmers and mandis and grades, ages or packs them for traders, food makers and exporters; seed firms sit upstream, supplying farmers.","howTheyMakeMoney":"Most earn a trading and processing margin on crops, helped by grading, ageing and branding; seed firms earn from research-led hybrids sold each season.","revenueSources":["Export sales","Domestic branded packs","Bulk sales to traders and processors","Seed sales to farmers","By-products such as bran and husk"],"operatingCosts":["Crop procurement","Milling and processing","Storage and fumigation","Freight and export logistics","Interest on inventory","Field trials and research (seed firms)"],"customersAndEndMarkets":"Export buyers in many countries, domestic wholesalers and retailers, food processors, and farmers for seeds.","demandSupplyDrivers":"Supply depends on the harvest and minimum support prices; demand comes from food consumption at home and export orders abroad.","domesticInternationalExposure":"Many are export-led, so global prices, shipping routes and the rupee matter; seed companies are mostly domestic.","capexIntensity":"Low","capexNote":"Milling, sorting and storage need modest investment compared with the money tied up in stock.","workingCapital":"Heavy: crops are bought at harvest and held for months, often with bank funding; seed sales are seasonal and involve dealer credit.","regulation":"DGFT and APEDA export rules (bans or minimum export prices at times), MSP-linked procurement, the Seeds Act and seed certification, and FSSAI food safety norms.","competitiveAdvantages":"Procurement networks, consistent quality, export certifications, established brands and, for seeds, proprietary hybrids.","drivers":[{"factor":"Monsoon & agriculture","impact":"Crop size and quality depend on rainfall and growing conditions."},{"factor":"Exports & global demand","impact":"Demand in buyer countries drives volumes and prices."},{"factor":"Government policy","impact":"Export bans, minimum export prices and MSP changes can quickly change economics."},{"factor":"Currency (INR)","impact":"Exporters earn more in rupees when the rupee weakens."}],"risks":[{"risk":"Export curbs","detail":"Sudden export restrictions can leave inventory stranded."},{"risk":"Price falls","detail":"Lower crop prices reduce the value of stock on hand."},{"risk":"Geopolitics and shipping","detail":"Conflicts or payment problems in buyer regions can delay exports."},{"risk":"Residue norms","detail":"Strict pesticide limits abroad can lead to rejected consignments."}],"cyclicality":"Mixed","cyclicalityNote":"Food demand is steady, but profits move with harvests, crop prices and trade policy.","metricSet":"agri-commodities","relatedBasicIndustries":["b-edible-oil","b-pesticides-and-agrochemicals","b-food-storage-facilities","b-trading-and-distributors","b-packaged-foods"],"aliases":["basmati rice","rice exporter","seeds","spices","agri products","pulses","cashew","agro processing","grains"],"themes":["Exports","Rural demand"]},"b-breweries-and-distilleries":{"simplifiedExplanation":"These companies make beer in breweries and spirits like whisky, rum and vodka in distilleries; many distilleries also make ethanol for fuel blending.","productsAndServices":["Beer","Indian-made foreign liquor (whisky, rum, brandy, vodka, gin)","Country liquor","Extra neutral alcohol (ENA)","Fuel ethanol"],"valueChainPosition":"Midstream to downstream: buys grain, molasses and malt, brews or distils, and sells through state corporations, licensed wholesalers and retailers; ethanol goes to oil marketing companies.","howTheyMakeMoney":"Brand owners earn margins on bottled drinks after heavy state excise; bulk distillers earn the gap between grain or molasses cost and ENA or ethanol prices.","revenueSources":["Branded spirits and beer","Country liquor","Bulk ENA sales to bottlers","Fuel ethanol supplies","Contract bottling"],"operatingCosts":["Grain, molasses and malt","Glass bottles and packaging","State excise (built into price)","Power and fuel","Brand promotion and trade spend"],"customersAndEndMarkets":"Adult consumers through state-run or licensed liquor shops, bars and restaurants; oil marketing companies buy ethanol and other bottlers buy ENA.","demandSupplyDrivers":"Demand rises with incomes, urbanisation and preference for premium brands; supply is controlled by state licences, and ethanol demand follows the fuel blending programme.","domesticInternationalExposure":"Mainly domestic; imported Scotch and malt, global barley and glass costs, and some spirits exports add global links.","capexIntensity":"Medium","capexNote":"Plants and bottling lines need steady spending, and grain-based ethanol capacity has needed significant investment.","workingCapital":"Large: excise and fees are paid upfront in many states, state corporations can pay late, and maturing spirits tie up inventory.","regulation":"Alcohol is a state subject outside GST: each state sets excise, licences, price approvals and sales channels, and liquor advertising is restricted.","competitiveAdvantages":"Strong brands, licences and relationships across many states, distribution reach and procurement scale create high entry barriers.","drivers":[{"factor":"Regulation","impact":"State excise rates, price approvals and retail policies directly change sales and margins."},{"factor":"Consumer demand","impact":"Rising incomes and premium preferences lift volumes and product mix."},{"factor":"Commodity prices","impact":"Grain, molasses, barley and glass costs drive gross margins."},{"factor":"Ethanol blending programme","impact":"Fuel ethanol gives distillers a large outlet with government-linked pricing."}],"risks":[{"risk":"State policy changes","detail":"Prohibition, tax hikes or retail policy changes in one state can hit sales quickly."},{"risk":"Input inflation","detail":"State price controls limit how fast cost increases can be passed on."},{"risk":"Receivable delays","detail":"Payments from state corporations can be slow."},{"risk":"Ethanol economics","detail":"Changes in ethanol prices or allowed feedstocks affect distillery returns."}],"cyclicality":"Mixed","cyclicalityNote":"Drinking demand is resilient, but state tax actions, grain prices and bulk alcohol prices make earnings uneven.","metricSet":"alcohol-beverages","relatedBasicIndustries":["b-sugar","b-other-beverages","b-glass-consumer","b-refineries-and-marketing","b-hotels-and-resorts"],"aliases":["liquor","alcohol","beer","brewery","distillery","whisky","spirits","IMFL","ENA","grain ethanol"],"themes":["Ethanol blending","Premiumisation"]},"b-other-beverages":{"simplifiedExplanation":"Companies that make non-alcoholic drinks such as soft drinks, fruit juices, energy drinks and packaged drinking water, often bottling under their own or franchised brands.","productsAndServices":["Carbonated soft drinks","Fruit juices and nectars","Packaged drinking water","Energy and sports drinks","Dairy-based and ready-to-drink beverages","Franchise bottling and distribution"],"valueChainPosition":"Downstream: buys concentrate, sugar, PET resin and cans, bottles drinks and sells through distributors, shops, restaurants and vending, often under franchise from a global brand owner.","howTheyMakeMoney":"They earn a margin on each case after concentrate, sugar, packaging and delivery costs; franchise bottlers depend on volumes and efficient delivery routes.","revenueSources":["Soft drink sales","Packaged water","Juices and value-added drinks","Energy drinks","Sales to restaurants and institutions"],"operatingCosts":["Concentrate and flavours","Sugar and sweeteners","PET bottles, cans and glass","Distribution, coolers and freight","Advertising and promotions","Power and water"],"customersAndEndMarkets":"Consumers through small shops, supermarkets, restaurants, cinemas and online; summer and festive periods matter most.","demandSupplyDrivers":"Demand peaks in hot summers and grows as coolers and cold chains reach smaller towns; low per-person consumption leaves room to grow.","domesticInternationalExposure":"Mostly domestic, but sugar, PET resin and aluminium cans follow global commodity prices; some bottlers also operate in nearby countries.","capexIntensity":"High","capexNote":"Bottling plants, production lines, visi-coolers and delivery fleets need large and continuous investment.","workingCapital":"Usually light because sales are largely cash or short credit, though inventory builds up ahead of summer.","regulation":"FSSAI labelling rules, mandatory BIS certification for packaged drinking water, plastic packaging EPR rules, and a higher GST rate on aerated and sugary drinks.","competitiveAdvantages":"Franchise rights, dense bottling and cooler networks, and delivery scale are hard for new entrants to copy.","drivers":[{"factor":"Summer weather","impact":"Hot, long summers lift volumes, while unseasonal rain hurts peak-season sales."},{"factor":"Consumer demand","impact":"Rising incomes and new flavours raise consumption, especially in smaller towns."},{"factor":"Commodity prices","impact":"Sugar, PET resin and aluminium costs shape gross margins."},{"factor":"Government policy","impact":"Taxes on sugary drinks and plastic rules affect pricing and packaging choices."}],"risks":[{"risk":"Weather","detail":"A cool or rainy summer can reduce annual volumes."},{"risk":"Health concerns","detail":"Shifts away from sugary drinks and new taxes can hurt demand."},{"risk":"Franchise dependence","detail":"Bottlers rely on agreements with brand owners."},{"risk":"Packaging rules","detail":"Plastic waste regulations raise compliance costs."}],"cyclicality":"Defensive","cyclicalityNote":"Everyday consumption keeps demand steady through the economic cycle, though weather causes big swings between quarters.","metricSet":"alcohol-beverages","relatedBasicIndustries":["b-breweries-and-distilleries","b-sugar","b-packaging","b-dairy-products","b-packaged-foods"],"aliases":["soft drinks","cold drinks","aerated drinks","juice","packaged water","mineral water","bottler","energy drink","non-alcoholic beverages"],"themes":["Rural demand"]},"b-cigarettes-and-tobacco-products":{"simplifiedExplanation":"Companies that make and sell cigarettes and other tobacco products, and some that buy, process and export leaf tobacco.","productsAndServices":["Cigarettes","Cigars and cigarillos","Smoking mixtures and pipe tobacco","Chewing tobacco","Processed leaf tobacco for export"],"valueChainPosition":"Midstream to downstream: buys leaf tobacco at regulated auctions or from growers, processes it, and sells branded cigarettes through distributors to a huge base of small retailers.","howTheyMakeMoney":"They earn a margin on branded packs after paying very high taxes, and regular price increases on strong brands drive profit. Leaf exporters earn a processing and trading margin.","revenueSources":["Domestic cigarette sales","Leaf tobacco exports","Other tobacco products","Contract manufacturing","Non-tobacco businesses in some companies"],"operatingCosts":["Excise, GST and cess (part of price)","Leaf tobacco","Packaging and cigarette paper","Distribution and trade margins","Factory staff and power"],"customersAndEndMarkets":"Adult smokers buying through paan shops, kirana stores and modern trade; processed leaf goes to cigarette makers abroad.","demandSupplyDrivers":"Volumes depend mainly on tax-driven price rises and the price gap to illicit cigarettes; habit-driven demand from regular smokers is stable.","domesticInternationalExposure":"Cigarettes are mainly domestic; leaf tobacco exports bring exposure to global crop prices and the rupee.","capexIntensity":"Low","capexNote":"Factories need fairly modest maintenance and modernisation spending.","workingCapital":"Light for finished goods, which sell quickly for cash, but leaf stock is held for months to age.","regulation":"COTPA bans tobacco advertising and mandates pictorial health warnings; tobacco taxes are high and revised often; the Tobacco Board regulates flue-cured tobacco auctions; e-cigarettes are banned.","competitiveAdvantages":"Established brands, licensed capacity, deep retail reach and the advertising ban make it very hard for new brands to enter.","drivers":[{"factor":"Government policy","impact":"Tax changes are the single biggest driver of volumes and margins."},{"factor":"Regulation","impact":"Rules on packaging, sales points and promotion limit how companies compete."},{"factor":"Commodity prices","impact":"Leaf tobacco prices affect costs and the leaf export business."},{"factor":"Illicit trade","impact":"Smuggled and counterfeit cigarettes gain when legal prices rise sharply."}],"risks":[{"risk":"Tax shocks","detail":"Large tax hikes can cut legal volumes."},{"risk":"Illicit cigarettes","detail":"A wide price gap pushes smokers to untaxed products."},{"risk":"Health regulation","detail":"Stricter warnings, sales curbs or packaging rules can reduce demand."},{"risk":"ESG exclusions","detail":"Some investors avoid tobacco stocks, limiting investor demand."}],"cyclicality":"Defensive","cyclicalityNote":"Habit-driven demand keeps volumes stable through economic cycles; tax policy is the main swing factor.","metricSet":"fmcg","relatedBasicIndustries":["b-diversified-fmcg","b-other-agricultural-products","b-packaging","b-paper-and-paper-products"],"aliases":["cigarettes","tobacco","cigarette maker","leaf tobacco","cigar","smoking","tobacco stocks","bidi"],"themes":[]},"b-animal-feed":{"simplifiedExplanation":"Companies that make ready feed for cattle, poultry, fish and shrimp from grains, oilmeals and other ingredients, helping farmers raise animals faster and healthier.","productsAndServices":["Cattle feed","Poultry feed","Shrimp and fish feed","Fishmeal and fish oil","Feed supplements and premixes","Pet food"],"valueChainPosition":"Midstream: buys maize, soybean meal, rice bran, fishmeal and additives, and supplies dairy, poultry and aquaculture farmers, mostly through dealers.","howTheyMakeMoney":"They earn a margin between ingredient cost and feed price; brand trust, nutrition quality and on-farm technical support help hold pricing.","revenueSources":["Feed sold through dealers","Direct sales to large farms and integrators","Fishmeal and fish oil","Marine ingredient exports","Allied farm inputs"],"operatingCosts":["Maize and soybean meal","Fishmeal and other proteins","Additives and premixes","Freight to rural markets","Plant power and labour","Cost of dealer credit"],"customersAndEndMarkets":"Dairy farmers, poultry integrators and farmers, and shrimp and fish farmers, mostly in rural India; marine ingredients also go overseas.","demandSupplyDrivers":"Demand follows animal numbers and farmer profits in milk, poultry and shrimp; ingredient supply depends on crop harvests.","domesticInternationalExposure":"Mostly domestic, but shrimp feed depends on shrimp exports, and soybean meal and fishmeal prices track global markets.","capexIntensity":"Medium","capexNote":"Feed mills are moderately capital intensive and need to sit close to farming clusters.","workingCapital":"Significant: ingredients are stocked at harvest and dealers and farmers need credit; aqua feed sales are seasonal around pond stocking.","regulation":"Light, general business regulation; BIS standards cover some feeds, and trade rules on imported inputs such as soybean meal and maize affect costs.","competitiveAdvantages":"Formulation know-how, sourcing scale, dealer networks and farm advisory services help leading feed makers keep customers.","drivers":[{"factor":"Commodity prices","impact":"Maize and soybean meal prices are the biggest swing factor in margins."},{"factor":"Monsoon & agriculture","impact":"Harvests set ingredient supply and the incomes of livestock farmers."},{"factor":"Rural demand","impact":"Dairy and poultry farmer profits decide how much ready feed is used."},{"factor":"Exports & global demand","impact":"Shrimp export demand drives aqua feed volumes."}],"risks":[{"risk":"Input spikes","detail":"Rapid rises in maize or soybean meal prices are hard to pass on quickly."},{"risk":"Disease outbreaks","detail":"Bird flu or shrimp disease shrinks animal populations."},{"risk":"Credit risk","detail":"Dealer and farmer dues can turn bad in weak seasons."},{"risk":"Export dependence","detail":"Aqua feed suffers when importing countries raise tariffs on shrimp."}],"cyclicality":"Cyclical","cyclicalityNote":"Margins move with grain and oilmeal prices and with the profitability of livestock and shrimp farming.","metricSet":"agri-commodities","relatedBasicIndustries":["b-seafood","b-meat-products-including-poultry","b-dairy-products","b-edible-oil","b-other-agricultural-products"],"aliases":["animal feed","cattle feed","poultry feed","shrimp feed","aqua feed","fish feed","fishmeal","livestock feed"],"themes":["Rural demand"]},"b-dairy-products":{"simplifiedExplanation":"Dairy companies collect milk from farmers, process it and sell packed milk and products like curd, butter, ghee, paneer, cheese and ice cream.","productsAndServices":["Packed liquid milk","Curd, buttermilk and lassi","Ghee and butter","Paneer and cheese","Ice cream and frozen desserts","Milk powder and whey"],"valueChainPosition":"Midstream to downstream: buys milk from farmers through village collection points and chilling centres, processes it and sells through distributors, retailers and own parlours.","howTheyMakeMoney":"They earn the spread between the price paid to farmers and the selling price; value-added products such as cheese, curd and ice cream earn far more than liquid milk.","revenueSources":["Liquid milk","Value-added dairy products","Ice cream","Bulk milk powder and butter","Institutional and B2B sales"],"operatingCosts":["Raw milk procurement","Chilling, processing and cold chain","Packaging","Distribution and freight","Brand advertising"],"customersAndEndMarkets":"Urban and semi-urban households, hotels, restaurants, sweet shops and food makers; ice cream sales peak in summer.","demandSupplyDrivers":"Demand is daily and steady, while milk supply has seasonal flush and lean periods that depend on fodder and weather.","domesticInternationalExposure":"Largely domestic; global milk powder and butter prices matter when surplus stock must be sold or exported.","capexIntensity":"Medium","capexNote":"Chilling centres, plants and cold chain need steady investment, more so for cheese and ice cream.","workingCapital":"Mixed: farmers are paid quickly and milk sells fast, but surplus milk turned into powder and butter in the flush season builds inventory.","regulation":"FSSAI sets dairy quality and adulteration standards; state milk cooperatives are strong competitors and price setters; fresh milk is exempt from GST while processed products are taxed.","competitiveAdvantages":"Secure milk procurement networks, cold chain reach, trusted brands and a larger share of value-added products protect strong players.","drivers":[{"factor":"Monsoon & agriculture","impact":"Fodder availability and weather decide milk supply and procurement prices."},{"factor":"Consumer demand","impact":"Rising protein intake and convenience lift demand for packed and value-added products."},{"factor":"Commodity prices","impact":"Farm milk prices and global dairy commodity prices drive margins."},{"factor":"Summer weather","impact":"Hot summers boost ice cream, curd and buttermilk sales."}],"risks":[{"risk":"Procurement inflation","detail":"Farm milk prices can rise faster than consumer prices."},{"risk":"Cattle disease","detail":"Outbreaks among cattle reduce milk supply."},{"risk":"Quality incidents","detail":"Adulteration or contamination can damage a brand."},{"risk":"Inventory losses","detail":"Stored milk powder and butter lose value when prices fall."}],"cyclicality":"Defensive","cyclicalityNote":"Milk is a daily necessity, though margins move with the farm milk price cycle.","metricSet":"fmcg","relatedBasicIndustries":["b-packaged-foods","b-animal-feed","b-food-storage-facilities","b-other-beverages","b-restaurants"],"aliases":["dairy","milk","ghee","paneer","ice cream","cheese","curd","butter","milk products"],"themes":["Rural demand"]},"b-other-food-products":{"simplifiedExplanation":"A catch-all group for food makers that do not fit one category, such as spice blends, food ingredients, specialty fats, nutraceuticals, flour, honey and ethnic foods.","productsAndServices":["Spices and masala blends","Specialty fats and butters for chocolate and cosmetics","Nutraceuticals and natural ingredients","Flour and semolina","Honey, makhana and health foods","Ready mixes and condiments"],"valueChainPosition":"Mostly midstream: buys agricultural or forest raw materials, processes them into ingredients or consumer packs, and supplies food and cosmetic makers, retailers and export buyers.","howTheyMakeMoney":"They earn processing margins on ingredients sold to other businesses or brand margins on consumer packs; rare or specialised ingredients can earn premium prices.","revenueSources":["B2B ingredient sales","Branded consumer packs","Exports to global food and cosmetic makers","Private-label manufacturing","Institutional supplies"],"operatingCosts":["Agricultural and forest raw materials","Processing and quality testing","Packaging","Freight and export logistics","Selling and marketing"],"customersAndEndMarkets":"Packaged food, confectionery, cosmetic and supplement makers, plus households through shops and online channels.","demandSupplyDrivers":"Demand follows growth in processed food and global interest in natural ingredients; supply depends on harvests or seasonal collection of raw produce.","domesticInternationalExposure":"Varies by company: ingredient and specialty-fat makers are often export-heavy, while spice and flour brands are mainly domestic.","capexIntensity":"Medium","capexNote":"Processing plants and testing labs need moderate investment, and specialty ingredients may need dedicated equipment.","workingCapital":"Often heavy because seasonal raw materials are bought once a year and stored, and export receivables add to it.","regulation":"FSSAI governs food safety, labelling and nutraceutical health claims; exporters must also meet the food standards of importing countries.","competitiveAdvantages":"Hard-to-copy sourcing networks, quality certifications with global customers, specialised processing know-how and regional brands.","drivers":[{"factor":"Consumer demand","impact":"Growth in packaged and convenience foods raises demand for ingredients and spice blends."},{"factor":"Exports & global demand","impact":"Orders from global food and cosmetic makers drive specialty ingredient makers."},{"factor":"Raw material availability","impact":"Harvests and seasonal collection decide supply and cost."},{"factor":"Commodity prices","impact":"Prices of grains, spices and substitutes such as cocoa butter affect margins."}],"risks":[{"risk":"Supply shortfalls","detail":"Poor harvests or collection seasons can limit raw material."},{"risk":"Customer concentration","detail":"Ingredient makers may depend on a few large buyers."},{"risk":"Quality rejections","detail":"Failed tests can lead to recalls or rejected export lots."},{"risk":"Low entry barriers","detail":"Some categories attract many small unorganised rivals."}],"cyclicality":"Mixed","cyclicalityNote":"Food demand is steady, but ingredient prices and export orders make earnings vary.","metricSet":"fmcg","relatedBasicIndustries":["b-packaged-foods","b-other-agricultural-products","b-specialty-chemicals","b-personal-care","b-edible-oil"],"aliases":["food products","food processing","spices","masala","food ingredients","nutraceuticals","specialty fats","flour mill","health foods"],"themes":["Exports"]},"b-packaged-foods":{"simplifiedExplanation":"Companies that sell branded ready-to-eat or easy-to-cook foods such as biscuits, noodles, chocolates, snacks, breakfast cereals and baby food.","productsAndServices":["Biscuits, cakes and rusks","Instant noodles and pasta","Chocolates and confectionery","Namkeen and snacks","Infant nutrition and health drinks","Ready-to-eat meals and sauces"],"valueChainPosition":"Downstream: buys flour, sugar, edible oil, milk, cocoa and packaging, makes products in own or contract plants and sells through distributors, kirana stores, modern trade and quick commerce.","howTheyMakeMoney":"They earn healthy gross margins from brand strength, spend a good part on advertising and trade schemes, and profit from scale in buying and distribution.","revenueSources":["Domestic branded sales","E-commerce and quick commerce sales","Exports to overseas Indian communities","Food-service and institutional sales","Contract manufacturing in some cases"],"operatingCosts":["Wheat, sugar, milk, palm oil and cocoa","Packaging laminates and cartons","Advertising and promotions","Distribution and trade margins","Plant and contract manufacturing costs"],"customersAndEndMarkets":"Households across urban and rural India, reached through small retailers, supermarkets and online platforms.","demandSupplyDrivers":"Demand grows with incomes, busy urban lifestyles and deeper rural reach; companies manage input inflation through price increases and smaller pack weights.","domesticInternationalExposure":"Mainly domestic; palm oil, cocoa and wheat costs follow global prices, and a few players export.","capexIntensity":"Medium","capexNote":"Plants need steady investment, though many companies use contract manufacturers to stay asset-light.","workingCapital":"Usually light or negative, since distributors pay quickly and suppliers give credit; stock builds up before festivals.","regulation":"FSSAI rules on ingredients, labelling and health claims; plastic packaging EPR rules; GST rates that differ across food categories.","competitiveAdvantages":"Trusted brands, deep distribution, scale in buying and advertising, and shelf space make it hard for new brands to scale up.","drivers":[{"factor":"Consumer demand","impact":"Convenience and snacking habits lift volumes and premium products."},{"factor":"Rural demand","impact":"Rural incomes decide how fast low-priced packs grow in villages."},{"factor":"Commodity prices","impact":"Wheat, sugar, palm oil, milk and cocoa costs drive gross margins."},{"factor":"New sales channels","impact":"Quick commerce and e-commerce change pack sizes, assortment and distributor economics."}],"risks":[{"risk":"Input inflation","detail":"Sharp cost increases may not be fully passed on to price-sensitive buyers."},{"risk":"Competition","detail":"Regional brands, private labels and D2C start-ups pressure share and pricing."},{"risk":"Health perception","detail":"Scrutiny of sugar, salt and fat content can hurt some categories."},{"risk":"Food safety","detail":"Contamination or regulatory action can damage a brand quickly."}],"cyclicality":"Defensive","cyclicalityNote":"Everyday food purchases hold up in slowdowns, though volume growth slows when rural incomes are weak.","metricSet":"fmcg","relatedBasicIndustries":["b-diversified-fmcg","b-dairy-products","b-other-food-products","b-edible-oil","b-packaging"],"aliases":["packaged food","biscuits","noodles","chocolate","snacks","namkeen","processed food","ready to eat","confectionery","FMCG food"],"themes":["Rural demand","Premiumisation"]},"b-seafood":{"simplifiedExplanation":"Companies that process and export seafood, mainly farmed shrimp, which they buy from fish farmers, clean, freeze and ship to buyers abroad.","productsAndServices":["Frozen raw and cooked shrimp","Peeled, breaded and marinated shrimp","Frozen fish and squid","Ready-to-cook seafood","Shrimp hatchery seed","Seafood for domestic retail"],"valueChainPosition":"Midstream: buys shrimp from aquaculture farmers (some also run hatcheries and farms), processes and freezes it, and sells to importers, supermarkets and food-service firms overseas.","howTheyMakeMoney":"They earn the gap between the farm-gate shrimp price and the export price, with better margins on value-added and ready-to-cook products than on plain frozen shrimp.","revenueSources":["Exports to North America","Exports to Europe and Asia","Value-added retail packs","Domestic seafood sales","Export incentives"],"operatingCosts":["Raw shrimp procurement","Processing labour","Freezing and cold storage power","Packaging","Ocean freight and testing","Import duties paid in buyer countries"],"customersAndEndMarkets":"Importers, grocery chains and restaurant suppliers in North America, Europe and Asia.","demandSupplyDrivers":"Demand depends on consumer spending and seafood prices in buyer countries; supply depends on farm stocking, disease and coastal weather.","domesticInternationalExposure":"Highly export-dependent, so the rupee, buyer-country tariffs and competition from other shrimp-producing countries drive results.","capexIntensity":"Medium","capexNote":"Processing plants, freezers and cold storage need moderate investment.","workingCapital":"Heavy: farmers are paid quickly while exports take time to ship and collect, and stocks build up in harvest seasons.","regulation":"MPEDA and the Export Inspection Council govern exports and quality; buyer countries test for antibiotic residues and may levy anti-dumping or countervailing duties.","competitiveAdvantages":"Approved export plants, long buyer relationships, traceability and value-added processing set leaders apart in a crowded field.","drivers":[{"factor":"Exports & global demand","impact":"Demand and prices in buyer countries decide volumes and realisations."},{"factor":"Currency (INR)","impact":"A weaker rupee raises rupee earnings from dollar sales."},{"factor":"Trade tariffs and duties","impact":"Tariffs and anti-dumping duties in buyer countries can quickly change competitiveness."},{"factor":"Raw material availability","impact":"Harvests, disease and weather affect shrimp supply and buying prices."}],"risks":[{"risk":"Trade barriers","detail":"New tariffs or duties in a key market can hit margins and orders."},{"risk":"Disease","detail":"Shrimp disease outbreaks can sharply cut supply."},{"risk":"Quality rejections","detail":"Antibiotic residue findings can lead to rejected shipments."},{"risk":"Global competition","detail":"Other shrimp-exporting countries compete hard on price."}],"cyclicality":"Cyclical","cyclicalityNote":"Earnings swing with global shrimp prices, trade policy and farm output.","metricSet":"agri-commodities","relatedBasicIndustries":["b-animal-feed","b-meat-products-including-poultry","b-food-storage-facilities","b-packaged-foods"],"aliases":["seafood","shrimp","prawns","aquaculture","frozen seafood","marine products","shrimp exporter","fish processing"],"themes":["Exports"]},"b-meat-products-including-poultry":{"simplifiedExplanation":"Companies that breed, raise or process chickens, eggs and meat, including integrated poultry firms, egg-powder makers and buffalo meat exporters.","productsAndServices":["Live broilers and dressed chicken","Day-old chicks and hatching eggs","Table eggs and egg powder","Processed and frozen meat","Buffalo meat for export","Ready-to-cook meat products"],"valueChainPosition":"Runs from breeding and hatcheries to processing: integrators give chicks and feed to contract farmers, then sell birds or meat to traders, retailers, restaurants and exporters.","howTheyMakeMoney":"Poultry integrators earn the spread between live bird prices and the cost of chicks and feed; egg-powder and meat exporters earn processing margins on overseas sales.","revenueSources":["Live bird sales","Processed chicken and meat","Day-old chicks and breeding stock","Buffalo meat and egg-product exports","Feed sales to farmers"],"operatingCosts":["Feed (maize and soybean meal)","Contract farmer payments","Vaccines and veterinary care","Processing and cold chain","Freight and export logistics"],"customersAndEndMarkets":"Meat traders, retailers, restaurants and quick-service chains in India, plus overseas buyers of buffalo meat and egg products.","demandSupplyDrivers":"Demand rises with protein consumption and eating out but dips during religious fasting periods; bird supply reacts quickly to prices, causing short boom-bust cycles.","domesticInternationalExposure":"Poultry is mostly domestic; buffalo meat and egg-product makers are export-led and exposed to global prices, the rupee and import rules abroad.","capexIntensity":"Medium","capexNote":"Hatcheries, feed mills, processing plants and abattoirs need moderate investment, while contract farming keeps bird rearing asset-light.","workingCapital":"Moderate: feed stocks and contract-farmer advances are needed, and export businesses carry receivables.","regulation":"FSSAI and state slaughter and hygiene rules, APEDA registration for meat export plants, state cattle-slaughter laws, and culling orders during bird flu outbreaks.","competitiveAdvantages":"Integration from breeding to feed, contract-farmer networks, approved export plants and biosecurity standards give scale players an edge.","drivers":[{"factor":"Commodity prices","impact":"Maize and soybean meal prices set feed cost, the largest expense."},{"factor":"Consumer demand","impact":"Rising protein consumption supports volumes, while fasting periods reduce them."},{"factor":"Exports & global demand","impact":"Global demand and market access drive meat and egg-product exporters."},{"factor":"Animal disease","impact":"Bird flu and other outbreaks can crash demand and prices."}],"risks":[{"risk":"Price cycles","detail":"An oversupply of birds can push live prices below cost."},{"risk":"Disease outbreaks","detail":"Bird flu scares cut consumption and can force culling."},{"risk":"Feed cost spikes","detail":"Grain and oilmeal inflation squeezes margins."},{"risk":"Market access","detail":"Bans or import restrictions abroad can halt shipments."}],"cyclicality":"Cyclical","cyclicalityNote":"Poultry and meat profits follow short, sharp cycles of bird supply, feed costs and disease.","metricSet":"agri-commodities","relatedBasicIndustries":["b-animal-feed","b-seafood","b-restaurants","b-food-storage-facilities","b-packaged-foods"],"aliases":["poultry","chicken","broiler","eggs","egg powder","meat","buffalo meat","meat exporter","hatchery"],"themes":["Exports","Rural demand"]},"b-personal-care":{"simplifiedExplanation":"Companies that sell products people use on their body every day, such as hair oil, shampoo, skin creams, deodorants, cosmetics and hygiene items.","productsAndServices":["Hair oils and shampoos","Skin creams, face washes and cosmetics","Deodorants and fragrances","Ayurvedic and herbal products","Sexual wellness and hygiene products","Men's grooming"],"valueChainPosition":"Downstream: buys oils, chemicals, fragrances and packaging, makes products in own or contract plants and sells through distributors, chemists, beauty stores, modern trade and online.","howTheyMakeMoney":"Brand-led prices give high gross margins, but a large share is spent on advertising, influencers and trade schemes; profit comes from scale and repeat buying.","revenueSources":["Domestic branded sales","E-commerce and D2C sales","Exports to nearby regions","Tender sales of hygiene products","Contract manufacturing"],"operatingCosts":["Vegetable oils and crude-based ingredients such as liquid paraffin","Fragrances, actives and packaging","Advertising and digital marketing","Distribution and trade margins","Contract manufacturing fees"],"customersAndEndMarkets":"Consumers across urban and rural India through kirana stores, chemists, supermarkets, salons and online marketplaces.","demandSupplyDrivers":"Demand grows as incomes rise and people add more grooming steps; small low-priced packs widen reach, while premium products grow in cities.","domesticInternationalExposure":"Mostly domestic with some exports; oils, crude derivatives and fragrances follow global prices.","capexIntensity":"Low","capexNote":"Manufacturing is simple and often outsourced; the main investment goes into brands rather than factories.","workingCapital":"Light: distributors get short credit and stock turns quickly, though online and modern trade can stretch receivables.","regulation":"Cosmetics fall under the Drugs and Cosmetics Act through CDSCO, ayurvedic products need AYUSH licences, and advertising claims are watched by ASCI and consumer protection rules.","competitiveAdvantages":"Brand trust, marketing scale and distribution reach protect leaders, though digital-first brands have lowered barriers in some niches.","drivers":[{"factor":"Consumer demand","impact":"Premiumisation and new categories raise the value of each purchase."},{"factor":"Rural demand","impact":"Rural income growth drives small-pack volumes in hair oil and creams."},{"factor":"Crude oil prices","impact":"Liquid paraffin, plastic packaging and some chemicals track crude prices."},{"factor":"Advertising spend","impact":"Media and influencer costs decide how much margin reaches profit."}],"risks":[{"risk":"Competition","detail":"D2C and global brands compete hard with heavy discounting."},{"risk":"Input inflation","detail":"Oil and packaging cost spikes squeeze margins."},{"risk":"Changing trends","detail":"Shifts in consumer taste can make a brand look dated."},{"risk":"Claim scrutiny","detail":"Rulings on misleading advertising can force product or message changes."}],"cyclicality":"Defensive","cyclicalityNote":"Daily-use products keep demand steady, though premium items slow in downturns.","metricSet":"fmcg","relatedBasicIndustries":["b-household-products","b-diversified-fmcg","b-pharmaceuticals","b-specialty-chemicals","b-e-retail-e-commerce"],"aliases":["personal care","cosmetics","beauty","skin care","hair oil","shampoo","grooming","toiletries","D2C beauty"],"themes":["Rural demand","Premiumisation","Digital"]},"b-household-products":{"simplifiedExplanation":"Companies that make everyday items for cleaning and running a home, such as detergents, dishwash bars, mosquito repellents, batteries, torches and air fresheners.","productsAndServices":["Detergents and fabric whiteners","Dishwash bars and liquids","Mosquito repellents and household insecticides","Dry-cell batteries","Torches and small lighting","Toilet and floor cleaners"],"valueChainPosition":"Downstream: buys chemicals, metals, plastics and packaging, makes products in own or outsourced plants, and sells through distributors to kirana stores, modern trade and online.","howTheyMakeMoney":"They earn brand-led margins on low-priced, often-bought items, relying on high volumes, wide distribution and tight cost control.","revenueSources":["Fabric and dish care","Household insecticides","Batteries and torches","Other home care products","Exports to nearby countries"],"operatingCosts":["Crude-linked chemicals such as surfactants","Soda ash, zinc and other metals","Packaging","Advertising and promotions","Distribution and trade margins"],"customersAndEndMarkets":"Households in cities and villages, buying mostly from local stores; repellent and battery sales have seasonal peaks.","demandSupplyDrivers":"Demand rises with hygiene awareness, new households and the move to branded products; the monsoon and mosquito season lift repellent sales.","domesticInternationalExposure":"Mostly domestic, but key inputs track global crude and metal prices, and cheap imported batteries and torches compete on price.","capexIntensity":"Low","capexNote":"Production lines cost little compared with brand and distribution spending, and some products are outsourced.","workingCapital":"Light to moderate: stock moves fast, but seasonal products build inventory before peak months.","regulation":"Household insecticides need registration under the Insecticides Act (CIB&RC); batteries and plastic packaging fall under waste management and EPR rules; BIS standards apply to some products.","competitiveAdvantages":"Trusted brands, wide rural and urban reach and efficient sourcing protect leaders against unorganised rivals.","drivers":[{"factor":"Consumer demand","impact":"Hygiene awareness and premium formats such as liquids lift value growth."},{"factor":"Rural demand","impact":"Rural spending drives low-priced packs and battery sales."},{"factor":"Crude oil prices","impact":"Detergent chemicals and plastic packaging follow crude prices."},{"factor":"Imports & dumping","impact":"Cheap imported batteries and lights pressure prices."}],"risks":[{"risk":"Input cost spikes","detail":"Crude, zinc and soda ash inflation squeezes margins."},{"risk":"Technology shifts","detail":"Rechargeable devices and LED lights reduce demand for dry-cell batteries."},{"risk":"Unorganised competition","detail":"Local brands undercut prices in price-sensitive markets."},{"risk":"Ingredient bans","detail":"Restrictions on certain insecticide molecules can force reformulation."}],"cyclicality":"Defensive","cyclicalityNote":"Essential household items sell through economic cycles, while margins vary with input costs.","metricSet":"fmcg","relatedBasicIndustries":["b-personal-care","b-diversified-fmcg","b-specialty-chemicals","b-household-appliances","b-pesticides-and-agrochemicals"],"aliases":["household products","home care","detergent","dishwash","mosquito repellent","batteries","torch","cleaning products"],"themes":["Rural demand"]},"b-stationary":{"simplifiedExplanation":"Companies that make writing and school supplies such as pens, pencils, notebooks, art materials and office stationery; some also publish educational books. NSE spells this industry 'Stationary'.","productsAndServices":["Pens and refills","Pencils, erasers and sharpeners","Notebooks and exercise books","Art, craft and colouring materials","Office supplies","Supplementary and educational books"],"valueChainPosition":"Downstream: buys paper, plastic resins, wood, graphite and inks, makes the products and sells through distributors, stationery shops, schools, modern trade and online; some products are exported.","howTheyMakeMoney":"They earn margins on high-volume, low-price items, with better margins on branded, premium and art products; publishers earn from book sales each academic year.","revenueSources":["Domestic branded sales","Exports of pens and stationery","Private-label supply to other brands","Educational book sales","Institutional and corporate orders"],"operatingCosts":["Paper and board","Plastic resins and inks","Wood and graphite","Assembly labour","Distribution and dealer margins","Advertising"],"customersAndEndMarkets":"School students and parents, offices and institutions, and overseas buyers; sales peak at the start of the school year.","demandSupplyDrivers":"Demand follows school enrolment, the academic calendar and exam cycles, while paper and resin prices drive costs.","domesticInternationalExposure":"Mostly domestic; some makers export pens and stationery, cheap imports compete, and paper and resin prices follow global markets.","capexIntensity":"Medium","capexNote":"Moulding, printing and assembly capacity needs periodic expansion, especially for makers who produce most parts in-house.","workingCapital":"Seasonal: inventory and dealer credit build up before the school season, and publishers carry large book stocks.","regulation":"Light, general business regulation; GST rates on stationery and paper, and changes in school curriculum or textbook policy, affect demand.","competitiveAdvantages":"Brand recall among students and parents, wide dealer networks, in-house manufacturing scale and product range help leaders.","drivers":[{"factor":"Consumer demand","impact":"School enrolment and household spending on education drive volumes."},{"factor":"Commodity prices","impact":"Paper, plastic resin and wood prices shape margins."},{"factor":"Imports & dumping","impact":"Low-cost imported stationery competes on price."},{"factor":"Technology change","impact":"Digital learning can reduce some paper-based demand."}],"risks":[{"risk":"Paper price spikes","detail":"Higher paper costs hurt notebook and book margins."},{"risk":"Curriculum changes","detail":"Syllabus changes can make printed book stocks obsolete."},{"risk":"Seasonality","detail":"A weak school season affects the whole year's sales."},{"risk":"Price competition","detail":"Local and imported products compete aggressively on price."}],"cyclicality":"Defensive","cyclicalityNote":"School supplies are essential and bought every year, though input costs make margins vary.","metricSet":"fmcg","relatedBasicIndustries":["b-paper-and-paper-products","b-printing-and-publication","b-plastic-products-consumer","b-education","b-household-products"],"aliases":["stationery","stationary","pens","pencils","notebooks","school supplies","art materials","writing instruments","office supplies"],"themes":[]},"b-diversified-fmcg":{"simplifiedExplanation":"Large consumer companies that sell many kinds of everyday products, such as foods, soaps, detergents, personal care and sometimes cigarettes; contract manufacturers making such goods for brand owners also sit here.","productsAndServices":["Soaps, detergents and home care","Personal care products","Packaged foods and beverages","Cigarettes (in some groups)","Contract manufacturing for FMCG brands"],"valueChainPosition":"Downstream: sources agricultural, chemical and packaging inputs at scale and sells through vast distributor and retailer networks; contract makers sit one step earlier, supplying brand owners.","howTheyMakeMoney":"Brand owners earn from pricing power across many categories that share one distribution system; contract manufacturers earn a fee or margin on volumes made.","revenueSources":["Home and personal care","Foods and beverages","Cigarettes (where present)","Contract manufacturing fees","Other segments such as paper, agri or hotels"],"operatingCosts":["Agricultural commodities and palm oil","Crude-linked chemicals and packaging","Advertising and promotions","Distribution and trade spend","Employee costs and brand royalties"],"customersAndEndMarkets":"Households across India through general trade, modern trade, e-commerce and quick commerce; contract makers serve FMCG brand owners.","demandSupplyDrivers":"Demand tracks overall consumption, rural incomes and premiumisation; a wide portfolio lets weak categories be offset by strong ones.","domesticInternationalExposure":"Mainly domestic; palm oil, crude derivatives and wheat follow global prices, and some players export to neighbouring countries.","capexIntensity":"Medium","capexNote":"Brand owners need moderate plant investment, while contract makers invest more in dedicated plants for clients.","workingCapital":"Usually light or negative for brand owners thanks to fast stock turns and supplier credit; contract makers carry more inventory.","regulation":"FSSAI for foods, CDSCO rules for cosmetics, COTPA and tobacco taxes for cigarettes, GST rate changes across categories, and plastic packaging EPR rules.","competitiveAdvantages":"A portfolio of trusted brands, very deep distribution, buying scale and large marketing budgets create high barriers to entry.","drivers":[{"factor":"Consumer demand","impact":"Urban premiumisation lifts mix and margins across categories."},{"factor":"Rural demand","impact":"Rural income growth drives volumes of mass-market packs."},{"factor":"Commodity prices","impact":"Palm oil, crude derivatives, wheat and tea costs move gross margins."},{"factor":"Government policy","impact":"GST and tobacco tax changes shift pricing and demand."}],"risks":[{"risk":"Volume slowdown","detail":"Weak consumption makes growth hard without price cuts."},{"risk":"Commodity inflation","detail":"Fast cost rises can squeeze margins before price hikes take effect."},{"risk":"New-age competition","detail":"D2C and regional brands chip away at specific categories."},{"risk":"Client dependence","detail":"Contract manufacturers rely on a few brand-owner customers."}],"cyclicality":"Defensive","cyclicalityNote":"A broad basket of essential products keeps earnings steady through economic cycles.","metricSet":"fmcg","relatedBasicIndustries":["b-personal-care","b-household-products","b-packaged-foods","b-cigarettes-and-tobacco-products","b-diversified"],"aliases":["FMCG","diversified FMCG","consumer staples","consumer goods","fast moving consumer goods","FMCG conglomerate","contract manufacturing"],"themes":["Rural demand","Premiumisation"]},"b-pharmaceuticals":{"simplifiedExplanation":"Companies that make medicines: the active ingredient (API or bulk drug) or finished tablets, capsules and injections. Most Indian firms make generics, copies of off-patent drugs.","productsAndServices":["Branded generics for India","Generics for regulated and emerging markets","APIs and intermediates","Injectables and complex generics","Over-the-counter (OTC) products"],"valueChainPosition":"Midstream to downstream: turns chemical intermediates (often imported) into APIs and finished doses for distributors, chemists, hospitals and overseas buyers.","howTheyMakeMoney":"At home they build doctor-prescribed brands via medical representatives; abroad they win approvals and supply low-cost generics, earning more on first-to-market or hard-to-make products.","revenueSources":["Domestic branded formulations","US and Europe generics","Emerging-market exports","API sales to other drug makers","Contract manufacturing (CDMO)"],"operatingCosts":["APIs, intermediates and solvents","Field-force salaries and marketing","R&D and regulatory filings","Quality compliance and remediation","Plant staff, power and utilities"],"customersAndEndMarkets":"Patients via doctors, chemists and hospitals in India; wholesalers, pharmacy chains and tenders abroad; other drug makers for APIs.","demandSupplyDrivers":"Medicine use is steady and rises with ageing, chronic disease and insurance; in exports, the number of approved rivals per molecule sets how fast prices fall.","domesticInternationalExposure":"Strongly export-linked, so the rupee and US pricing matter; many raw materials are imported, notably from China.","capexIntensity":"Medium","capexNote":"GMP-grade plants and R&D labs need steady spending, though less than heavy industry.","workingCapital":"Large inventories across many products and long supply chains, plus receivables from overseas distributors and stockists.","regulation":"CDSCO and state drug controllers license plants and products; NPPA caps essential-medicine prices under the DPCO; exports need USFDA, EU or WHO-GMP approval.","competitiveAdvantages":"Strong doctor-facing brands, a clean regulatory record, low-cost integrated plants and complex products are hard to copy.","drivers":[{"factor":"US generic drug pricing","impact":"US price erosion or shortages swing export margins."},{"factor":"Regulation","impact":"USFDA inspections decide whether plants can ship to regulated markets."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts export value but raises imported input costs."},{"factor":"Healthcare spending","impact":"Wider access to doctors and insurance lifts domestic prescriptions."},{"factor":"Government policy","impact":"Price controls cap essential-drug prices; PLI aids local APIs."}],"risks":[{"risk":"Regulatory action","detail":"A warning letter or import alert can halt a plant's exports."},{"risk":"Price erosion","detail":"More rivals on a molecule push prices down fast."},{"risk":"Input dependence","detail":"Concentrated sourcing of starting materials exposes cost and supply."},{"risk":"Patent disputes","detail":"Litigation brings legal costs or delayed launches."}],"cyclicality":"Defensive","cyclicalityNote":"Medicine demand holds up in downturns, though export pricing and regulatory events make profits lumpy.","metricSet":"pharma","relatedBasicIndustries":["b-biotechnology","b-healthcare-research-analytics-and-technology","b-specialty-chemicals","b-pharmacy-retail","b-hospital"],"aliases":["pharma","pharmaceutical","drug makers","generics","formulations","api","bulk drugs","medicines","pharma stocks"],"themes":["Exports","China+1"]},"b-biotechnology":{"simplifiedExplanation":"Companies that use living cells, microbes or enzymes to make biologic medicines, biosimilars, vaccines, enzymes and probiotics. It is science-heavy and slower to scale than chemical drug making.","productsAndServices":["Biosimilars and biologic drugs","Vaccines","Insulin and peptides","Food, feed and industrial enzymes","Probiotics and nutraceutical ingredients","Biologics contract development and manufacturing"],"valueChainPosition":"Midstream: buys cell lines, culture media, reagents and bioprocess equipment, and supplies drug makers, food and feed processors, hospitals and governments.","howTheyMakeMoney":"They sell hard-to-make biological products at premium prices, or charge global clients to develop and make biologics; a few products often drive most profit.","revenueSources":["Biosimilar and biologic sales","Vaccine supplies to governments","Enzyme and probiotic sales","Biologics CDMO fees and milestones"],"operatingCosts":["Scientist salaries and R&D","Clinical trials","Culture media and consumables","Cleanroom utilities and quality control","Bioreactor plant depreciation"],"customersAndEndMarkets":"Pharma partners, hospitals and governments for biologics and vaccines; food, feed, textile and detergent makers for enzymes.","demandSupplyDrivers":"Demand grows as big biologics lose patents and industries swap chemical processes for enzymes; scarce talent, long plant qualification and slow approvals limit supply.","domesticInternationalExposure":"Tied to regulated export markets and global partners; key inputs and equipment are mostly imported, so the rupee matters.","capexIntensity":"High","capexNote":"Bioreactors, cleanrooms and long validation make plants costly and slow to bring online.","workingCapital":"Development absorbs cash long before revenue; biologics need cold-chain storage and partner milestones are lumpy.","regulation":"CDSCO approves biologics and vaccines; genetically engineered organisms and products need clearance from RCGM and GEAC; export products need USFDA or European approval and inspections.","competitiveAdvantages":"Proprietary strains or cell lines, process know-how, approved plants and a regulatory record take years to build.","drivers":[{"factor":"Biologic patent expiries","impact":"Big biologics going off-patent open markets for biosimilars."},{"factor":"Regulation","impact":"Approval timelines and inspections decide when products start earning."},{"factor":"Global biotech funding","impact":"Overseas biotech funding drives contract development demand."},{"factor":"Technology change","impact":"Cell, gene and mRNA therapies can raise or reduce the value of existing platforms."}],"risks":[{"risk":"Clinical failure","detail":"A product can fail in trials after years of spending."},{"risk":"Approval delays","detail":"Slow or rejected approvals push revenue out."},{"risk":"Biosimilar price competition","detail":"Prices fall as more makers launch the same molecule."},{"risk":"Batch failures","detail":"Failed biological batches are costly."}],"cyclicality":"Mixed","cyclicalityNote":"End demand is steady, but funding cycles, partner decisions and approvals make earnings uneven.","metricSet":"biotech-research","relatedBasicIndustries":["b-pharmaceuticals","b-healthcare-research-analytics-and-technology","b-specialty-chemicals","b-animal-feed"],"aliases":["biotech","bio technology","biologics","biosimilars","enzymes","vaccines","fermentation","probiotics","biopharma"],"themes":["Exports","China+1"]},"b-medical-equipment-and-supplies":{"simplifiedExplanation":"Companies that make the physical tools of healthcare, from syringes, catheters and gloves to implants, dental products, diagnostic machines and lab plasticware.","productsAndServices":["Syringes, cannulas, catheters and other disposables","Orthopaedic, cardiac and dental implants","Diagnostic and imaging equipment","Lab plasticware and consumables","Dental aligners and products","Surgical instruments and wound care"],"valueChainPosition":"Midstream: converts medical-grade plastics, steel, electronics and chemicals into devices, and sells to hospitals, labs, clinics, distributors and overseas device brands.","howTheyMakeMoney":"Most earn repeat revenue from consumables used on every patient; equipment makers add machine sales, servicing and the consumables machines need.","revenueSources":["Consumables and disposables","Equipment sales","Service and maintenance contracts","Exports to distributors and device brands","Government and hospital tenders"],"operatingCosts":["Medical-grade polymers, metals and electronics","Sterilisation and quality systems","Imported components","Distributor margins and sales staff","R&D and product certification"],"customersAndEndMarkets":"Hospitals, clinics, diagnostic labs, dentists, research labs and public health programmes in India and overseas.","demandSupplyDrivers":"Volumes rise with hospital beds, surgeries, testing and infection-control norms; local makers compete with imported global brands on cost and service.","domesticInternationalExposure":"Many firms export disposables to regulated markets, while advanced equipment and electronic parts are largely imported.","capexIntensity":"Medium","capexNote":"Cleanroom moulding, sterilisation and automated lines need investment, though less than drug or biotech plants.","workingCapital":"Many products and sizes push up inventory, and payments from hospitals and government tenders can be slow.","regulation":"CDSCO licenses devices by risk class under the Medical Devices Rules; NPPA caps some prices such as stents and knee implants; exports need CE or USFDA clearance; PLI aids local makers.","competitiveAdvantages":"Regulatory approvals, doctor familiarity with a product, wide distribution and low-cost precision manufacturing protect established firms.","drivers":[{"factor":"Healthcare spending","impact":"More hospitals, surgeries and tests raise device and consumable use."},{"factor":"Government policy","impact":"PLI, local-preference procurement and import duties favour domestic makers."},{"factor":"Exports & global demand","impact":"Global buyers diversifying suppliers support disposable exports."},{"factor":"Commodity prices","impact":"Polymer and metal costs move margins on low-priced disposables."}],"risks":[{"risk":"Price caps","detail":"Government price controls can cut realisations."},{"risk":"Import competition","detail":"Global brands win on technology, cheap imports on price."},{"risk":"Product recalls","detail":"Quality failures trigger recalls and lost hospital trust."},{"risk":"Tender dependence","detail":"Government tenders bring price pressure and payment delays."}],"cyclicality":"Mixed","cyclicalityNote":"Daily-use consumables are defensive, while equipment purchases follow hospital budgets and expansion plans.","metricSet":"medical-devices","relatedBasicIndustries":["b-hospital","b-healthcare-service-provider","b-pharmaceuticals","b-plastic-products-industrial"],"aliases":["medical devices","medtech","meditech","surgical products","medical disposables","implants","diagnostic equipment","dental products","lab consumables"],"themes":["Make in India","Exports"]},"b-hospital":{"simplifiedExplanation":"Companies that run hospitals: multi-speciality chains and single-speciality centres such as eye, heart, cancer, fertility or mother-and-child hospitals, treating admitted patients and outpatients.","productsAndServices":["Inpatient treatment and surgeries","Outpatient consultations","ICU and emergency care","In-house pharmacy and diagnostics","Speciality care such as cardiac, cancer, eye and IVF"],"valueChainPosition":"Downstream: buys medicines, devices, consumables and doctors' time, and serves patients directly; bills are paid by patients, insurers and government schemes.","howTheyMakeMoney":"They fill beds with complex, higher-paying treatments; profit depends on occupancy, revenue per occupied bed and staff costs, and mature hospitals earn far more than new ones.","revenueSources":["Inpatient bills (rooms, procedures, surgeries)","Outpatient consultations","Pharmacy and consumables","Diagnostics and imaging","International patients"],"operatingCosts":["Doctor fees and retainers","Nursing and support staff","Medicines and consumables","Building rent or lease","Power, housekeeping and maintenance","Equipment depreciation"],"customersAndEndMarkets":"Self-paying patients, health insurers and TPAs, government schemes such as PM-JAY and CGHS, corporates and foreign patients.","demandSupplyDrivers":"Demand grows with chronic disease, ageing, insurance and preference for private care; scarce doctors, nurses and quality beds, plus long build times, limit supply.","domesticInternationalExposure":"Mostly domestic; medical tourism adds foreign revenue, and imported equipment ties some costs to the rupee.","capexIntensity":"High","capexNote":"Land, buildings and medical equipment are expensive, and new beds take years to fill.","workingCapital":"Cash patients pay quickly, but insurers and government schemes pay with a delay; drug and consumable inventory is modest.","regulation":"State clinical-establishment, fire and pollution approvals; NABH accreditation; package rates fixed by PM-JAY and CGHS; IRDAI rules on cashless claims; NPPA price caps on some implants.","competitiveAdvantages":"Reputation, well-known doctors, prime locations, accreditation and the years needed to build trust make established brands hard to challenge locally.","drivers":[{"factor":"Healthcare spending","impact":"Rising private health spending lifts footfall and complex procedures."},{"factor":"Health insurance penetration","impact":"More insured patients can afford costlier treatment."},{"factor":"Government policy","impact":"Scheme rates and implant price caps affect revenue per patient."},{"factor":"Tourism & travel","impact":"Visa ease and flight links drive medical tourism."},{"factor":"Capacity utilisation","impact":"Higher occupancy spreads fixed costs."}],"risks":[{"risk":"Doctor exits","detail":"Losing key doctors can take patients away."},{"risk":"Pricing intervention","detail":"Caps on rates, implants or drugs cut revenue per patient."},{"risk":"New-hospital ramp-up","detail":"New hospitals lose money until occupancy builds."},{"risk":"Reputation incidents","detail":"Negligence claims or billing disputes damage trust."}],"cyclicality":"Defensive","cyclicalityNote":"Most treatment cannot be postponed, though elective procedures and medical tourism can dip in bad times.","metricSet":"hospital","relatedBasicIndustries":["b-healthcare-service-provider","b-medical-equipment-and-supplies","b-pharmaceuticals","b-general-insurance","b-pharmacy-retail"],"aliases":["hospitals","hospital chain","multispeciality hospital","multi-specialty hospital","healthcare delivery","eye hospital","medical tourism","hospital stocks"],"themes":["Medical tourism"]},"b-healthcare-service-provider":{"simplifiedExplanation":"Healthcare businesses other than full hospitals: mainly diagnostic labs that test samples and centres that do scans, plus dialysis and home-care providers and some test-kit makers.","productsAndServices":["Pathology tests (blood, urine, biopsy)","Radiology: X-ray, ultrasound, CT and MRI","Preventive health check-ups","Home sample collection","Molecular (PCR) test kits","Dialysis and home healthcare"],"valueChainPosition":"Downstream: buys analysers, reagents and scanners from equipment makers and sells test results and care to patients, doctors, hospitals and public programmes.","howTheyMakeMoney":"They charge per test or session; collection centres feed central labs (hub-and-spoke), so profit rises as more tests run through the same machines and staff.","revenueSources":["Walk-in and doctor-referred patients","Wellness packages","Testing for hospitals and smaller labs","Government partnership contracts","Corporate and insurer health checks"],"operatingCosts":["Reagents and test kits","Technician, pathologist and radiologist salaries","Collection network and sample logistics","Centre rent and equipment leases","Marketing"],"customersAndEndMarkets":"Individual patients, referring doctors, hospitals and smaller labs, employers, insurers and state health programmes.","demandSupplyDrivers":"Demand grows with chronic-disease monitoring, preventive-health awareness and insurance. The market is crowded with small standalone labs, and online test aggregators sharpen price competition.","domesticInternationalExposure":"Almost entirely domestic; analysers, reagents and imaging machines are often imported, so some costs move with the rupee.","capexIntensity":"Medium","capexNote":"Imaging machines and central labs need capital, but collection centres are light and often franchised.","workingCapital":"Retail patients pay upfront; hospital and government contracts create receivables; reagent stocks are modest.","regulation":"NABL and NABH accreditation signal quality; ultrasound centres follow the PCPNDT Act; X-ray and CT units need AERB licences; biomedical-waste rules apply.","competitiveAdvantages":"A brand doctors trust, a dense collection network, accreditation and high volumes per lab give lower costs than small rivals.","drivers":[{"factor":"Healthcare spending","impact":"More testing and chronic-disease care raises volumes."},{"factor":"Preventive health awareness","impact":"Regular check-ups bring repeat customers."},{"factor":"Online price competition","impact":"Aggregators and new entrants push down routine test prices."},{"factor":"Technology change","impact":"Lab automation cuts costs; home testing changes how customers are reached."}],"risks":[{"risk":"Price wars","detail":"Discounting by aggregators and new labs squeezes margins."},{"risk":"Report errors","detail":"Wrong results damage the brand and can draw penalties."},{"risk":"Expansion costs","detail":"New cities lose money until volumes build."},{"risk":"One-off demand fading","detail":"Volumes drop after temporary spikes such as epidemics."}],"cyclicality":"Defensive","cyclicalityNote":"Most tests are medically needed, though wellness and discretionary tests slow in weaker times.","metricSet":"healthcare-services","relatedBasicIndustries":["b-hospital","b-medical-equipment-and-supplies","b-pharmacy-retail","b-general-insurance"],"aliases":["diagnostics","diagnostic centre","diagnostic labs","pathology","path labs","radiology","imaging centres","dialysis","health check-up"],"themes":["Preventive health","Digital"]},"b-healthcare-research-analytics-and-technology":{"simplifiedExplanation":"Companies that do research, testing and technology work for drug and biotech makers rather than selling medicines: contract research (CRO), contract manufacturing (CDMO), testing labs and pharma data services.","productsAndServices":["Drug-discovery chemistry and biology","Contract development and manufacturing","Pre-clinical and clinical trial services","Analytical, drug and food testing","Regulatory and drug-safety services","Pharma analytics and digital marketing"],"valueChainPosition":"Upstream service partner to the drug industry: supplies scientists, labs and data to drug developers, and buys reagents, lab instruments and software.","howTheyMakeMoney":"They charge per project, per dedicated scientist (FTE model) or per milestone, and earn supply revenue when a client's molecule reaches the market.","revenueSources":["Discovery and dedicated-team contracts","Development and manufacturing contracts","Testing fees","Clinical trial services","Analytics and digital services to pharma"],"operatingCosts":["Scientist and analyst salaries","Lab consumables and reagents","Instrument and plant depreciation","Quality and compliance systems","Technology and data infrastructure"],"customersAndEndMarkets":"Global pharma and biotech companies, Indian drug makers, food and consumer firms needing tests, and clinical-trial sponsors.","demandSupplyDrivers":"Demand depends on global R&D budgets, biotech funding and big pharma's push to outsource and diversify suppliers; supply depends on scientists and audit-ready labs.","domesticInternationalExposure":"Mainly exports services to US, European and Japanese clients, so the rupee, global R&D spending and supplier-diversification policies matter.","capexIntensity":"Medium","capexNote":"Lab- and plant-based research firms invest heavily, while analytics and technology service firms are asset-light.","workingCapital":"Mostly client receivables and unbilled work; milestone billing makes cash flows lumpy.","regulation":"Trials follow CDSCO's clinical-trial rules; labs follow GLP and GMP norms and face client and USFDA audits; data work must meet privacy and pharmacovigilance requirements.","competitiveAdvantages":"Long client relationships, a clean audit record, scientific depth and trusted data confidentiality make clients slow to switch.","drivers":[{"factor":"Global pharma R&D spending","impact":"Bigger research budgets and more outsourcing lift project demand."},{"factor":"Biotech funding","impact":"Booms and busts in overseas biotech funding move discovery orders."},{"factor":"China+1 sourcing","impact":"Clients diversifying from China can shift work to India."},{"factor":"Technology change","impact":"AI and data tools change drug discovery and pharma marketing."}],"risks":[{"risk":"Client concentration","detail":"Losing a large client or molecule hits revenue."},{"risk":"Project cancellations","detail":"Failed trials or budget cuts end contracts early."},{"risk":"Talent costs","detail":"Competition for scientists pushes up wages."},{"risk":"Audit failures","detail":"A failed regulator or client audit can halt work."}],"cyclicality":"Mixed","cyclicalityNote":"Outsourcing is a long-term trend, but global biotech funding and pharma budgets move in cycles.","metricSet":"biotech-research","relatedBasicIndustries":["b-pharmaceuticals","b-biotechnology","b-computers-software-and-consulting","b-specialty-chemicals"],"aliases":["cro","cdmo","crams","contract research","drug discovery","clinical trials","testing labs","pharma analytics","life sciences services"],"themes":["Exports","China+1"]},"b-computers-software-and-consulting":{"simplifiedExplanation":"IT services companies that build, run and maintain software and technology systems for businesses, mostly large overseas clients, using teams of engineers in India and abroad.","productsAndServices":["Application development and maintenance","Cloud migration and infrastructure management","Digital transformation consulting","ERP and CRM implementation","Data, analytics and AI services","Cybersecurity and testing services"],"valueChainPosition":"Midstream services layer: works on global software and cloud platforms to deliver solutions for banks, insurers, retailers, manufacturers, telecom firms and governments.","howTheyMakeMoney":"They bill for people-time (time-and-material), fixed-price projects or multi-year managed-services deals. Margins depend on billing rates, staff utilisation and how much work is done offshore.","revenueSources":["Multi-year managed-services contracts","Transformation and project work","Consulting fees","Resale of software licences and platforms","Large outsourcing deals"],"operatingCosts":["Employee salaries and benefits","Subcontractors and onsite staff","Travel and visas","Offices and IT infrastructure","Sales and pre-sales teams"],"customersAndEndMarkets":"Large and mid-sized firms in the US, Europe and elsewhere, mainly banking, insurance, retail, manufacturing, healthcare and telecom, plus Indian enterprises and government.","demandSupplyDrivers":"Demand follows global corporate technology budgets: run-the-business spending is sticky, discretionary projects get cut when client economies slow. Supply depends on hiring engineers.","domesticInternationalExposure":"Highly export-oriented: revenue mostly in dollars, euros and pounds, costs mostly in rupees, so currency moves flow into margins.","capexIntensity":"Low","capexNote":"Spending goes mainly on offices, laptops and some data centres; people are the main asset.","workingCapital":"Mostly client receivables and unbilled revenue; there is no physical inventory.","regulation":"Light in India (SEZ and STPI rules, labour laws, DPDP Act); overseas, work-visa rules such as H-1B and privacy laws such as GDPR affect delivery.","competitiveAdvantages":"Deep client relationships, industry know-how, delivery scale and high vendor-switching costs protect leading firms.","drivers":[{"factor":"Exports & global demand","impact":"US and European client budgets set the pace of new deals."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts revenue against India-based costs."},{"factor":"Technology change","impact":"Cloud and AI create new work but shrink effort on older services."},{"factor":"Talent and wage costs","impact":"Attrition and salary hikes move margins."}],"risks":[{"risk":"Client budget cuts","detail":"Slowdowns in key client industries delay projects and squeeze pricing."},{"risk":"AI-led deflation","detail":"Automation can shrink billable hours."},{"risk":"Attrition","detail":"High staff turnover raises hiring and training costs."},{"risk":"Protectionism","detail":"Visa curbs or local-hiring rules raise delivery costs."}],"cyclicality":"Mixed","cyclicalityNote":"Long maintenance contracts give stability, but new projects follow the global business cycle.","metricSet":"it-services","relatedBasicIndustries":["b-software-products","b-it-enabled-services","b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo","b-consulting-services","b-data-processing-services"],"aliases":["it services","software services","it companies","infotech","it consulting","tech services","IT","software exporters","IT stocks"],"themes":["Digital","Exports","AI"]},"b-software-products":{"simplifiedExplanation":"Companies that own and sell their own software, such as banking, lending or compliance platforms, business messaging platforms, digital maps and business apps, instead of renting out engineers.","productsAndServices":["Core banking and lending software","SaaS subscriptions","Business messaging platforms (CPaaS)","Regulatory and compliance software","Digital maps and location data","Business apps for smaller firms"],"valueChainPosition":"Upstream in software: builds intellectual property and sells licences or subscriptions to banks, enterprises, telecom operators and governments, directly or through partners.","howTheyMakeMoney":"They earn licence fees, subscriptions, usage charges and annual maintenance; once built, each extra customer costs little to serve, so margins can widen with scale.","revenueSources":["Subscriptions and SaaS fees","Licence sales","Annual maintenance contracts","Implementation and customisation services","Usage or transaction-based fees"],"operatingCosts":["Product engineering and R&D salaries","Cloud hosting","Sales and marketing","Telecom carrier charges for messaging platforms","Implementation staff"],"customersAndEndMarkets":"Banks, NBFCs, insurers, enterprises, telecom operators, government bodies and small businesses in India and overseas.","demandSupplyDrivers":"Demand grows with digitisation of banking, payments and compliance and with the shift to cloud. Competition from global software vendors and open-source tools limits pricing.","domesticInternationalExposure":"A mix of domestic and export customers; overseas sales earn foreign currency, and competition is global even at home.","capexIntensity":"Low","capexNote":"Most investment is product development spending rather than plants or machinery.","workingCapital":"Subscriptions help cash flow, but licence and implementation deals with banks and government can leave long receivables.","regulation":"Mostly light, but client-sector rules matter: RBI, SEBI and IRDAI norms shape financial software, TRAI rules govern commercial messaging, and the DPDP Act covers personal data.","competitiveAdvantages":"Products embedded in client workflows, high switching costs, proprietary data and regulatory know-how protect leading firms.","drivers":[{"factor":"Technology change","impact":"Cloud, AI and new platforms can open markets or make products obsolete."},{"factor":"Credit growth","impact":"Expanding lenders need more banking and lending software."},{"factor":"Regulation","impact":"New compliance and reporting rules create regtech demand."},{"factor":"Digital adoption","impact":"More online transactions and business messages raise usage revenue."}],"risks":[{"risk":"Product obsolescence","detail":"A better rival product can erode the customer base."},{"risk":"Lumpy deals","detail":"Large licence wins are irregular, so quarters can be uneven."},{"risk":"Global competition","detail":"Bigger global vendors chase the same clients."},{"risk":"Platform dependence","detail":"Reliance on telecom carriers or cloud providers can squeeze margins."}],"cyclicality":"Mixed","cyclicalityNote":"Recurring subscriptions are steady, but new licence sales slow when clients cut budgets.","metricSet":"software-products","relatedBasicIndustries":["b-computers-software-and-consulting","b-financial-technology-fintech","b-it-enabled-services","b-telecom-cellular-and-fixed-line-services"],"aliases":["saas","software product","software products","enterprise software","banking software","cpaas","product companies","regtech"],"themes":["Digital","AI"]},"b-it-enabled-services":{"simplifiedExplanation":"Companies that deliver services using IT systems and skilled staff, such as engineering R&D services, data-centre and cloud hosting, managed IT operations and digital back-office work.","productsAndServices":["Engineering and product design (ER&D) services","Data-centre, cloud and managed hosting","Remote IT infrastructure management","Digital content and data annotation","Back-office and transaction processing","Technical staffing"],"valueChainPosition":"Midstream services: uses IT infrastructure and trained staff to support manufacturers, automotive and aerospace firms, enterprises and government; buys servers, power and connectivity.","howTheyMakeMoney":"They bill per engineer-hour, per project, per transaction or for hosting capacity used. Profit comes from keeping people or infrastructure well utilised.","revenueSources":["Engineering services contracts","Hosting and cloud fees","Managed-services retainers","Per-transaction processing fees","Staffing fees"],"operatingCosts":["Employee costs","Data-centre power and cooling","Bandwidth and hardware","Office space","Training and recruitment"],"customersAndEndMarkets":"Automotive, aerospace, industrial and technology companies for engineering work; enterprises, banks and government departments for hosting and processing.","demandSupplyDrivers":"Demand rises as companies outsource product engineering and move workloads to cloud and local data centres; supply depends on engineers and data-centre power.","domesticInternationalExposure":"Engineering services are largely exported and billed in foreign currency; hosting demand is mainly domestic, helped by data-localisation needs.","capexIntensity":"Low","capexNote":"People-based services are asset-light, but data-centre and cloud operators are capital-heavy exceptions.","workingCapital":"Mainly client receivables; government contracts can pay slowly.","regulation":"Light general regulation plus the DPDP Act; hosting for government and financial clients follows MeitY cloud empanelment and RBI data-localisation norms.","competitiveAdvantages":"Deep know-how in specific client industries, long relationships, certified facilities and reliable delivery create switching costs.","drivers":[{"factor":"Exports & global demand","impact":"Global auto, aerospace and industrial R&D budgets drive engineering orders."},{"factor":"Technology change","impact":"Electric vehicles, software-defined products and AI add engineering and data work."},{"factor":"Government policy","impact":"Data localisation and digital government create local hosting demand."},{"factor":"Electricity demand","impact":"Reliable, affordable power shapes data-centre expansion."},{"factor":"Currency (INR)","impact":"Export billing gains when the rupee weakens."}],"risks":[{"risk":"Client concentration","detail":"Many firms depend on a few large clients."},{"risk":"Client-industry slowdown","detail":"Downturns in auto or aerospace cut engineering budgets."},{"risk":"Automation","detail":"AI tools reduce the need for manual processing and content work."},{"risk":"Funding needs","detail":"Data-centre expansion needs heavy capital and power."}],"cyclicality":"Mixed","cyclicalityNote":"Hosting and managed services recur steadily, while engineering projects follow client investment cycles.","metricSet":"bpo-services","relatedBasicIndustries":["b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo","b-computers-software-and-consulting","b-data-processing-services","b-consulting-services"],"aliases":["ites","it enabled services","er&d","engineering services","data centre","data center","cloud hosting","managed services","outsourcing"],"themes":["Digital","Exports","AI"]},"b-computers-hardware-and-equipments":{"simplifiedExplanation":"Companies that make, assemble or distribute computers and related equipment, such as PCs, laptops, servers, storage, printers, networking and satellite-communication gear, and industrial coding and marking printers.","productsAndServices":["Desktops, laptops and servers","Storage and networking equipment","Printers, peripherals and consumables","Industrial coding and marking printers","Satellite (VSAT) communication equipment","IT hardware distribution","Point-of-sale terminals"],"valueChainPosition":"Midstream to downstream: imports chips, parts or finished devices from global brands, assembles or distributes them, and sells to resellers, integrators, enterprises and government.","howTheyMakeMoney":"Distributors earn thin margins on high volumes plus vendor incentives and credit services. Manufacturers earn on equipment sales, consumables and service contracts.","revenueSources":["Hardware sales","Distribution margins and vendor incentives","Consumables such as ink and ribbons","Service contracts","Government and enterprise projects"],"operatingCosts":["Imported components and finished goods","Logistics and warehousing","Interest on working capital","Channel incentives and sales staff","Service engineers"],"customersAndEndMarkets":"Households and small businesses via resellers, enterprises, data centres, banks, government and schools, and factories using coding printers.","demandSupplyDrivers":"Demand follows PC refresh cycles, enterprise and government IT budgets and digitisation. Supply depends on global chip and component availability.","domesticInternationalExposure":"Heavily import-dependent for chips and components, so global component prices and the rupee matter; PLI encourages local assembly, including for export.","capexIntensity":"Low","capexNote":"Assembly and distribution need modest fixed assets; the main capital need is working capital.","workingCapital":"Heavy: large inventory, channel credit and slow government payments make working-capital control central.","regulation":"BIS compulsory registration for many electronics, the PLI scheme for IT hardware, import-authorisation rules for laptops and PCs, local-preference public procurement, and e-waste rules.","competitiveAdvantages":"Distribution reach, vendor tie-ups, disciplined credit control, service networks and local manufacturing scale protect established players.","drivers":[{"factor":"Technology change","impact":"New operating systems and AI-ready PCs drive replacements."},{"factor":"Government policy","impact":"PLI, import rules and local-preference buying favour local assembly."},{"factor":"Currency (INR)","impact":"A weaker rupee raises import costs that may not pass through quickly."},{"factor":"Raw material availability","impact":"Chip shortages limit supply and raise prices."},{"factor":"Consumer demand","impact":"Household and small-business buying follows incomes and festive seasons."}],"risks":[{"risk":"Thin margins","detail":"Small price moves or stock losses can wipe out profit."},{"risk":"Inventory obsolescence","detail":"Fast product cycles force discounting of old stock."},{"risk":"Receivable delays","detail":"Slow-paying partners or government buyers tie up cash."},{"risk":"Vendor dependence","detail":"Losing a key brand's distribution rights cuts revenue."}],"cyclicality":"Cyclical","cyclicalityNote":"Buyers can postpone computer and equipment purchases when budgets tighten.","metricSet":"it-hardware","relatedBasicIndustries":["b-consumer-electronics","b-telecom-equipment-and-accessories","b-trading-and-distributors","b-computers-software-and-consulting"],"aliases":["computer hardware","it hardware","pc","laptops","servers","printers","peripherals","it distribution","computers hardware and equipment"],"themes":["Digital","Make in India"]},"b-civil-construction":{"simplifiedExplanation":"These companies are builders for hire. They win contracts to construct roads, bridges, buildings, water pipelines, metro lines, factories and power projects, and get paid as the work progresses.","productsAndServices":["Roads and highways","Bridges, flyovers and tunnels","Railway, metro and station works","Water supply, irrigation and sewerage projects","Commercial, residential and institutional buildings","Industrial plants and power or solar EPC"],"valueChainPosition":"Downstream of cement, steel, bitumen and equipment suppliers; they deliver finished assets to government agencies, public sector units, developers and industrial owners.","howTheyMakeMoney":"They earn the difference between the contract value and the cost of materials, labour, subcontractors and equipment. Some also earn annuity or toll income on projects they build and own.","revenueSources":["EPC and item-rate contract billing","Price-escalation and variation claims","Annuity or toll income on owned projects","Operation and maintenance contracts"],"operatingCosts":["Steel, cement, bitumen and aggregates","Subcontractors and site labour","Equipment hire, fuel and depreciation","Interest on working capital and guarantees","Site overheads and mobilisation"],"customersAndEndMarkets":"Mainly central and state bodies for highways, rail, water and urban works, plus public sector units, real estate developers and industrial companies.","demandSupplyDrivers":"Demand depends on how many projects governments and companies award and fund. The field is crowded with bidders, so pricing gets tight when fewer projects are on offer.","domesticInternationalExposure":"Mostly domestic; a few larger contractors take projects abroad. Input costs follow domestic steel and cement prices and crude oil for bitumen and diesel.","capexIntensity":"Medium","capexNote":"A construction equipment fleet is needed, though much can be hired; owned toll or annuity projects add large one-off investment.","workingCapital":"Heavy: retention money, unbilled work and slow government payments tie up cash, and performance guarantees use up bank limits. Site work slows in the monsoon.","regulation":"Government procurement rules and model contracts (EPC, hybrid annuity, BOT), GST on works contracts, land and environmental clearances, and labour laws apply.","competitiveAdvantages":"An execution track record that pre-qualifies them for large tenders, a strong balance sheet for bank guarantees, and owned equipment and skilled teams.","drivers":[{"factor":"Infrastructure spending","impact":"Government capital budgets for roads, rail, water and urban projects set the size of the order pipeline."},{"factor":"Commodity prices","impact":"Steel, cement and bitumen costs hit margins on contracts without full price-escalation clauses."},{"factor":"Interest rates","impact":"Higher rates raise the cost of working capital and of funding owned annuity or toll projects."},{"factor":"Government policy","impact":"Contract models, payment timelines and dispute settlement schemes affect cash flow."},{"factor":"Real estate cycle","impact":"Building contractors depend on how fast developers launch and build projects."}],"risks":[{"risk":"Payment delays","detail":"Slow payments from state agencies stretch working capital and raise debt."},{"risk":"Execution delays","detail":"Land, clearance or design hold-ups push out revenue and raise costs."},{"risk":"Aggressive bidding","detail":"Tenders won at thin prices leave little room for cost overruns."},{"risk":"Order book quality","detail":"Stalled projects can inflate the order book without producing revenue."}],"cyclicality":"Cyclical","cyclicalityNote":"Orders and margins track public and private capex cycles, including spending pauses around elections.","metricSet":"construction-epc","relatedBasicIndustries":["b-cement-and-cement-products","b-road-assets-toll-annuity-hybrid-annuity","b-construction-vehicles","b-iron-and-steel-products","b-residential-commercial-projects"],"aliases":["construction","EPC","infra","infrastructure company","contractor","road builder","civil contractor","HAM projects","engineering procurement construction"],"themes":["Infrastructure"]},"b-aerospace-and-defense":{"simplifiedExplanation":"These companies make equipment for the armed forces and the aviation industry, such as aircraft, helicopters, radars, missiles, defence electronics, ammunition and the precision parts that go into them.","productsAndServices":["Fighter aircraft, helicopters and trainers","Radars, sonar and avionics","Missiles and ammunition systems","Defence electronics and communication systems","Aerostructures and precision components","Repair, overhaul and upgrade services"],"valueChainPosition":"Platform makers sit at the top and buy sub-systems from specialist electronics and component firms, which source alloys, chips and materials; end buyers are the armed forces and global aerospace companies.","howTheyMakeMoney":"They earn on long contracts for supply, development and upgrades, usually paid against milestones. Spares, maintenance and overhaul of delivered fleets add recurring income for decades of service life.","revenueSources":["Platform and system supply contracts","Spares, repair and overhaul","Government-funded development contracts","Export orders","Build-to-print work for global aerospace firms"],"operatingCosts":["Imported electronic parts and sub-systems","Special alloys and composite materials","Skilled engineers and staff","Research and development","Testing, certification and quality systems"],"customersAndEndMarkets":"Primarily the Ministry of Defence and the armed forces, plus other defence public sector units, paramilitary forces, space agencies, global aircraft makers and friendly foreign governments.","demandSupplyDrivers":"Demand follows defence budgets, modernisation plans and security needs. Supply is limited by technology, security clearances and qualification by the forces, so few firms can bid for major programmes.","domesticInternationalExposure":"Mostly domestic government demand, with a growing export push and work for overseas aerospace supply chains; many critical components are still imported, so the rupee matters.","capexIntensity":"Medium","capexNote":"Platform makers need costly plants, test ranges and labs, while electronics and component firms are lighter; some development is customer-funded.","workingCapital":"Often heavy: long build cycles create large inventory and work in progress. Customer advances on big orders help, while slipped milestones or delayed payments hurt cash flow.","regulation":"Ministry of Defence procurement under the Defence Acquisition Procedure, industrial licences for defence items, positive indigenisation lists and export authorisation rules govern the business; aircraft work needs airworthiness certification.","competitiveAdvantages":"Proven qualification with the armed forces, proprietary designs, long platform lifecycles with captive spares business, and security clearances form high barriers.","drivers":[{"factor":"Defence spending","impact":"Capital outlay for new weapons and platforms decides the flow of big orders."},{"factor":"Government policy","impact":"Indigenisation lists and preference for domestic suppliers move orders from imports to local makers."},{"factor":"Exports & global demand","impact":"Export orders and global aerospace outsourcing add a second source of growth."},{"factor":"Technology change","impact":"The shift to drones, electronics and software-driven systems rewards firms that keep investing in R&D."},{"factor":"Currency (INR)","impact":"Imported components and export receipts make margins sensitive to the rupee."}],"risks":[{"risk":"Order timing","detail":"Large orders can slip by quarters or longer, making revenue lumpy."},{"risk":"Customer concentration","detail":"Dependence on one government buyer limits pricing power."},{"risk":"Development risk","detail":"Delays or failed trials can hold up whole programmes."},{"risk":"Geopolitics","detail":"Sanctions or supply disruptions can block key imported parts."}],"cyclicality":"Mixed","cyclicalityNote":"Spending follows budgets and security needs rather than the business cycle, but order flow is lumpy.","metricSet":"defence","relatedBasicIndustries":["b-ship-building-and-allied-services","b-explosives","b-other-electrical-equipment","b-castings-and-forgings","b-computers-hardware-and-equipments"],"aliases":["defence","defense","aerospace","defence PSU","military","missiles","drones","avionics","defence electronics","ammunition"],"themes":["Defence","Exports"]},"b-tractors":{"simplifiedExplanation":"These companies make tractors and related farm machines that farmers use for ploughing, sowing, harvesting and hauling.","productsAndServices":["Tractors across horsepower ranges","Power tillers","Implements such as rotavators and harvesters","Spare parts and lubricants","Farm engines"],"valueChainPosition":"Midstream assemblers that buy engines, castings, gears, tyres and hydraulics from component makers and sell through dealers to farmers and contractors.","howTheyMakeMoney":"They earn a margin on each tractor and implement sold through dealers, plus steadier income from spare parts and service. Exports to other farming markets add volume.","revenueSources":["Domestic tractor sales","Tractor exports","Spare parts and service","Farm implements and machinery"],"operatingCosts":["Steel, castings and forgings","Engines, tyres and hydraulic parts","Employee costs","Dealer incentives and promotions","Warranty and logistics"],"customersAndEndMarkets":"Farmers, agricultural contractors and rural haulage users across India, plus buyers in overseas farming markets.","demandSupplyDrivers":"Sales rise with good monsoons, crop prices, rural incomes and easy farm credit, and fall sharply in droughts. Tractors also haul goods, so part of demand follows rural construction.","domesticInternationalExposure":"Mainly domestic and rural; exports give some diversification. Input costs follow global steel and metal prices.","capexIntensity":"Medium","capexNote":"Assembly plants and engine lines need steady but moderate investment.","workingCapital":"Seasonal: makers and dealers build stock before the harvest and festive months, and most farmer purchases are loan-financed.","regulation":"Tractor emission norms (TREM) and safety standards, farm-credit rules, state subsidies on farm machinery and GST rates on tractors and parts affect cost and pricing.","competitiveAdvantages":"A wide rural dealer and service network, brand trust among farmers, finance tie-ups and good resale value protect leaders.","drivers":[{"factor":"Monsoon & agriculture","impact":"Rainfall, reservoir levels and crop output drive farmer sentiment and purchases."},{"factor":"Rural demand","impact":"Farm incomes, MSP and rural wages decide affordability."},{"factor":"Credit growth","impact":"Most tractors are bought on loans, so rural lending and interest rates matter."},{"factor":"Government policy","impact":"Farm schemes, machinery subsidies and emission rules shift demand and costs."},{"factor":"Commodity prices","impact":"Steel and metal prices change production costs."}],"risks":[{"risk":"Weak monsoon","detail":"A poor rainy season can sharply cut sales."},{"risk":"Emission-norm cost","detail":"Stricter norms raise tractor prices and can slow demand."},{"risk":"Price competition","detail":"Discounting in a mature market squeezes margins."},{"risk":"Rural stress","detail":"Low crop prices or farm loan stress reduce buying power."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes swing with the monsoon and the farm income cycle.","metricSet":"auto-oem","relatedBasicIndustries":["b-commercial-vehicles","b-compressors-pumps-and-diesel-engines","b-dealers-commercial-vehicles-tractors-construction-vehicles","b-fertilizers","b-auto-components-and-equipments"],"aliases":["tractor","tractors","farm equipment","farm machinery","agri equipment","agricultural machinery","power tiller","farm mechanisation"],"themes":["Rural demand","Exports"]},"b-commercial-vehicles":{"simplifiedExplanation":"These companies make trucks, buses, vans and small goods carriers that businesses use to move goods and people.","productsAndServices":["Heavy and medium trucks and tippers","Light and small commercial vehicles","Buses, including electric buses","Pickups and three-wheel cargo vehicles","Defence and special-purpose vehicles","Spare parts and service"],"valueChainPosition":"Midstream: they assemble engines, axles, chassis and electronics from component makers and sell through dealers to fleet operators, transporters and state transport undertakings.","howTheyMakeMoney":"They earn a margin on each vehicle, plus aftermarket parts, service and exports. Discounts swing with the cycle, so margins rise sharply in good years and shrink in bad ones.","revenueSources":["Truck sales","Bus sales, including government tenders","Small commercial vehicle sales","Spare parts and service","Exports"],"operatingCosts":["Steel and aluminium","Engines, axles, tyres and electronics","Employee costs","Dealer discounts and marketing","Warranty and R&D"],"customersAndEndMarkets":"Fleet owners, transporters, logistics and e-commerce firms, construction and mining operators, schools and state transport undertakings.","demandSupplyDrivers":"Demand follows freight volumes, freight rates, infrastructure work and replacement of old vehicles. Emission and scrappage rules can trigger pre-buying followed by slumps.","domesticInternationalExposure":"Mostly domestic, with exports to nearby emerging markets; costs track global steel and commodity prices.","capexIntensity":"High","capexNote":"Plants, new platforms and new fuel technologies such as electric, CNG and LNG need large investment.","workingCapital":"Moderate: plant and dealer stocks rise in weak periods, and government bus orders can carry longer receivables.","regulation":"Bharat Stage emission norms, axle-load and safety rules, the vehicle scrappage policy and central incentives for electric buses shape costs and demand.","competitiveAdvantages":"Scale, a nationwide dealer and service network, reliable products with good resale value and a full range across load classes.","drivers":[{"factor":"Infrastructure spending","impact":"Road building, mining and construction raise demand for tippers and haulage trucks."},{"factor":"Credit growth","impact":"Most vehicles are financed, so loan availability and rates drive purchases."},{"factor":"Crude oil prices","impact":"Diesel costs affect fleet operator profits and their appetite for new trucks."},{"factor":"Regulation","impact":"Emission and safety upgrades raise vehicle costs and cause pre-buying cycles."},{"factor":"Technology change","impact":"The move to electric, CNG and LNG vehicles changes product mix and investment needs."}],"risks":[{"risk":"Sharp downcycles","detail":"Volumes can fall steeply when freight demand or financing dries up."},{"risk":"Cost inflation","detail":"Steel and component prices compress margins if not passed on."},{"risk":"Discounting","detail":"Price wars in weak markets erode profits."},{"risk":"Fuel transition","detail":"Investments in new fuel platforms may take long to pay off."}],"cyclicality":"Cyclical","cyclicalityNote":"One of the most cyclical vehicle segments, swinging with the economy and the freight cycle.","metricSet":"auto-oem","relatedBasicIndustries":["b-auto-components-and-equipments","b-tyres-and-rubber-products","b-road-transport","b-dealers-commercial-vehicles-tractors-construction-vehicles","b-logistics-solution-provider"],"aliases":["CV","trucks","buses","commercial vehicle","LCV","MHCV","heavy trucks","electric bus","tippers"],"themes":["Infrastructure","EV"]},"b-construction-vehicles":{"simplifiedExplanation":"These companies make heavy machines used on building sites, roads, mines and ports, such as cranes, excavators, loaders and road-building equipment.","productsAndServices":["Mobile and tower cranes","Excavators and backhoe loaders","Concrete mixers and batching equipment","Rollers, pavers and other road machines","Mining equipment and dumpers","Forklifts and material handling equipment"],"valueChainPosition":"Midstream: they buy engines, hydraulics, steel and electronics and sell machines through dealers or directly to contractors, mine operators, rental firms and government bodies.","howTheyMakeMoney":"They earn on machine sales and on higher-margin spare parts and service over each machine's working life; some also supply defence and rail equipment against orders.","revenueSources":["Machine sales","Spare parts and service","Defence or rail equipment orders","Exports","Rental and finance tie-ups"],"operatingCosts":["Steel and fabricated parts","Engines and hydraulic systems","Employee costs","Dealer and marketing costs","R&D and certification"],"customersAndEndMarkets":"Construction contractors, equipment rental companies, mining firms, ports, industrial plants and government agencies.","demandSupplyDrivers":"Demand moves with road, metro, housing and mining activity and with contractors' access to finance. Global brands compete with domestic makers, so pricing depends on capacity and imports.","domesticInternationalExposure":"Mainly domestic, with some exports; key parts such as engines and hydraulics are often imported, so the rupee and global supply chains matter.","capexIntensity":"Medium","capexNote":"Assembly plants are lighter than process industries, but product development and testing need steady spending.","workingCapital":"Machine and spares inventory is large, and sales drop in the monsoon months when sites stop work.","regulation":"Construction equipment vehicle (CEV) emission norms, road and safety rules, and tender rules for defence and public buyers apply.","competitiveAdvantages":"Brand reliability, product range, dealer and service coverage, and fast parts supply that keeps machines running.","drivers":[{"factor":"Infrastructure spending","impact":"Road, metro, port and urban projects are the core demand source."},{"factor":"Credit growth","impact":"Most machines are bought on equipment loans, so financing access matters."},{"factor":"Commodity prices","impact":"Steel and engine costs drive pricing and margins."},{"factor":"Regulation","impact":"Emission-norm upgrades raise machine prices and can bring pre-buying."},{"factor":"Real estate cycle","impact":"Housing and commercial construction lift demand for cranes and concrete equipment."}],"risks":[{"risk":"Project slowdown","detail":"A pause in awarding or executing projects cuts orders quickly."},{"risk":"Import competition","detail":"Global brands and imported machines pressure prices."},{"risk":"Seasonality","detail":"Monsoon months bring weak sales."},{"risk":"Component dependence","detail":"Imported engines and hydraulics expose makers to shortages."}],"cyclicality":"Cyclical","cyclicalityNote":"Sales track the infrastructure and mining investment cycle.","metricSet":"auto-oem","relatedBasicIndustries":["b-civil-construction","b-commercial-vehicles","b-industrial-minerals","b-compressors-pumps-and-diesel-engines","b-dealers-commercial-vehicles-tractors-construction-vehicles"],"aliases":["construction equipment","CE","earthmoving equipment","cranes","excavators","backhoe loader","mining equipment","heavy machinery"],"themes":["Infrastructure"]},"b-dealers-commercial-vehicles-tractors-construction-vehicles":{"simplifiedExplanation":"These are dealers, not manufacturers. They run showrooms and workshops that sell trucks, buses, tractors or construction machines made by others, and service them afterwards.","productsAndServices":["New vehicle and machine sales","Spare parts sales","Workshop service and repairs","Loan and insurance arrangement","Used vehicle exchange","Annual maintenance contracts"],"valueChainPosition":"Downstream: they buy finished vehicles and parts from manufacturers and sell them to fleet owners, farmers and contractors in their territory.","howTheyMakeMoney":"They earn a dealer margin on each sale plus manufacturer incentives, and steadier profit from spares, service and finance or insurance commissions.","revenueSources":["Vehicle and machine sales","Spare parts","Service and repairs","Finance and insurance commissions","Manufacturer volume incentives"],"operatingCosts":["Cost of vehicles and parts bought","Showroom and workshop rent","Sales staff and mechanics","Interest on inventory funding","Discounts and local marketing"],"customersAndEndMarkets":"Transporters, farmers, contractors, mining and rental firms, and institutions within the dealer's region.","demandSupplyDrivers":"Volumes follow the cycles of the vehicles they sell: the farm economy for tractors, and freight and infrastructure for trucks and machines. Margins are largely set by the manufacturer.","domesticInternationalExposure":"Entirely domestic; vehicle prices still reflect global commodity costs passed on by manufacturers.","capexIntensity":"Low","capexNote":"Investment is mainly in showrooms, workshops and tools, often on leased premises.","workingCapital":"Inventory-heavy: dealers fund stock through bank or manufacturer-linked trade finance, and unsold stock in slow periods raises interest costs.","regulation":"Light, general business regulation, plus GST, vehicle registration rules and the terms of the manufacturer's dealer agreement.","competitiveAdvantages":"Exclusive territory rights for a strong brand, a large local base of vehicles needing service, and long customer relationships.","drivers":[{"factor":"Credit growth","impact":"Customer loans and dealer inventory funding both depend on lenders."},{"factor":"Rural demand","impact":"Tractor dealers rely on farm incomes in their area."},{"factor":"Monsoon & agriculture","impact":"Good rains lift tractor and rural vehicle sales."},{"factor":"Infrastructure spending","impact":"Local road and mining projects drive truck and machine sales."}],"risks":[{"risk":"Manufacturer dependence","detail":"Margins, territory and product line depend on one brand's terms."},{"risk":"Inventory build-up","detail":"Stock pushed by manufacturers in slow periods raises costs."},{"risk":"Thin margins","detail":"Low dealer margins leave little room for error."}],"cyclicality":"Cyclical","cyclicalityNote":"Sales mirror the cycle of the vehicles they sell, cushioned by service income.","metricSet":"auto-dealer","relatedBasicIndustries":["b-commercial-vehicles","b-tractors","b-construction-vehicles","b-auto-dealer"],"aliases":["truck dealer","tractor dealer","CV dealer","dealership","equipment dealer","construction equipment dealer","commercial vehicle dealer"],"themes":[]},"b-heavy-electrical-equipment":{"simplifiedExplanation":"These companies make large equipment for power plants, the electricity grid and heavy industry, such as transformers, turbines, generators, switchgear and transmission towers.","productsAndServices":["Power and distribution transformers","Switchgear and substations","Turbines and generators","Transmission towers and structures","Large motors and industrial gearboxes","Boilers and power plant equipment"],"valueChainPosition":"Midstream: they turn steel, copper, aluminium, electrical steel and insulation into engineered equipment for utilities, transmission firms, renewable developers and industrial plants.","howTheyMakeMoney":"They win orders through tenders or negotiation, build to specification and get paid in milestones; service, spares and refurbishment add recurring income.","revenueSources":["Equipment supply orders","Turnkey substation and plant projects","Spares and services","Exports"],"operatingCosts":["Copper, CRGO electrical steel and steel","Aluminium and insulating materials","Skilled labour and engineering","Testing and transport of oversized equipment","Warranty and delay penalties"],"customersAndEndMarkets":"Central and state power utilities, transmission companies, renewable and thermal power developers, railways, metros, data centres, refineries and heavy industry.","demandSupplyDrivers":"Demand follows generation and grid investment, renewable additions and industrial capex. Supply is limited by test facilities, approvals and specialised capacity, which can stretch delivery times.","domesticInternationalExposure":"Mostly domestic, with export demand for grid equipment; copper and electrical steel follow global prices and some materials are imported.","capexIntensity":"High","capexNote":"Large shops, heavy cranes, test bays and high-voltage labs need heavy investment.","workingCapital":"Long build cycles tie up inventory; customer advances help, but retention money and slow utility payments can stretch receivables.","regulation":"Equipment must meet BIS and Central Electricity Authority standards and utility type-tests; Ministry of Power plans and CERC tariff rules shape utility spending.","competitiveAdvantages":"Type-tested designs, approvals with utilities, a long execution record and specialised high-voltage capacity create high entry barriers.","drivers":[{"factor":"Electricity demand","impact":"Rising power use pushes utilities to add generation and grid capacity."},{"factor":"Infrastructure spending","impact":"Transmission and distribution programmes drive order inflow."},{"factor":"Commodity prices","impact":"Copper and electrical steel costs move margins, especially on fixed-price orders."},{"factor":"Exports & global demand","impact":"Grid upgrades abroad create export opportunities."},{"factor":"Government policy","impact":"Renewable targets and grid plans set the tender pipeline."}],"risks":[{"risk":"Raw material spikes","detail":"Copper and CRGO steel costs can hurt fixed-price contracts."},{"risk":"Delivery penalties","detail":"Late delivery or failed tests can trigger penalties."},{"risk":"Utility payments","detail":"State utilities can pay late."},{"risk":"New capacity","detail":"Expansions by many players can pressure prices later in the cycle."}],"cyclicality":"Cyclical","cyclicalityNote":"Orders follow the power and industrial capex cycle, though order books give visibility.","metricSet":"capital-goods","relatedBasicIndustries":["b-power-transmission","b-other-electrical-equipment","b-cables-electricals","b-power-generation","b-aluminium-copper-and-zinc-products"],"aliases":["transformers","switchgear","power equipment","turbines","T&D equipment","transmission towers","grid equipment","electrical engineering"],"themes":["Infrastructure","Renewable energy","Exports"]},"b-other-electrical-equipment":{"simplifiedExplanation":"These companies make smaller electrical products and parts, such as solar panels, motors, electrical contacts, meters, inverters and control panels, and some also install solar systems.","productsAndServices":["Solar modules and cells","Electric motors and drives","Control panels and automation gear","Electrical contacts and components","Meters, inverters and power electronics","Solar EPC and rooftop systems"],"valueChainPosition":"Midstream: they buy metals, solar cells, glass, electronics and plastics and supply finished components or systems to utilities, renewable developers, equipment makers, factories and distributors.","howTheyMakeMoney":"They earn a manufacturing margin on each product, sold directly to industry and projects or through distributors; some add EPC and installation services.","revenueSources":["Product sales to OEMs and industry","Solar module and system sales","Project and EPC services","Exports","Distributor channel sales"],"operatingCosts":["Copper, silver and other metals","Imported cells, wafers or chips","Glass, aluminium frames and plastics","Employee costs","Freight and warranty"],"customersAndEndMarkets":"Renewable developers, utilities, rooftop and home users, machinery and appliance makers, railways and factories.","demandSupplyDrivers":"Demand follows renewable additions, industrial output and electrification. In solar, fast capacity build-up by many makers and global module prices can swing pricing quickly.","domesticInternationalExposure":"Many products rely on imported inputs, especially solar cells and electronics; exports and global module prices strongly affect solar makers.","capexIntensity":"Medium","capexNote":"Solar cell and module lines need large and frequent upgrades, while component makers spend moderately.","workingCapital":"Imported input stocks and long project receivables can be heavy; advances from developers help when supply is tight.","regulation":"BIS standards, MNRE's ALMM list for solar modules, customs duties on imported cells and modules, PLI schemes for solar manufacturing and rooftop solar subsidy schemes shape the business.","competitiveAdvantages":"Scale and backward integration in solar, keeping up with cell technology, approved-vendor status with big buyers and a known brand in distribution.","drivers":[{"factor":"Government policy","impact":"Duties, ALMM and PLI support local solar manufacturing against imports."},{"factor":"Electricity demand","impact":"Electrification lifts sales of motors, meters and controls."},{"factor":"Imports & dumping","impact":"Cheap Chinese modules and parts set global price levels."},{"factor":"Technology change","impact":"Rapid shifts in solar cell technology can make older lines uncompetitive."},{"factor":"Exports & global demand","impact":"US and European demand and trade rules affect export orders."}],"risks":[{"risk":"Price crashes","detail":"Global oversupply can cut module prices sharply."},{"risk":"Technology obsolescence","detail":"New cell types can strand older equipment."},{"risk":"Trade policy","detail":"Changes in Indian duties or foreign tariffs can shift economics fast."},{"risk":"Input dependence","detail":"Reliance on imported cells or chips adds supply and currency risk."}],"cyclicality":"Cyclical","cyclicalityNote":"Solar and industrial electrical demand moves with investment cycles and policy changes.","metricSet":"capital-goods","relatedBasicIndustries":["b-heavy-electrical-equipment","b-power-generation","b-cables-electricals","b-glass-industrial","b-aluminium-copper-and-zinc-products"],"aliases":["solar panels","solar modules","solar manufacturing","electric motors","electrical components","inverters","control panels","electrical equipment"],"themes":["Renewable energy","China+1","Exports"]},"b-railway-wagons":{"simplifiedExplanation":"These companies build railway freight wagons and, in some cases, metro and passenger coaches and rail parts like bogies, couplers, wheels and castings.","productsAndServices":["Freight wagons of various types","Metro and passenger coaches","Bogies, couplers and draft gear","Wheels, axles and rail castings","Rail electrical and propulsion parts"],"valueChainPosition":"Midstream: they turn steel, castings and bought-out components into rolling stock for Indian Railways, metro corporations and private freight wagon owners.","howTheyMakeMoney":"They win large tenders and execute them over many months, earning a margin per wagon or coach; spares, components and exports add to revenue.","revenueSources":["Wagon orders from Indian Railways","Wagons for private and industrial owners","Metro and passenger coach orders","Rail components and castings","Exports"],"operatingCosts":["Steel plates and sections","Castings, wheels and axles","Brake and bogie components","Fabrication labour","Testing and certification"],"customersAndEndMarkets":"Indian Railways is the main buyer, followed by metro corporations, private wagon owners such as cement, steel and logistics firms, and overseas rail operators.","demandSupplyDrivers":"Demand depends on railway capex plans, freight loading targets, dedicated freight corridors and private wagon schemes. Only a few approved makers can supply, but tenders are price competitive.","domesticInternationalExposure":"Mostly domestic; some firms export wagons or parts. Steel prices and the supply of wheels and axles, some of it imported, affect costs.","capexIntensity":"Medium","capexNote":"Fabrication shops and foundries need investment, but expansions are modest compared with heavy process industries.","workingCapital":"Steel and component stocks build up during long orders; Railway payments are generally regular, but late component supply can hold up deliveries and billing.","regulation":"Designs need RDSO approval, and supply follows Indian Railways tender rules, often with price-variation clauses linked to input costs.","competitiveAdvantages":"RDSO approvals, a proven delivery record, large fabrication capacity and in-house castings for critical parts set leaders apart.","drivers":[{"factor":"Infrastructure spending","impact":"Railway budgets for freight capacity and new lines drive wagon tenders."},{"factor":"Commodity prices","impact":"Steel price changes affect margins between price-variation resets."},{"factor":"Raw material availability","impact":"Shortages of wheels and axles can slow deliveries."},{"factor":"Capacity utilisation","impact":"Full order books and steady component supply raise plant output and margins."},{"factor":"Exports & global demand","impact":"Export orders for wagons and parts add diversification."}],"risks":[{"risk":"Single-buyer dependence","detail":"Reliance on Indian Railways tenders makes revenue lumpy."},{"risk":"Component shortages","detail":"Delays in wheelsets or castings hold up deliveries."},{"risk":"Price competition","detail":"Aggressive tender bidding can thin margins."},{"risk":"Policy shifts","detail":"Changes in railway priorities can slow wagon ordering."}],"cyclicality":"Mixed","cyclicalityNote":"Driven more by government rail spending than by the economic cycle, but tenders come in waves.","metricSet":"capital-goods","relatedBasicIndustries":["b-railways","b-castings-and-forgings","b-iron-and-steel-products","b-logistics-solution-provider"],"aliases":["wagons","rolling stock","railway stocks","rail coaches","metro coaches","freight wagons","railway equipment","rail"],"themes":["Infrastructure","Railways"]},"b-ship-building-and-allied-services":{"simplifiedExplanation":"These companies build and repair ships, from naval warships and submarines to commercial vessels, ferries, tugs and offshore support ships.","productsAndServices":["Naval warships and submarines","Commercial ships, tugs and barges","Ferries and offshore vessels","Ship repair and refits","Marine engineering and steel structures"],"valueChainPosition":"Downstream integrators: they buy steel plates, engines, propulsion, weapons and electronics from suppliers and deliver finished vessels to the navy, coast guard, shipping lines and port operators.","howTheyMakeMoney":"They earn on long shipbuilding contracts paid in stages, plus ship repair and refit work that brings quicker, steadier income.","revenueSources":["Naval shipbuilding contracts","Commercial and export vessel orders","Ship repair and refits","Offshore and engineering projects"],"operatingCosts":["Steel plates and sections","Imported engines, propulsion and systems","Skilled labour and subcontractors","Dry dock and yard upkeep","Design and engineering"],"customersAndEndMarkets":"The Indian Navy and Coast Guard, government bodies, domestic and foreign shipping lines, port and inland waterway operators, and offshore companies.","demandSupplyDrivers":"Naval orders follow defence modernisation plans, while commercial orders follow global shipping cycles and policies to build ships in India. Few yards have the dock size and approvals for large vessels.","domesticInternationalExposure":"Naval work is domestic, while commercial building and repair compete with yards abroad; many key systems are imported, so the rupee matters.","capexIntensity":"High","capexNote":"Docks, slipways and yard equipment are costly and slow to expand.","workingCapital":"Long build cycles create large work in progress, partly funded by milestone advances; missed milestones can strain cash.","regulation":"Naval work follows Ministry of Defence procurement rules; commercial vessels must meet Directorate General of Shipping and classification society norms, and shipbuilding financial assistance policies affect pricing.","competitiveAdvantages":"Large docks, naval security clearances, design experience and a skilled workforce create high barriers.","drivers":[{"factor":"Defence spending","impact":"Naval budgets and fleet plans decide warship and submarine orders."},{"factor":"Government policy","impact":"Support schemes and preference for Indian-built ships boost commercial orders."},{"factor":"Exports & global demand","impact":"Global fleet renewal creates export and repair work."},{"factor":"Commodity prices","impact":"Steel and imported equipment costs affect contract margins."},{"factor":"Currency (INR)","impact":"Imported systems make costs sensitive to the rupee."}],"risks":[{"risk":"Execution delays","detail":"Complex vessels can run late and raise costs."},{"risk":"Lumpy orders","detail":"A few large contracts make revenue uneven."},{"risk":"Fixed-price contracts","detail":"Cost overruns may not be recovered."},{"risk":"Global competition","detail":"Yards abroad are often cheaper and faster for commercial ships."}],"cyclicality":"Mixed","cyclicalityNote":"Naval orders are budget-driven and steadier, while commercial shipbuilding follows the global shipping cycle.","metricSet":"defence","relatedBasicIndustries":["b-aerospace-and-defense","b-shipping","b-port-and-port-services","b-offshore-support-solution-drilling","b-iron-and-steel-products"],"aliases":["shipyard","shipbuilding","warships","submarines","ship repair","naval","defence shipyard","marine engineering"],"themes":["Defence","Exports"]},"b-industrial-products":{"simplifiedExplanation":"These companies make the machines and equipment that other factories use to produce goods, such as textile machinery, plastic processing machines, foundry and mining equipment, machine tools and process plant equipment.","productsAndServices":["Textile machinery","Plastic extrusion and processing machines","Foundry and moulding equipment","Machine tools","Mining and material handling equipment","Process equipment such as heat exchangers, filters and dryers"],"valueChainPosition":"Upstream for other manufacturers: they buy steel, castings, motors and electronics and supply finished machinery to textile, plastics, auto, mining, chemical and food factories.","howTheyMakeMoney":"They earn a margin on each machine or plant line, often built to order, plus steadier income from spares, upgrades and servicing of the machines already installed.","revenueSources":["Machine and equipment sales","Turnkey plant supply","Spares and service","Exports","Retrofits and upgrades"],"operatingCosts":["Steel, castings and fabricated parts","Motors, drives and electronics","Engineers and skilled staff","Imported parts and technology fees","Installation and warranty"],"customersAndEndMarkets":"Manufacturers in textiles, plastics, packaging, auto, steel, mining, cement, chemicals, food and pharma, in India and abroad.","demandSupplyDrivers":"Demand rises when user industries add capacity or modernise, and falls when their margins are weak. Buyers can choose imported machines, so technology and price both matter.","domesticInternationalExposure":"Mainly domestic with some exports; competition comes from European, Japanese and Chinese machine makers, and some parts are imported.","capexIntensity":"Medium","capexNote":"Machine shops and assembly halls need moderate investment, plus steady spending on design and R&D.","workingCapital":"Built-to-order machines create work in progress; customer advances help, but receivables lengthen when user industries are under stress.","regulation":"Light, general business regulation; machinery safety standards and import duties on competing machines can matter.","competitiveAdvantages":"Engineering know-how, technology tie-ups, a large installed base that needs spares, and a strong after-sales service network.","drivers":[{"factor":"Capacity utilisation","impact":"When user industries run near full capacity, they order new machines."},{"factor":"Exports & global demand","impact":"Global textile, plastics and mining investment drives export orders."},{"factor":"Technology change","impact":"Automation and energy-efficient designs decide competitiveness."},{"factor":"Imports & dumping","impact":"Cheaper imported machinery limits pricing power."},{"factor":"Interest rates","impact":"Factory buyers delay machine purchases when borrowing is costly."}],"risks":[{"risk":"User-industry slowdown","detail":"A downturn in textiles or other client industries cuts orders sharply."},{"risk":"Import competition","detail":"Foreign machines with better technology or lower prices win orders."},{"risk":"Order concentration","detail":"A few large orders can dominate a year's revenue."},{"risk":"Commissioning delays","detail":"Late installation can hold back final payments."}],"cyclicality":"Cyclical","cyclicalityNote":"Orders follow the investment cycle of the factories they serve.","metricSet":"capital-goods","relatedBasicIndustries":["b-compressors-pumps-and-diesel-engines","b-castings-and-forgings","b-other-industrial-products","b-other-textile-products","b-heavy-electrical-equipment"],"aliases":["industrial machinery","capital goods","machine tools","textile machinery","engineering company","industrial equipment","plant machinery","manufacturing equipment"],"themes":["Exports"]},"b-cables-electricals":{"simplifiedExplanation":"These companies make electrical wires and cables that carry power and signals in homes, buildings, factories, power grids and telecom networks.","productsAndServices":["Building and house wires","Low, medium and high voltage power cables","Extra-high voltage cables","Control, instrumentation and solar cables","Telecom and optical fibre cables","Allied products such as fans and switches"],"valueChainPosition":"Midstream converters: they buy copper, aluminium and PVC or XLPE compounds and sell cables to distributors, electricians, EPC contractors, utilities and industry.","howTheyMakeMoney":"They earn a conversion margin over metal and polymer costs. Retail wires sold through dealers earn better margins, while project cables are sold through tenders and bulk orders.","revenueSources":["Retail wire sales through distributors","Power cables for utilities and EPC firms","Specialty and EHV cables","Exports","Allied electrical products"],"operatingCosts":["Copper and aluminium","PVC, XLPE and other polymers","Freight and packing drums","Power and employee costs","Dealer schemes and branding"],"customersAndEndMarkets":"Housing and buildings through electricians and dealers, power utilities, renewable and data centre projects, railways, oil and gas, industrial plants and overseas buyers.","demandSupplyDrivers":"Demand comes from housing, infrastructure, power grids and industrial capex. Organised brands compete with many smaller regional makers, especially in house wires.","domesticInternationalExposure":"Copper and aluminium prices are set globally, so the rupee matters; several makers export cables to grid and infrastructure projects abroad.","capexIntensity":"Medium","capexNote":"Most expansions are moderate, but EHV cable lines and test labs need bigger investment.","workingCapital":"Significant: metal stocks and dealer credit in retail, longer receivables in projects; sharp metal moves cause inventory gains or losses.","regulation":"BIS standards and certification for wires and cables, utility approvals for power cables, and GST shape the market.","competitiveAdvantages":"Brand trust with electricians, wide distribution, approvals for high-voltage cables and scale in buying metal.","drivers":[{"factor":"Real estate cycle","impact":"Housing and commercial construction drive building-wire demand."},{"factor":"Infrastructure spending","impact":"Power, rail, metro and data centre projects lift cable orders."},{"factor":"Commodity prices","impact":"Copper and aluminium swings change selling prices and inventory values."},{"factor":"Electricity demand","impact":"Grid expansion and renewable connections need more power cables."},{"factor":"Exports & global demand","impact":"Grid and data centre build-out abroad supports exports."}],"risks":[{"risk":"Metal price swings","detail":"Sudden copper falls can cause inventory losses."},{"risk":"New entrants","detail":"Fresh capacity and new players can pressure prices."},{"risk":"Project receivables","detail":"EPC and utility clients may pay late."},{"risk":"Quality and fire safety","detail":"Product failures can damage brand trust."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes track construction and infrastructure cycles, while retail wires are somewhat steadier.","metricSet":"industrial-products","relatedBasicIndustries":["b-copper","b-aluminium","b-heavy-electrical-equipment","b-aluminium-copper-and-zinc-products","b-residential-commercial-projects"],"aliases":["cables","wires","wires and cables","power cables","electrical cables","house wire","EHV cable","optical fibre cable"],"themes":["Infrastructure","Renewable energy","Exports"]},"b-castings-and-forgings":{"simplifiedExplanation":"These companies shape metal into strong parts. Casting pours molten metal into moulds; forging presses or hammers hot metal into shape. The parts go into vehicles, machines, railways, mines and power plants.","productsAndServices":["Engine and transmission parts","Crankshafts, axles and gears","Grinding media and mill liners","Valve, pump and machinery castings","Precision investment castings","Rail and wind turbine components"],"valueChainPosition":"Midstream: they buy steel, pig iron, scrap, alloys or aluminium and supply rough or machined parts to vehicle makers, machinery builders, mining, cement and energy companies.","howTheyMakeMoney":"They earn a conversion and machining margin per tonne or per part; changes in metal cost are usually passed on to customers with a lag through price formulas.","revenueSources":["Parts for vehicle makers","Industrial and energy components","Wear parts for mining and cement","Exports","Machined and assembled parts"],"operatingCosts":["Steel, scrap, pig iron and alloys","Power and fuel","Labour and machining","Dies, moulds and tooling","Freight and packaging"],"customersAndEndMarkets":"Truck, tractor and car makers, industrial and oilfield equipment makers, railways, mines and cement plants, and global buyers.","demandSupplyDrivers":"Demand follows vehicle, farm, industrial and mining activity in India and abroad. Global buyers spreading sourcing beyond China open export work for qualified suppliers.","domesticInternationalExposure":"Many are export-heavy, so global truck, energy and mining cycles, foreign tariffs and the rupee matter; metal inputs follow global prices.","capexIntensity":"High","capexNote":"Presses, furnaces, moulding lines and machining centres are costly and need regular upgrades.","workingCapital":"Raw material and finished stock plus long export receivables tie up cash; lagged metal pass-through moves margins quarter to quarter.","regulation":"State Pollution Control Board rules for foundries and furnaces, power tariffs, and export incentive and trade policies matter.","competitiveAdvantages":"Long customer qualification, metallurgy know-how, in-house machining and established export relationships protect good firms.","drivers":[{"factor":"Exports & global demand","impact":"Overseas truck, industrial and energy demand drives export volumes."},{"factor":"Commodity prices","impact":"Steel and alloy prices shift selling prices and margins during the pass-through lag."},{"factor":"Capacity utilisation","impact":"Fixed costs are high, so fuller plants earn much better margins."},{"factor":"China+1 sourcing","impact":"Global buyers adding non-Chinese suppliers favour capable Indian forgers and foundries."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts export realisations."}],"risks":[{"risk":"Vehicle cycle","detail":"A downturn in truck or tractor volumes hits demand."},{"risk":"Customer concentration","detail":"A few large clients often dominate sales."},{"risk":"Power costs","detail":"Energy-intensive processes suffer when tariffs rise."},{"risk":"Trade tariffs","detail":"Foreign import duties can hurt export competitiveness."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes rise and fall with global vehicle, industrial and mining cycles.","metricSet":"industrial-products","relatedBasicIndustries":["b-auto-components-and-equipments","b-iron-and-steel-products","b-commercial-vehicles","b-railway-wagons","b-pig-iron"],"aliases":["forgings","castings","foundry","forging","precision castings","investment casting","crankshafts","metal components"],"themes":["Exports","China+1"]},"b-packaging":{"simplifiedExplanation":"These companies make the materials that wrap and protect products, such as plastic films, laminates, printed cartons, glass bottles, tubes, caps and containers.","productsAndServices":["Flexible packaging films and laminates","BOPP and BOPET films","Printed cartons and paperboard boxes","Glass bottles and containers","Laminated tubes, caps and closures","Corrugated boxes and rigid plastic packs"],"valueChainPosition":"Midstream: they buy polymers, paperboard, glass raw materials, inks and adhesives and supply finished packaging to FMCG, food, beverage, pharma and liquor companies.","howTheyMakeMoney":"They earn a conversion margin over raw material costs, with more for printed, specialty and value-added packs; commodity film makers earn spreads that swing with the cycle.","revenueSources":["Packaging sold to brand owners","Films sold to converters","Exports of films and packaging","Specialty and recyclable packaging"],"operatingCosts":["Polymer resins such as polypropylene and polyester","Paperboard and pulp","Soda ash, sand and fuel for glass","Inks, adhesives and chemicals","Power and freight"],"customersAndEndMarkets":"FMCG, food and beverage, pharma, liquor, personal care, e-commerce and industrial companies in India and overseas.","demandSupplyDrivers":"Demand follows packaged goods consumption and is fairly steady. Film segments go through boom-and-bust cycles when many producers add capacity at the same time.","domesticInternationalExposure":"Raw materials track crude-linked polymer and global pulp prices; several companies export films or packaging and face global oversupply.","capexIntensity":"High","capexNote":"Film lines, glass furnaces and printing presses are expensive and need periodic rebuilding.","workingCapital":"Moderate: raw material stocks and credit to large brand owners; resin price swings affect margins until prices are reset.","regulation":"Plastic Waste Management Rules with Extended Producer Responsibility, bans on some single-use plastics, and FSSAI and drug rules for food- and medicine-contact packaging apply.","competitiveAdvantages":"Long ties with brand owners, printing and design skill, scale and a wide material range; commodity film makers rely on low cost.","drivers":[{"factor":"Consumer demand","impact":"Packaged food, beverage and personal care volumes drive orders."},{"factor":"Crude oil prices","impact":"Polymer costs follow crude and petrochemical prices."},{"factor":"Capacity utilisation","impact":"Industry-wide film capacity additions can crush spreads."},{"factor":"Regulation","impact":"Plastic rules push a shift to recyclable and paper-based packs."},{"factor":"Exports & global demand","impact":"Global film prices and export demand affect realisations."}],"risks":[{"risk":"Raw material swings","detail":"Resin and paper price spikes squeeze margins before pass-through."},{"risk":"Overcapacity","detail":"New film lines around the world can depress prices."},{"risk":"Regulatory shift","detail":"Bans or EPR costs can hurt certain plastic formats."},{"risk":"Buyer power","detail":"Large FMCG customers negotiate hard on price."}],"cyclicality":"Mixed","cyclicalityNote":"Demand is steady with consumption, but film spreads are cyclical.","metricSet":"industrial-products","relatedBasicIndustries":["b-plastic-products-industrial","b-paper-and-paper-products","b-glass-industrial","b-packaged-foods","b-petrochemicals"],"aliases":["packaging","flexible packaging","BOPP film","BOPET film","polyester film","cartons","glass bottles","laminates"],"themes":["Exports"]},"b-plastic-products-industrial":{"simplifiedExplanation":"These companies mould and extrude plastic into goods used by builders, farmers and other industries, such as pipes, water tanks, technical films, plastic sheets and engineered plastic compounds.","productsAndServices":["PVC and polyethylene pipes and fittings","Water storage tanks","Specialty and protective films","Engineering plastic compounds","Industrial moulded components","Plastic sheets"],"valueChainPosition":"Midstream converters: they buy PVC, polyethylene, polypropylene and additives from petrochemical makers and sell to dealers, builders, farmers, and vehicle and appliance makers.","howTheyMakeMoney":"They earn a conversion margin over polymer costs; branded products sold through dealers earn more than commodity items, and specialty films or compounds can carry higher margins.","revenueSources":["Pipes and fittings through dealers","Industrial films and sheets","Compounds for vehicle and appliance makers","Moulded parts","Exports"],"operatingCosts":["PVC, PE and PP resins and additives","Power","Freight for bulky products","Employee costs","Dealer schemes and branding"],"customersAndEndMarkets":"Housing and plumbing, farm irrigation, water supply schemes, vehicle and appliance makers, packaging and construction firms.","demandSupplyDrivers":"Demand follows housing, irrigation, water infrastructure and manufacturing. Dealers stock up when resin prices rise and hold back when they fall, which makes quarterly volumes jumpy.","domesticInternationalExposure":"Resin prices follow global petrochemical markets and India depends partly on imported PVC; some specialty film and compound makers export.","capexIntensity":"Medium","capexNote":"Extrusion and moulding lines are moderately priced, but bulky goods like pipes need many plants close to markets.","workingCapital":"Raw material and channel inventory are significant; falling polymer prices can cause inventory losses.","regulation":"BIS standards for pipes and tanks, import duties and trade remedies on resins, and plastic waste and EPR rules apply.","competitiveAdvantages":"Brand and dealer reach, plants located near customers, a wide product range and know-how in specialty grades.","drivers":[{"factor":"Crude oil prices","impact":"Polymer costs move with crude and petrochemical cycles."},{"factor":"Real estate cycle","impact":"Housing construction drives plumbing pipe demand."},{"factor":"Monsoon & agriculture","impact":"Irrigation pipes and tanks sell more when farm incomes are healthy."},{"factor":"Infrastructure spending","impact":"Water supply and sewerage schemes lift pipe volumes."},{"factor":"Imports & dumping","impact":"Cheap imported resins or finished goods affect pricing."}],"risks":[{"risk":"Polymer price volatility","detail":"Sharp PVC price falls cause inventory losses and channel destocking."},{"risk":"Regional competition","detail":"Many local makers compete on price."},{"risk":"Plastic rules","detail":"Tighter environmental rules raise compliance costs."}],"cyclicality":"Mixed","cyclicalityNote":"Demand is broad-based, but margins swing with resin cycles.","metricSet":"industrial-products","relatedBasicIndustries":["b-packaging","b-petrochemicals","b-plastic-products-consumer","b-rubber","b-commodity-chemicals"],"aliases":["plastic pipes","PVC pipes","polymer products","plastic films","pipes and fittings","water tanks","plastic compounds","engineering plastics"],"themes":["Infrastructure","Rural demand"]},"b-rubber":{"simplifiedExplanation":"These companies make rubber-based industrial goods and materials, such as reclaimed rubber from old tyres, synthetic rubber and latex, transmission and conveyor belts, hoses and moulded rubber parts.","productsAndServices":["Reclaimed and crumb rubber","Synthetic rubber and latex","Transmission and conveyor belts","Hoses, seals and moulded parts","Rubber compounds","Recycled rubber products"],"valueChainPosition":"Midstream: they process natural, synthetic or waste rubber and supply tyre makers, vehicle and industrial OEMs, and footwear, paper and construction users.","howTheyMakeMoney":"They earn a processing margin over rubber and chemical costs; recycled rubber gains when virgin rubber is costly, and belt and part makers earn more on engineered products.","revenueSources":["Sales to tyre makers","Industrial belts, hoses and parts","Latex and synthetic rubber","Exports","Replacement market sales"],"operatingCosts":["Natural and synthetic rubber","Scrap tyres and waste rubber","Carbon black, chemicals and oils","Power and fuel","Labour and freight"],"customersAndEndMarkets":"Tyre makers, vehicle and machinery makers, mines and cement plants, paper and textile mills, footwear and glove makers, and overseas buyers.","demandSupplyDrivers":"Demand follows tyre and vehicle output and industrial activity. Natural rubber supply depends on plantation output, while crude oil drives synthetic rubber and chemical costs.","domesticInternationalExposure":"Natural rubber prices follow global markets and India imports part of its needs; several firms export reclaimed rubber, belts or latex.","capexIntensity":"Medium","capexNote":"Processing and moulding plants need moderate investment plus pollution controls.","workingCapital":"Raw material stocking around seasonal natural rubber supply and credit to OEM customers raise needs.","regulation":"The Rubber Board oversees natural rubber, import duties and anti-dumping measures affect inputs, and pollution rules and EPR for waste tyres apply.","competitiveAdvantages":"Approvals with tyre and OEM customers, compounding know-how and secure access to raw material or waste tyres.","drivers":[{"factor":"Commodity prices","impact":"Natural rubber prices set costs and the appeal of reclaimed alternatives."},{"factor":"Crude oil prices","impact":"Synthetic rubber, carbon black and process oils follow crude."},{"factor":"Vehicle and tyre output","impact":"Vehicle production and replacement tyre demand set volumes."},{"factor":"Exports & global demand","impact":"Overseas tyre and industrial demand drives export sales."},{"factor":"Regulation","impact":"Recycling and EPR rules support use of reclaimed rubber."}],"risks":[{"risk":"Input price swings","detail":"Rubber and chemical prices can move faster than selling prices."},{"risk":"Customer concentration","detail":"Dependence on a few tyre makers limits pricing power."},{"risk":"Environmental compliance","detail":"Processing waste rubber needs strict pollution controls."}],"cyclicality":"Cyclical","cyclicalityNote":"Linked to vehicle and industrial cycles and to rubber price swings.","metricSet":"industrial-products","relatedBasicIndustries":["b-tyres-and-rubber-products","b-carbon-black","b-auto-components-and-equipments","b-plastic-products-industrial","b-specialty-chemicals"],"aliases":["rubber","reclaimed rubber","synthetic rubber","latex","conveyor belts","rubber products","crumb rubber","industrial rubber"],"themes":["Exports"]},"b-other-industrial-products":{"simplifiedExplanation":"A mixed group of makers of industrial goods that do not fit other categories, such as welding consumables, safety gear, precision alloys and components, valves, tools and specialised hardware.","productsAndServices":["Welding electrodes and equipment","Industrial safety gear and protective clothing","Precision metal and alloy components","Valves, fittings and flow parts","Tools, fasteners and hardware","Specialised engineered parts"],"valueChainPosition":"Mostly midstream suppliers that buy metals, chemicals and parts and sell to factories, projects, OEMs and distributors.","howTheyMakeMoney":"They earn a manufacturing margin on niche products; margins are better where technology, approvals or brand matter more than price.","revenueSources":["Sales to OEMs and industrial users","Distributor and dealer sales","Exports","Project and replacement demand"],"operatingCosts":["Metals and alloys","Chemicals and other raw materials","Employee costs","Power and fuel","Freight and distribution"],"customersAndEndMarkets":"Fabrication, engineering, oil and gas, power, aerospace, vehicle, construction and manufacturing customers in India and overseas.","demandSupplyDrivers":"Demand tracks overall industrial production and capex. Niche positions can protect pricing, while standard items face cheap imports.","domesticInternationalExposure":"Varies by product; many export to global industrial buyers and compete with Chinese and other imports.","capexIntensity":"Medium","capexNote":"Needs vary widely, from light assembly to costly melting and precision machining facilities.","workingCapital":"Usually moderate, with stock across many product lines and normal credit to industrial buyers.","regulation":"Light, general business regulation; BIS standards apply to some products, and aerospace or defence parts need customer and quality certifications.","competitiveAdvantages":"Niche technical know-how, customer approvals and long relationships matter more than scale.","drivers":[{"factor":"Infrastructure spending","impact":"Projects lift demand for welding products, valves and safety gear."},{"factor":"Exports & global demand","impact":"Global industrial and aerospace demand supports export-oriented makers."},{"factor":"Commodity prices","impact":"Metal and chemical costs shift margins."},{"factor":"Imports & dumping","impact":"Low-cost imports pressure standard product lines."},{"factor":"Defence spending","impact":"Precision alloy and component makers gain from defence and aerospace programmes."}],"risks":[{"risk":"Hard to compare","detail":"Businesses differ widely, so peer comparison within this group is weak."},{"risk":"Import competition","detail":"Cheaper imports hurt standard products."},{"risk":"Small scale","detail":"Many firms are small and depend on a few customers."}],"cyclicality":"Cyclical","cyclicalityNote":"Most demand follows industrial production and capex cycles.","metricSet":"manufacturing-generic","relatedBasicIndustries":["b-industrial-products","b-castings-and-forgings","b-abrasives-and-bearings","b-compressors-pumps-and-diesel-engines","b-aerospace-and-defense"],"aliases":["industrial products","engineering products","welding","safety equipment","valves","precision components","industrial goods","miscellaneous industrial"],"themes":[]},"b-glass-industrial":{"simplifiedExplanation":"These companies make glass for industrial uses, such as solar glass that covers solar panels, laboratory and scientific glassware, and processed glass for buildings.","productsAndServices":["Solar glass for photovoltaic modules","Laboratory and scientific glassware","Toughened and laminated glass","Architectural and facade glass","Pharma glass tubing and vials","Specialty processed glass"],"valueChainPosition":"Midstream: they melt sand, soda ash and other minerals into glass or process bought glass, and supply solar module makers, labs, pharma companies, builders and OEMs.","howTheyMakeMoney":"They earn on volume and price per tonne or square metre. Furnaces run nonstop, so high utilisation and energy efficiency drive profits.","revenueSources":["Solar glass sales","Scientific and lab glassware","Processed architectural glass","Exports"],"operatingCosts":["Natural gas and fuel","Soda ash and silica sand","Power","Furnace repairs and rebuilds","Freight and breakage"],"customersAndEndMarkets":"Solar module makers, pharma and research labs, educational institutions, builders and facade contractors, and overseas buyers.","demandSupplyDrivers":"Demand follows solar manufacturing, construction and pharma activity. Large global capacity, much of it in China, sets the price of solar glass.","domesticInternationalExposure":"Exposed to imports from China and Southeast Asia and to global energy prices; some firms export solar or scientific glass.","capexIntensity":"High","capexNote":"Glass furnaces are expensive and need periodic cold repairs or rebuilds.","workingCapital":"Moderate; furnaces must run continuously, so stock builds up when demand is weak.","regulation":"Anti-dumping duties on some imported glass, BIS standards for certain products, and pollution control rules for furnaces matter.","competitiveAdvantages":"Furnace scale, technology for low-iron solar glass, energy efficiency and approvals with module makers or labs.","drivers":[{"factor":"Imports & dumping","impact":"Cheap imports cap local prices, and trade duties can change that quickly."},{"factor":"Fuel and gas prices","impact":"Natural gas and power are among the largest costs."},{"factor":"Government policy","impact":"Support for local solar manufacturing raises demand for Indian solar glass."},{"factor":"Capacity utilisation","impact":"Continuous furnaces need high utilisation to cover fixed costs."},{"factor":"Healthcare spending","impact":"Pharma and research spending drives scientific glassware demand."}],"risks":[{"risk":"Dumping","detail":"Low-priced imports can undercut local makers."},{"risk":"Energy costs","detail":"Gas price spikes hit margins."},{"risk":"Furnace downtime","detail":"Breakdowns or rebuilds cut output."},{"risk":"Solar slowdown","detail":"Weak module production cuts solar glass demand."}],"cyclicality":"Cyclical","cyclicalityNote":"Prices swing with global capacity, energy costs and solar demand.","metricSet":"industrial-products","relatedBasicIndustries":["b-glass-consumer","b-other-electrical-equipment","b-packaging","b-industrial-minerals"],"aliases":["solar glass","glass","industrial glass","scientific glassware","lab glass","toughened glass","pharma glass"],"themes":["Renewable energy","China+1"]},"b-aluminium-copper-and-zinc-products":{"simplifiedExplanation":"These companies turn non-ferrous metals into products other industries use, such as copper winding wires, copper rods and strips, aluminium extrusions and foils, and zinc-based alloys.","productsAndServices":["Copper winding and enamelled wires","Copper rods, strips and busbars","Aluminium extrusions and profiles","Aluminium foils and sheets","Zinc and alloy products","Overhead line conductors"],"valueChainPosition":"Midstream converters between primary metal producers and users: they buy ingots, rods or billets and supply motor, transformer, appliance, vehicle, construction and packaging makers.","howTheyMakeMoney":"They earn a conversion charge per tonne over the metal price, which is usually passed on to buyers; value-added and specialty products earn more.","revenueSources":["Conversion of metal into wires, rods and profiles","Value-added and specialty products","Exports","Scrap and by-product sales"],"operatingCosts":["Copper, aluminium or zinc metal","Power and fuel","Enamels, chemicals and dies","Labour","Freight and hedging costs"],"customersAndEndMarkets":"Motor, transformer, fan and appliance makers, vehicle and EV part makers, construction and facade firms, power utilities and packaging companies.","demandSupplyDrivers":"Volumes follow electrification, appliances, construction, vehicles and power demand. Metal prices pass through, so profit depends on volumes and the conversion spread.","domesticInternationalExposure":"Metal prices are set on global exchanges such as the LME, so global prices and the rupee move revenue; Asian imports compete in some products and some firms export.","capexIntensity":"Medium","capexNote":"Drawing and extrusion lines need moderate capital, while foil and rolling mills need more.","workingCapital":"Metal stocks and customer credit are large in value; firms hedge metal to avoid price losses.","regulation":"BIS standards and quality rules on some metal products, import duties and trade remedies on certain items, and GST apply.","competitiveAdvantages":"Approvals with OEMs, consistent quality, scale for efficient metal buying and disciplined hedging.","drivers":[{"factor":"Commodity prices","impact":"Copper, aluminium and zinc prices change revenue and working capital needs."},{"factor":"Electricity demand","impact":"Motors, transformers and grid lines use more winding wire and conductors as power use grows."},{"factor":"Technology change","impact":"EVs and efficient motors raise demand for copper winding products."},{"factor":"Consumer demand","impact":"Fans, appliances and air conditioners use winding wire and aluminium parts."},{"factor":"Imports & dumping","impact":"Imports from Asia compete on price."}],"risks":[{"risk":"Metal price swings","detail":"Unhedged positions can create losses."},{"risk":"Thin spreads","detail":"Conversion margins are small, so small cost changes matter."},{"risk":"Buyer power","detail":"Large OEM buyers negotiate hard on conversion charges."},{"risk":"Import competition","detail":"Cheaper imports pressure realisations."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes follow industrial, construction and appliance cycles.","metricSet":"metals","relatedBasicIndustries":["b-copper","b-aluminium","b-zinc","b-cables-electricals","b-heavy-electrical-equipment"],"aliases":["copper products","aluminium extrusion","aluminum products","winding wires","copper wire","non-ferrous products","conductors","aluminium foil"],"themes":["EV","Infrastructure"]},"b-iron-and-steel-products":{"simplifiedExplanation":"These companies make steel goods used in construction and industry, such as pipes and tubes, TMT bars, wires, structural sections, coated sheets and alloy steel, often from small or mid-sized plants.","productsAndServices":["Steel pipes and tubes","TMT bars and rebars","Structural sections and angles","Wire rods, wires and fasteners","Galvanised and coated sheets","Alloy and special steel bars"],"valueChainPosition":"Midstream to downstream: they buy iron ore, sponge iron, scrap, billets or steel coil, or make their own in mini plants, and sell finished steel goods to builders, projects, pipelines, OEMs and dealers.","howTheyMakeMoney":"They earn the spread between finished product price and input cost; integrated mini plants capture more of the chain, while pure processors earn a conversion margin.","revenueSources":["Pipes and tubes for water, gas and structures","Long products such as TMT bars","Wires and wire products","Coated and value-added steel","Exports"],"operatingCosts":["Iron ore, scrap, sponge iron or steel coil","Coal, power and fuel","Ferroalloys and zinc","Labour","Freight"],"customersAndEndMarkets":"Builders and steel dealers, infrastructure contractors, water and gas pipeline projects, oil and gas, vehicle and engineering firms, and export buyers.","demandSupplyDrivers":"Demand follows construction, infrastructure and pipeline programmes. Domestic steel prices and fresh capacity decide spreads.","domesticInternationalExposure":"Steel prices follow global markets and Chinese exports; pipe makers often export, and imports can pressure local prices.","capexIntensity":"High","capexNote":"Mini steel plants and pipe mills need heavy investment, though pure processors are lighter.","workingCapital":"Steel stocks and dealer or project receivables are significant; falling steel prices can cause inventory losses.","regulation":"BIS quality control orders cover many steel products; safeguard or anti-dumping duties on imports, mining rules and State Pollution Control Boards also matter.","competitiveAdvantages":"Backward integration, low-cost locations near raw materials, a known brand in TMT or pipes, and approvals for project supply.","drivers":[{"factor":"Infrastructure spending","impact":"Roads, water schemes, gas pipelines and buildings drive volumes."},{"factor":"Commodity prices","impact":"Steel, iron ore and coal prices set spreads."},{"factor":"Imports & dumping","impact":"Cheap imports can drag down domestic steel prices."},{"factor":"Real estate cycle","impact":"Housing demand supports TMT and structural steel."},{"factor":"Government policy","impact":"Trade duties and quality orders shape import competition."}],"risks":[{"risk":"Price volatility","detail":"Sharp steel price falls hit margins and inventory."},{"risk":"Fragmented competition","detail":"Many small plants compete mainly on price."},{"risk":"Pollution rules","detail":"Small plants face tightening environmental compliance."},{"risk":"Scheme dependence","detail":"Pipe orders depend on government scheme funding and payments."}],"cyclicality":"Cyclical","cyclicalityNote":"Steel products follow construction activity and the steel price cycle.","metricSet":"metals","relatedBasicIndustries":["b-iron-and-steel","b-sponge-iron","b-civil-construction","b-castings-and-forgings","b-ferro-and-silica-manganese"],"aliases":["steel pipes","steel tubes","TMT bars","steel products","secondary steel","DI pipes","structural steel","mini steel plant","wire products"],"themes":["Infrastructure"]},"b-abrasives-and-bearings":{"simplifiedExplanation":"These companies make bearings, which let shafts and wheels spin smoothly in vehicles and machines, and abrasives, which grind, cut and polish metal and other materials.","productsAndServices":["Ball and roller bearings","Tapered roller bearings for rail and trucks","Grinding wheels and cutting discs","Coated abrasives such as sandpaper","Super abrasives and diamond tools","Silicon carbide and ceramic materials"],"valueChainPosition":"Midstream component suppliers: they buy special steel, abrasive grains and bonding materials and supply vehicle, rail, machinery, steel and fabrication users through OEM and distributor channels.","howTheyMakeMoney":"They earn on OEM supply and on higher-margin replacement sales through dealers; many also trade products made by their global parent groups.","revenueSources":["OEM supply to vehicle and machinery makers","Replacement and aftermarket sales","Exports to group companies","Trading of imported products"],"operatingCosts":["Special steel and alloys","Abrasive grains, resins and bonds","Power and fuel","Royalty and technology fees","Employee costs"],"customersAndEndMarkets":"Car, truck, tractor and two-wheeler makers, railways, machinery builders, steel and cement plants, fabricators and workshops.","demandSupplyDrivers":"Demand follows vehicle output, industrial production and rail spending; the aftermarket gives steadier demand, while cheap imports compete in standard sizes.","domesticInternationalExposure":"Many firms belong to global groups and export to them; imported bearings and abrasives from Asia compete on price.","capexIntensity":"Medium","capexNote":"Precision grinding and heat-treatment lines need steady investment.","workingCapital":"Moderate: thousands of product sizes need inventory, and distributors expect credit.","regulation":"Light, general business regulation; BIS standards for some products and import duties or quality rules on bearings affect competition.","competitiveAdvantages":"Global technology and brands, OEM approvals, a wide product range and strong distribution.","drivers":[{"factor":"Vehicle production","impact":"Vehicle output drives OEM demand for bearings and abrasives."},{"factor":"Infrastructure spending","impact":"Rail, construction and industrial projects raise bearing and grinding demand."},{"factor":"Imports & dumping","impact":"Low-cost imports pressure standard products."},{"factor":"Exports & global demand","impact":"Exports to global group networks add volume."},{"factor":"Technology change","impact":"EVs and high-precision machines need specialised bearings."}],"risks":[{"risk":"Vehicle slowdown","detail":"Weak vehicle production cuts OEM volumes."},{"risk":"Import competition","detail":"Cheaper imports hurt standard ranges."},{"risk":"Input costs","detail":"Special steel and grain price hikes squeeze margins."},{"risk":"Parent dependence","detail":"Royalties and intra-group pricing affect reported profit."}],"cyclicality":"Mixed","cyclicalityNote":"OEM demand is cyclical, while the replacement market is steadier.","metricSet":"industrial-products","relatedBasicIndustries":["b-auto-components-and-equipments","b-railway-wagons","b-industrial-products","b-other-industrial-products","b-iron-and-steel"],"aliases":["bearings","ball bearings","roller bearings","abrasives","grinding wheels","cutting discs","sandpaper","silicon carbide"],"themes":["Exports"]},"b-compressors-pumps-and-diesel-engines":{"simplifiedExplanation":"These companies make machines that move water, air and fluids, and engines that supply power, such as water pumps, compressors, hydraulic systems, diesel engines and generator sets.","productsAndServices":["Farm and domestic water pumps","Industrial and municipal pumps","Air and gas compressors","Diesel engines for tractors and equipment","Diesel and gas generator sets","Hydraulic systems and valves","Solar pumps"],"valueChainPosition":"Midstream: they buy castings, motors, steel and electronics and sell to farmers, builders, water projects, factories and OEMs such as tractor makers, directly or through dealers.","howTheyMakeMoney":"They earn margins on products sold through dealers and on project orders, plus spares and service from a large installed base; government water and solar pump schemes add order-based revenue.","revenueSources":["Pump sales through dealers","Industrial and project orders","Engines supplied to OEMs","Gensets and power solutions","Spares, service and exports"],"operatingCosts":["Castings, steel and copper","Motors and electronic parts","Employee costs","Dealer schemes and freight","R&D and emission compliance"],"customersAndEndMarkets":"Farmers, households and builders, municipal and irrigation projects, oil and gas, power and process plants, data centres, and tractor and equipment makers.","demandSupplyDrivers":"Demand follows farm incomes, water and irrigation schemes, industrial capex and the need for backup power. Grid reliability and emission norms shape genset demand.","domesticInternationalExposure":"Mostly domestic, with exports of pumps, compressors and engines; imported products compete in standard ranges.","capexIntensity":"Medium","capexNote":"Foundry, machining and assembly plants need moderate, steady investment.","workingCapital":"Dealer stocking and seasonal farm demand raise inventory; receivables on government projects can be slow.","regulation":"BEE star labelling for pumps, CPCB emission norms for gensets, tractor emission norms for engines, and the PM-KUSUM scheme for solar pumps matter.","competitiveAdvantages":"Brand and dealer reach in rural markets, OEM approvals, engineering for large custom pumps and a wide service network.","drivers":[{"factor":"Monsoon & agriculture","impact":"Rainfall patterns and farm income shape sales of farm pumps and tractor engines."},{"factor":"Infrastructure spending","impact":"Water supply, irrigation and sewerage projects drive large pump orders."},{"factor":"Government policy","impact":"Solar pump schemes and emission norms shift demand and product design."},{"factor":"Electricity demand","impact":"Data centres, hospitals and factories need backup gensets and efficient compressors."},{"factor":"Commodity prices","impact":"Castings, steel and copper prices drive costs."}],"risks":[{"risk":"Seasonality","detail":"Farm demand is seasonal and weather dependent."},{"risk":"Emission costs","detail":"Stricter norms raise genset and engine prices."},{"risk":"Project payments","detail":"Government water project receivables can be delayed."},{"risk":"Price competition","detail":"Many small pump makers compete on price."}],"cyclicality":"Mixed","cyclicalityNote":"Farm and replacement demand is steadier, while industrial and project orders are cyclical.","metricSet":"capital-goods","relatedBasicIndustries":["b-tractors","b-industrial-products","b-water-supply-and-management","b-castings-and-forgings","b-heavy-electrical-equipment"],"aliases":["pumps","compressors","diesel engines","gensets","generator sets","water pumps","solar pumps","hydraulics"],"themes":["Infrastructure","Rural demand","Renewable energy"]},"b-electrodes-and-refractories":{"simplifiedExplanation":"These companies make materials that survive extreme heat in metal and glass plants. Graphite electrodes carry electricity to melt scrap in electric steel furnaces, while refractories line furnaces, kilns and ladles.","productsAndServices":["Graphite electrodes","Refractory bricks and monolithics","Furnace and ladle linings","Flow control products for steel casting","Silica ramming mass","Insulation and ceramic fibre products"],"valueChainPosition":"Upstream suppliers to heavy industry: they buy needle coke and minerals such as bauxite, magnesia and silica, and supply steel, cement, glass, aluminium and power plants.","howTheyMakeMoney":"Electrode makers earn the spread between electrode prices and needle coke and power costs; refractory makers earn per tonne and from contracts to manage furnace linings.","revenueSources":["Graphite electrode sales","Refractory product sales","Refractory management and service contracts","Exports"],"operatingCosts":["Needle coke and petroleum coke","Refractory minerals","Power and fuel","Labour","Freight"],"customersAndEndMarkets":"Electric arc and induction furnace steel makers, integrated steel plants, cement, glass and aluminium producers, and overseas steel makers.","demandSupplyDrivers":"Demand follows steel output, especially electric furnace steel, and cement and glass production. Global electrode capacity, much of it in China, and needle coke supply set prices.","domesticInternationalExposure":"Graphite electrodes are traded globally, so export demand and Chinese supply drive prices; needle coke and many refractory minerals are imported.","capexIntensity":"High","capexNote":"Electrode plants need long, energy-intensive process lines; refractory plants are moderately capital intensive.","workingCapital":"Electrode production takes a long time from raw material to finished product, so inventory is heavy; refractory makers carry many product grades for customers.","regulation":"Trade remedies on imported electrodes and refractories, pollution control norms and industrial power tariffs matter.","competitiveAdvantages":"Process know-how, secure needle coke supply, scale with cost-efficient power, and long relationships with steel plants.","drivers":[{"factor":"Steel production","impact":"More steel output, especially from electric furnaces, raises electrode and refractory use."},{"factor":"Exports & global demand","impact":"Global steel cycles and export orders set electrode volumes."},{"factor":"Imports & dumping","impact":"Chinese oversupply can depress global electrode prices."},{"factor":"Raw material availability","impact":"Needle coke and imported minerals affect cost and supply."},{"factor":"Technology change","impact":"A shift to lower-emission electric furnace steel supports electrode demand."}],"risks":[{"risk":"Price cycles","detail":"Electrode prices can swing sharply between boom and bust."},{"risk":"Input costs","detail":"Needle coke and power price spikes squeeze margins."},{"risk":"Steel slowdown","detail":"Weak steel demand cuts volumes for both electrodes and refractories."},{"risk":"Import dependence","detail":"Reliance on imported minerals adds supply risk."}],"cyclicality":"Cyclical","cyclicalityNote":"Fortunes rise and fall with the global steel cycle.","metricSet":"industrial-products","relatedBasicIndustries":["b-iron-and-steel","b-cement-and-cement-products","b-industrial-minerals","b-glass-industrial","b-aluminium"],"aliases":["graphite electrodes","refractories","refractory bricks","electrodes","furnace lining","needle coke","monolithics","ramming mass"],"themes":["Exports"]},"b-dredging":{"simplifiedExplanation":"Dredging companies dig up and remove silt, sand and rock from the bottom of seas, rivers and harbours so that ships can move safely. They also use the dredged material to reclaim land for ports and coastal projects.","productsAndServices":["Capital dredging for new ports and berths","Maintenance dredging of shipping channels","Land reclamation","River and inland waterway dredging","Beach nourishment and coastal protection","Marine construction support"],"valueChainPosition":"Midstream contractor in marine infrastructure: it buys or charters dredgers from shipyards and works for port authorities, waterway agencies and port developers.","howTheyMakeMoney":"They win contracts, mostly through tenders, and are paid per volume of material dredged or per project milestone. Keeping costly dredgers busy between contracts decides profit.","revenueSources":["Maintenance dredging contracts with ports","Capital dredging projects","Land reclamation work","Inland waterway contracts","Chartering out dredgers"],"operatingCosts":["Fuel for dredgers","Crew and technical staff","Dry-docking and repairs","Depreciation of the fleet","Spare parts and dredging pipes","Moving dredgers between sites"],"customersAndEndMarkets":"Major and non-major port authorities, private port operators, inland waterway agencies and coastal state governments.","demandSupplyDrivers":"Demand comes from new port capacity, deeper drafts for bigger ships, yearly siltation of channels and inland waterway development. Supply is limited by the number of large dredgers available, and global dredging firms also bid for big contracts.","domesticInternationalExposure":"Work is mostly domestic, but global contractors compete strongly on large projects; dredgers and many spare parts are imported.","capexIntensity":"High","capexNote":"Dredgers are expensive specialised vessels that need regular dry-docking and eventual replacement.","workingCapital":"Government port clients can pay slowly and hold back retention money until work is accepted; monsoon weather can pause work for weeks.","regulation":"Work is shaped by the Ministry of Ports, Shipping and Waterways, port authorities and the Inland Waterways Authority of India; coastal works need environmental and coastal zone clearances.","competitiveAdvantages":"A modern fleet of the right dredger types, a track record that qualifies for large tenders and long relationships with port authorities keep new entrants out.","drivers":[{"factor":"Infrastructure spending","impact":"Port expansion and coastal development programmes create capital dredging work."},{"factor":"Government policy","impact":"Plans to develop inland waterways and coastal shipping add regular dredging needs."},{"factor":"Crude oil prices","impact":"Fuel is a big running cost, so higher prices squeeze margins unless contracts pass them on."},{"factor":"Capacity utilisation","impact":"Idle time between contracts hurts profit because fleet costs continue."},{"factor":"Monsoon & weather","impact":"Rough seas cut working days, while heavy silt flow later raises maintenance dredging needs."}],"risks":[{"risk":"Contract lumpiness","detail":"Revenue depends on winning a few large tenders, so gaps between projects hit results."},{"risk":"Payment delays","detail":"Government clients may pay late, stretching cash flow."},{"risk":"Foreign competition","detail":"Global dredging firms with larger fleets can underbid on big projects."},{"risk":"Fleet breakdowns","detail":"An ageing or damaged dredger can lose weeks of work and need costly repairs."}],"cyclicality":"Cyclical","cyclicalityNote":"Work follows port and waterway investment cycles and the timing of large government tenders.","metricSet":"construction-epc","relatedBasicIndustries":["b-port-and-port-services","b-civil-construction","b-ship-building-and-allied-services","b-shipping"],"aliases":["dredging","dredger","marine dredging","port dredging","capital dredging","maintenance dredging","land reclamation","marine engineering"],"themes":["Infrastructure"]},"b-airline":{"simplifiedExplanation":"Airlines fly passengers and cargo between cities in India and abroad. They earn mainly from ticket sales, and their profit swings with fuel prices, fares and how full their planes are.","productsAndServices":["Domestic passenger flights","International passenger flights","Belly cargo on passenger flights","Paid seats, extra baggage and meals","Loyalty programme and co-branded card tie-ups","Charter flights"],"valueChainPosition":"Downstream service provider: it leases or buys aircraft from manufacturers and lessors, buys jet fuel from oil marketers and pays airports, then sells seats to travellers directly or through travel agents.","howTheyMakeMoney":"They sell seats at fares that change with demand, aiming to fill each flight while covering fuel, leases and staff. Ancillary fees and cargo add income on the same flights.","revenueSources":["Passenger fares","Ancillary fees (baggage, seats, meals)","Cargo","Loyalty and card partnerships"],"operatingCosts":["Aviation turbine fuel (ATF)","Aircraft lease rentals or depreciation","Maintenance and engine overhauls","Airport, landing and navigation charges","Pilot, crew and ground staff salaries","Sales and distribution costs"],"customersAndEndMarkets":"Leisure, business, pilgrimage and visiting-family travellers, plus freight forwarders for cargo; demand is concentrated on metro routes but is spreading to smaller cities.","demandSupplyDrivers":"Passenger demand rises with incomes, tourism and business activity, and peaks in holidays and festivals. Supply depends on aircraft deliveries, engine availability, airport slots and rivals entering or exiting, which sets fare levels.","domesticInternationalExposure":"Revenue is mostly in rupees, while fuel follows global crude prices and leases and maintenance are largely in US dollars, so a weaker rupee raises costs.","capexIntensity":"High","capexNote":"A fleet is a large long-term commitment, even though many Indian airlines lease aircraft rather than own them.","workingCapital":"Tickets are paid before flying, so airlines hold customer advances, but they need cash buffers for fuel, lease payments and weak seasons.","regulation":"DGCA licenses airlines and sets safety rules, BCAS oversees security and the Ministry of Civil Aviation runs schemes such as UDAN; taxes on ATF and airport charges approved by AERA affect costs.","competitiveAdvantages":"Scale, low unit costs, on-time reliability, slots at busy airports and a wide route network protect strong players; weak airlines have repeatedly failed.","drivers":[{"factor":"Crude oil prices","impact":"Jet fuel is a very large cost and moves with global crude prices."},{"factor":"Currency (INR)","impact":"A weaker rupee raises dollar-linked lease, maintenance and fuel costs."},{"factor":"Tourism & travel","impact":"Holiday, pilgrimage and business travel set seat demand and fares."},{"factor":"Consumer demand","impact":"Rising middle-class incomes bring new first-time flyers."},{"factor":"Aircraft and engine supply","impact":"Delivery delays or engine problems ground planes and limit capacity."}],"risks":[{"risk":"Fuel price spikes","detail":"Sharp rises in ATF can wipe out profit if fares cannot rise fast enough."},{"risk":"Fare wars","detail":"Aggressive capacity additions by rivals push fares down."},{"risk":"Grounded aircraft","detail":"Engine or supply-chain issues can leave planes idle while costs continue."},{"risk":"Safety incidents","detail":"Accidents or regulatory action can hurt demand and reputation."},{"risk":"External shocks","detail":"Pandemics, conflicts or airspace closures can collapse traffic quickly."}],"cyclicality":"Cyclical","cyclicalityNote":"Profits swing sharply with fuel prices, fares and travel demand, and shocks can quickly turn them into losses.","metricSet":"airline","relatedBasicIndustries":["b-airport-and-airport-services","b-tour-travel-related-services","b-hotels-and-resorts","b-refineries-and-marketing"],"aliases":["airline","airlines","aviation","air travel","low-cost carrier","LCC","flights","air cargo","civil aviation"],"themes":["Tourism"]},"b-logistics-solution-provider":{"simplifiedExplanation":"Logistics companies move and store goods for other businesses, through trucking, express parcels, container trains, warehouses and freight forwarding. Some own few assets and coordinate carriers; others run their own fleets, terminals and warehouses.","productsAndServices":["Full and part truckload transport","Express parcel and courier delivery","Container rail transport and inland container depots","Warehousing and contract logistics","Freight forwarding and customs clearance","Cold-chain logistics","Multimodal supply chain solutions"],"valueChainPosition":"Midstream link between producers, ports and consumers: it buys transport capacity (trucks, rail rakes, ships, aircraft) and sells end-to-end movement and storage to manufacturers, retailers and e-commerce firms.","howTheyMakeMoney":"They charge per shipment, per kilogram or per contract and keep the gap between that price and fleet, fuel and handling costs. Denser networks and better asset use lift margins.","revenueSources":["Freight charges per load or kilogram","Warehousing and handling fees","Express and value-added delivery","Freight forwarding and customs services","Terminal and depot charges"],"operatingCosts":["Diesel and hired vehicle costs","Rail haulage and terminal charges","Warehouse rent","Staff and delivery workforce","Tolls","Tracking and IT systems"],"customersAndEndMarkets":"Manufacturers, FMCG and auto companies, e-commerce and retail, exporters and importers, and pharma firms needing cold chains.","demandSupplyDrivers":"Volumes track industrial output, consumption, e-commerce and foreign trade. Trucking is fragmented and price-competitive, while new freight corridors, better highways and GST-led warehouse consolidation are reshaping routes.","domesticInternationalExposure":"Most revenue is domestic, but freight forwarding and container logistics depend on export-import volumes and global container freight rates.","capexIntensity":"Medium","capexNote":"Asset-light players need little capital, while those owning fleets, rakes, terminals or warehouses invest heavily.","workingCapital":"Corporate customers usually pay on credit while fuel and hired trucks are paid quickly, so receivable control matters; festive and harvest seasons raise volumes.","regulation":"GST and e-way bills shape warehouse locations and paperwork; the National Logistics Policy and PM Gati Shakti aim to cut logistics costs, and rail freight runs under Indian Railways rules.","competitiveAdvantages":"A dense branch and hub network, good tracking technology, long contracts with large shippers and owned terminals near ports or rail lines are hard to copy.","drivers":[{"factor":"Consumer demand","impact":"Higher consumption and online shopping raise parcel and distribution volumes."},{"factor":"Exports & global demand","impact":"Container and forwarding businesses follow export-import trade."},{"factor":"Crude oil prices","impact":"Diesel is a major cost; slow pass-through to customers squeezes margins."},{"factor":"Infrastructure spending","impact":"Freight corridors, highways and logistics parks change route costs and the road-rail mix."},{"factor":"Government policy","impact":"GST, e-way bills and logistics policy push business toward organised players."}],"risks":[{"risk":"Price competition","detail":"A fragmented market of small truckers limits pricing power."},{"risk":"Fuel cost pass-through","detail":"Delays in passing on diesel price changes hurt margins."},{"risk":"Customer concentration","detail":"Losing one large client can dent volumes."},{"risk":"Economic slowdown","detail":"Lower industrial and trade activity cuts shipments quickly."}],"cyclicality":"Cyclical","cyclicalityNote":"Freight volumes move with industrial output, consumption and trade, though long-term contract logistics is steadier.","metricSet":"logistics-transport","relatedBasicIndustries":["b-road-transport","b-railways","b-port-and-port-services","b-shipping","b-e-retail-e-commerce"],"aliases":["logistics","supply chain","courier","express delivery","warehousing","3PL","freight forwarding","container logistics","CFS ICD","cold chain"],"themes":["Infrastructure"]},"b-railways":{"simplifiedExplanation":"This group covers listed businesses that run or support train operations, such as moving freight or providing rail services. In India the track network itself belongs to Indian Railways, so listed players work alongside it under its rules.","productsAndServices":["Rail freight operations","Private freight and container train services","Rail sidings and freight terminals","Rolling stock leasing and maintenance","Railway operation and maintenance contracts","Passenger-related rail services"],"valueChainPosition":"Midstream transport operator: it relies on track, signalling and train paths from Indian Railways and on wagon and locomotive makers, and serves bulk shippers, container users and travellers.","howTheyMakeMoney":"They earn haulage, terminal or service charges per tonne, per container or per contract, often paying haulage fees to Indian Railways. Profit depends on running full trains, ideally loaded in both directions.","revenueSources":["Freight haulage charges","Terminal and siding fees","Operation and maintenance contracts","Rolling stock lease income","Passenger-related service fees"],"operatingCosts":["Haulage charges paid to Indian Railways","Wagon and rake leases","Traction power or diesel","Staff","Rolling stock maintenance","Terminal handling"],"customersAndEndMarkets":"Shippers of coal, cement, steel, fertiliser and food grain, container and port users, and Indian Railways or government agencies for service contracts.","demandSupplyDrivers":"Freight demand follows bulk commodity output and port traffic, while capacity depends on line congestion, new freight corridors and rake availability. Government policy decides how much private participation is allowed.","domesticInternationalExposure":"Almost entirely domestic, though export-import containers and imported coal moving inland by rail link volumes to foreign trade.","capexIntensity":"High","capexNote":"Rolling stock, terminals and sidings need large upfront investment with a long payback.","workingCapital":"Government and PSU clients can pay with delays; bulk freight runs through the year but some cargo slows in the monsoon.","regulation":"The Ministry of Railways, through Indian Railways, controls track access, freight rates, haulage charges and the policies for private wagons, terminals and trains.","competitiveAdvantages":"Long-term agreements with Indian Railways, access to terminals and sidings and scale in rakes are hard to replicate; road transport is the main competitor.","drivers":[{"factor":"Infrastructure spending","impact":"Dedicated freight corridors and network upgrades raise capacity and train speeds."},{"factor":"Government policy","impact":"Rules on private trains, wagon schemes and freight rates set the size of the opportunity."},{"factor":"Bulk commodity volumes","impact":"Coal, ore, cement and grain output decides how much freight there is to move."},{"factor":"Crude oil prices","impact":"Costlier diesel makes rail cheaper than road over long distances, shifting cargo to rail."},{"factor":"Capacity utilisation","impact":"Full rakes and quick turnarounds decide margins."}],"risks":[{"risk":"Policy dependence","detail":"Changes in haulage charges or private-operator rules can alter returns."},{"risk":"Network congestion","detail":"Slow trains and delays reduce the number of trips per rake."},{"risk":"Road competition","detail":"Better highways and bigger trucks can win back cargo."},{"risk":"Cargo concentration","detail":"A slowdown in coal or steel can cut volumes sharply."}],"cyclicality":"Mixed","cyclicalityNote":"Bulk freight is fairly steady, but volumes still rise and fall with industrial and trade cycles.","metricSet":"logistics-transport","relatedBasicIndustries":["b-railway-wagons","b-logistics-solution-provider","b-transport-related-services","b-civil-construction"],"aliases":["railways","rail","rail freight","train operator","indian railways","freight train","rail logistics","rolling stock"],"themes":["Infrastructure"]},"b-road-transport":{"simplifiedExplanation":"Road transport companies carry people or goods by road using their own or hired vehicles. Listed players include bus operators, car rental and chauffeur services, employee transport providers and truck fleet owners.","productsAndServices":["Chauffeur-driven car rentals","Employee transport for offices","City and intercity bus services","Self-drive car rental","Truck fleet operations","Tourist and event transport"],"valueChainPosition":"Downstream operator: it buys or leases vehicles from automakers and fuel from oil marketers, and sells trips or contracts to companies, travellers and shippers.","howTheyMakeMoney":"They charge per trip, per kilometre or a monthly contract fee. Profit depends on keeping vehicles busy, controlling fuel and driver costs and replacing vehicles at the right time.","revenueSources":["Corporate car rental and employee transport contracts","Passenger fares per trip","Freight hire charges","Self-drive rental fees","Tourist and event bookings"],"operatingCosts":["Fuel (diesel, petrol, CNG or electricity)","Driver salaries","Vehicle depreciation or lease costs","Maintenance and tyres","Tolls and permits","Insurance"],"customersAndEndMarkets":"Corporates and IT parks for employee transport, hotels and travellers, government agencies, and manufacturers and traders for freight.","demandSupplyDrivers":"Passenger demand follows office attendance, business travel and tourism, while freight follows industrial activity. Ride-hailing apps and many small operators keep supply plentiful and pricing competitive.","domesticInternationalExposure":"Almost fully domestic; the main global link is through fuel prices.","capexIntensity":"Medium","capexNote":"Fleets need steady replacement, though some operators lease vehicles or use vehicles owned by attached partners.","workingCapital":"Corporate clients pay on credit while fuel and salaries are paid quickly; vehicle loans add regular debt repayments.","regulation":"State transport departments issue permits and enforce the Motor Vehicles Act; state transport corporations dominate many bus routes, and EV and emission rules shape fleet choices.","competitiveAdvantages":"Long-standing corporate contracts, reliable service, multi-city presence and fleet scale bring pricing and purchasing advantages.","drivers":[{"factor":"Crude oil prices","impact":"Fuel is a major running cost, so price rises hurt margins until fares are revised."},{"factor":"Tourism & travel","impact":"Holiday and business travel drive car rental and tourist transport demand."},{"factor":"Office attendance","impact":"Employee transport volumes depend on how often staff work from offices."},{"factor":"Technology change","impact":"Ride-hailing apps and electric vehicles change competition and cost structures."},{"factor":"Interest rates","impact":"Fleet purchases are often loan-funded, so borrowing costs matter."}],"risks":[{"risk":"Fuel price swings","detail":"Contracts may not adjust quickly to fuel cost changes."},{"risk":"App-based competition","detail":"Ride-hailing platforms can undercut prices."},{"risk":"Driver shortages","detail":"Finding and keeping trained drivers raises costs."},{"risk":"Accidents and liability","detail":"Road accidents bring claims, downtime and reputation damage."}],"cyclicality":"Cyclical","cyclicalityNote":"Trip volumes rise and fall with business travel, tourism and economic activity.","metricSet":"logistics-transport","relatedBasicIndustries":["b-logistics-solution-provider","b-tour-travel-related-services","b-commercial-vehicles","b-passenger-cars-and-utility-vehicles"],"aliases":["road transport","car rental","cab services","chauffeur","bus operator","fleet operator","employee transport","trucking","transport operator"],"themes":["EV","Tourism"]},"b-shipping":{"simplifiedExplanation":"Shipping companies own or charter vessels that carry crude oil, fuels, gas, coal, ores and containers across the seas. Their earnings depend mainly on global freight (charter) rates, which can swing sharply.","productsAndServices":["Crude oil tankers","Petroleum product tankers","Dry bulk carriers for coal, ore and grain","LPG and gas carriers","Container feeder services","Offshore support vessels","Coastal shipping"],"valueChainPosition":"Midstream transport link: it buys ships from shipyards or second-hand markets and carries cargo for oil companies, commodity traders, miners and container lines.","howTheyMakeMoney":"Vessels are hired on short spot voyages or longer time charters at a daily rate. Profit is charter income minus running costs, voyage fuel and financing.","revenueSources":["Spot voyage freight","Time charter hire","Contracts of affreightment","Gains on sale of older vessels","Offshore vessel charters"],"operatingCosts":["Bunker fuel on voyage charters","Crew wages","Repairs, dry-docking and insurance","Port and canal charges","Vessel depreciation","Interest on ship loans"],"customersAndEndMarkets":"Oil refiners and marketers, power and steel producers, commodity traders, container lines and offshore oil and gas operators, in India and abroad.","demandSupplyDrivers":"Demand follows global trade in oil, coal, ore and goods and the distance cargo must travel. Supply depends on new ships delivered and old ones scrapped; war, sanctions or canal disruptions can tighten capacity suddenly.","domesticInternationalExposure":"Highly global: freight rates are set in world markets in US dollars, so earnings swing with world trade and the rupee.","capexIntensity":"High","capexNote":"Ships are very costly, and buying them at the right point in the cycle decides long-term returns.","workingCapital":"Charter hire is usually received in advance or promptly, so working capital is modest, but cash flows swing with freight rates.","regulation":"The Directorate General of Shipping regulates Indian-flag vessels and the tonnage tax scheme taxes ships on tonnage rather than profit; global emission and safety rules set by the IMO raise compliance costs.","competitiveAdvantages":"A young fuel-efficient fleet, low-cost financing, strong charterer relationships and well-timed buying and selling of ships separate good operators.","drivers":[{"factor":"Exports & global demand","impact":"World trade in energy, bulk goods and containers sets demand for ships."},{"factor":"Crude oil prices","impact":"Oil trade patterns drive tanker demand, and bunker prices affect voyage costs."},{"factor":"Currency (INR)","impact":"Dollar-based freight income gains when the rupee weakens."},{"factor":"Global fleet supply","impact":"New ship deliveries and scrapping of old ships set capacity and rates."},{"factor":"Geopolitics and trade routes","impact":"Conflicts, sanctions and canal disruptions lengthen voyages and can lift rates."}],"risks":[{"risk":"Freight rate collapse","detail":"Excess ships or weak trade can push rates below running costs."},{"risk":"Ship value swings","detail":"Vessel prices fall in downturns, hurting resale and borrowing capacity."},{"risk":"Emission rules","detail":"Stricter global fuel and emission norms may force costly upgrades."},{"risk":"Accidents and sanctions","detail":"Casualties, piracy or sanctions on routes can disrupt operations."}],"cyclicality":"Cyclical","cyclicalityNote":"Highly cyclical: freight rates and ship values can rise and fall sharply within short periods.","metricSet":"logistics-transport","relatedBasicIndustries":["b-port-and-port-services","b-ship-building-and-allied-services","b-offshore-support-solution-drilling","b-oil-storage-and-transportation"],"aliases":["shipping","tankers","dry bulk","freight rates","charter rates","vessels","marine transport","LPG carrier","ship owner"],"themes":["Exports"]},"b-transport-related-services":{"simplifiedExplanation":"These companies do not run vehicles themselves but provide services and technology that help transport work, such as digital freight platforms, fleet tracking, toll and fuel payments, and railway safety and signalling systems.","productsAndServices":["Digital freight marketplaces for truckers","Fleet telematics and GPS tracking","FASTag, toll and fuel payment services","Railway signalling and train collision-avoidance systems","Services platforms for fleet owners","Parking and traffic management"],"valueChainPosition":"Support layer around transport: it supplies software, devices or engineered systems to fleet owners, shippers, toll operators and Indian Railways.","howTheyMakeMoney":"They earn transaction fees, subscriptions, commissions or project fees. Platform businesses grow by adding users and transactions, while system suppliers earn from contracts plus annual maintenance.","revenueSources":["Payment and transaction fees","Telematics subscriptions","Marketplace commissions","Signalling and safety system contracts","Maintenance and support fees"],"operatingCosts":["Software development","Employee costs","Devices and electronic components","Marketing and user acquisition","Installation and field service"],"customersAndEndMarkets":"Truck owners and fleet operators, shippers, toll operators, central and state agencies, and Indian Railways.","demandSupplyDrivers":"Demand grows as freight booking and payments go digital, tolling becomes electronic and railways invest in safety. Many start-ups and engineering firms compete, so scale and proven technology matter.","domesticInternationalExposure":"Mostly domestic, tied to India's freight activity and rail spending; some electronic components are imported.","capexIntensity":"Low","capexNote":"Money goes mainly into software, people and devices rather than heavy assets.","workingCapital":"Platform businesses are paid quickly, but suppliers to railways and government projects can face long receivable cycles and retention money.","regulation":"RBI and NPCI rules govern FASTag and digital payments, railway safety systems need approval from Indian Railways' standards bodies, and government work follows tender rules.","competitiveAdvantages":"Network effects from a large user base, approved and field-tested safety technology and data on freight flows create barriers.","drivers":[{"factor":"Technology change","impact":"Digital freight booking, payments and tracking widen the market."},{"factor":"Infrastructure spending","impact":"Railway safety and highway tolling programmes create large contracts."},{"factor":"Government policy","impact":"Mandates such as electronic tolling and rail safety systems drive adoption."},{"factor":"Freight activity","impact":"More trucks and cargo on the move mean more transactions on platforms."}],"risks":[{"risk":"Project delays","detail":"Government contracts can slip, delaying revenue and payments."},{"risk":"Competition","detail":"Start-ups and large tech firms target the same users."},{"risk":"Cash burn","detail":"Platforms may spend heavily on growth before turning profitable."},{"risk":"Technology failure","detail":"Faults in safety or payment systems can bring penalties and lost trust."}],"cyclicality":"Mixed","cyclicalityNote":"Transaction volumes follow freight activity, while government safety and tolling contracts follow budget cycles.","metricSet":"services-generic","relatedBasicIndustries":["b-logistics-solution-provider","b-road-transport","b-railways","b-financial-technology-fintech"],"aliases":["transport services","freight tech","fleet management","telematics","fastag","railway signalling","kavach","trucking platform","logistics tech"],"themes":["Digital","Infrastructure"]},"b-airport-and-airport-services":{"simplifiedExplanation":"Airport companies build and run airports under long concessions from the government, and service firms handle ground operations, cargo and lounges. Income comes from airlines and passengers, and also from shops, parking and property around the airport.","productsAndServices":["Airport operation under concession","Landing, parking and passenger fees","Duty-free and retail","Food and beverage concessions","Car parking and advertising","Cargo terminals","Ground handling","City-side real estate"],"valueChainPosition":"Downstream infrastructure owner: it receives a concession from the government or the Airports Authority of India, builds terminals through contractors and serves airlines, passengers, cargo agents and retailers.","howTheyMakeMoney":"Aeronautical income such as landing and user development fees is regulated, while non-aeronautical income from retail, parking, advertising and land is earned commercially and grows with passenger numbers.","revenueSources":["Aeronautical charges (landing, parking, user fees)","Retail, duty-free and F&B concessions","Parking and advertising","Cargo handling","Real estate leasing"],"operatingCosts":["Revenue share or concession fee to the authority","Staff and security","Power and utilities","Terminal and runway maintenance","Interest on project debt","Depreciation"],"customersAndEndMarkets":"Airlines, domestic and international passengers, cargo agents, retail and food operators, and businesses renting land near the airport.","demandSupplyDrivers":"Passenger and cargo traffic drive income, while terminal capacity is added in large blocks under concession plans. Tariff resets by the regulator decide how well new investment is rewarded.","domesticInternationalExposure":"Mostly domestic, but international traffic, duty-free sales and tourism tie earnings to global travel; some borrowing may be in foreign currency.","capexIntensity":"High","capexNote":"New terminals and runways need heavy upfront investment recovered over long concession periods.","workingCapital":"Airlines pay charges on short credit and retail partners pay monthly; the main risk is unpaid dues when an airline is in distress.","regulation":"AERA sets aeronautical tariffs at major airports, the Airports Authority of India and the Ministry of Civil Aviation award concessions, and DGCA and BCAS govern safety and security.","competitiveAdvantages":"An airport is a natural local monopoly protected by a long concession; competition comes mainly from a new airport in the same city region.","drivers":[{"factor":"Tourism & travel","impact":"Passenger growth lifts both regulated fees and retail and parking income."},{"factor":"Regulation","impact":"AERA tariff orders decide the return earned on airport investment."},{"factor":"Interest rates","impact":"Large project debt makes financing costs important."},{"factor":"Consumer demand","impact":"Passenger spending in shops and restaurants drives non-aeronautical income."},{"factor":"Infrastructure spending","impact":"New airports and terminal expansions add capacity and future earning potential."}],"risks":[{"risk":"Tariff resets","detail":"Lower-than-expected regulated tariffs reduce returns."},{"risk":"Traffic shocks","detail":"Pandemics, airline failures or conflicts can cut passenger numbers."},{"risk":"Project overruns","detail":"Delays and cost overruns in terminal construction raise debt."},{"risk":"Concession terms","detail":"Revenue-share obligations stay even when traffic falls."}],"cyclicality":"Mixed","cyclicalityNote":"Traffic grows over time but drops sharply in travel shocks; regulated tariffs add some stability.","metricSet":"transport-assets","relatedBasicIndustries":["b-airline","b-tour-travel-related-services","b-port-and-port-services","b-road-assets-toll-annuity-hybrid-annuity"],"aliases":["airport","airports","airport operator","ground handling","duty free","aviation infrastructure","airport terminal","cargo terminal"],"themes":["Infrastructure","Tourism"]},"b-port-and-port-services":{"simplifiedExplanation":"Port companies run terminals where ships load and unload containers, coal, oil and other cargo, earning a fee for each tonne or container handled. Some also offer marine services, storage, rail links and logistics parks near the port.","productsAndServices":["Container terminal handling","Bulk and break-bulk cargo handling","Liquid cargo jetties and tank farms","Marine services such as pilotage and towage","Container freight stations","Port-linked rail and logistics","Port-based industrial land"],"valueChainPosition":"Midstream gateway between sea and land: it serves shipping lines, importers and exporters, and connects to railways, roads and logistics firms inland.","howTheyMakeMoney":"They charge per tonne or per container moved, plus storage, marine and other port fees. Long-term contracts with anchor customers such as power plants and refineries give steady volume.","revenueSources":["Cargo handling charges","Storage and warehousing","Marine services","Port logistics and rail services","Land lease and SEZ income"],"operatingCosts":["Royalty or revenue share to the port authority or maritime board","Fuel and power for cranes and equipment","Staff","Maintenance dredging","Depreciation","Interest on project debt"],"customersAndEndMarkets":"Shipping lines, power producers, refiners, steel and cement makers, exporters, importers and freight forwarders.","demandSupplyDrivers":"Cargo volumes follow India's imports of coal, crude and fertiliser and its export-import container trade. Capacity grows through new berths, deeper drafts and new ports, and nearby ports compete for the same inland markets.","domesticInternationalExposure":"Directly tied to foreign trade; some tariffs and contracts are dollar-linked, and global shipping lines decide which ports their ships call at.","capexIntensity":"High","capexNote":"Berths, breakwaters, cranes and road and rail links need large upfront spend recovered over long concessions.","workingCapital":"Customers usually pay on short credit and anchor contracts are stable, so working capital needs are generally modest.","regulation":"Major ports come under the Major Port Authorities Act and the Ministry of Ports, Shipping and Waterways, while other ports fall under state maritime boards; customs and coastal zone clearances also apply.","competitiveAdvantages":"A natural deep-water site, rail and road links to a large hinterland, long concessions and anchor cargo contracts are hard to replicate.","drivers":[{"factor":"Exports & global demand","impact":"Container traffic rises and falls with India's foreign trade."},{"factor":"Commodity prices","impact":"Import volumes of coal, crude and fertiliser respond to global prices and domestic demand."},{"factor":"Infrastructure spending","impact":"Better rail and road connections widen the area a port can serve."},{"factor":"Government policy","impact":"PPP concessions and port-led development programmes shape new capacity."},{"factor":"Interest rates","impact":"Debt-funded expansions become costlier when rates rise."}],"risks":[{"risk":"Trade slowdown","detail":"Weaker imports and exports reduce cargo volumes."},{"risk":"Competition from nearby ports","detail":"New capacity in the same region can draw cargo away."},{"risk":"Concession issues","detail":"Disputes or renewal terms with the port authority can affect earnings."},{"risk":"Customer concentration","detail":"A large anchor customer cutting volumes hurts throughput."}],"cyclicality":"Mixed","cyclicalityNote":"Long-term contracts steady volumes, but cargo still follows trade and commodity cycles.","metricSet":"transport-assets","relatedBasicIndustries":["b-shipping","b-logistics-solution-provider","b-dredging","b-railways"],"aliases":["port","ports","port operator","container terminal","SEZ","cargo handling","harbour","maritime","terminal operator"],"themes":["Infrastructure","Exports"]},"b-road-assets-toll-annuity-hybrid-annuity":{"simplifiedExplanation":"These companies own road projects such as highways built under concessions from NHAI or state agencies, and earn either tolls from vehicles or fixed annuity payments from the government. Many hold roads through project companies or infrastructure investment trusts (InvITs).","productsAndServices":["Toll roads (build-operate-transfer)","Annuity road projects","Hybrid annuity model (HAM) projects","Toll-operate-transfer (TOT) bundles","Road operation and maintenance","Road InvIT holdings"],"valueChainPosition":"Downstream asset owner: EPC contractors build the road, the owner raises equity and debt, and the road authority or road users pay over the concession period.","howTheyMakeMoney":"Toll roads collect fees that rise with traffic and periodic inflation-linked toll revisions. Annuity and hybrid annuity projects receive scheduled payments from the authority, removing most traffic risk.","revenueSources":["Toll collections","Annuity payments from NHAI or state authorities","Interest on hybrid annuity receivables","Operation and maintenance income","Gains on selling projects to InvITs"],"operatingCosts":["Interest on project loans","Routine and periodic road maintenance","Toll collection costs","Concession fee or premium to the authority","Staff and insurance"],"customersAndEndMarkets":"Trucks, buses and cars using toll roads, and NHAI, MoRTH or state road authorities for annuity-type projects.","demandSupplyDrivers":"Toll income follows freight movement, car ownership and economic activity, while annuity income depends on the authority paying on time. New projects follow government highway award cycles.","domesticInternationalExposure":"Fully domestic; costs and income are in rupees, and the main outside influence is interest rates and inflation.","capexIntensity":"High","capexNote":"Roads are built upfront with heavy debt and equity, then recovered over a long concession.","workingCapital":"Tolls arrive daily through FASTag and cash, while annuity projects depend on timely government payments; working capital is otherwise light.","regulation":"Concession agreements with NHAI, MoRTH or state agencies set tolls, annuities and obligations; toll rates follow notified fee rules, and InvITs are regulated by SEBI.","competitiveAdvantages":"Long concessions on busy corridors without a free alternative road are valuable; low funding costs and execution skill matter when bidding.","drivers":[{"factor":"Infrastructure spending","impact":"Highway award programmes create new projects to build and own."},{"factor":"Interest rates","impact":"Heavy project debt makes refinancing costs a key driver of returns."},{"factor":"Inflation-linked tolls","impact":"Toll rates are revised periodically using an inflation-linked formula."},{"factor":"Government policy","impact":"Asset monetisation and the HAM model shape how roads are funded and sold."},{"factor":"Commercial vehicle traffic","impact":"Truck movement linked to industry and trade decides toll income."}],"risks":[{"risk":"Traffic shortfall","detail":"Toll roads earn less if traffic grows slower than planned or diverts to new roads."},{"risk":"Payment delays","detail":"Late annuity payments from authorities strain cash flow."},{"risk":"Refinancing risk","detail":"Higher rates raise interest costs on large project loans."},{"risk":"Toll policy changes","detail":"Protests, exemptions or policy shifts can cut toll collections."}],"cyclicality":"Mixed","cyclicalityNote":"Annuity roads behave defensively, while toll roads follow economic and freight cycles.","metricSet":"transport-assets","relatedBasicIndustries":["b-civil-construction","b-airport-and-airport-services","b-port-and-port-services","b-power-transmission"],"aliases":["toll road","highway","BOT","HAM","hybrid annuity","annuity road","InvIT","road assets","NHAI projects","TOT"],"themes":["Infrastructure"]},"b-trading-and-distributors":{"simplifiedExplanation":"These are trading houses and distributors that buy goods in bulk and resell them, earning a margin rather than making the products. In India this includes government trading agencies, e-auction platforms and distributors of building materials, electronics and other goods.","productsAndServices":["Import and export trading of commodities","Distribution of building materials","Distribution of electronics and IT products","E-auction and e-procurement services","Agri commodity trading","Industrial goods supply"],"valueChainPosition":"Midstream intermediary: it buys from manufacturers, importers or government sellers and supplies retailers, contractors, industries and consumers.","howTheyMakeMoney":"They earn a markup on goods sold, while auction platforms earn a commission on the value traded. Fast inventory turnover and tight credit control matter more than large margins.","revenueSources":["Trading margin on goods sold","Commissions and service fees","Auction and platform fees","Logistics and value-added services"],"operatingCosts":["Cost of goods purchased","Warehousing and freight","Interest on working capital loans","Staff and sales network","Bad debts"],"customersAndEndMarkets":"Retailers, contractors, small builders, industrial buyers, government departments, and exporters or importers.","demandSupplyDrivers":"Volumes follow construction, consumer demand, government procurement and trade flows. Manufacturers selling directly or online can squeeze the role of distributors.","domesticInternationalExposure":"Varies by business: commodity traders follow global prices and the rupee, while domestic distributors depend on local demand.","capexIntensity":"Low","capexNote":"Spending is mostly on warehouses, branches and IT systems.","workingCapital":"Working capital is heavy: inventory and customer credit are usually funded by bank lines, so inventory and receivable days drive cash flow.","regulation":"GST compliance and DGFT import-export rules matter most; government trading entities also follow ministry directions. Otherwise light, general business regulation.","competitiveAdvantages":"Exclusive distribution rights, a wide dealer network, good supplier terms and strong credit control separate strong traders from weak ones.","drivers":[{"factor":"Commodity prices","impact":"Price swings change the value of inventory and trading margins."},{"factor":"Consumer demand","impact":"Retail and household spending drive distributor volumes."},{"factor":"Real estate cycle","impact":"Construction activity drives demand for building material distributors."},{"factor":"Interest rates","impact":"Borrowing costs on inventory and credit directly hit thin margins."},{"factor":"Government policy","impact":"Procurement rules and import-export policy shape government trading and auction volumes."}],"risks":[{"risk":"Thin margins","detail":"Small cost increases or price cuts can erase profit."},{"risk":"Credit losses","detail":"Customers delaying or defaulting on payments hurt cash flow."},{"risk":"Inventory losses","detail":"Falling prices reduce the value of stock held."},{"risk":"Disintermediation","detail":"Suppliers selling directly or online can bypass distributors."}],"cyclicality":"Cyclical","cyclicalityNote":"Volumes and margins follow the demand and price cycle of the goods being traded.","metricSet":"trading-distribution","relatedBasicIndustries":["b-distributors","b-trading-metals","b-trading-chemicals","b-other-construction-materials"],"aliases":["trading","trader","distributor","distribution","trading house","wholesale","e-auction","import export","state trading"],"themes":[]},"b-consulting-services":{"simplifiedExplanation":"Consulting firms sell expert advice and design work, such as engineering design, project planning, mine planning and management consulting. Their main asset is skilled people, and they are paid per study, per assignment or per project stage.","productsAndServices":["Engineering design and detailed project reports","Project management consultancy","Mine planning and exploration services","Feasibility studies","Environmental and technical assessments","Management and advisory services"],"valueChainPosition":"Upstream of project execution: consultants plan and design projects for owners before contractors build them, and may supervise construction.","howTheyMakeMoney":"They charge fees per assignment, per milestone or as a share of project cost. Profit depends on billing skilled staff at good rates and keeping them busy.","revenueSources":["Consultancy fees","Project management fees","Design and engineering contracts","Exploration and survey services","Training and advisory"],"operatingCosts":["Employee salaries","Subcontracted specialists","Travel and site costs","Software and survey equipment","Office costs"],"customersAndEndMarkets":"Government departments, PSUs, mining and infrastructure companies, and private industry.","demandSupplyDrivers":"Demand follows the capital spending plans of governments and industry; the supply of experienced engineers and specialists limits how fast firms can grow.","domesticInternationalExposure":"Mostly domestic, though some firms win overseas assignments and global consulting firms compete for large projects.","capexIntensity":"Low","capexNote":"Spending is mainly on people, software and some field equipment.","workingCapital":"Government clients may delay payment and hold back retention money, so receivables can build up.","regulation":"Light, general business regulation; government assignments follow public procurement and empanelment rules.","competitiveAdvantages":"Domain expertise, a track record on complex projects, empanelment with government bodies and long client relationships protect good firms.","drivers":[{"factor":"Infrastructure spending","impact":"More public projects mean more design, planning and supervision work."},{"factor":"Government policy","impact":"Mining, energy and infrastructure programmes create new consulting assignments."},{"factor":"Capital expenditure cycle","impact":"Industry expansion plans decide demand for feasibility and engineering studies."},{"factor":"Technology change","impact":"Digital design and survey tools change productivity and the services offered."}],"risks":[{"risk":"Client concentration","detail":"Dependence on a few government or PSU clients makes revenue lumpy."},{"risk":"Talent retention","detail":"Losing experienced specialists weakens delivery and bidding."},{"risk":"Payment delays","detail":"Slow government payments stretch cash flow."},{"risk":"Fee pressure","detail":"Competitive tenders can push fees down."}],"cyclicality":"Mixed","cyclicalityNote":"Work follows government and industry capex plans, but long assignments smooth revenue.","metricSet":"services-generic","relatedBasicIndustries":["b-civil-construction","b-computers-software-and-consulting","b-diversified-commercial-services","b-coal"],"aliases":["consulting","consultancy","engineering consultancy","project management consultancy","PMC","DPR","mine planning","advisory services"],"themes":["Infrastructure"]},"b-data-processing-services":{"simplifiedExplanation":"These firms handle large volumes of data for other organisations, such as processing transactions, digitising and managing documents, and cleaning, storing or analysing data. They are paid to do this accurately and securely at scale.","productsAndServices":["Transaction processing","Document digitisation and records management","Data entry and data cleansing","Data analytics and reporting","Data hosting and management","Identity and verification processing"],"valueChainPosition":"Midstream service provider: it uses software, data centres and trained staff to process data for banks, insurers, government bodies and corporates.","howTheyMakeMoney":"They charge per transaction, per record or through multi-year contracts. Automation and scale lower the cost of each unit processed and lift margins.","revenueSources":["Per-transaction fees","Long-term processing contracts","Analytics and reporting fees","Storage and hosting charges"],"operatingCosts":["Employee costs","Software licences and technology","Data centre and cloud costs","Data security and compliance","Office and facility costs"],"customersAndEndMarkets":"Banks, insurers, capital-market intermediaries, government departments, healthcare providers and large corporates in India and abroad.","demandSupplyDrivers":"Demand grows with digitisation, record-keeping rules and rising data volumes. Cloud platforms and automation tools both create new work and threaten manual processing.","domesticInternationalExposure":"A mix: some firms serve Indian clients, while others export services and earn in foreign currency.","capexIntensity":"Medium","capexNote":"Needs ongoing investment in servers, software and secure facilities, though far less than heavy industry.","workingCapital":"Receivables from enterprise and government clients are the main item; there is little or no inventory.","regulation":"The Digital Personal Data Protection Act, RBI and SEBI rules on outsourcing and data storage for financial clients, and CERT-In cyber security directions apply.","competitiveAdvantages":"Security certifications, long client relationships, process accuracy and scale give an edge, and switching providers is costly for clients.","drivers":[{"factor":"Technology change","impact":"Automation and AI cut processing costs but can also shrink manual work."},{"factor":"Regulation","impact":"Data protection and record-keeping rules raise demand for secure processing."},{"factor":"Digital adoption","impact":"The shift of records and payments to digital formats expands volumes."},{"factor":"Exports & global demand","impact":"Overseas clients' outsourcing budgets drive export revenue."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts the rupee value of export earnings."}],"risks":[{"risk":"Data breaches","detail":"A security lapse can bring penalties and lost clients."},{"risk":"Automation","detail":"Clients may move simple processing to software and cloud tools."},{"risk":"Client concentration","detail":"A few large contracts may account for much of revenue."},{"risk":"Pricing pressure","detail":"Renewals and tenders can push per-unit prices down."}],"cyclicality":"Mixed","cyclicalityNote":"Recurring processing contracts are steady, but new projects and volumes depend on client budgets.","metricSet":"bpo-services","relatedBasicIndustries":["b-it-enabled-services","b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo","b-computers-software-and-consulting","b-depositories-clearing-houses-and-other-intermediaries"],"aliases":["data processing","transaction processing","data management","document management","digitisation","data analytics","records management","data services"],"themes":["Digital"]},"b-diversified-commercial-services":{"simplifiedExplanation":"A wide group of businesses that provide services to companies, institutions and households, such as facility management, security guards, staffing, testing and certification, furniture or appliance rental, and student housing. What they share is that they sell services, not products.","productsAndServices":["Facility management and housekeeping","Security services","Staffing and manpower supply","Testing, inspection and certification","Furniture and appliance rental","Student and co-living accommodation","Event and exhibition services","Business support services"],"valueChainPosition":"Downstream service layer: it uses manpower, equipment and premises to deliver outsourced services to corporates, institutions, government and households.","howTheyMakeMoney":"Most earn monthly fees per contract or per person deployed, while rental and certification businesses earn per item rented or per certificate issued. Margins depend on pricing power and staff productivity.","revenueSources":["Contract service fees","Manpower billing","Rental income","Testing and certification fees","Accommodation fees"],"operatingCosts":["Wages and statutory benefits","Depreciation of rental assets and equipment","Premises rent","Consumables","Supervision and travel","Technology"],"customersAndEndMarkets":"Corporates, factories, IT parks, hospitals, educational institutions, government bodies, students and households.","demandSupplyDrivers":"Demand comes from companies outsourcing non-core work, formal employment, office occupancy and campus growth. Many small local players keep pricing competitive in basic services.","domesticInternationalExposure":"Largely domestic; certification and some specialised services may serve international clients or work with global partners.","capexIntensity":"Medium","capexNote":"Manpower services need little capital, but rental, housing and testing businesses invest upfront in assets.","workingCapital":"Wages are paid monthly while clients pay on credit, so receivable control decides cash flow for manpower-heavy firms.","regulation":"Labour laws and labour codes, state minimum wage notifications, PSARA licences for private security agencies and GST on services matter most.","competitiveAdvantages":"Scale, a clean compliance record, long client relationships and trusted brands in certification help; entry barriers are low in basic manpower services.","drivers":[{"factor":"Outsourcing trend","impact":"More companies handing over non-core work widens the market."},{"factor":"Regulation","impact":"Labour code compliance favours larger, organised providers."},{"factor":"Wage inflation","impact":"Minimum wage revisions raise costs and must be passed to clients."},{"factor":"Real estate cycle","impact":"Office, campus and housing occupancy drives facility and rental demand."},{"factor":"Consumer demand","impact":"Household spending drives rental and certification volumes."}],"risks":[{"risk":"Low margins","detail":"Basic services face intense price competition."},{"risk":"Wage cost increases","detail":"Delays in passing on wage hikes squeeze profit."},{"risk":"Client loss","detail":"Contracts can move to cheaper rivals at renewal."},{"risk":"Compliance lapses","detail":"Labour or licensing violations bring penalties and reputation damage."}],"cyclicality":"Mixed","cyclicalityNote":"Essential support services are steady, while rental, events and staffing follow business activity.","metricSet":"services-generic","relatedBasicIndustries":["b-consulting-services","b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo","b-real-estate-related-services","b-other-consumer-services"],"aliases":["commercial services","facility management","staffing","manpower","security services","rental","testing and certification","co-living","student housing","business services"],"themes":[]},"b-business-process-outsourcing-bpo-knowledge-process-outsourcing-kpo":{"simplifiedExplanation":"BPO and KPO companies run business processes for other companies, such as customer support, back-office work, finance and accounting, analytics and research. BPO is mostly routine process work, while KPO involves higher-skill knowledge work.","productsAndServices":["Customer support and contact centres","Finance and accounting outsourcing","Data analytics and research","Healthcare and insurance back office","Collections support","HR and payroll processing","Digital operations and content moderation"],"valueChainPosition":"Midstream service exporter: it uses trained staff, delivery centres and software to take over processes from banks, telecoms, retailers, healthcare firms and others in India and abroad.","howTheyMakeMoney":"They bill per employee, per transaction or per outcome under multi-year contracts. Margins come from staff productivity, utilisation, automation and India's cost advantage.","revenueSources":["Per-seat or per-employee billing","Per-transaction fees","Outcome-based contracts","Analytics and consulting projects"],"operatingCosts":["Employee salaries and training","Delivery centre rent","Technology and telecom","Travel and onsite costs","Recruitment to replace attrition"],"customersAndEndMarkets":"Global and Indian companies in banking, insurance, telecom, healthcare, retail, travel and technology.","demandSupplyDrivers":"Demand comes from companies seeking lower costs and specialised skills. A large graduate pool supports supply, while automation and AI tools can replace routine work but also create new digital work.","domesticInternationalExposure":"Many earn much of their revenue in US dollars, pounds or euros, so currency moves and client spending abroad matter; domestic BPO serves Indian banks, telecom and e-commerce.","capexIntensity":"Low","capexNote":"Spending is mainly on offices, IT equipment and software.","workingCapital":"Receivables from clients are the main working capital item; there is no inventory.","regulation":"SEZ and STPI rules affect tax and operations, DoT's Other Service Provider rules have been relaxed, and data protection laws in India and client countries apply.","competitiveAdvantages":"Domain expertise, deep client relationships, quality certifications and automation capability make clients reluctant to switch.","drivers":[{"factor":"Exports & global demand","impact":"Outsourcing budgets of overseas clients drive most growth."},{"factor":"Currency (INR)","impact":"A weaker rupee lifts rupee revenue and margins on export contracts."},{"factor":"Technology change","impact":"AI and automation reshape which processes are outsourced and how they are priced."},{"factor":"Wage inflation and attrition","impact":"Salary rises and staff turnover raise delivery costs."},{"factor":"Regulation","impact":"Data protection rules raise compliance needs but favour trusted providers."}],"risks":[{"risk":"Automation and AI","detail":"Routine voice and back-office work can be automated away."},{"risk":"Client concentration","detail":"A few large clients may contribute much of revenue."},{"risk":"Attrition","detail":"High staff turnover hurts quality and raises hiring costs."},{"risk":"Data security","detail":"Breaches of client data can end contracts."}],"cyclicality":"Mixed","cyclicalityNote":"Contracts are recurring, but clients cut discretionary work in downturns and can renegotiate volumes.","metricSet":"bpo-services","relatedBasicIndustries":["b-it-enabled-services","b-computers-software-and-consulting","b-data-processing-services","b-diversified-commercial-services"],"aliases":["BPO","KPO","BPM","call centre","contact center","back office","outsourcing","knowledge process outsourcing","customer experience","CX"],"themes":["Exports","Digital"]},"b-urban-local-bodies":{"simplifiedExplanation":"Urban local bodies are city municipal corporations and councils. They appear on the exchange because they raise money by issuing municipal bonds, not shares, to fund water, sewerage, roads and other city projects.","productsAndServices":["Municipal bonds","Green municipal bonds","Water supply and sewerage projects","Roads and storm-water drainage","Solid waste management","Other civic services"],"valueChainPosition":"Public service provider and borrower: it collects taxes and fees from citizens and businesses, receives government grants, and borrows from bond investors to build city infrastructure.","howTheyMakeMoney":"They are not profit-making businesses. Bonds are repaid from property tax, user charges such as water fees and grants from state and central governments, often routed through escrow accounts.","revenueSources":["Property tax","Water and sewerage user charges","Grants from state and central governments","Fees, licences and rents","Government incentives for bond issues"],"operatingCosts":["Staff salaries and pensions","Running city services","Electricity for water pumping and street lights","Interest on borrowings","Project spending"],"customersAndEndMarkets":"Citizens and businesses in the city who pay taxes and user charges, and bond investors such as banks, insurers, pension funds and individuals.","demandSupplyDrivers":"The need for urban infrastructure grows with city populations. The ability to borrow depends on own revenue collection, credit ratings and government support for municipal bonds.","domesticInternationalExposure":"Fully domestic, with no international exposure.","capexIntensity":"High","capexNote":"Bond money goes into long-life public assets such as water, sewerage and roads.","workingCapital":"Tax collections can be seasonal and grants can arrive late, so bond structures often use escrow accounts to protect repayments.","regulation":"SEBI's regulations on issue and listing of municipal debt securities govern the bonds, state municipal laws set their powers, and schemes such as AMRUT and the Smart Cities Mission support projects.","competitiveAdvantages":"Not competitive businesses; creditworthiness rests on a strong tax base, collection efficiency, transparent accounts and state government support.","drivers":[{"factor":"Government policy","impact":"Central and state schemes provide grants and incentives for municipal borrowing."},{"factor":"Interest rates","impact":"Bond yields decide how costly it is to borrow for city projects."},{"factor":"Property tax collection","impact":"Better collection and updated assessments strengthen repayment capacity."},{"factor":"Infrastructure spending","impact":"Planned water, sewerage and road projects decide how much is borrowed."}],"risks":[{"risk":"Weak own revenue","detail":"Low tax and user-charge collection limits repayment capacity."},{"risk":"Grant dependence","detail":"Delays in state or central transfers can strain finances."},{"risk":"Project delays","detail":"Slow execution delays the user income projects were meant to bring."},{"risk":"Thin bond trading","detail":"Listed municipal bonds may be hard to buy or sell."}],"cyclicality":"Defensive","cyclicalityNote":"Essential civic services and tax-backed income are steady, though finances depend on state support.","metricSet":"public-services","relatedBasicIndustries":["b-development-authority","b-water-supply-and-management","b-waste-management","b-financial-institution"],"aliases":["municipal corporation","municipal bonds","muni bonds","urban local body","ULB","city corporation","nagar nigam","green municipal bond"],"themes":["Infrastructure"]},"b-development-authority":{"simplifiedExplanation":"Development authorities are state government bodies that plan and develop cities and regions, acquire land, build infrastructure and sell plots or housing. They appear on the exchange mainly as bond issuers that borrow to fund their projects.","productsAndServices":["Bonds to fund development projects","Land development and plot sales","Housing schemes","Urban roads, flyovers and transit-linked projects","Township and industrial area planning","Building plan approvals"],"valueChainPosition":"Public planning and development body: it acquires land, hires contractors to build infrastructure, and sells or leases developed land to developers, industries and households.","howTheyMakeMoney":"They are not run for profit; income comes from selling or leasing developed land, development charges, approval fees and government grants, which together also service their bonds.","revenueSources":["Sale and lease of developed land","Housing scheme sales","Development and betterment charges","Building approval fees","State government grants"],"operatingCosts":["Land acquisition and compensation","Infrastructure construction","Staff costs","Interest on borrowings","Upkeep of developed areas"],"customersAndEndMarkets":"Home buyers, real estate developers, industries and commercial users buying land, plus bond investors.","demandSupplyDrivers":"Income depends on demand for land and housing in their region, which follows the property cycle. Their capacity to borrow depends on land sales and state government backing.","domesticInternationalExposure":"Fully domestic.","capexIntensity":"High","capexNote":"Land and infrastructure development needs large sums before plots can be sold.","workingCapital":"Land banks behave like inventory and sell slowly in weak property markets, while compensation and contractor bills must be paid upfront.","regulation":"They are created under state town planning and development laws and follow state government direction; their bonds fall under SEBI's debt listing rules, and land acquisition law applies.","competitiveAdvantages":"Statutory planning powers and control over large land parcels give them a unique position; credit strength rests on state support and saleable land.","drivers":[{"factor":"Real estate cycle","impact":"Demand for plots and housing decides land sale income."},{"factor":"Government policy","impact":"State development plans and approvals set project pipelines."},{"factor":"Interest rates","impact":"Borrowing costs affect both the authority and buyers of its land and homes."},{"factor":"Infrastructure spending","impact":"New roads and transit raise land values in their areas."}],"risks":[{"risk":"Weak land sales","detail":"A property slowdown leaves land unsold and cash tied up."},{"risk":"Land disputes","detail":"Acquisition disputes and litigation can stall projects."},{"risk":"State finances","detail":"Weak state support can hurt their credit standing."},{"risk":"Project delays","detail":"Slow execution delays land monetisation."}],"cyclicality":"Mixed","cyclicalityNote":"Land sale income follows the property cycle, while state backing keeps them steadier as borrowers.","metricSet":"public-services","relatedBasicIndustries":["b-urban-local-bodies","b-residential-commercial-projects","b-civil-construction","b-financial-institution"],"aliases":["development authority","urban development authority","development authority bonds","city development","town planning","land development","metropolitan development authority"],"themes":["Infrastructure"]},"b-telecom-cellular-and-fixed-line-services":{"simplifiedExplanation":"Telecom operators provide mobile calls and data, home broadband, fixed lines and business connectivity. They earn prepaid and monthly charges from very large customer bases and must invest heavily in spectrum and networks.","productsAndServices":["Prepaid and postpaid mobile plans","Mobile data","Home fibre broadband","Fixed-line voice","Enterprise connectivity and leased lines","International bandwidth and submarine cable capacity","Cloud, IoT and managed network services","Digital TV and content bundles"],"valueChainPosition":"Downstream network operator: it buys spectrum from the government, equipment from network vendors and tower and fibre capacity from infrastructure firms, and sells connectivity to consumers and enterprises.","howTheyMakeMoney":"They earn recurring recharge and subscription fees, so revenue per user and subscriber numbers drive income. Network costs are largely fixed, so tariff increases flow mostly to profit.","revenueSources":["Mobile recharges and subscriptions","Home broadband","Enterprise data and voice","Interconnect and roaming charges","Wholesale and international bandwidth"],"operatingCosts":["Tower rentals and network operations","Energy for network sites","Licence fees and spectrum usage charges","Spectrum amortisation and interest","Dealer commissions and marketing","Staff"],"customersAndEndMarkets":"Mobile and broadband users across urban and rural India, plus enterprises, government and other carriers.","demandSupplyDrivers":"Data use keeps rising with video, apps and digital payments, while tariffs depend on how many operators compete and how disciplined their pricing is. Spectrum auctions and network rollouts decide capacity.","domesticInternationalExposure":"Revenue is largely domestic in rupees, but much network equipment is imported and priced in dollars; some operators run overseas or global enterprise businesses.","capexIntensity":"High","capexNote":"Spectrum purchases and constant network upgrades require very large recurring investment.","workingCapital":"Prepaid customers pay in advance, so working capital is light, but deferred spectrum payments and government dues create large long-term liabilities.","regulation":"DoT issues licences and auctions spectrum, TRAI regulates tariffs and service quality, and licence fees, spectrum charges and AGR dues are major regulatory items.","competitiveAdvantages":"Spectrum holdings, network coverage, scale and brand create very high entry barriers, and the market has consolidated to a few large players.","drivers":[{"factor":"Regulation","impact":"Spectrum pricing, licence fees and government dues shape costs and debt."},{"factor":"Technology change","impact":"5G and fibre rollouts need heavy capex but open new revenue streams."},{"factor":"Consumer demand","impact":"Growing data use and upgrades to costlier plans lift revenue per user."},{"factor":"Rural demand","impact":"Rural smartphone adoption adds subscribers and data users."},{"factor":"Interest rates","impact":"High debt from spectrum and networks makes borrowing costs important."}],"risks":[{"risk":"Tariff competition","detail":"Price wars can sharply cut revenue per user."},{"risk":"Regulatory dues","detail":"Large government levies or disputed dues can strain balance sheets."},{"risk":"High debt","detail":"Weak cash flows make heavy debt hard to service."},{"risk":"Subscriber churn","detail":"Customers can easily port numbers to rivals."}],"cyclicality":"Defensive","cyclicalityNote":"Connectivity is an everyday necessity, so revenue is steady, though competition and regulation drive profits.","metricSet":"telecom-services","relatedBasicIndustries":["b-telecom-infrastructure","b-other-telecom-services","b-telecom-equipment-and-accessories","b-digital-entertainment"],"aliases":["telecom","telecom operator","mobile operator","telco","5G","broadband","ARPU","fibre to home","FTTH","cellular"],"themes":["Digital","5G"]},"b-telecom-infrastructure":{"simplifiedExplanation":"Telecom infrastructure companies build and lease the physical backbone that operators use, such as mobile towers, optical fibre networks and small cells. Some also lay fibre and install networks under contract for operators and government.","productsAndServices":["Shared tower leasing","Optical fibre networks and fibre leasing","Fibre and network rollout contracts","Small cells and in-building coverage","Power management at tower sites","Edge data centre sites"],"valueChainPosition":"Midstream: it buys steel structures, fibre cable, batteries and power equipment, and leases or builds network infrastructure for telecom operators and enterprises.","howTheyMakeMoney":"Tower firms earn long-term rent per operator on each site, so adding more tenants to the same tower lifts returns. Network rollout firms earn project fees per site or per kilometre.","revenueSources":["Tower rentals per tenant","Energy and pass-through charges","Fibre leasing","Network rollout and EPC contracts","Maintenance services"],"operatingCosts":["Site rent to landowners","Power and diesel at sites","Maintenance","Depreciation","Interest on debt","Materials and subcontractors for rollouts"],"customersAndEndMarkets":"Mobile operators, broadband providers, government network programmes such as BharatNet, and enterprises.","demandSupplyDrivers":"Demand rises as operators densify networks for 5G and connect towers and homes with fibre. Because there are only a few operators, each one's financial health and capex plans matter a lot.","domesticInternationalExposure":"Mostly domestic; some fibre and network builders export, and some components are imported.","capexIntensity":"High","capexNote":"Towers and fibre are long-life assets built upfront and leased out over many years.","workingCapital":"Receivables from financially weak operators can build up, and rollout contractors face long government payment cycles.","regulation":"Infrastructure providers register with DoT, right-of-way rules for fibre and towers come from central and state governments, and DoT radiation (EMF) norms apply.","competitiveAdvantages":"A large portfolio of well-located sites, long contracts with exit penalties and the economics of sharing make it hard for new entrants.","drivers":[{"factor":"Technology change","impact":"5G densification and fibre backhaul need more sites and fibre."},{"factor":"Operator capex","impact":"Spending plans of a few operators decide new tenancies and rollout orders."},{"factor":"Government policy","impact":"BharatNet and right-of-way reforms affect rollout speed and orders."},{"factor":"Interest rates","impact":"Asset-heavy tower and fibre owners carry significant debt."},{"factor":"Electricity demand","impact":"Power cost and grid availability at sites affect operating costs."}],"risks":[{"risk":"Customer concentration","detail":"A handful of operators supply nearly all revenue."},{"risk":"Operator stress","detail":"A weak operator may delay payments or exit tenancies."},{"risk":"Tenancy consolidation","detail":"Operator mergers can remove duplicate tenancies."},{"risk":"Execution delays","detail":"Right-of-way and permission issues slow rollouts."}],"cyclicality":"Mixed","cyclicalityNote":"Tower rentals are contracted and steady, while rollout contracts swing with operator and government capex.","metricSet":"telecom-infra","relatedBasicIndustries":["b-telecom-cellular-and-fixed-line-services","b-telecom-equipment-and-accessories","b-cables-electricals","b-civil-construction"],"aliases":["telecom towers","tower company","towerco","fibre network","optical fibre","OFC","small cells","bharatnet","telecom infra"],"themes":["Digital","5G","Infrastructure"]},"b-other-telecom-services":{"simplifiedExplanation":"This group covers specialised telecom businesses other than mainstream mobile operators, such as enterprise messaging platforms, bandwidth and network services for businesses and government, and network integration. They mainly serve organisations rather than individual consumers.","productsAndServices":["A2P SMS and enterprise messaging (CPaaS)","Bandwidth and leased line services","Network integration and managed services","VPN and enterprise connectivity","Satellite and VSAT services","Voice and video communication solutions"],"valueChainPosition":"Midstream: it uses capacity from telecom operators or its own network and builds or resells communication services for enterprises and government.","howTheyMakeMoney":"Messaging platforms earn per message or interaction, while bandwidth and network firms earn rental and project fees. Margins depend on the charges paid to operators and on scale.","revenueSources":["Per-message and usage fees","Bandwidth leasing","Network projects and integration","Managed services contracts"],"operatingCosts":["Operator termination and carriage charges","Network operation and maintenance","Employee costs","Technology platforms","Subcontracted project work"],"customersAndEndMarkets":"Banks, e-commerce and app companies, government departments, PSUs and enterprises in India and abroad.","demandSupplyDrivers":"Demand grows with digital transactions, OTP and alert messages, and government digital projects. Operator pricing and free chat apps influence the economics of messaging.","domesticInternationalExposure":"Many messaging platforms earn a large share abroad, while bandwidth and project firms are mostly domestic.","capexIntensity":"Medium","capexNote":"Platform firms need little capex, while owners of fibre or satellite networks invest more.","workingCapital":"Government and PSU projects can tie up receivables, while messaging businesses must pay operators promptly.","regulation":"DoT licences and TRAI rules, including regulations on commercial communication and spam, shape operations; government projects follow tender norms.","competitiveAdvantages":"Direct connections with operators, enterprise relationships and platform reliability, plus owned right-of-way assets for network firms.","drivers":[{"factor":"Technology change","impact":"Rich messaging, chat apps and cloud communication shift where value is captured."},{"factor":"Regulation","impact":"Anti-spam and commercial communication rules change messaging volumes and costs."},{"factor":"Exports & global demand","impact":"Overseas enterprise demand drives international messaging revenue."},{"factor":"Government policy","impact":"Digital government and railway or utility network projects create orders."}],"risks":[{"risk":"Operator pricing","detail":"Higher termination charges from operators squeeze messaging margins."},{"risk":"Substitution","detail":"Free chat apps can replace paid SMS."},{"risk":"Client concentration","detail":"Large enterprise or government clients dominate revenue."},{"risk":"Project delays","detail":"Government network projects can slip and delay payments."}],"cyclicality":"Mixed","cyclicalityNote":"Usage-based messaging and bandwidth revenue recur, while project revenue is lumpy.","metricSet":"services-generic","relatedBasicIndustries":["b-telecom-cellular-and-fixed-line-services","b-telecom-infrastructure","b-it-enabled-services","b-computers-software-and-consulting"],"aliases":["CPaaS","A2P SMS","enterprise messaging","bandwidth","telecom services","VSAT","network integration","leased line","satellite communication"],"themes":["Digital"]},"b-telecom-equipment-and-accessories":{"simplifiedExplanation":"These companies make the hardware telecom networks and users depend on, such as transmission and switching equipment, routers, optical fibre and cables, and handsets or accessories. Some design products in-house, while others assemble under contract.","productsAndServices":["Optical transmission and switching equipment","Radio access equipment for mobile networks","Broadband routers and customer-premises equipment","Optical fibre and telecom cables","Mobile handsets and accessories","Contract manufacturing of telecom electronics"],"valueChainPosition":"Upstream supplier to the telecom chain: it buys chips, components and raw materials, often imported, and supplies operators, infrastructure firms, government networks and consumers.","howTheyMakeMoney":"They sell equipment through tenders or supply contracts and also earn from installation, software and maintenance. Volumes, product mix and component costs decide margins.","revenueSources":["Equipment sales","Installation and commissioning","Annual maintenance contracts","Fibre and cable sales","Contract manufacturing fees"],"operatingCosts":["Electronic components and chips","Raw materials such as glass preform, copper and plastics","Research and development","Manufacturing labour","Warranty and logistics"],"customersAndEndMarkets":"Telecom operators, government programmes such as BharatNet, defence and railways, enterprises, and consumers through retail.","demandSupplyDrivers":"Demand follows operator network spending and government broadband projects. Global vendors compete strongly, while trusted-source and local manufacturing rules favour domestic makers.","domesticInternationalExposure":"Components are largely imported, so global supply chains and the rupee matter, and several makers export fibre, cables or equipment.","capexIntensity":"Medium","capexNote":"Factories and R&D need steady investment, though contract assemblers spend less.","workingCapital":"Component inventory and receivables from operators and government tenders make working capital heavy and lumpy.","regulation":"PLI schemes for telecom and networking products, the trusted-source rule for network equipment, mandatory testing and certification (MTCTE) by TEC and public procurement preference for local products matter.","competitiveAdvantages":"In-house technology and intellectual property, trusted-vendor status, operator approvals and manufacturing scale create barriers.","drivers":[{"factor":"Technology change","impact":"Each network generation brings new equipment demand and makes older products obsolete."},{"factor":"Government policy","impact":"PLI incentives, trusted-source rules and local-content preferences support domestic makers."},{"factor":"China+1 sourcing","impact":"Global buyers diversifying supply chains open export opportunities."},{"factor":"Currency (INR)","impact":"A weaker rupee raises imported component costs but helps exports."},{"factor":"Operator capex","impact":"Network rollout spending by operators decides order flow."}],"risks":[{"risk":"Lumpy orders","detail":"A few large tenders can make revenue swing sharply."},{"risk":"Customer concentration","detail":"Dependence on a few operators or government buyers."},{"risk":"Component shortages","detail":"Chip supply problems can delay deliveries and raise costs."},{"risk":"Global competition","detail":"Large international vendors compete on price and technology."}],"cyclicality":"Cyclical","cyclicalityNote":"Orders swing with operator and government network spending cycles.","metricSet":"telecom-equipment","relatedBasicIndustries":["b-telecom-infrastructure","b-telecom-cellular-and-fixed-line-services","b-cables-electricals","b-computers-hardware-and-equipments","b-consumer-electronics"],"aliases":["telecom equipment","network equipment","5G equipment","optical fibre cable","OFC","routers","handsets","telecom gear","make in india telecom"],"themes":["Digital","5G","China+1","Exports"]},"b-diversified":{"simplifiedExplanation":"Diversified companies run several unrelated businesses inside one listed company, such as chemicals, consumer products, agri inputs, real estate or investments in group companies. No single industry explains their results, so each segment has to be studied.","productsAndServices":["Chemicals and industrial products","Consumer and healthcare products","Agri inputs and sugar","Real estate development","Investments in group companies","Plastics, textiles or other manufacturing"],"valueChainPosition":"Spread across the value chain: different segments may be upstream manufacturers, downstream consumer brands or investment holding arms.","howTheyMakeMoney":"Each segment earns in its own way, and the parent also earns dividends from subsidiaries and gains on investments. How capital is shared between segments decides long-term returns.","revenueSources":["Segment product sales","Dividends from subsidiaries and associates","Real estate sales","Investment income"],"operatingCosts":["Raw materials for each segment","Employee costs","Power and fuel","Marketing","Interest"],"customersAndEndMarkets":"Varies by segment: industries, farmers, consumers and businesses across India and abroad.","demandSupplyDrivers":"Each segment has its own cycle; diversification can smooth earnings when one segment is weak and another strong.","domesticInternationalExposure":"Depends on the mix: chemical or agri segments may follow global prices, while consumer segments are mostly domestic.","capexIntensity":"Medium","capexNote":"Spending varies by segment, from heavy plants to light consumer brands.","workingCapital":"Varies by segment; agri and chemical units may carry seasonal inventory, while consumer units extend credit to distributors.","regulation":"Each segment faces its own regulators, and group structures face SEBI rules on related-party transactions and segment disclosure.","competitiveAdvantages":"Strong positions in individual segments, a trusted group brand, financial strength and disciplined capital allocation.","drivers":[{"factor":"Commodity prices","impact":"Chemical and agri segments move with input and output prices."},{"factor":"Consumer demand","impact":"Consumer product segments follow household spending."},{"factor":"Monsoon & agriculture","impact":"Agri input and sugar segments depend on the farm season."},{"factor":"Capital market activity","impact":"The value of listed group holdings affects how the company is valued."},{"factor":"Interest rates","impact":"Borrowing costs affect debt-funded expansions across segments."}],"risks":[{"risk":"Conglomerate discount","detail":"Markets often value the group below the sum of its parts."},{"risk":"Capital misallocation","detail":"Profits from strong segments may fund weak ones."},{"risk":"Related-party dealings","detail":"Transactions with group companies can raise governance concerns."},{"risk":"Complex structure","detail":"Many segments and subsidiaries make results harder to analyse."}],"cyclicality":"Mixed","cyclicalityNote":"Earnings blend several cycles, so they are usually less volatile than single-industry firms but rarely immune.","metricSet":"diversified","relatedBasicIndustries":["b-holding-company","b-diversified-fmcg","b-diversified-metals","b-investment-company"],"aliases":["conglomerate","diversified","multi-business","group company","business house","multi-segment"],"themes":[]}}};
